// createMenu
// ---------------------------------------------------------------------------

export interface CreateMenuDeps {
  /** Required for submitted HTML; Node hosts can use the navigation/node adapter. */
  normalizeMenuHtml?: MenuHtmlNormalizer | undefined;
  repo: MenuRepoPort;
  clock: Clock;
  idGen: IdGenerator;
  /** Enqueues `navigation.menu.created` after a successful save. */ 
  outbox: OutboxPort;
}

/** Validated, merged HTML-mode doc fields — `menu-html.ts`'s problem check raised as this file's own error. */
function menuHtmlFields(
  { input, existing, normalizeHtml }: { input: MenuHtmlAuthoring; existing?: Pick<NavMenuDoc, "mode" | "html"> | undefined; normalizeHtml?: MenuHtmlNormalizer | undefined },
): Pick<NavMenuDoc, "mode" | "html"> {
  const problem = menuHtmlInputProblem(input);
  if (problem) throw new MenuValidationError({ message: problem });
  return mergeMenuHtml({ input, existing }, { normalizeHtml });
}

export interface CreateMenuServiceInput {
  workspaceId: UUID;
  title: string;
  slug: string;
  /** Optional initial tree; defaults to an empty menu. Items must carry ids. */ 
  items?: readonly NavItemNode[] | undefined;
  /** HTML mode (`menu-html.ts`). The host gates raw HTML behind its own permission first. */
  mode?: NavMenuMode | undefined;
  html?: string | undefined;
}

export interface CreateMenuRequired {
  deps: CreateMenuDeps;
  input: CreateMenuServiceInput;
}

export interface CreateMenuOptional {
  limits?: TreeValidationLimits | undefined;
}

/**
 * Creates a new `menu` entry in `published` status with no location
 * assignments. Rejects a duplicate slug within the workspace.
 *
 * Was `draft` originally (mirroring `posts`), changed 2026-08-09 on explicit product direction: a
 * menu has no separate review/approval workflow the way a post does, and `resolveForLocation`
 * (`resolver.ts`) never actually branched on `status` — the field only ever gated the trash/purge
 * lifecycle. Landing a new menu in `draft` produced a status label at odds with its real behavior
 * (already fully live wherever it gets bound to a location) rather than gating anything real, so
 * the default now matches the actual behavior instead of implying a workflow that doesn't exist.
 *
 * @complexity O(n) in the initial tree size for validation; O(m) in existing
 * menu count for the slug-uniqueness scan (repo-dependent).
 * @overallScore 100
 */ 
export async function createMenu(
  required: CreateMenuRequired,
  optional: CreateMenuOptional = {}
): Promise<{ menu: NavMenuEntry }> {
  const { deps, input } = required;
  const title = input.title.trim();
  const slug = input.slug.trim().toLowerCase();
  assertValidTitleAndSlug(title, slug);

  await assertSlugAvailable({ repo: deps.repo, workspaceId: input.workspaceId, slug });

  const items = validateAndCloneTree({ items: input.items ?? [] }, optional.limits);
  const htmlFields = menuHtmlFields({ input, normalizeHtml: deps.normalizeMenuHtml });

  const menu: NavMenuEntry = {
    id: deps.idGen.newId(),
    workspaceId: input.workspaceId,
    slug,
    title,
    status: "published",
    doc: { type: NAV_DOC_TYPE, version: 1, items, ...htmlFields },
    locations: [],
    updatedAt: kernelNowIso({ clock: deps.clock }),
    version: 1,
  };

  await deps.repo.save(menu);

  await enqueueEvent({
    deps,
    name: "navigation.menu.created",
    workspaceId: menu.workspaceId,
    aggregateId: menu.id,
    payload: { menuId: menu.id, slug: menu.slug },
  });

  return { menu };
}

// ---------------------------------------------------------------------------
// updateMenuTree
// ---------------------------------------------------------------------------

export interface UpdateMenuTreeDeps {
  /** Required for submitted HTML; omitted markup retains the already-normalized stored value. */
  normalizeMenuHtml?: MenuHtmlNormalizer | undefined;
  repo: MenuRepoPort;
  clock: Clock;
  /** Not previously present on this deps bag — needed to mint the outbox event's id. */ 
  idGen: IdGenerator;
  /** Enqueues `navigation.menu.updated` after a successful save. */ 
  outbox: OutboxPort;
}

export interface UpdateMenuTreeServiceInput {
  workspaceId: UUID;
  id: UUID;
  /** The entry `version` this edit was based on — OCC guard. */ 
  expectedVersion: number;
  title?: string | undefined;
  slug?: string | undefined;
  /** The full replacement tree (whole-tree edit). Omitted keeps the stored tree (an HTML-only edit). */ 
  items?: readonly NavItemNode[] | undefined;
  /** HTML mode (`menu-html.ts`); omitted keeps the stored value. The host gates raw HTML first. */
  mode?: NavMenuMode | undefined;
  html?: string | undefined;
}

export interface UpdateMenuTreeRequired {
  deps: UpdateMenuTreeDeps;
  input: UpdateMenuTreeServiceInput;
}

export interface UpdateMenuTreeOptional {
  limits?: TreeValidationLimits | undefined;
}

/** The stored `entryRef` hint fields a whole-tree save carries forward when the submitted target omits them. */
const ENTRY_HINT_KEYS = ["entryType", "lastKnownHref"] as const;

function entryTargetsById(nodes: readonly NavItemNode[], into = new Map<string, NavEntryTarget>()): Map<string, NavEntryTarget> {
  for (const node of nodes) {
    if (node.target?.kind === "entryRef") into.set(node.id, node.target);
    if (node.children) entryTargetsById(node.children, into);
  }
  return into;
}

function withStoredHints(target: NavTarget, stored: NavEntryTarget | undefined): NavTarget {
  if (target.kind !== "entryRef" || !stored || stored.entryId !== target.entryId) return target;
  const merged: Record<string, unknown> = { ...target };
  for (const key of ENTRY_HINT_KEYS) {
    if (merged[key] === undefined && stored[key] !== undefined) merged[key] = stored[key];
  }
  return merged as unknown as NavEntryTarget;
}

/**
 * Whole-tree saves arrive from callers that may not know an item's stored hint fields (an agent
 * echoing a read through a schema, an older editor build). Dropping them on every save made an
 * untouched menu look changed (dry run 2026-10-05: ~30 header page links lost `entryType: "page"`
 * on one assistant save and the menu showed pending-to-live). So a hint is kept when the same item
 * id still points at the same entry and the submitted target leaves that hint out; a re-pointed
 * link or an explicitly submitted hint is taken as sent.
 */
export function carryForwardEntryHints(
  { previous, next }: { previous: readonly NavItemNode[]; next: readonly NavItemNode[] },
  _optional = {}
): NavItemNode[] {
  const stored = entryTargetsById(previous);
  const walk = (nodes: readonly NavItemNode[]): NavItemNode[] =>
    nodes.map((node) => ({
      ...node,
      target: withStoredHints(node.target, stored.get(node.id)),
      children: node.children ? walk(node.children) : undefined,
    }));
  return walk(next);
}

/**
 * Replaces a menu's whole item tree, guarded by optimistic concurrency on the
 * entry `version` (matches the host's `updatePost` pattern): `expectedVersion` must equal the version
 * read, and the repo's `save` compares it again atomically with the write; either miss throws
 * `MenuVersionConflictError`.
 *
 * Id-stability note ("an update may not renumber surviving items"):
 * this build enforces only that ids are present and unique within the
 * submitted tree (`validateAndCloneTree`). Detecting whether a *specific*
 * surviving node kept its original id would require diffing against the
 * previous tree and is deferred — a caller-discipline requirement for now,
 * not a runtime-enforced invariant.
 *
 * @complexity O(n) in the new tree size for validation; O additional repo
 * calls (one read, at most one slug-uniqueness read, one write).
 * @overallScore 90
 * @findings Medium: id-stability across edits (ids not renumbered on survive)
 * is documented but not runtime-enforced — see doc comment above. Deferred
 * pending a tree-diff mechanism; would need the previous tree's id set passed
 * in to check "no id vanished and reappeared elsewhere," which is more than
 * this slice's scope calls for.
 */ 
export async function updateMenuTree(
  required: UpdateMenuTreeRequired,
  optional: UpdateMenuTreeOptional = {}
): Promise<{ menu: NavMenuEntry }> {
  const { deps, input } = required;
  const existing = await findMenuOrThrow({ repo: deps.repo, workspaceId: input.workspaceId, id: input.id });
  assertMenuLive({ menu: existing });
  // The new record is built from this read, so a basis that differs from it must not reach the save:
  // it could match a version another writer lands after this read and overwrite that writer.
  if (existing.version !== input.expectedVersion) {
    throw menuVersionConflictError({ id: input.id, expectedVersion: input.expectedVersion, found: existing.version });
  }

  const title = (input.title ?? existing.title).trim();
  const slug = (input.slug ?? existing.slug).trim().toLowerCase();
  assertValidTitleAndSlug(title, slug);

  if (slug !== existing.slug) {
    await assertSlugAvailable({ repo: deps.repo, workspaceId: input.workspaceId, slug }, { ownerId: existing.id });
  }

  const items = input.items === undefined ? existing.doc.items : carryForwardEntryHints({
    previous: existing.doc.items,
    next: validateAndCloneTree({ items: input.items }, optional.limits),
  });
  // Every writer (admin, agent tool, publish repoint, reverters) comes through here, so the stored
  // HTML-mode fields are carried forward unless this write sets them — an items-only save never drops them.
  const htmlFields = menuHtmlFields({ input, existing: existing.doc, normalizeHtml: deps.normalizeMenuHtml });

  const menu: NavMenuEntry = {
    ...existing,
    title,
    slug,
    doc: { type: NAV_DOC_TYPE, version: existing.doc.version, items, ...htmlFields },
    updatedAt: kernelNowIso({ clock: deps.clock }),
    version: existing.version + 1,
  };

  // The version check is ALSO the save's compare-and-set, not only the read above: a check before
  // the write alone let two editors that read the same version both land (wm S4).
  await deps.repo.save(menu, { expectedVersion: input.expectedVersion });

  await enqueueEvent({
    deps,
    name: "navigation.menu.updated",
    workspaceId: menu.workspaceId,
    aggregateId: menu.id,
    payload: { menuId: menu.id, slug: menu.slug },
  });

  return { menu };
}

// ---------------------------------------------------------------------------
// assignLocation
// ---------------------------------------------------------------------------

export interface AssignLocationDeps {
  repo: MenuRepoPort;
  bindingRepo: NavLocationBindingRepoPort;
  clock: Clock;
  /** Not previously present on this deps bag — needed to mint outbox event ids. */ 
  idGen: IdGenerator;
  /** Enqueues `navigation.location.assigned` (+ `.unassigned` on reassignment). */ 
  outbox: OutboxPort;
}

export interface AssignLocationServiceInput {
  workspaceId: UUID;
  menuId: UUID;
  locationKey: NavLocationKey;
}

export interface AssignLocationRequired {
  deps: AssignLocationDeps;
  input: AssignLocationServiceInput;
}

export interface AssignLocationOptional {}

/**
 * Assigns a menu to a theme location. This writes two
 * representations that must stay in lockstep:
 * 1. the menu's own `locations` field (source of truth, revisioned), and
 * 2. the derived `nav_location_bindings` row (uniqueness index).
 *
 * If the location was already bound to a *different* menu, that menu is
 * **reassigned away** (last-writer-wins, the chosen
 * default) and its `locations` field is updated to drop the key — recorded as
 * its own revision-worthy write.
 *
 * Atomicity: these writes are ONE transaction (`repo.transaction`) — the displaced
 * menu's save, this menu's save, the binding upsert and the outbox events commit
 * together or not at all. Both menu saves are compare-and-set, so the second can
 * lose to another editor AFTER the first landed: without the transaction, that
 * left the displaced menu's `locations` without the key while the binding still
 * pointed at it, and a binding rebuild then dropped the assignment. A
 * `MenuVersionConflictError` (or any other throw) rolls the whole unit back in a
 * store that can roll back; `InMemoryMenuRepo` cannot (see its `transaction`).
 *
 * @complexity O repo calls (bounded: at most two menu reads/writes plus one
 * binding upsert), independent of workspace size.
 * @overallScore 100
 */ 
export async function assignLocation(
  required: AssignLocationRequired,
  _optional: AssignLocationOptional = {}
): Promise<{ menu: NavMenuEntry; binding: NavLocationBindingRow; displacedMenu: NavMenuEntry | null }> {
  const { deps, input } = required;
  const menu = await findMenuOrThrow({ repo: deps.repo, workspaceId: input.workspaceId, id: input.menuId });
  assertMenuLive({ menu });

  const now = kernelNowIso({ clock: deps.clock });

  const updatedMenu: NavMenuEntry = {
    ...menu,
    locations: menu.locations.includes(input.locationKey)
      ? menu.locations
      : [...menu.locations, input.locationKey],
    updatedAt: now,
    version: menu.version + 1,
  };

  return deps.repo.transaction({ fn: async () => {
    const existingBinding = await deps.bindingRepo.findByLocation({
      workspaceId: input.workspaceId,
      locationKey: input.locationKey,
    });

    let displacedMenu: NavMenuEntry | null = null;
    if (existingBinding && existingBinding.menuId !== input.menuId) {
      const displaced = await deps.repo.findById({
        workspaceId: input.workspaceId,
        id: existingBinding.menuId,
      });
      if (displaced) {
        const updatedDisplaced: NavMenuEntry = {
          ...displaced,
          locations: displaced.locations.filter((key) => key !== input.locationKey),
          updatedAt: now,
          version: displaced.version + 1,
        };
        await deps.repo.save(updatedDisplaced, { expectedVersion: displaced.version });
        displacedMenu = updatedDisplaced;
      }
    }

    await deps.repo.save(updatedMenu, { expectedVersion: menu.version });

    const binding = await deps.bindingRepo.upsert({
      workspaceId: input.workspaceId,
      locationKey: input.locationKey,
      menuId: input.menuId,
      boundAt: now,
    });

    if (displacedMenu) {
      await enqueueEvent({
        deps,
        name: "navigation.location.unassigned",
        workspaceId: input.workspaceId,
        aggregateId: displacedMenu.id,
        payload: { locationKey: input.locationKey, menuId: displacedMenu.id },
      });
    }

    await enqueueEvent({
      deps,
      name: "navigation.location.assigned",
      workspaceId: input.workspaceId,
      aggregateId: input.menuId,
      payload: { locationKey: input.locationKey, menuId: input.menuId },
    });

    return { menu: updatedMenu, binding, displacedMenu };
  } });
}

// ---------------------------------------------------------------------------
// deleteMenu (trash → purge ladder, mirrors the media library's deletion ladder)
// ---------------------------------------------------------------------------

export interface DeleteMenuDeps {
  repo: MenuRepoPort;
  bindingRepo: NavLocationBindingRepoPort;
  clock: Clock;
  /** Not previously present on this deps bag — needed to mint outbox event ids. */ 
  idGen: IdGenerator;
  /** Enqueues `navigation.menu.updated` (trash) or `navigation.menu.deleted` (purge); nothing on a blocked purge. */ 
  outbox: OutboxPort;
}

export interface DeleteMenuServiceInput {
  workspaceId: UUID;
  id: UUID;
  /** Force past the 409 dangling-location guard (needs `navigation.delete.force`). */ 
  force?: boolean | undefined;
}

export interface DeleteMenuRequired {
  deps: DeleteMenuDeps;
  input: DeleteMenuServiceInput;
}

export interface DeleteMenuOptional {}

/**
 * Deletion ladder (mirrors the media library's):
 * 1. First call on a non-trashed menu **soft-deletes** it (`status: 'trash'`,
 * revisioned) and returns — no purge yet.
 * 2. A second call on an already-trashed menu attempts the **hard purge** If
 * the menu is still bound to any location, purge is rejected with
 * `MenuLocationBoundError` (409-style) listing the bound keys, unless
 * `force` is set — permission-gating that error behind
 * `navigation.delete.force` is the caller's (gateway's) job, not this
 * function's; this function only enforces the *shape* of the guard.
 * 3. On a successful purge, the menu row and all of its location bindings are
 * removed.
 *
 * @complexity O repo calls; O(k) bindings scanned where k = locations this
 * menu holds (small, bounded by registered locations).
 * @overallScore 100
 */ 
export async function deleteMenu(
  required: DeleteMenuRequired,
  _optional: DeleteMenuOptional = {}
): Promise<{ menu: NavMenuEntry | null; purged: boolean }> {
  const { deps, input } = required;
  const existing = await findMenuOrThrow({ repo: deps.repo, workspaceId: input.workspaceId, id: input.id });

  if (existing.status !== "trash") {
    const trashed: NavMenuEntry = {
      ...existing,
      status: "trash",
      updatedAt: kernelNowIso({ clock: deps.clock }),
      version: existing.version + 1,
    };
    await deps.repo.save(trashed);

    await enqueueEvent({
      deps,
      name: "navigation.menu.updated",
      workspaceId: trashed.workspaceId,
      aggregateId: trashed.id,
      payload: { menuId: trashed.id, slug: trashed.slug },
    });

    return { menu: trashed, purged: false };
  }

  const bindings = await deps.bindingRepo.listByMenu({
    workspaceId: input.workspaceId,
    menuId: input.id,
  });

  if (bindings.length > 0 && !input.force) {
    const boundLocations = bindings.map((row) => row.locationKey);
    throw new MenuLocationBoundError({ message: `menu '${input.id}' is still bound to location(s): ${boundLocations.join(", ")} — unassign before purging, or use force`, boundLocations: boundLocations }
    );
  }

  await deps.repo.remove({ workspaceId: input.workspaceId, id: input.id });
  await deps.bindingRepo.removeByMenu({ workspaceId: input.workspaceId, menuId: input.id });

  await enqueueEvent({
    deps,
    name: "navigation.menu.deleted",
    workspaceId: existing.workspaceId,
    aggregateId: existing.id,
    payload: { menuId: existing.id, slug: existing.slug },
  });

  return { menu: null, purged: true };
}

/**
 * @file In-memory adapters for the `navigation` library.
 *
 * Purpose:
 * Provides the two dev/test persistence adapters this build needs:
 *
 * - `InMemoryNavLocationBindingRepo` — the real `NavLocationBindingRepoPort`
 *   adapter (`ports.ts`) for the derived `nav_location_bindings` index, honoring
 *   its `UNIQUE (workspace_id, location_key)` constraint via last-writer-wins
 *   `upsert`.
 * - `InMemoryMenuRepo` — a **self-contained** menu store. The original design is explicit
 *   that a menu "adds NO new persistence port" because it should ride the
 *   generic entries repo. That generic entries system is not yet
 *   implemented as reusable code (only `post` exists as a concrete type in the
 *   host that first built this), so this build stores menu records directly
 *   instead of force-fitting the not-yet-generic entries system. `MenuRepoPort`
 *   below is a local, navigation-owned interface (not part of the frozen
 *   `ports.ts` surface) that exists only to make this simplification
 *   swappable later without touching `menu-service.ts` call sites. When the
 *   generic entries system ships, this repo should be deleted in favor of the
 *   entries repo, and `MenuRepoPort` should be deleted in favor of typed reads
 *   over it.
 *
 * How it relates to the project:
 * - `menu-service.ts` and `resolver.ts` depend on `MenuRepoPort`, not this
 *   concrete class, so a host-supplied SQLite/entries-backed adapter is a
 *   drop-in.
 *
 * Architectural role:
 * Adapters only. No validation or business rules live here (that is
 * `menu-service.ts`'s job) — these classes are dumb, uniqueness-enforcing
 * collections.
 */
import type { UUID } from "@jini-ai/core/primitives";
import { menuVersionConflictError } from "./menu-service.js";
import type { NavLocationBindingRepoPort } from "./ports.js";
import type { NavLocationBindingRow, NavLocationKey, NavMenuEntry } from "./types.js";

// ---------------------------------------------------------------------------
// Local, navigation-owned menu repo port (deliberately NOT in ports.ts —
// see file header: menus ride the entries repo once it exists generically).
// ---------------------------------------------------------------------------

/**
 * Storage seam for menu records, standing in for the generic entries
 * repo until that generic system exists as reusable code. Shape mirrors the
 * `post` feature's own repo port plus a `remove` for hard purge, since menus
 * have a real hard-delete step in their deletion ladder (mirrors the media
 * library's).
 */
export interface MenuRepoPort {
  findById(required: { workspaceId: UUID; id: UUID }): Promise<NavMenuEntry | null>;
  findBySlug(required: { workspaceId: UUID; slug: string }): Promise<NavMenuEntry | null>;
  list(required: { workspaceId: UUID }): Promise<NavMenuEntry[]>;
  /**
   * Writes `record` by id. With `expectedVersion`, the write is a compare-and-set: it lands only when
   * the stored row is live (not `status: "trash"`) and still holds that version, checked atomically
   * with the write (one conditional UPDATE in a SQL adapter), so two writers that read the same
   * version cannot both land. With `expectedVersion: null` it is insert-if-absent (a create that
   * keeps a caller-given id, e.g. a host's id-preserving import; `INSERT ... ON CONFLICT DO NOTHING`
   * in a SQL adapter), so two creates of one id cannot both land either. Without it, the write is
   * unconditional (`createMenu`'s freshly minted id, trash seams).
   * @throws MenuVersionConflictError ``menu '<id>' was modified concurrently (expected version <n>, found <stored|none>)``,
   *         or ``menu '<id>' already exists (expected no menu, found version <n>)`` for a create
   *         ({@link menuVersionConflictError}).
   */
  save(record: NavMenuEntry, options?: MenuSaveOptions): Promise<void>;
  /** Hard-remove a menu row. Only called after the trash step. */
  remove(required: { workspaceId: UUID; id: UUID }): Promise<void>;
  /**
   * Runs `fn` as ONE unit of work: every menu save, binding write and outbox enqueue inside it commits
   * together or not at all, and a nested call joins the outer one. `assignLocation` needs it because it
   * writes two menus, then the binding: a conflict on the second menu must not leave the first one's
   * `locations` changed while the binding still points at it. A SQL adapter runs its connection's
   * transaction, and the binding repo and outbox must write through that same connection (a wiring
   * obligation of the host). A store with nothing to roll back may just call `fn` (see
   * `InMemoryMenuRepo.transaction`).
   */
  transaction<T>(required: { fn: () => Promise<T> }): Promise<T>;
}

/** Options for {@link MenuRepoPort.save}. */
export interface MenuSaveOptions {
  /** The version the caller read; the save throws `MenuVersionConflictError` unless the stored live row still holds it.
   *  `null` is a create: the save throws unless no row (live, trashed, or in another workspace) holds the id. */
  expectedVersion?: number | null | undefined;
}

/** Re-exported from here, where it has always been exported from; it lives in `menu-service.ts` so that
 *  module's own read check can throw it without a value import cycle. */
export { menuVersionConflictError };

/**
 * In-memory `MenuRepoPort` adapter for dev/tests. See file header for why a
 * self-contained repo exists instead of an entries-backed one.
 *
 * @complexity Every operation is O(n) in the workspace's menu count via a
 * linear scan; acceptable for the in-memory/dev-test adapter this library
 * builds now. A SQLite adapter would index `(workspace_id, id)` /
 * `(workspace_id, slug)` instead.
 * @overallScore 100
 */
export class InMemoryMenuRepo implements MenuRepoPort {
  private rows: NavMenuEntry[];

  constructor(requiredArgs: Record<string, never>, optionalArgs: { initialRows?: NavMenuEntry[] } = {}) {
    const { initialRows = [] } = optionalArgs;
    this.rows = [...initialRows];
  }

  async findById(required: { workspaceId: UUID; id: UUID }): Promise<NavMenuEntry | null> {
    return (
      this.rows.find(
        (row) => row.workspaceId === required.workspaceId && row.id === required.id
      ) ?? null
    );
  }

  async findBySlug(required: { workspaceId: UUID; slug: string }): Promise<NavMenuEntry | null> {
    return (
      this.rows.find(
        (row) => row.workspaceId === required.workspaceId && row.slug === required.slug
      ) ?? null
    );
  }

  async list(required: { workspaceId: UUID }): Promise<NavMenuEntry[]> {
    return this.rows.filter((row) => row.workspaceId === required.workspaceId);
  }

  async save(record: NavMenuEntry, options: MenuSaveOptions = {}): Promise<void> {
    const index = this.rows.findIndex(
      (row) => row.workspaceId === record.workspaceId && row.id === record.id
    );
    if (options.expectedVersion === null) {
      // A create needs the id free in every workspace and status, as a SQL primary key on `id` does.
      const holder = this.rows.find((row) => row.id === record.id);
      if (holder) throw menuVersionConflictError({ id: record.id, expectedVersion: null, found: holder.version });
    } else if (options.expectedVersion !== undefined) {
      const stored = this.rows[index];
      const found = stored && stored.status !== "trash" ? stored.version : null;
      if (found !== options.expectedVersion) {
        throw menuVersionConflictError({ id: record.id, expectedVersion: options.expectedVersion, found });
      }
    } else {
      // An omitted expected version selects the existing unconditional-save contract.
    }
    if (index === -1) {
      this.rows.push(record);
      return;
    }
    this.rows[index] = record;
  }

  /**
   * Just runs `fn`: nothing here rolls back, the same disclosed choice as `InMemoryEntryRepo`'s. A
   * partial write can only be left by a version conflict on a later save of the same unit, which in
   * this single-process store needs another writer to land between that unit's awaits; dev and test
   * hosts accept that, and every durable host adapter must roll back.
   * @complexity O(1) beyond `fn`.
   */
  async transaction<T>(required: { fn: () => Promise<T> }): Promise<T> {
    return required.fn();
  }

  async remove(required: { workspaceId: UUID; id: UUID }): Promise<void> {
    this.rows = this.rows.filter(
      (row) => !(row.workspaceId === required.workspaceId && row.id === required.id)
    );
  }
}

// ---------------------------------------------------------------------------
// NavLocationBindingRepoPort — the one real port this library declares
// ---------------------------------------------------------------------------

/**
 * In-memory `NavLocationBindingRepoPort` adapter for dev/tests. Enforces the
 * derived index's `UNIQUE (workspace_id, location_key)` constraint by storing
 * at most one row per `(workspaceId, locationKey)` pair: `upsert` replaces
 * whatever row previously held that key (last-writer-wins).
 *
 * @complexity O(n) linear scan per operation over the workspace's binding
 * count; `n` is bounded by the number of registered locations, which is small
 * by construction (never a user-scale collection).
 * @overallScore 100
 */
export class InMemoryNavLocationBindingRepo implements NavLocationBindingRepoPort {
  private rows: NavLocationBindingRow[];

  constructor(requiredArgs: Record<string, never>, optionalArgs: { initialRows?: NavLocationBindingRow[] } = {}) {
    const { initialRows = [] } = optionalArgs;
    this.rows = [...initialRows];
  }

  async findByLocation(required: {
    workspaceId: UUID;
    locationKey: NavLocationKey;
  }): Promise<NavLocationBindingRow | null> {
    return (
      this.rows.find(
        (row) =>
          row.workspaceId === required.workspaceId && row.locationKey === required.locationKey
      ) ?? null
    );
  }

  async listByMenu(required: {
    workspaceId: UUID;
    menuId: UUID;
  }): Promise<NavLocationBindingRow[]> {
    return this.rows.filter(
      (row) => row.workspaceId === required.workspaceId && row.menuId === required.menuId
    );
  }

  async listByWorkspace(required: { workspaceId: UUID }): Promise<NavLocationBindingRow[]> {
    return this.rows.filter((row) => row.workspaceId === required.workspaceId);
  }

  async upsert(required: {
    workspaceId: UUID;
    locationKey: NavLocationKey;
    menuId: UUID;
    boundAt: string;
  }): Promise<NavLocationBindingRow> {
    const row: NavLocationBindingRow = {
      workspaceId: required.workspaceId,
      locationKey: required.locationKey,
      menuId: required.menuId,
      boundAt: required.boundAt,
    };
    const index = this.rows.findIndex(
      (existing) =>
        existing.workspaceId === required.workspaceId &&
        existing.locationKey === required.locationKey
    );
    if (index === -1) {
      this.rows.push(row);
    } else {
      // Last-writer-wins reassignment: the UNIQUE(workspace_id, location_key)
      // constraint means there is never more than one row for this key.
      this.rows[index] = row;
    }
    return row;
  }

  async remove(required: { workspaceId: UUID; locationKey: NavLocationKey }): Promise<void> {
    this.rows = this.rows.filter(
      (row) =>
        !(row.workspaceId === required.workspaceId && row.locationKey === required.locationKey)
    );
  }

  async removeByMenu(required: { workspaceId: UUID; menuId: UUID }): Promise<void> {
    this.rows = this.rows.filter(
      (row) => !(row.workspaceId === required.workspaceId && row.menuId === required.menuId)
    );
  }

  async rebuildForWorkspace(required: {
    workspaceId: UUID;
    bindings: readonly NavLocationBindingRow[];
  }): Promise<void> {
    const others = this.rows.filter((row) => row.workspaceId !== required.workspaceId);
    this.rows = [...others, ...required.bindings];
  }
}

import type { IdGenerator } from "@jini-ai/core/primitives";
import { adaptLegacyAuthorize } from "../core/tools/index.js";
import type { Clock } from "@jini-ai/core/primitives";
/**
 * @file Navigation's (Menus') half of the agent-tool authorization wiring: maps `agent-tools.ts`'s five
 * catalog entries onto `menu-service.ts`'s read/create/update/assign operations, as
 * `ToolRegistration`s. The entire catalog is wired — `deleteMenu` is deliberately absent from the
 * catalog rather than present-but-unwired; see `navigation/agent-tools.ts`'s own header.
 *
 * Authorization shape: like Media and unlike Forms/Identity/Widgets, `menu-service.ts`'s functions
 * perform NO internal `authorize()` call of their own — every admin HTTP route a host builds gates
 * inline. Every handler here does the same via the kit's `requireToolPermission`, which is the
 * single evaluation for these tools, located where the real route locates it.
 */
import { ToolInputError } from "@jini-ai/core";
import type { AuthorizeFn } from "../core/commands/command.js";
import type { OutboxPort } from "../core/ports.js";
import { buildDomainRegistrations, indexCatalogById, requireInputRecord, requireNumber, requireString, withSchemaOnRejection, type AgentToolSideEffect, type DerivedRiskByToolId, type ToolHandler, type ToolRegistration } from "@jini-ai/core";
import { requireToolPermission } from "../core/tools/index.js";
import { menusAgentToolCatalog } from "./agent-tools.js";
import { assignLocation, createMenu, MenuNotFoundError, MenuValidationError, updateMenuTree } from "./menu-service.js";
import { isMenuHtmlAuthoring, type MenuHtmlNormalizer } from "./menu-html.js";
import type { NavLocationBindingRepoPort } from "./ports.js";
import type { MenuRepoPort } from "./repo.memory.js";
import type { NavItemNode, NavMenuEntry, NavMenuMode } from "./types.js";

const CATALOG_BY_ID = indexCatalogById({ catalog: menusAgentToolCatalog });

/**
 * The exact slice of the route-deps bag Menus' tool handlers read. Declared structurally (rather
 * than importing a host's own `RouteDeps`) so this module carries no back-edge into any host's
 * composition root. A host's `server/routes/*` satisfies this structurally by passing its existing
 * route-deps object after binding the kernel clock/ID contracts.
 */
export interface MenusToolDeps {
  /** Environment-owned fragment normalizer, forwarded to the audited menu write services. */
  normalizeMenuHtml?: MenuHtmlNormalizer | undefined;
  authorize: AuthorizeFn;
  workspaceId: string;
  clock: Clock;
  idGen: IdGenerator;
  outbox: OutboxPort;
  menuRepo: MenuRepoPort;
  navLocationBindingRepo: NavLocationBindingRepoPort;
  /**
   * The host's raw-HTML permission (host example: `pages.edit_html`, the one HTML-mode forms use). A write
   * carrying menu HTML is checked against it on top of the menu permission; unset, HTML menus are refused.
   */
  rawHtmlPermission?: string | undefined;
}

/**
 * This wiring layer's OWN risk classification, authored from what each handler below actually
 * calls. See `DerivedRiskByToolId` in the kit for why it is independent of the catalog's own
 * `sideEffects` declaration.
 */
export const menusDerivedRisk: DerivedRiskByToolId = new Map<string, AgentToolSideEffect>([
  // -> menuRepo.list: reads only.
  ["menus_list_menus", "none"],
  // -> menuRepo.findById: reads only.
  ["menus_get_menu", "none"],
  // -> createMenu (menu-service.ts): repo.save + outbox.enqueue.
  ["menus_create_menu", "mutates-durable-state"],
  // -> updateMenuTree (menu-service.ts): repo.save + outbox.enqueue.
  ["menus_update_menu_tree", "mutates-durable-state"],
  // -> assignLocation (menu-service.ts): repo.save (maybe twice, on displacement) + bindingRepo.upsert
  //    + outbox.enqueue. Never a delete: deleteMenu is deliberately not exposed (see
  //    navigation/agent-tools.ts's file header).
  ["menus_assign_location", "mutates-durable-state"],
]);

/** The only Menus rejection worth decorating with the published schema — a shape problem a different input would fix. */
function isMenusShapeRejection(error: unknown): boolean {
  return error instanceof MenuValidationError;
}

/** What a Menus tool returns to the model — see {@link toMenuToolView}. */
interface MenuToolView {
  id: string;
  slug: string;
  title: string;
  status: NavMenuEntry["status"];
  items: NavItemNode[];
  mode?: NavMenuMode | undefined;
  html?: string | undefined;
  locations: string[];
  version: number;
}

/**
 * Projects a `NavMenuEntry` into an explicit model-facing shape rather than returning the domain
 * record verbatim — the same discipline Forms' `toFormDefinitionView` applies. `items` is
 * deep-cloned via a JSON round-trip (the tree is JSON-serializable by construction, `types.ts`'s
 * `NavMenuDoc` doc comment) rather than shallow-copied, since a tool caller pushing onto a nested
 * `children` array must not be able to mutate domain state through the returned view the way a
 * single top-level spread could not protect against.
 */
function toMenuToolView(menu: NavMenuEntry): MenuToolView {
  return {
    id: menu.id,
    slug: menu.slug,
    title: menu.title,
    status: menu.status,
    items: JSON.parse(JSON.stringify(menu.doc.items)) as NavItemNode[],
    ...(menu.doc.mode !== undefined ? { mode: menu.doc.mode } : {}),
    ...(menu.doc.html !== undefined ? { html: menu.doc.html } : {}),
    locations: [...menu.locations],
    version: menu.version,
  };
}

/** A write's HTML-mode fields as sent; `menu-service.ts` validates their values. */
function htmlAuthoring(input: Record<string, unknown>): { mode?: NavMenuMode; html?: string } {
  return {
    ...(input.mode !== undefined ? { mode: input.mode as NavMenuMode } : {}),
    ...(input.html !== undefined ? { html: input.html as string } : {}),
  };
}

/**
 * Raw HTML is the host's trust boundary (HTML Pages, HTML-mode forms), so a write that authors menu
 * HTML also needs that permission. Checked before the write, like forms' `prepareFormAuthoring`.
 */
async function requireHtmlAuthoringPermission(
  { routeDeps, principalId, authoring, menuId }: { routeDeps: MenusToolDeps; principalId: string; authoring: { mode?: NavMenuMode; html?: string }; menuId?: string },
): Promise<void> {
  if (!isMenuHtmlAuthoring(authoring)) return;
  if (!routeDeps.rawHtmlPermission) throw new ToolInputError({ message: "HTML menus are not enabled on this site" });
  await requireToolPermission({ authorize: adaptLegacyAuthorize({ authorize: routeDeps.authorize }), workspaceId: routeDeps.workspaceId, principalId, permission: routeDeps.rawHtmlPermission }, { entityType: "menu", ...(menuId ? { entityId: menuId } : {}) });
}

function menusDeps(routeDeps: MenusToolDeps) {
  return { repo: routeDeps.menuRepo, clock: routeDeps.clock, idGen: routeDeps.idGen, outbox: routeDeps.outbox, normalizeMenuHtml: routeDeps.normalizeMenuHtml };
}

/**
 * Normalize the update target's legacy menuId to id before the executor's schema/policy gates.
 * Retain menuId for 90 days from the coordinated release, including the key spellings the shared
 * normalizer previously accepted. Read selectors and assignment references keep their own ABI.
 * Direct handler callers use this same adapter to retain their legacy input contract.
 * @returns Canonical input and value-free rewrite notes; never mutates the caller's record.
 * @throws {ToolInputError} If more than one spelling supplies the update target, even if equal.
 * @complexity O(k) time and space for k top-level input keys; no I/O.
 */
function normalizeMenuUpdateInput(
  { input }: { input: Readonly<Record<string, unknown>> },
  _options: Record<string, never> = {},
): { input: Readonly<Record<string, unknown>>; notes: readonly string[] } {
  const aliases = Object.keys(input).filter((key) => key.replace(/[_-]/g, "").toLowerCase() === "menuid");
  const alias = aliases[0];
  if (alias === undefined) return { input, notes: [] };
  if (Object.hasOwn(input, "id") || aliases.length > 1) {
    throw new ToolInputError({ message: "Conflicting inputs for the menu target. Send only 'id', not multiple id/menuId spellings." });
  }
  const { [alias]: menuId, ...rest } = input;
  return { input: { ...rest, id: menuId }, notes: [`${alias}→id`] };
}

export function buildMenusRegistrations(routeDeps: MenusToolDeps): ToolRegistration[] {
  const handlers: Record<string, ToolHandler> = {
    menus_list_menus: async (ctx) => {
      await requireToolPermission({ authorize: adaptLegacyAuthorize({ authorize: routeDeps.authorize }), workspaceId: routeDeps.workspaceId, principalId: ctx.principal.id, permission: "admin.menus.read" }, { entityType: "menu" });
      const menus = await routeDeps.menuRepo.list({ workspaceId: routeDeps.workspaceId });
      return { menus: menus.map(toMenuToolView) };
    },

    menus_get_menu: async (ctx) => {
      const menuId = requireString({ input: requireInputRecord({ input: ctx.input }), key: "menuId" });
      await requireToolPermission({ authorize: adaptLegacyAuthorize({ authorize: routeDeps.authorize }), workspaceId: routeDeps.workspaceId, principalId: ctx.principal.id, permission: "admin.menus.read" }, { entityType: "menu", entityId: menuId });
      const menu = await routeDeps.menuRepo.findById({ workspaceId: routeDeps.workspaceId, id: menuId });
      if (!menu) throw new MenuNotFoundError({ message: `menu '${menuId}' was not found` });
      return { menu: toMenuToolView(menu) };
    },

    menus_create_menu: async (ctx) => {
      const input = requireInputRecord({ input: ctx.input });
      await requireToolPermission({ authorize: adaptLegacyAuthorize({ authorize: routeDeps.authorize }), workspaceId: routeDeps.workspaceId, principalId: ctx.principal.id, permission: "admin.menus.create" }, { entityType: "menu" });
      if (input.items !== undefined && !Array.isArray(input.items)) {
        throw new ToolInputError({ message: "'items' must be an array of nav items" });
      }
      const authoring = htmlAuthoring(input);
      await requireHtmlAuthoringPermission({ routeDeps, principalId: ctx.principal.id, authoring });
      return withSchemaOnRejection({ toolId: "menus_create_menu", catalog: CATALOG_BY_ID, isShapeRejection: ({ error }) => isMenusShapeRejection(error), fn: async () => {
        const { menu } = await createMenu({
          deps: menusDeps(routeDeps),
          input: {
            workspaceId: routeDeps.workspaceId,
            title: requireString({ input: input, key: "title" }),
            slug: requireString({ input: input, key: "slug" }),
            items: Array.isArray(input.items) ? (input.items as NavItemNode[]) : undefined,
            ...authoring,
          },
        });
        return { menu: toMenuToolView(menu) };
      } });
    },

    menus_update_menu_tree: async (ctx) => {
      const { input } = normalizeMenuUpdateInput({ input: requireInputRecord({ input: ctx.input }) });
      const menuId = requireString({ input: input, key: "id" });
      await requireToolPermission({ authorize: adaptLegacyAuthorize({ authorize: routeDeps.authorize }), workspaceId: routeDeps.workspaceId, principalId: ctx.principal.id, permission: "admin.menus.update" }, { entityType: "menu", entityId: menuId });
      const authoring = htmlAuthoring(input);
      if (input.items === undefined && authoring.mode === undefined && authoring.html === undefined) {
        throw new Error("'items' (array), 'html' or 'mode' is required");
      }
      if (input.items !== undefined && !Array.isArray(input.items)) throw new Error("'items' must be an array of nav items");
      await requireHtmlAuthoringPermission({ routeDeps, principalId: ctx.principal.id, authoring, menuId });
      return withSchemaOnRejection({ toolId: "menus_update_menu_tree", catalog: CATALOG_BY_ID, isShapeRejection: ({ error }) => isMenusShapeRejection(error), fn: async () => {
        const { menu } = await updateMenuTree({
          deps: menusDeps(routeDeps),
          input: {
            workspaceId: routeDeps.workspaceId,
            id: menuId,
            expectedVersion: requireNumber({ input: input, key: "expectedVersion" }),
            title: typeof input.title === "string" ? input.title : undefined,
            slug: typeof input.slug === "string" ? input.slug : undefined,
            items: input.items as NavItemNode[] | undefined,
            ...authoring,
          },
        });
        return { menu: toMenuToolView(menu) };
      } });
    },

    menus_assign_location: async (ctx) => {
      const input = requireInputRecord({ input: ctx.input });
      const menuId = requireString({ input: input, key: "menuId" });
      await requireToolPermission({ authorize: adaptLegacyAuthorize({ authorize: routeDeps.authorize }), workspaceId: routeDeps.workspaceId, principalId: ctx.principal.id, permission: "admin.menus.assign" }, { entityType: "menu", entityId: menuId });
      const { menu, binding, displacedMenu } = await assignLocation({
        deps: { ...menusDeps(routeDeps), bindingRepo: routeDeps.navLocationBindingRepo },
        input: { workspaceId: routeDeps.workspaceId, menuId, locationKey: requireString({ input: input, key: "locationKey" }) },
      });
      return {
        menu: toMenuToolView(menu),
        binding: { locationKey: binding.locationKey, menuId: binding.menuId },
        displacedMenu: displacedMenu ? toMenuToolView(displacedMenu) : null,
      };
    },
  };

  // No `unwiredToolIds`: Menus wires its ENTIRE catalog, same tripwire discipline as Forms.
  return buildDomainRegistrations({
    domain: "menus",
    catalogModule: "navigation/agent-tools.ts",
    catalog: CATALOG_BY_ID,
    handlers,
    inputNormalizers: { menus_update_menu_tree: normalizeMenuUpdateInput },
    derivedRisk: menusDerivedRisk,
  });
}

/**
 * @file Core type definitions for the `navigation` library.
 *
 * Purpose:
 * Menus/nav are **navigation trees as editable content**. A menu is a generic
 * content entry (type `menu`); its ordered, nested item tree lives in the
 * entry's validated `bodyJson` as a `navigation`-namespaced block vocabulary.
 * Link targets that point at other content (entries, taxonomy terms) are `ref`
 * values so the write-chokepoint extracts them into the rebuildable
 * `entry_refs` index (where-used + safe-delete), exactly as the media library reuses it
 * for media. External URLs and named routes carry no ref.
 *
 * How it relates to the project:
 * - `core/ports.ts` supplies the shared primitives (`UUID`, `JsonObject`, …).
 * - `navigation/ports.ts` declares the one rule-of-two port this library adds
 *   (`NavLocationBindingRepoPort`) plus the typed-call resolver contract.
 * - The theme renderer consumes `ResolvedNav` (data only — no theme code
 *   resolves refs; the render-IR boundary).
 *
 * Architectural role:
 * INTERFACES + TYPES ONLY (no feature logic). This is the design-frozen shape
 * this library introduces; the entries repo, revisions, `entry_refs`, and the command
 * gateway are reused unchanged from the generic entries model.
 */
import type { ISODateTime, JsonObject, UUID } from "@jini-ai/core/primitives";

// ---------------------------------------------------------------------------
// Content-type identity
// ---------------------------------------------------------------------------

/**
 * `menu` ships as a **seeded content-type registry row**, like
 * `post`/`page`/`media`. Core may special-case it in admin UI/rendering, never
 * in storage. The extension-field owner namespace for menu-level fields
 * (`fields.ext.navigation.*`) is `navigation`.
 */
export const NAV_MENU_CONTENT_TYPE = "menu" as const;
export const NAV_FIELD_NAMESPACE = "navigation" as const;

/** Discriminator marking an entry's `bodyJson` as a navigation tree document. */
export const NAV_DOC_TYPE = "menu" as const;

// ---------------------------------------------------------------------------
// Link targets
// ---------------------------------------------------------------------------

/**
 * The v1 link-target kinds. `entryRef`/`termRef` are integrity-tracked (their
 * ids are extracted to `entry_refs`); `url`/`route` are validated-only.
 */
export type NavTargetKind = "entryRef" | "termRef" | "url" | "route";

/**
 * Reserved-but-rejected target kinds — the named deferred seams.
 * Recognized by the validator and **rejected with a clear "coming later" error**
 * until their resolver stage ships, so the discriminant never has to widen in a
 * breaking way. `dynamicQuery` needs a total/bounded expression
 * language; `content` needs a mega-menu block-embed resolver.
 */
export type ReservedNavTargetKind = "dynamicQuery" | "content";

/** A link to another content entry (page/post/media/…). Integrity-tracked. */
export interface NavEntryTarget {
  readonly kind: "entryRef";
  /** Optional content-type hint for editors; reference integrity and routing still use entryId. */
  readonly entryType?: string;
  /** Author's last known URL, retained for exports and routing misses. A known unavailable
   * entry must remain hidden; this snapshot never overrides an availability decision. */
  readonly lastKnownHref?: string;
  /** Target entry id. Extracted to `entry_refs` at the write chokepoint. */
  readonly entryId: UUID;
}

/** A link to a taxonomy term (category/tag archive). Integrity-tracked. */
export interface NavTermTarget {
  readonly kind: "termRef";
  /** Target term id. Extracted to `entry_refs` (target kind = term). */
  readonly termId: UUID;
  /** Taxonomy the term belongs to, for archive-route resolution. */
  readonly taxonomy: string;
}

/** An absolute or site-relative external URL. Validated, not ref-tracked. */
export interface NavUrlTarget {
  readonly kind: "url";
  /** Sanitized/validated at write time (scheme allowlist, no `javascript:`). */
  readonly href: string;
}

/** A named core route (e.g. `home`, `search`), resolved by the routing lib. */
export interface NavRouteTarget {
  readonly kind: "route";
  readonly route: string;
  /** Optional static params passed to the route resolver. */
  readonly params?: JsonObject | undefined;
}

/** v1 discriminated union of link targets. */
export type NavTarget = NavEntryTarget | NavTermTarget | NavUrlTarget | NavRouteTarget;

// ---------------------------------------------------------------------------
// The stored item tree (lives in entry `bodyJson`)
// ---------------------------------------------------------------------------

/**
 * Presentational attributes carried on an item, kept separate from identity and
 * target so the render model can pass them through without interpreting them.
 */
export interface NavItemAttrs {
  readonly openInNewTab?: boolean | undefined;
  /** `rel` tokens (e.g. `nofollow`), validated against an allowlist. */
  readonly rel?: string | undefined;
  /** Theme-facing CSS class hint. */
  readonly cssClass?: string | undefined;
  /** Optional description/subtitle (mega-menu-adjacent, cosmetic in v1). */
  readonly description?: string | undefined;
  /** Icon token resolved by the theme's icon set, if any. */
  readonly icon?: string | undefined;
}

/**
 * One node in the menu tree. **Ordering = array order** among siblings;
 * **nesting = `children`**. `id` is a **stable ULID minted on item creation and
 * preserved across edits/moves** (never regenerated on reorder) — the stable
 * identity `entry_refs` locators and per-item caches depend on (a discipline
 * discipline applied within the doc). The chokepoint validator enforces id
 * stability and bounded depth/breadth.
 */
export interface NavItemNode {
  readonly id: UUID;
  /** Editable display label. Falls back to the target's title when absent. */
  readonly label?: string | undefined;
  readonly target: NavTarget;
  readonly attrs?: NavItemAttrs | undefined;
  /** Child items (one level of nesting per depth). */
  readonly children?: readonly NavItemNode[] | undefined;
}

/**
 * The full navigation document stored in a menu entry's `bodyJson`. Shaped so it
 * satisfies `JsonObject` structurally (all fields are JSON-serializable), which
 * keeps it inside the storage contract and the serializable
 * ABI.
 */
export interface NavMenuDoc {
  readonly type: typeof NAV_DOC_TYPE;
  /** Doc-schema version, so the validator can migrate shapes later. */
  readonly version: number;
  readonly items: readonly NavItemNode[];
  /** What renders at the menu's marker; absent means `"items"`. See `menu-html.ts`. */
  readonly mode?: NavMenuMode | undefined;
  /** Author-written HTML for `"html"` mode, kept even while the menu renders its items. */
  readonly html?: string | undefined;
}

/** `"items"` renders the item tree; `"html"` renders the author's own markup (`menu-html.ts`). */
export type NavMenuMode = "items" | "html";

// ---------------------------------------------------------------------------
// The menu read model (a typed view over the generic entries row)
// ---------------------------------------------------------------------------

export type MenuStatus = "draft" | "published" | "trash";

/**
 * A typed read model over a `type='menu'` entries row (universal
 * columns) plus the parsed `bodyJson` tree and the `navigation`-namespaced
 * fields. This is a **projection**, not a new table — menus are entries.
 */
export interface NavMenuEntry {
  readonly id: UUID;
  readonly workspaceId: UUID;
  /** Stable machine handle, e.g. `primary-nav` (the entry `slug`). */
  readonly slug: string;
  /** Human menu name (the entry `title`). */
  readonly title: string;
  readonly status: MenuStatus;
  /** The parsed navigation tree (entry `bodyJson`). */
  readonly doc: NavMenuDoc;
  /**
   * Theme-location keys this menu is assigned to fill
   * (`fields.ext.navigation.locations`). Source of truth for assignment;
   * the binding index (below) is the derived, uniqueness-enforcing projection.
   */
  readonly locations: readonly string[];
  readonly updatedAt: ISODateTime;
  readonly version: number;
}

// ---------------------------------------------------------------------------
// Location binding index (derived, rebuildable — the one new core table)
// ---------------------------------------------------------------------------

/** A theme-registered location key (e.g. `primary`, `footer`, `social`). */
export type NavLocationKey = string;

/**
 * A row of the derived `nav_location_bindings` index.
 * **Derived + rebuildable** from `NavMenuEntry.locations` at the write
 * chokepoint (same species as `entry_refs`), NOT a source of truth
 * and NOT revision-generating. Its purpose is a single indexed location→menu
 * lookup at render time and a **`UNIQUE (workspace_id, location_key)`**
 * constraint that enforces *exactly one menu per location* — an invariant a
 * per-entry JSON field cannot express.
 */
export interface NavLocationBindingRow {
  readonly workspaceId: UUID;
  readonly locationKey: NavLocationKey;
  /** The menu entry currently bound to this location. */
  readonly menuId: UUID;
  /** When the binding was last (re)assigned; for audit/debug only. */
  readonly boundAt: ISODateTime;
}

/**
 * A theme/plugin-registered navigation location (registered via
 * `navigation.locations.register`). Registration is data; a menu may be bound to
 * an **unregistered** key so assignments survive a theme switch (fixes WP's
 * "lose your menus on theme change" sin).
 */
export interface NavLocationDescriptor {
  readonly key: NavLocationKey;
  /** Admin-facing label. */
  readonly label: string;
  /** Which theme/plugin registered it (attribution + orphan detection). */
  readonly registeredBy: string;
  readonly description?: string | undefined;
}

// ---------------------------------------------------------------------------
// The resolved render model (data handed to themes)
// ---------------------------------------------------------------------------

/**
 * A single item after resolution: target → concrete `href` + display `label` +
 * `isActive`/`isCurrent` computed against the current route. Refs are resolved
 * by core (routing/entries/taxonomy), never by theme code. Items whose target
 * has been trashed/deleted are resolved to `available: false` so the theme can
 * omit them rather than emit a dead link.
 */
export interface ResolvedNavItem {
  readonly id: UUID;
  readonly label: string;
  /** Fully-resolved href, or `null` when the target is unavailable. */
  readonly href: string | null;
  readonly available: boolean;
  /** True when this item's href matches the current route. */
  readonly isCurrent: boolean;
  /** True when this or a descendant is current (for open/expanded state). */
  readonly isActive: boolean;
  readonly attrs?: NavItemAttrs | undefined;
  readonly children: readonly ResolvedNavItem[];
}

/** A fully-resolved menu ready for a theme to render at a location. */
export interface ResolvedNav {
  readonly menuId: UUID;
  readonly locationKey: NavLocationKey;
  readonly title: string;
  readonly items: readonly ResolvedNavItem[];
}

/**
 * @file Port + seam contracts for the `redirects` Tier-2 library (ADR-033).
 *
 * ADR-006 accounting (rule-of-two):
 * - `RedirectRepoPort` is a genuine port — it rides the ADR-015 seam with two
 *   adapters built now (in-memory for tests + Drizzle/SQLite for persistence),
 *   matching every other feature in `src/features/*`.
 * - `RedirectMatcher` and `RedirectHitSink` are declared here as ordinary
 *   INTERNAL SEAMS, not ADR-006 ports. Neither has a second adapter under
 *   construction today: the matcher's plausible-second is an edge/CDN compiler
 *   (emit an nginx `map` / Cloudflare ruleset), the hit sink's is an external
 *   analytics store — both real, neither built now. Per ADR-006 they stay
 *   ordinary code with a documented seam, promoted to a port the day the second
 *   adapter is real. They are typed as interfaces purely for testability.
 *
 * Architectural role:
 * INTERFACES ONLY — no feature logic.
 *
 * Grounding: ADR-006 (rule-of-two), ADR-015 (repo behind a port), ADR-009
 * (typed calls / outbox / hooks), ADR-022 (chokepoint writes record a revision
 * in the same tx; bounded matching = the totality/bounded-cost trust primitive),
 * ADR-021 (permission strings enforced by the calling gateway, not the repo).
 */
import type { ISODateTime, UUID } from "@jini-ai/core/primitives";
import type { RedirectLocationRefusalReason } from "./target-gate.js";
import type { DomainEvent } from "../core/index.js";
import type {
  ListRedirectsFilter,
  RedirectHitStats,
  RedirectRecord,
  RedirectRequest,
  RedirectResolution,
  RedirectRevision,
} from "./types.js";

/**
 * Persistence port for redirect rules + their revision ledger + tombstones.
 * The single write chokepoint (ADR-022 §4a): `save` MUST persist the record and
 * its {@link RedirectRevision} in one transaction; no other module writes the
 * `redirects` / `redirect_revisions` tables (CI import-graph canary, ADR-027
 * precedent).
 */
export interface RedirectRepoPort {
  findById(required: { workspaceId: UUID; id: UUID }, optional?: Record<string, never>): Promise<RedirectRecord | null>;

  /** Index-backed O(1) exact-path lookup (active rules only). */
  lookupExact(required: {
    workspaceId: UUID;
    path: string;
    includeOverrideOnly: boolean;
  }, optional?: Record<string, never>): Promise<RedirectRecord | null>;

  /** Longest-prefix match over active `prefix` rules (index/trie-backed). */
  lookupLongestPrefix(required: {
    workspaceId: UUID;
    path: string;
    includeOverrideOnly: boolean;
  }, optional?: Record<string, never>): Promise<RedirectRecord | null>;

  /**
   * The bounded "dynamic" set: active `wildcard` + `regex` rules in evaluation
   * order (specificity → priority → recency). Returned capped; callers evaluate
   * them through {@link RedirectMatcher} only after exact/prefix miss.
   */
  listDynamic(required: {
    workspaceId: UUID;
    includeOverrideOnly: boolean;
    limit: number;
  }, optional?: Record<string, never>): Promise<RedirectRecord[]>;

  list(filter: ListRedirectsFilter, optional?: Record<string, never>): Promise<RedirectRecord[]>;

  /**
   * Resolve where an existing rule with the given `fromPattern` already points,
   * used at write time for cycle detection + chain collapsing (ADR-033 §6).
   */
  findByFromPattern(required: {
    workspaceId: UUID;
    fromPattern: string;
  }, optional?: Record<string, never>): Promise<RedirectRecord | null>;

  /** Chokepoint write: upsert the record and append its revision in one tx. */
  save(required: { record: RedirectRecord; revision: RedirectRevision }, optional?: Record<string, never>): Promise<void>;

  /** Tombstone (soft-delete): flip status + append a tombstone revision in one tx. */
  tombstone(required: { workspaceId: UUID; id: UUID; revision: RedirectRevision }, optional?: Record<string, never>): Promise<void>;
}

/**
 * INTERNAL SEAM (not an ADR-006 port). Pure, bounded matching of a request
 * against the dynamic rule set. Implementations MUST be total and
 * bounded-cost — linear-time / RE2 semantics, an anchored pattern, and a
 * per-request evaluation cap — because this is the request-hot-path expression
 * evaluator ADR-022's amendment designates a trust-boundary primitive. No
 * backtracking regex engine may back this.
 */
export interface RedirectMatcher {
  /**
   * Return the first matching rule with captures interpolated into `location`,
   * or `{ matched: false }`. `rules` is the already-ordered, already-capped
   * dynamic set from {@link RedirectRepoPort.listDynamic}.
   */
  match(required: {
    request: RedirectRequest;
    rules: RedirectRecord[];
  }, optional?: Record<string, never>): RedirectResolution;

  /**
   * Compile-time validation of a single pattern (called at the write
   * chokepoint): rejects unbounded/backtracking constructs before a rule is
   * ever stored, so an unsafe pattern cannot reach the hot path.
   */
  validatePattern(required: {
    matchType: RedirectRecord["matchType"];
    fromPattern: string;
  }, optional?: Record<string, never>): { ok: true } | { ok: false; reason: string };
}

/**
 * INTERNAL SEAM (not an ADR-006 port). Best-effort, off-hot-path hit
 * aggregation. The resolver emits a {@link RedirectHitEvent} via the outbox
 * (ADR-009 async lane); an idempotent handler folds it into the
 * `redirect_hits` sidecar through this sink. A dropped increment loses a
 * statistic, never a redirect.
 */
export interface RedirectHitSink {
  record(required: { workspaceId: UUID; redirectId: UUID; at: ISODateTime }, optional?: Record<string, never>): Promise<void>;
  getStats(required: { workspaceId: UUID; redirectId: UUID }, optional?: Record<string, never>): Promise<RedirectHitStats | null>;
  listStats(required: { workspaceId: UUID }, optional?: Record<string, never>): Promise<RedirectHitStats[]>;
}

/**
 * Application service consulted by the routing resolution chain. It is invoked
 * twice per request lifecycle: `pre_content` (override rules only) and
 * `post_content` (the 404-fill pass). The exact registration contract with the
 * (not-yet-designed) `routing` library is OWED by the future routing ADR —
 * ADR-033 §4 specifies the redirects side and flags the seam as co-dependent.
 */
export interface RedirectResolver {
  resolve(request: RedirectRequest, optional?: Record<string, never>): Promise<RedirectResolution>;
}

/* ------------------------------------------------------------------ *
 * Events (ADR-009 lane 2 — outbox, async) + Hooks (lane 3 — sync)     *
 * ------------------------------------------------------------------ */

export interface RedirectMutatedEventPayload {
  workspaceId: UUID;
  redirectId: UUID;
  change: "created" | "updated" | "tombstoned";
}
export type RedirectMutatedEvent = DomainEvent<RedirectMutatedEventPayload>;

export interface RedirectHitEventPayload {
  workspaceId: UUID;
  redirectId: UUID;
  at: ISODateTime;
}
export type RedirectHitEvent = DomainEvent<RedirectHitEventPayload>;

/**
 * Sync filter hook (ADR-009 lane 3): lets a plugin transform or short-circuit a
 * resolution — e.g. an i18n plugin rewriting the target per locale, or an SEO
 * plugin adding canonicalization. Declared-before-attached; ordered by explicit
 * priority. Conditional (geo/device/auth) redirects are the named v1-deferred
 * feature that lands ON this hook, not in core.
 */
export interface RedirectResolveHookContext {
  request: RedirectRequest;
  /** The resolution core computed; the hook returns it unchanged or replaces it. */
  resolution: RedirectResolution;
}
export type RedirectResolveHook = (
  ctx: RedirectResolveHookContext
) => RedirectResolution | Promise<RedirectResolution>;

// Structural host routing contracts: no dependency on a product routing registry.
export interface RouteResolveContext {
  readonly workspaceId: UUID;
  readonly siteId?: string;
  readonly locale?: string;
  readonly originKey?: string;
  /**
   * TODO(ADR-040): compose canonicalUrl from OriginRegistryPort.canonicalOrigin(ctx)
   * once src/origin exists. Until then, a caller that knows the verified origin
   * may pass it here; absent, canonicalUrl falls back to the relative path.
   */
  readonly originOverride?: string;
}

/** Terminal decision a phase resolver may return; anything else falls through. */
export type RouteResolvePhaseOutcome =
  | { readonly kind: "redirect"; readonly location: string; readonly statusCode: number }
  | { readonly kind: "resolved"; readonly path: string }
  | { readonly kind: "not_found" };

/** Payload handed to the bound {@link SlugChangeCapture} inside the rename transaction. */
export interface SlugChangeCaptureInput {
  readonly workspaceId: UUID;
  readonly entryId: UUID;
  readonly oldPath: string;
  readonly newPath: string;
  readonly actor: UUID;
  readonly changeSetId?: UUID;
}

/**
 * The single named slot content's write chokepoint calls inside the rename
 * transaction (ADR-039 §4). Declared here by routing (content knows nothing of
 * redirects); implemented by the redirects library; wired by the composition
 * root. **No slot implementation may be plugin-supplied** (Round-2 amendment 1
 * — the slot is core-resident by definition).
 *
 * Constraints on any bound implementation (Round-2 amendment 2): idempotent by
 * `changeSetId`, no external I/O, no in-tx publish (an outbox row may be
 * written in-tx per the transactional-outbox pattern, but dispatch happens
 * post-commit), and a strict lock order of content row before redirect rows.
 *
 * Fail-closed nuance (Round-2 amendment 3, not enforced by this library):
 * absent binding is a no-op only before Redirects is installed, or while
 * slug-preservation is disabled for the workspace. Once link-preservation is
 * enabled, a slug-changing rename with no bound capture MUST fail
 * `LINK_PRESERVATION_UNAVAILABLE` rather than silently skip the redirect. That
 * enforcement belongs to the content write chokepoint (which knows whether
 * preservation is enabled) and to Redirects (which doesn't exist yet in this
 * repo) — this library only exposes the registration slot.
 */
export interface SlugChangeCapture {
  onSlugChange(input: SlugChangeCaptureInput, optional?: Record<string, never>): Promise<void>;
}

/** Refusal evidence never exposes a redirect that bypassed the INV-03 gate. */
export interface RedirectRefusal {
  redirectId: UUID;
  location: string;
  reason: RedirectLocationRefusalReason;
}
export interface RedirectResolutionReport {
  resolution: RedirectResolution;
  refused: RedirectRefusal[];
}
/** The legacy resolver plus refusal evidence for adapters that must report declines. */
export interface RedirectResolverWithRefusals extends RedirectResolver {
  resolveWithRefusals(request: RedirectRequest, optional?: Record<string, never>): Promise<RedirectResolutionReport>;
}

import { nowIso as clockNowIso } from "@jini-ai/core/primitives";
/**
 * @file THE `redirects` write chokepoint (SPEC-009 REQ-01/04/05/06/07/08/13/
 * 14/22/26; ADR-PIPE-009 C-001..C-004).
 *
 * Purpose:
 * `createRedirect`/`updateRedirect`/`tombstoneRedirect`/`importRedirects` —
 * the single manual-write entry point for redirect rules. Validates the
 * pattern (via `RedirectMatcher.validatePattern`), rejects unsafe targets —
 * absolute ones against the origin allowlist and site-relative ones against
 * the admin application's own URL space (write-path open-redirect oracle,
 * REQ-08; see `assertTargetAllowed`) — collapses/rejects
 * one-hop chains (INV-04), enforces the exact-match dedup rule
 * (behavior.spec.md §5.1), and writes the record + its revision in one
 * transaction via `ports.internal.ts`'s shared `insertRedirectAndRevision`
 * (INV-01/INV-07 — no other file writes `redirects`/`redirect_revisions`).
 *
 * Architectural role:
 * Feature logic. No Express/route code — route handlers (Phase 2) call these
 * functions directly and map thrown typed errors to HTTP codes per
 * errors.spec.md.
 */
import { type Clock as ClockPort, type IdGenerator as IdGeneratorPort } from "@jini-ai/core/primitives";
import { assertEntityLive, type DomainEvent, type OutboxPort } from "../core/index.js";
import { callerSafeErrorMessage, type CallerSafeErrorRule } from "@jini-ai/core/model-facing-tool-errors";
import { hasForbiddenRawUrlCharacter } from "@jini-ai/http-kit/verified-origin";
import type { OriginRegistryPort, RedirectTargetContext } from "@jini-ai/http-kit/verified-origin";

import { checkSiteRelativeTarget } from "@jini-ai/http-kit/verified-origin";
import type { SiteRelativeTargetCheck } from "@jini-ai/http-kit/verified-origin";

import { insertRedirectAndRevision, type RedirectDbHandle } from "./ports.internal.js";
import type { RedirectMatcher, RedirectMutatedEvent, RedirectRepoPort } from "./ports.js";
import { isReferrerAliasLocation } from "./referrer-alias.js";
import { checkSameOriginDestination } from "./reserved-destination.js";
import {
  RedirectConflictError,
  RedirectLoopError,
  RedirectNotFoundError,
  RedirectTargetNotAllowedError,
  RedirectValidationError,
} from "./types.js";
import type {
  CreateRedirectInput,
  ListRedirectsFilter,
  RedirectMatchType,
  RedirectRecord,
  RedirectRevision,
  RedirectStatus,
  RedirectStatusCode,
  UpdateRedirectInput,
} from "./types.js";

// Exported (unchanged values) so `agent-tools.ts`'s published JSON Schema can reuse the exact
// bounds this chokepoint validates against, rather than restating them — same discipline as
// `seo/write-service.ts`'s identical export note.
export const MIN_TARGET_LENGTH = 1;
export const MAX_TARGET_LENGTH = 2048;
export const MIN_PRIORITY = 0;
export const MAX_PRIORITY = 1000;
const DEFAULT_PRIORITY = 0;
export const VALID_STATUS_CODES: readonly RedirectStatusCode[] = [301, 302, 307, 308];
const VALID_STATUSES: readonly RedirectStatus[] = ["active", "disabled"];
export const MAX_IMPORT_BATCH_SIZE = 500;

function isAbsoluteOrProtocolRelative(target: string): boolean {
  return target.startsWith("//") || /^[a-z][a-z0-9+.-]*:/i.test(target);
}

/**
 * The removal primitive this domain is handed, rather than one it implements.
 *
 * Structurally typed ON PURPOSE — `features/redirects` imports nothing from `features/trash`, and
 * must not. The composition root binds the real implementation (marker flip AND Trash index row, in
 * one transaction) pre-bound to this domain's entity type. `display` is required so the two strings
 * the Trash screen shows come from columns the caller already holds.
 */
export type RemoveRedirectFn = (required: {
  workspaceId: string;
  id: string;
  display: { title: string; subtitle?: string | null };
  at: string;
  expectedVersion: number | null;
  actor: { principalId: string; pluginId?: string | null };
}) => Promise<{ ok: true; version: number | null } | { ok: false; reason: "not-found" | "version-changed" }>;

export interface RedirectsWriteDeps {
  repo: RedirectRepoPort;
  /** See {@link RemoveRedirectFn}. Replaces `tombstoneRedirect`'s own `status` write. */
  remove: RemoveRedirectFn;
  /**
   * Whether this rule has a Trash index row (S7, web-high fix plan 2026-09-24) — the thing
   * `tombstoneRedirect` creates and Trash restore/purge match on, and NOT the same thing as
   * `status === "disabled"` (an ordinary toggle-off has no Trash row at all). Structurally typed,
   * same discipline as {@link RemoveRedirectFn}: this domain imports nothing from `features/trash`.
   */
  isInTrash: (required: { workspaceId: string; id: string }) => Promise<boolean>;
  /**
   * Un-trashes this rule (S7). Mirrors `TrashPort.restore`'s outcome union structurally, again
   * without importing `features/trash`. `"adapter-unavailable"` is not reachable for redirects (the
   * composition root always registers an adapter for `REDIRECT_ENTITY_TYPE`), but is part of the
   * union it mirrors.
   */
  restore: (required: {
    workspaceId: string;
    id: string;
    at: string;
    actor: { principalId: string; pluginId?: string | null };
  }) => Promise<"restored" | "not-found" | "version-changed" | "adapter-unavailable">;
  /** The shared, non-tx-opening write handle (Decision A) — used via `ports.internal.ts`. */
  db: RedirectDbHandle;
  /** Opens/commits/rolls back the chokepoint's own transaction around a write. */
  transaction: <T>(fn: () => Promise<T>) => Promise<T>;
  matcher: RedirectMatcher;
  originRegistry: OriginRegistryPort;
  /** First path segments reserved by the composing host; no product-policy default. */
  reservedSegments: ReadonlySet<string>;
  clock: ClockPort;
  idGen: IdGeneratorPort;
  outbox: OutboxPort;
}

function validateStatusCode(statusCode: RedirectStatusCode): void {
  if (!VALID_STATUS_CODES.includes(statusCode)) {
    throw new RedirectValidationError(`statusCode must be one of ${VALID_STATUS_CODES.join(", ")}`);
  }
}

/**
 * `RedirectStatus`'s union isn't enforced at the HTTP boundary — the admin PATCH route
 * (`routes/redirects/update.ts`) passes `body.status` straight through as a cast, so a
 * non-canonical spelling (`"Disabled"`, `"ACTIVE"`, `""`) would otherwise be stored as-is. Both
 * repo backends read only `status === "active"` rows, so a garbage value fails closed for
 * matching — but it also misses {@link isDisableOnlyUpdate}'s exact-string fast path, silently
 * routing that PATCH through the full field re-validation instead of the disable-only skip.
 */
function validateStatus(status: RedirectStatus): void {
  if (!VALID_STATUSES.includes(status)) {
    throw new RedirectValidationError(`status must be one of ${VALID_STATUSES.join(", ")}`);
  }
}

function validateToTargetLength(toTarget: string): void {
  if (toTarget.length < MIN_TARGET_LENGTH || toTarget.length > MAX_TARGET_LENGTH) {
    throw new RedirectValidationError(
      `toTarget must be ${MIN_TARGET_LENGTH}-${MAX_TARGET_LENGTH} characters (got ${toTarget.length})`
    );
  }
}

function validatePriority(priority: number): void {
  if (!Number.isInteger(priority) || priority < MIN_PRIORITY || priority > MAX_PRIORITY) {
    throw new RedirectValidationError(
      `priority must be an integer ${MIN_PRIORITY}-${MAX_PRIORITY} (got ${priority})`
    );
  }
}

/**
 * Resolve the actual target this rule should persist, applying one-hop
 * collapse (AC-16) and cycle rejection (AC-17): if `toTarget` (relative)
 * itself matches an existing active rule's `fromPattern`, collapse to that
 * rule's own target — the request path never chases more than one hop
 * (INV-04). If the collapsed target equals `fromPattern`, this create/update
 * would introduce a cycle; reject it instead of writing a self-loop.
 */
async function resolveCollapsedTarget(
  repo: RedirectRepoPort,
  workspaceId: string,
  fromPattern: string,
  toTarget: string
): Promise<string> {
  const finalTarget = await collapseOneHop({ repo, workspaceId, toTarget });
  if (finalTarget === fromPattern) {
    throw new RedirectLoopError(
      `redirect from '${fromPattern}' would create a cycle via '${toTarget}' (resolves back to '${fromPattern}')`
    );
  }
  await assertChainDoesNotReturn({ repo, workspaceId, fromPattern, toTarget, finalTarget });
  return finalTarget;
}

/**
 * The single hop {@link resolveCollapsedTarget} collapses: a relative target that is itself an
 * active rule's `fromPattern` becomes that rule's target (AC-16).
 *
 * @complexity O(1) plus one repo read for a relative target.
 */
async function collapseOneHop(
  { repo, workspaceId, toTarget }: { repo: RedirectRepoPort; workspaceId: string; toTarget: string },
): Promise<string> {
  if (isAbsoluteOrProtocolRelative(toTarget)) return toTarget;
  const chained = await repo.findByFromPattern({ workspaceId, fromPattern: toTarget });
  return chained && chained.status === "active" ? chained.toTarget : toTarget;
}

/**
 * Walk existing rules from `finalTarget` and refuse a write whose chain leads back to `fromPattern`.
 *
 * @throws {RedirectLoopError} When the walk reaches `fromPattern` within 32 hops.
 * @complexity O(32) repo reads at most.
 */
async function assertChainDoesNotReturn(
  { repo, workspaceId, fromPattern, toTarget, finalTarget }:
  { repo: RedirectRepoPort; workspaceId: string; fromPattern: string; toTarget: string; finalTarget: string },
): Promise<void> {
  // The collapse above only follows ONE hop (INV-04's own bound on what a request resolution
  // chases). But a create/update whose finalTarget lands on an EXISTING rule can still complete a
  // longer cycle through rules this call never collapses through — walk the rest of the chain (up
  // to 32 hops, matching REQ-26) so e.g. /b->/c, /c->/a, then creating /a->/b is rejected too.
  // Only a walk that reaches `fromPattern` itself is THIS write's cycle. A loop among other rules
  // (legacy data written before this walk existed) ends the walk instead: this write neither
  // creates it nor would removing this rule break it, and naming `fromPattern` would be false.
  let cur = finalTarget;
  const seen = new Set<string>();
  for (let hop = 0; hop < 32; hop++) {
    if (isAbsoluteOrProtocolRelative(cur)) return;
    if (cur === fromPattern) {
      throw new RedirectLoopError(
        `redirect from '${fromPattern}' would create a cycle via '${toTarget}' (following existing redirects leads back to '${fromPattern}')`
      );
    }
    if (seen.has(cur)) return;
    seen.add(cur);
    const rule = await repo.findByFromPattern({ workspaceId, fromPattern: cur });
    if (!rule || rule.status !== "active") return;
    cur = rule.toTarget;
  }
}

/**
 * Why a site-relative target was refused, phrased for the operator or agent that wrote it.
 *
 * Split out of {@link assertTargetAllowed} so the refusal wording lives next to the verdict union
 * it exhausts — a new arm in `SiteRelativeTargetCheck` becomes a type error here rather than a
 * silently generic message.
 *
 * @param check - The verdict from `checkSiteRelativeTarget`, or from `checkSameOriginDestination`
 * when `assertTargetAllowed` phrases the absolute same-origin verdict (t91 B1, 2026-09-16) — its
 * arms are a subset of this parameter's, so no separate phrasing function is needed.
 * @returns The reason clause, or `null` when the target is allowed.
 * @complexity O(1).
 */
function siteRelativeRefusalReason(check: SiteRelativeTargetCheck): string | null {
  switch (check.kind) {
    case "ok":
      return null;
    case "reserved":
      return `it resolves to '/${check.surface}', which serves the authenticated admin application rather than this site's public pages`;
    case "off-origin":
      return "it looks site-relative but resolves to a different host (a URL parser reads '\\' as '/')";
    case "unparseable":
      return "it is not a parseable URL path";
    case "malformed-encoding":
      return "it contains a malformed percent-encoding";
    case "disallowed-character":
      return "it contains, or decodes to, a backslash or a control character";
  }
}

/** Refuse source patterns whose decoded first segment belongs to a host route.
 * Uses the same decoding and case folding as the target gate; wildcard tails remain patterns.
 * @throws RedirectValidationError before any write. @complexity O(n) in the pattern length.
 */
export function assertRedirectSourceAllowed(
  { fromPattern, reservedSegments }: { fromPattern: string; reservedSegments: ReadonlySet<string> },
  _optional: Record<string, never> = {},
): void {
  const verdict = checkSiteRelativeTarget({ raw: fromPattern, reservedSegments }, {});
  if (verdict.kind === "reserved") {
    throw new RedirectValidationError(`fromPattern '${fromPattern}' is reserved for the '${verdict.surface}' surface`);
  }
}

/**
 * The site-relative half of the write gate: routing's structural + reserved-path verdict, then the
 * redirect oracle's own raw-character rule. The read path hands a relative location to that oracle
 * by concatenation, so a target it refuses (a raw backslash, any whitespace) would be stored and
 * never fire; refusing it here keeps write and read agreeing. Checked SECOND so the more specific
 * routing reasons (off-origin, control character, reserved) keep their own wording — a bare
 * backslash target is `ok` to `checkSiteRelativeTarget` (on this site, `\` really does resolve to
 * `/`), so only this second check ever refuses it (t91 B2, 2026-09-16). Last, the exact target
 * `back`, which Express serves as the visitor's `Referer` instead of a path (see
 * `./referrer-alias.ts`; t91 review F1, 2026-09-16).
 *
 * Exported as THE check for any caller-chosen, site-relative `Location` (t91 open-redirect fix,
 * 2026-09-16): `routes/site/store.ts`'s `returnTo` had its own `startsWith("/") && !startsWith("//")`
 * copy, which `/\evil.example` walks straight through. A caller that needs a path-absolute value
 * still checks `startsWith("/")` itself — this function also accepts relative references (`new`,
 * `?x`), which stay on-site but resolve against the current URL.
 *
 * @param required.target - The untrusted reference exactly as received, before any `new URL()` parse. Anything
 * that is not site-relative (an absolute or protocol-relative URL, `javascript:`) is refused too.
 * @returns The reason clause, or `null` when the target is allowed.
 * @complexity O(n) in the target length.
 * @example siteRelativeTargetReason({ target: "/products", reservedSegments }, {}); // => null
 * @example siteRelativeTargetReason({ target: "/\\evil.example", reservedSegments }, {}) !== null; // => true
 */
export function siteRelativeTargetReason(
  { target, reservedSegments }: { target: string; reservedSegments: ReadonlySet<string> },
  _optional: Record<string, never> = {},
): string | null {
  const reason = siteRelativeRefusalReason(checkSiteRelativeTarget({ raw: target, reservedSegments }, {}));
  if (reason !== null) return reason;
  if (hasForbiddenRawUrlCharacter({ raw: target })) {
    return "it contains a backslash or whitespace, which the redirect origin check refuses (write a space as '%20')";
  }
  if (isReferrerAliasLocation({ location: target }, {})) {
    return "it is 'back', which the server replaces with the visitor's Referer header (a redirect to whatever page linked here)";
  }
  return null;
}

/**
 * The write-path target gate (REQ-08), in two halves that close the SAME hole from opposite sides.
 *
 * An ABSOLUTE or protocol-relative target names a host, so the question is "is that host allowed"
 * and `OriginRegistryPort` answers it. A SITE-RELATIVE target names no host, so the origin
 * allowlist has nothing to say about it — and that used to mean it was not checked at all, which
 * left the admin application's own URL space (`/admin`, `/api/...`, served by this same Express
 * app) usable as a redirect destination from a public-site rule, including through the
 * agent-callable `redirects_create`. `checkSiteRelativeTarget` is the second half; it is the same
 * rule `site-inspection`'s `published_page_fetch` applies to a caller-supplied site path, shared
 * from `platform/routing/reserved-paths.ts` rather than restated here.
 *
 * Note for a workspace that predates this gate: a stored rule whose target is now refused can
 * still be turned off with `tombstoneRedirect` (which only flips `status` and never re-validates
 * the target) or with an `updateRedirect` that changes nothing but `status -> disabled` (see
 * `isDisableOnlyUpdate`), or repointed with `updateRedirect` by supplying a new `toTarget`.
 *
 * An absolute target that names the workspace's OWN origin passes the host oracle trivially (its
 * own host is always allowed there), so it also gets the reserved-path rule — via the same
 * `checkSameOriginDestination` the read path applies to the interpolated `Location` (t91 B1,
 * 2026-09-16). Before this, `/admin`/`/api/...` written as an absolute same-origin target was
 * stored and simply never served, because only the read gate refused it.
 *
 * @throws {RedirectTargetNotAllowedError} Naming which half refused, and why.
 * @complexity O(n) in the target length, plus one or two `OriginRegistryPort`/`canonicalOrigin`
 * reads for absolute targets.
 */
async function assertTargetAllowed(
  originRegistry: OriginRegistryPort,
  workspaceId: string,
  target: string,
  reservedSegments: ReadonlySet<string>
): Promise<void> {
  if (!isAbsoluteOrProtocolRelative(target)) {
    const reason = siteRelativeTargetReason({ target, reservedSegments }, {});
    if (reason === null) return;
    throw new RedirectTargetNotAllowedError(
      `toTarget '${target}' is not an allowed redirect destination: ${reason}`
    );
  }
  const ctx: RedirectTargetContext = { workspaceId };
  const allowed = await originRegistry.isAllowedRedirectTarget({ context: ctx, url: target });
  if (!allowed) {
    throw new RedirectTargetNotAllowedError(`toTarget '${target}' is not an allowed redirect destination`);
  }
  // The host oracle only answers "is that host allowed" — a same-origin target passes it by
  // construction, so it still needs the reserved-path check. No try/catch around
  // canonicalOrigin: isAllowedRedirectTarget above only returns true once a canonical origin
  // exists, so a throw here is a real repo/infra error and must surface — the write does not
  // happen (fail closed), not get reworded as a target verdict.
  const verdict = checkSameOriginDestination({ candidate: target, canonical: await originRegistry.canonicalOrigin(ctx), reservedSegments }, {});
  const reason = siteRelativeRefusalReason(verdict);
  if (reason === null) return;
  throw new RedirectTargetNotAllowedError(`toTarget '${target}' is not an allowed redirect destination: ${reason}`);
}

async function assertNoDuplicate(
  repo: RedirectRepoPort,
  workspaceId: string,
  matchType: string,
  fromPattern: string,
  excludeId?: string
): Promise<void> {
  if (matchType !== "exact") return;
  const dup = await repo.lookupExact({ workspaceId, path: fromPattern, includeOverrideOnly: false });
  if (dup && dup.id !== excludeId) {
    throw new RedirectConflictError(`an active exact rule for '${fromPattern}' already exists`);
  }
}

/** The rule fields every create/update/precheck validates. */
interface WriteValidatedFields {
  matchType: RedirectMatchType;
  fromPattern: string;
  toTarget: string;
  statusCode: RedirectStatusCode;
  priority: number;
}

/**
 * The one validation sequence {@link createRedirect}, {@link updateRedirect} and
 * {@link checkRedirectFieldsWouldWrite} share, so the three can never drift onto different rulesets.
 * Returns the target to store (one-hop collapsed, AC-16).
 *
 * @param optional.excludeId The row's own id, when validating an update against itself.
 * @param optional.status A merged update's status, checked in the same position an update always checked it.
 * @throws {RedirectValidationError | RedirectTargetNotAllowedError | RedirectLoopError | RedirectConflictError}
 * @complexity O(n) in the target length, plus the repo and origin reads each check makes.
 */
async function validateWriteFields(
  { deps, workspaceId, fields }: { deps: RedirectsWriteDeps; workspaceId: string; fields: WriteValidatedFields },
  { excludeId, status }: { excludeId?: string | undefined; status?: RedirectStatus } = {},
): Promise<string> {
  const patternCheck = deps.matcher.validatePattern({ matchType: fields.matchType, fromPattern: fields.fromPattern });
  if (!patternCheck.ok) throw new RedirectValidationError(patternCheck.reason);
  validateToTargetLength(fields.toTarget);
  validateStatusCode(fields.statusCode);
  if (status !== undefined) validateStatus(status);
  validatePriority(fields.priority);

  assertRedirectSourceAllowed({ fromPattern: fields.fromPattern, reservedSegments: deps.reservedSegments });
  await assertTargetAllowed(deps.originRegistry, workspaceId, fields.toTarget, deps.reservedSegments);
  const finalTarget = await resolveCollapsedTarget(deps.repo, workspaceId, fields.fromPattern, fields.toTarget);
  if (finalTarget !== fields.toTarget) {
    await assertTargetAllowed(deps.originRegistry, workspaceId, finalTarget, deps.reservedSegments);
  }
  await assertNoDuplicate(deps.repo, workspaceId, fields.matchType, fields.fromPattern, excludeId);
  return finalTarget;
}

/**
 * Pure precondition check mirroring every validator `createRedirect`/`updateRedirect` run, with NO
 * write — `features/redirects/publish-content.ts`'s `precheck()` reuses this so the two can never
 * drift onto different rulesets. Returns the refusal message a create/update against these exact
 * fields would throw, or `null` when nothing would block.
 *
 * @param excludeId Mirrors {@link assertNoDuplicate}'s own parameter — the destination's own row id,
 * when checking an update against itself.
 * @complexity O(n) in `toTarget`'s length, plus the repo/origin reads each check makes — identical
 * cost to `createRedirect`'s own validation pass, since this runs the exact same sequence.
 */
export async function checkRedirectFieldsWouldWrite(
  { deps, fields }: { deps: RedirectsWriteDeps; fields: {
    workspaceId: string;
    matchType: RedirectMatchType;
    fromPattern: string;
    toTarget: string;
    statusCode: RedirectStatusCode;
    priority: number;
  } },
  { excludeId }: { excludeId?: string } = {},
): Promise<string | null> {
  try {
    await validateWriteFields({ deps, workspaceId: fields.workspaceId, fields }, { excludeId });
    return null;
  } catch (err) {
    return err instanceof Error ? err.message : String(err);
  }
}

async function enqueueMutatedEvent(
  deps: RedirectsWriteDeps,
  record: RedirectRecord,
  change: "created" | "updated" | "tombstoned"
): Promise<void> {
  const event: RedirectMutatedEvent = {
    id: deps.idGen.newId(),
    name: `redirect.${change}`,
    occurredAt: clockNowIso({ clock: deps.clock }),
    aggregateId: record.id,
    workspaceId: record.workspaceId,
    actorId: record.createdByPrincipal,
    payload: { workspaceId: record.workspaceId, redirectId: record.id, change },
  };
  // `OutboxPort.enqueue`'s `DomainEvent` parameter defaults its payload generic to
  // `Record<string, unknown>`; a named `interface` payload (as opposed to a type alias/object
  // literal) isn't automatically assignable to that without an explicit index signature — the
  // same TS quirk affects every other typed-payload event in this codebase (e.g.
  // `menu-service.ts`'s `NavMenuChangedPayload`). `ports.ts`'s `RedirectMutatedEventPayload` stays
  // unchanged (ADR-PIPE-009 says `ports.ts` is frozen), so the widening is a call-site cast.
  await deps.outbox.enqueue(event as unknown as DomainEvent);
}

export interface CreateRedirectRequired {
  deps: RedirectsWriteDeps;
  input: CreateRedirectInput;
  /**
   * Provenance to stamp on the created record (REQ-01/26). Defaults to
   * `'manual'`. `importRedirects` (C-004) passes `'import'` here — this is
   * an internal parameter, not part of `CreateRedirectInput`'s public shape
   * (an API caller never chooses their own provenance).
   */
  source?: "manual" | "import";
}

/** C-001: manual-create entry point (REQ-01). */
export async function createRedirect(required: CreateRedirectRequired, _optional: Record<string, never> = {}): Promise<{ record: RedirectRecord }> {
  const { deps, input, source = "manual" } = required;

  const priority = input.priority ?? DEFAULT_PRIORITY;
  const finalTarget = await validateWriteFields({ deps, workspaceId: input.workspaceId, fields: { ...input, priority } });

  const now = clockNowIso({ clock: deps.clock });
  const id = deps.idGen.newId();
  const record: RedirectRecord = {
    id,
    workspaceId: input.workspaceId,
    matchType: input.matchType,
    fromPattern: input.fromPattern,
    toTarget: finalTarget,
    statusCode: input.statusCode,
    status: "active",
    override: input.override ?? false,
    priority,
    source,
    createdByPrincipal: input.actorId,
    createdByPluginId: input.pluginId,
    createdAt: now,
    updatedAt: now,
    version: 1,
  };
  const revision: RedirectRevision = {
    redirectId: id,
    workspaceId: input.workspaceId,
    seq: 1,
    state: record,
    tombstoned: false,
    actorId: input.actorId,
    pluginId: input.pluginId,
    recordedAt: now,
  };

  await deps.transaction(async () => {
    await insertRedirectAndRevision({ db: deps.db, record, revision });
  });
  await enqueueMutatedEvent(deps, record, "created");

  return { record };
}

export interface UpdateRedirectRequired {
  deps: RedirectsWriteDeps;
  input: UpdateRedirectInput;
}

/** The PATCH-able subset of a redirect record — `updateRedirect`'s input, one field at a time,
 *  falls back to `existing`'s own value. */
type UpdatableRedirectFields = Pick<
  RedirectRecord,
  "matchType" | "fromPattern" | "toTarget" | "statusCode" | "priority" | "override" | "status"
>;

/** Merges a partial `UpdateRedirectInput` over the existing record's own values — C-002's
 *  "apply only what changed" PATCH semantics, isolated as its own defaulting decision so
 *  {@link updateRedirect} itself only has to sequence validate → write against the result. */
function resolveUpdateFields(input: UpdateRedirectInput, existing: RedirectRecord): UpdatableRedirectFields {
  return {
    matchType: input.matchType ?? existing.matchType,
    fromPattern: input.fromPattern ?? existing.fromPattern,
    toTarget: input.toTarget ?? existing.toTarget,
    statusCode: input.statusCode ?? existing.statusCode,
    priority: input.priority ?? existing.priority,
    override: input.override ?? existing.override,
    status: input.status ?? existing.status,
  };
}

/** Every PATCH-able field except `status`, for {@link isDisableOnlyUpdate}'s "nothing else changed" test. */
const NON_STATUS_UPDATABLE_FIELDS = [
  "matchType",
  "fromPattern",
  "toTarget",
  "statusCode",
  "priority",
  "override",
] as const satisfies readonly (keyof UpdatableRedirectFields)[];

/**
 * Whether this update does nothing but switch the rule OFF (t91 review F2, coordinator ruling
 * 2026-09-16). The admin Redirects screen's on/off toggle PATCHes `status` alone, and a legacy rule
 * whose stored target the gate now refuses used to fail that toggle on the target check. A disabled
 * rule is never served, so turning one off only reduces risk; re-enabling it, or changing any other
 * field, is a full update and runs every check. A field sent with the value it already has counts as
 * unchanged, so a client that PATCHes the whole record gets the same answer as one that sends only
 * `status`.
 *
 * @param fields - {@link resolveUpdateFields}'s merge of the input over `existing`.
 * @param existing - The stored record being updated.
 * @returns `true` only when `fields.status` is `disabled` and every other field equals `existing`'s.
 * @complexity O(1) — a fixed set of scalar comparisons.
 */
function isDisableOnlyUpdate(fields: UpdatableRedirectFields, existing: RedirectRecord): boolean {
  return fields.status === "disabled" && NON_STATUS_UPDATABLE_FIELDS.every((key) => fields[key] === existing[key]);
}

/**
 * Whether this update states nothing but `status: "active"` (S7, web-high fix plan 2026-09-24) — a
 * pure re-enable, which on a rule that is in the Trash means "restore it," the same intent the admin
 * Redirects screen's Enable toggle already carries for an ordinary disabled rule. Checked against
 * the INPUT actually sent, not {@link resolveUpdateFields}'s merge over `existing` — unlike
 * {@link isDisableOnlyUpdate}'s "unchanged" test, a trashed row's OWN stored fields cannot be used as
 * the comparison basis here, since nothing about being in the Trash guarantees they are still valid
 * (the whole point of the `else` branch below is that a trashed row may not be edited sight-unseen).
 *
 * @complexity O(1) — a fixed set of `undefined` checks.
 */
function isRestoreOnlyUpdate(input: UpdateRedirectInput): boolean {
  return input.status === "active" && NON_STATUS_UPDATABLE_FIELDS.every((key) => input[key] === undefined);
}

/**
 * S7: the only update a trashed rule accepts is a pure restore ({@link isRestoreOnlyUpdate}); any
 * other PATCH is refused rather than editing a row the caller cannot see the current shape of.
 *
 * @throws {EntityNotLiveError} On a non-restore update.
 * @throws {RedirectNotFoundError | RedirectConflictError} When the restore does not land.
 * @complexity O(1) plus the restore and one repo re-read.
 */
async function restoreTrashedRedirect(
  { deps, input, existing }: { deps: RedirectsWriteDeps; input: UpdateRedirectInput; existing: RedirectRecord },
): Promise<{ record: RedirectRecord }> {
  if (!isRestoreOnlyUpdate(input)) {
    assertEntityLive({ entityType: "redirect", entityId: input.id, state: "trashed" });
  }

  assertRedirectSourceAllowed({ fromPattern: existing.fromPattern, reservedSegments: deps.reservedSegments });
  const outcome = await deps.restore({
    workspaceId: input.workspaceId,
    id: input.id,
    at: clockNowIso({ clock: deps.clock }),
    actor: { principalId: input.actorId, pluginId: input.pluginId ?? null },
  });
  assertRestoreLanded({ outcome, id: input.id });

  const restored = await deps.repo.findById({ workspaceId: input.workspaceId, id: input.id });
  if (!restored) throw new RedirectNotFoundError(`redirect '${input.id}' was not found`);
  await enqueueMutatedEvent(deps, restored, "updated");
  return { record: restored };
}

/**
 * Map a non-"restored" Trash outcome to the error the caller sees.
 *
 * @complexity O(1).
 */
function assertRestoreLanded(
  { outcome, id }: { outcome: Awaited<ReturnType<RedirectsWriteDeps["restore"]>>; id: string },
): void {
  if (outcome === "not-found") throw new RedirectNotFoundError(`redirect '${id}' was not found`);
  if (outcome === "version-changed") {
    throw new RedirectConflictError(`redirect '${id}' changed while it was being restored`);
  }
  if (outcome === "adapter-unavailable") {
    throw new Error(`trash: no Trash adapter is registered for entity type 'redirect' (id '${id}')`);
  }
}

/**
 * C-002: symmetric chokepoint entry for updates (REQ-04). A disable-only update
 * ({@link isDisableOnlyUpdate}) writes the status change without re-validating the unchanged fields
 * — it stores the existing target as-is, with no one-hop collapse.
 *
 * S7 (web-high fix plan 2026-09-24): a rule with a Trash index row (`deps.isInTrash`, distinct from
 * `status === "disabled"` — see {@link RedirectsWriteDeps.isInTrash}'s own doc) refuses every update
 * EXCEPT a pure `status: "active"` PATCH ({@link isRestoreOnlyUpdate}), which restores it instead of
 * editing a row the caller cannot see the current shape of.
 *
 * @throws {EntityNotLiveError} On a non-restore update to a rule in the Trash.
 * @throws {RedirectConflictError} If the Trash row's version moved before the restore landed.
 */
export async function updateRedirect(required: UpdateRedirectRequired, _optional: Record<string, never> = {}): Promise<{ record: RedirectRecord }> {
  const { deps, input } = required;

  const existing = await deps.repo.findById({ workspaceId: input.workspaceId, id: input.id });
  if (!existing) throw new RedirectNotFoundError(`redirect '${input.id}' was not found`);

  const inTrash = await deps.isInTrash({ workspaceId: input.workspaceId, id: input.id });
  if (inTrash) return restoreTrashedRedirect({ deps, input, existing });

  const fields = resolveUpdateFields(input, existing);
  // Every field check a create runs, against the merged update; a disable-only update skips it as
  // one decision and keeps the existing target as-is.
  const finalTarget = isDisableOnlyUpdate(fields, existing)
    ? existing.toTarget
    : await validateWriteFields({ deps, workspaceId: input.workspaceId, fields }, { excludeId: existing.id, status: fields.status });

  const now = clockNowIso({ clock: deps.clock });
  const version = existing.version + 1;
  const record: RedirectRecord = { ...existing, ...fields, toTarget: finalTarget, updatedAt: now, version };
  const revision: RedirectRevision = {
    redirectId: existing.id,
    workspaceId: input.workspaceId,
    seq: version,
    state: record,
    tombstoned: false,
    actorId: input.actorId,
    pluginId: input.pluginId,
    recordedAt: now,
  };

  await deps.transaction(async () => {
    await insertRedirectAndRevision({ db: deps.db, record, revision });
  });
  await enqueueMutatedEvent(deps, record, "updated");

  return { record };
}

export interface TombstoneRedirectRequired {
  deps: RedirectsWriteDeps;
  input: { workspaceId: string; id: string; actorId: string; pluginId?: string };
}

/** C-003: soft-delete (REQ-05). */
export async function tombstoneRedirect(
  required: TombstoneRedirectRequired,
  _optional: Record<string, never> = {},
): Promise<{ record: RedirectRecord }> {
  const { deps, input } = required;

  const existing = await deps.repo.findById({ workspaceId: input.workspaceId, id: input.id });
  if (!existing) throw new RedirectNotFoundError(`redirect '${input.id}' was not found`);

  // Idempotent no-op: already in the Trash, no new revision needed. Keyed on the Trash index row,
  // not `status === "disabled"` (Bug B, 2026-10-22): a rule an operator merely toggled off is also
  // `disabled`, and treating that as "already removed" left it in the normal list for good.
  if (await deps.isInTrash({ workspaceId: input.workspaceId, id: input.id })) {
    return { record: existing };
  }

  const now = clockNowIso({ clock: deps.clock });
  const version = existing.version + 1;
  const record: RedirectRecord = { ...existing, status: "disabled", updatedAt: now, version };
  const revision: RedirectRevision = {
    redirectId: existing.id,
    workspaceId: input.workspaceId,
    seq: version,
    state: record,
    tombstoned: true,
    actorId: input.actorId,
    pluginId: input.pluginId,
    recordedAt: now,
  };

  // The marker flip, the Trash index row and the revision append are one unit. `deps.remove` joins
  // this transaction rather than opening its own, so a tombstone can never land without its Trash
  // row (which would make the redirect unrecoverable through the UI) or vice versa.
  await deps.transaction(async () => {
    const removed = await deps.remove({
      workspaceId: input.workspaceId,
      id: input.id,
      // From columns already loaded above — no second read.
      display: { title: existing.fromPattern, subtitle: existing.toTarget },
      at: now,
      expectedVersion: existing.version,
      actor: { principalId: input.actorId, pluginId: input.pluginId ?? null },
    });
    if (!removed.ok) {
      if (removed.reason === "not-found") throw new RedirectNotFoundError(`redirect '${input.id}' was not found`);
      throw new RedirectConflictError(`redirect '${input.id}' changed while it was being tombstoned`);
    }
    await deps.db.insertRevision(revision);
  });
  await enqueueMutatedEvent(deps, record, "tombstoned");

  return { record };
}

/** The two ports {@link listRedirects} reads — a structural slice of {@link RedirectsWriteDeps}. */
export interface ListRedirectsDeps {
  repo: Pick<RedirectRepoPort, "list">;
  isInTrash: RedirectsWriteDeps["isInTrash"];
}

export interface ListRedirectsRequired {
  deps: ListRedirectsDeps;
  filter: ListRedirectsFilter;
}

/**
 * The admin/AI rule list (Bug B, 2026-10-22): {@link RedirectRepoPort.list} minus every rule in the
 * Trash. Removing a rule moves it to the Trash, so it must leave the normal list and be visible only
 * there until it is restored (Trash restore, or an `updateRedirect` `status: "active"` PATCH). Only
 * `disabled` rules are checked — {@link tombstoneRedirect}'s marker is `disabled`, so an `active`
 * row cannot be in the Trash — which keeps the lookups to the switched-off rows. They run one at a
 * time so a long list never fans out into a burst of concurrent index reads.
 *
 * @complexity O(n) for n listed rules, plus one Trash index lookup per `disabled` rule.
 */
export async function listRedirects(required: ListRedirectsRequired, _optional: Record<string, never> = {}): Promise<RedirectRecord[]> {
  const { deps, filter } = required;
  const listed: RedirectRecord[] = [];
  for (const rule of await deps.repo.list(filter)) {
    const removed = rule.status === "disabled" && await deps.isInTrash({ workspaceId: filter.workspaceId, id: rule.id });
    if (!removed) listed.push(rule);
  }
  return listed;
}

export interface ImportRedirectsRequired {
  deps: RedirectsWriteDeps;
  input: { workspaceId: string; actorId: string; rules: CreateRedirectInput[] };
}

export interface ImportRedirectsFailure {
  index: number;
  code: string;
  message: string;
}

function errorToCode(err: unknown): string {
  if (err instanceof RedirectValidationError) return "REDIRECT_VALIDATION_ERROR";
  if (err instanceof RedirectTargetNotAllowedError) return "REDIRECT_TARGET_NOT_ALLOWED";
  if (err instanceof RedirectConflictError) return "REDIRECT_CONFLICT";
  if (err instanceof RedirectLoopError) return "REDIRECT_LOOP_DETECTED";
  return "INTERNAL_ERROR";
}

/**
 * The classes whose message a per-rule import failure may carry verbatim — the same four
 * {@link errorToCode} names (wm S16, 2026-10-04). `failed[]` is a RETURNED result (the agent tool
 * and the admin import route both hand it out as-is), so it bypasses the transport's
 * INTERNAL_ERROR redaction; before this, an infrastructure error (a driver failure quoting a file
 * path, say) put its raw message straight into the model's and the admin's view.
 */
const IMPORT_FAILURE_SAFE_RULES: readonly CallerSafeErrorRule[] = [
  { error: RedirectValidationError },
  { error: RedirectTargetNotAllowedError },
  { error: RedirectConflictError },
  { error: RedirectLoopError },
];

/**
 * C-004: batch-create reusing the same chokepoint, no bypass (REQ-26). Each
 * item is processed independently through `createRedirect` — NOT one shared
 * transaction across items (EC-08); a per-item failure does not abort
 * already-written prior items.
 */
export async function importRedirects(
  required: ImportRedirectsRequired,
  _optional: Record<string, never> = {},
): Promise<{ created: RedirectRecord[]; failed: ImportRedirectsFailure[] }> {
  const { deps, input } = required;

  if (input.rules.length < 1 || input.rules.length > MAX_IMPORT_BATCH_SIZE) {
    throw new RedirectValidationError(
      `import batch size must be 1-${MAX_IMPORT_BATCH_SIZE} (got ${input.rules.length})`
    );
  }

  const created: RedirectRecord[] = [];
  const failed: ImportRedirectsFailure[] = [];

  for (const [index, rule] of input.rules.entries()) {
    try {
      const { record } = await createRedirect({
        deps,
        input: { ...rule, workspaceId: input.workspaceId, actorId: input.actorId },
        source: "import",
      });
      created.push(record);
    } catch (err) {
      failed.push({
        index,
        code: errorToCode(err),
        message: callerSafeErrorMessage({ err, rules: IMPORT_FAILURE_SAFE_RULES, fallback: "an internal error occurred" }),
      });
    }
  }

  return { created, failed };
}

/**
 * @file Resolution logic for the host `routing` Tier-2 library (ADR-039 v0).
 *
 * Purpose:
 * Implements the inverse resolver (`urlFor`/`isActive`) Menus (ADR-029) and
 * SEO (ADR-032) consume, the forward resolution pipeline registration seam
 * Redirects (ADR-033) will consume, the named-route registry backing `route`
 * targets, and the `SlugChangeCapture` registration slot (ADR-039 §4).
 *
 * How it relates to the project:
 * - `routing/types.ts` supplies the `RouteTarget` vocabulary and result shapes.
 * - `routing/ports.ts` supplies `RouteResolverDeps` (reuses `PostRepoPort`).
 * - Only `post` is a real implemented content type today, so `entryRef`
 *   resolution goes through `PostRepoPort` directly; `termRef` is a documented
 *   stub (taxonomy doesn't exist yet — ADR-029 Round-3 fold item 1).
 *
 * Architectural role:
 * Core-owned Tier-2 library code. No Drizzle/SQLite adapter and no HTTP
 * wiring live here (that is out of scope for this v0 build) — this file is
 * pure resolution logic over injected ports and in-module registries.
 */
import type { RouteResolverDeps, RoutingContentRecord, RoutingPorts } from './ports.js';
import type { EntryRefTarget, RouteRefTarget, RouteResolveContext, RouteResolvePhaseHandler, RouteResolvePhaseName, RouteResolvePhaseOutcome, RouteResolveResult, RouteTarget, RouteUrl, SlugChangeCapture, TermRefTarget, UrlTarget } from './types.js';

/** Raised when a `RouteTarget` carries a discriminant this library does not recognize. */
export class RouteResolutionError extends Error {}

export interface RegisterNamedRouteInput {
  readonly name: string;
  readonly path: string;
}

// ---------------------------------------------------------------------------
// Inverse resolver — `urlFor` / `isActive` (ADR-039 §2, Round-2 amendment 4)
// ---------------------------------------------------------------------------

export interface UrlForRequired {
  deps: RouteResolverDeps;
  target: RouteTarget;
  ctx: RouteResolveContext;
}

export interface UrlForOptional {}

export interface IsActiveRequired {
  deps: RouteResolverDeps;
  target: RouteTarget;
  currentPath: string;
  ctx: RouteResolveContext;
}

export interface IsActiveOptional {}

// ---------------------------------------------------------------------------
// Forward resolution pipeline (ADR-039 §1) — registration seam for Redirects
// ---------------------------------------------------------------------------

/**
 * One handler plus the registrant that owns it. `owner` is an opaque identity
 * token supplied by the registrant (see {@link RegisterResolvePhaseOptions.owner});
 * `undefined` means "unowned", the historical append-only behavior. `onError`
 * is this registration's own fault policy — see {@link RegisterResolvePhaseOptions.onError}.
 */
interface PhaseRegistration {
  readonly owner: unknown;
  readonly handler: RouteResolvePhaseHandler;
  readonly onError: "skip" | "fail";
}

type PhaseRegistry = Record<RouteResolvePhaseName, PhaseRegistration[]>;

export interface RegisterResolvePhaseOptions {
  /**
   * The registrant's identity. Registering under an owner that already holds
   * handlers in this phase REPLACES them rather than appending, so a registrant
   * whose handlers close over a per-boot resource (a site's database handle, a
   * request-scoped client) cannot leave the previous boot's closures reachable.
   *
   * Omit it and the registration is appended and never superseded — the v0
   * behavior this library's own tests still use.
   */
  readonly owner?: unknown;
  /**
   * This registration's fault policy when its handler throws. `"fail"` (the default) rethrows
   * out of the phase, so the caller's own error handling runs (the public site routes answer
   * `500 <h1>Site error</h1>`, on BOTH phases as of 2026-09-16, t91 F4.3-A: `post_content` on
   * `GET /:slug` used to leave a default-policy throw with no response at all — see
   * `routes/site/pages.ts`'s `handlePostNotFoundInSlugCatch`). `"skip"` logs `[routing] a <phase>
   * resolver failed for <path> — skipping it` and continues to the phase's remaining handlers.
   *
   * Choose `"skip"` only for a handler whose failure can only DECLINE an outcome — it can never
   * fabricate one, so a swallowed failure cannot weaken any guard. Redirects opts into it for
   * exactly that reason (INV-03: a lookup failure means "no redirect", never "gone"). A future
   * guard-type handler (a takedown or reserved-path check, which must BLOCK on failure, not wave
   * a request through) fails CLOSED by default unless it deliberately opts into `"skip"` too.
   */
  readonly onError?: "skip" | "fail";
}

export interface ResolveInput {
  path: string;
  ctx: RouteResolveContext;
}

export interface ResolveRequired {
  input: ResolveInput;
}

export interface ResolveOptional {}
export type EmptyOptions = Record<string, never>;
export interface CreateRoutingRequired { readonly ports: RoutingPorts }
export interface CreateRoutingOptional { readonly namedRoutes?: ReadonlyArray<readonly [string, string]> }

/** Bound routing API. All methods share one instance's registrations and host ports. */
export interface Routing {
  entryPublicPath(required: { post: RoutingContentRecord; ctx: RouteResolveContext }, optional?: EmptyOptions): RouteUrl | null;
  postPublicPath(required: { slug: string }, optional?: EmptyOptions): string;
  getNamedRoute(required: { name: string }, optional?: EmptyOptions): string | null;
  registerNamedRoute(required: RegisterNamedRouteInput, optional?: EmptyOptions): void;
  urlFor(required: UrlForRequired, optional?: UrlForOptional): Promise<RouteUrl | null>;
  isActive(required: IsActiveRequired, optional?: IsActiveOptional): Promise<boolean>;
  resolve(required: ResolveRequired, optional?: ResolveOptional): Promise<RouteResolveResult>;
  registerResolvePhase(required: { phase: RouteResolvePhaseName; resolver: RouteResolvePhaseHandler }, optional?: RegisterResolvePhaseOptions): () => void;
  unregisterResolvePhaseOwner(required: { owner: unknown }, optional?: EmptyOptions): void;
  runPreContentPhase(required: { path: string; ctx: RouteResolveContext }, optional?: EmptyOptions): Promise<RouteResolvePhaseOutcome | null>;
  runPostContentPhase(required: { path: string; ctx: RouteResolveContext }, optional?: EmptyOptions): Promise<RouteResolvePhaseOutcome | null>;
  registerSlugChangeCapture(required: { impl: SlugChangeCapture }, optional?: EmptyOptions): () => void;
  getSlugChangeCapture(required: EmptyOptions, optional?: EmptyOptions): SlugChangeCapture | undefined;
  /** Test-only reset of this instance; never resets another instance's registrations. */
  resetRoutingRegistrationsForTests(required: EmptyOptions, optional?: EmptyOptions): void;
}

/**
 * Create routing over host-owned content visibility and fault reporting.
 * Each instance owns its registrations; a host that historically shared one process registry
 * must bind one instance and reuse it across composition roots. No database or clock is constructed.
 * @param required Host ports; visibility errors propagate unchanged.
 * @param optional Initial named-route configuration (home/search by default).
 * @returns Resolvers and registration lifecycles sharing this instance's state.
 * @complexity O(r) initialization for r configured named routes.
 * @example const routing = createRouting({ ports }, { namedRoutes: [['home', '/']] });
 */
export function createRouting(required: CreateRoutingRequired, optional: CreateRoutingOptional = {}): Routing {

  // ---------------------------------------------------------------------------
  // Named-route registry (backs `route` targets — ADR-039 §3)
  // ---------------------------------------------------------------------------

  const DEFAULT_NAMED_ROUTES: ReadonlyArray<readonly [string, string]> = [
    ["home", "/"],
    ["search", "/search"],
  ];

  const initialNamedRoutes = optional.namedRoutes ?? DEFAULT_NAMED_ROUTES;
  const namedRoutes = new Map<string, string>(initialNamedRoutes);

  /**
   * Register (or overwrite) a named core route. Core-owned registration, not an
   * open plugin hook — matches ADR-039 §1's treatment of the forward pipeline.
   *
   * @complexity O(1) time/space.
   */
  function registerNamedRoute(input: RegisterNamedRouteInput, _optional: EmptyOptions = {}): void {
    namedRoutes.set(input.name, input.path);
  }

  /**
   * Look up a named route's fixed path.
   *
   * @returns the registered path, or `null` if `name` has no registration
   * (mirrors the library-wide "unavailable → null" contract).
   * @complexity O(1) time/space.
   */
  function getNamedRoute({ name }: { name: string }, _optional: EmptyOptions = {}): string | null {
    return namedRoutes.get(name) ?? null;
  }

  // ---------------------------------------------------------------------------
  // Path normalization + canonical URL composition
  // ---------------------------------------------------------------------------

  const ABSOLUTE_URL_PATTERN = /^[a-z][a-z0-9+.-]*:\/\//i;

  function isAbsoluteUrl(value: string): boolean {
    return ABSOLUTE_URL_PATTERN.test(value) || value.startsWith("//");
  }

  /**
   * Normalize a request/target path: strip query/hash, force a leading slash,
   * and drop a trailing slash (except for the root path itself).
   *
   * @complexity O(n) in path length.
   */
  function normalizePath(rawPath: string): string {
    // `split` always yields at least one element (an empty input gives [""]), so [0] is defined.
    const withoutQueryOrHash = rawPath.split(/[?#]/, 1)[0]!;
    const withLeadingSlash = withoutQueryOrHash.startsWith("/")
      ? withoutQueryOrHash
      : `/${withoutQueryOrHash}`;
    if (withLeadingSlash.length > 1 && withLeadingSlash.endsWith("/")) {
      return withLeadingSlash.slice(0, -1);
    }
    return withLeadingSlash;
  }

  /**
   * Builds a post/page's own public path from its `slug` — the one point every call site that turns a
   * `PostRecord.slug` into a route string goes through, so the content-owned-homepage `"/"` root-slug
   * exception (`post.ts`'s `ROOT_SLUG`) has exactly one implementation instead of N independently
   * re-deriving it. `/${slug}` is correct for every ordinary slug; the one deliberate exception is the
   * literal `"/"` slug itself, which a naive `/${slug}` template would double up into `"//"` — a Page
   * that has claimed the site's own homepage (`post.ts`'s `ROOT_SLUG` doc has the write-time gate that
   * makes `"/"` the only slug this can ever matter for).
   *
   * @complexity O(1).
   */
  function postPublicPath({ slug }: { slug: string }, _optional: EmptyOptions = {}): string {
    return slug === "/" ? "/" : `/${slug}`;
  }

  /**
   * Compose the `canonicalUrl` a resolved `path` implies.
   *
   * TODO(ADR-040): compose canonicalUrl from OriginRegistryPort.canonicalOrigin(ctx)
   * once `src/origin` exists, instead of `ctx.originOverride`. `src/origin` is
   * being built in parallel by another agent and does not exist yet, so this
   * library must not import it.
   *
   * @complexity O(1).
   */
  function composeCanonicalUrl(path: string, ctx: RouteResolveContext): string {
    if (isAbsoluteUrl(path)) return path;
    const origin = ctx.originOverride?.replace(/\/$/, "");
    return origin ? `${origin}${path}` : path;
  }

  // ---------------------------------------------------------------------------
  // Per-kind target resolvers (internal — dispatched by `urlFor`)
  // ---------------------------------------------------------------------------

  /**
   * `published` is the only status that yields a live, linkable path (mirrors `getPublishedPostBySlug`,
   * `post.ts`). Checks `isTrashed` too, not just `status` — `softDelete` (post.ts) stamps only
   * `deletedAt`/`updatedAt`/`version`, never `status`, so a post that was `published` when trashed
   * stays `status: "published"` forever, and `postRepo.findById` (this module's `resolveEntryRefTarget`
   * and every other caller of {@link entryPublicPath}) is documented trash-BLIND. Without this check a
   * trashed post would resolve to a live, linkable URL through `urlFor`/menu href resolution
   * (`resolveStaticMenusForRender`, `server/inbound/public-http/routes/site/pages.ts`) even though the
   * post itself 404s at every real render entrypoint. Same defect pattern as
   * caa116115c103630ba5253f9bbe3bceb234347d8 (sitemap.xml/llms.txt) and a5c9bac8 (media rendition
   * gating).
   */
  function isPublished(post: RoutingContentRecord): boolean {
    // Scheduled publishing (2026-10-05): a published row whose `publishAt` is still ahead gets no
    // live link yet either — `isLiveAt` is `status === "published" && !isTrashed` plus that check.
    return required.ports.isLive({ post });
  }

  /**
   * Pure half of `entryRef` resolution: given a `PostRecord` already in hand, decides its public path
   * with no repo call of its own. Factored out of {@link resolveEntryRefTarget} (and exported) so a
   * caller that already holds the record — e.g. `features/post/tool-registrations.ts`'s
   * `content_post_list`, iterating rows a prior `postRepo.list()` already fetched — can resolve
   * `publicUrl` without a redundant `postRepo.findById` per row. `resolveEntryRefTarget`/`urlFor`
   * still call this internally, so a caller resolving by id and a caller resolving from an
   * already-held record always compute the identical path/canonicalUrl — the one-resolver property
   * SEO's canonical tags depend on is unchanged.
   *
   * @returns `null` for a draft, unpublished, or otherwise non-live row — never a link a visitor
   * would 404 on.
   * @complexity O(1).
   */
  function entryPublicPath(
    { post, ctx }: { post: RoutingContentRecord; ctx: RouteResolveContext },
    _optional: EmptyOptions = {}
  ): RouteUrl | null {
    if (!isPublished(post)) return null;
    const path = postPublicPath({ slug: post.slug });
    return { path, canonicalUrl: composeCanonicalUrl(path, ctx) };
  }

  async function resolveEntryRefTarget(
    deps: RouteResolverDeps,
    target: EntryRefTarget,
    ctx: RouteResolveContext
  ): Promise<RouteUrl | null> {
    const post = await deps.postRepo.findById({ workspaceId: ctx.workspaceId, id: target.entryId });
    if (!post) return null;
    return entryPublicPath({ post: post, ctx: ctx });
  }

  /**
   * Stub: taxonomy isn't implemented in this repo. ADR-029's Round-3 audit fold
   * promoted "term-link schema" from an Open item to a Wave-1 acceptance
   * blocker — ADR-022 §5's `entry_refs` covers entry-to-entry references only,
   * with no term-target schema yet (content-lib sign-off on a typed `term_refs`
   * index, or an accepted `entry_refs` extension for term targets, is owed).
   * Always resolves `null` until that schema lands.
   */
  function resolveTermRefTarget(_target: TermRefTarget, _ctx: RouteResolveContext): RouteUrl | null {
    return null;
  }

  const UNSAFE_URL_SCHEMES = ["javascript:", "data:"] as const;

  /**
   * @complexity O(1) (bounded scheme-prefix check).
   */
  function resolveUrlTarget(target: UrlTarget, ctx: RouteResolveContext): RouteUrl | null {
    const href = target.href.trim();
    const lowered = href.toLowerCase();
    if (UNSAFE_URL_SCHEMES.some((scheme) => lowered.startsWith(scheme))) {
      return null;
    }
    return { path: href, canonicalUrl: composeCanonicalUrl(href, ctx) };
  }

  function resolveRouteRefTarget(target: RouteRefTarget, ctx: RouteResolveContext): RouteUrl | null {
    const path = getNamedRoute({ name: target.route });
    if (path === null) return null;
    return { path, canonicalUrl: composeCanonicalUrl(path, ctx) };
  }

  /**
   * Resolve a `RouteTarget` to its concrete path + canonical URL.
   *
   * Purpose: the one inverse-resolution entrypoint Menus and SEO depend on.
   * Deviates from ADR-039 §2's 2-arg pseudocode (`urlFor(target, ctx)`) by
   * taking a required-object first parameter carrying `deps` — `entryRef`
   * resolution needs an async `PostRepoPort` call, so `urlFor` must be async and
   * (per this repo's house style) DI'd rather than reaching for a singleton.
   * The semantic contract (target + workspace-scoped ctx → `RouteUrl | null`) is
   * unchanged.
   *
   * @returns `null` when the target is unavailable (not found, unpublished,
   * unresolvable taxonomy term, unsafe URL scheme, or unregistered route name) —
   * never throws for those cases, so callers can treat "no link" uniformly.
   * @throws {RouteResolutionError} only if `target.kind` is not one of the four
   * known discriminants (defensive; unreachable through the typed union).
   * @complexity O(1) plus the cost of one repo call for `entryRef` targets.
   */
  async function urlFor(
    required: UrlForRequired,
    _optional: UrlForOptional = {}
  ): Promise<RouteUrl | null> {
    const { deps, target, ctx } = required;
    switch (target.kind) {
      case "entryRef":
        return resolveEntryRefTarget(deps, target, ctx);
      case "termRef":
        return resolveTermRefTarget(target, ctx);
      case "url":
        return resolveUrlTarget(target, ctx);
      case "route":
        return resolveRouteRefTarget(target, ctx);
      default: {
        const unreachable: never = target;
        throw new RouteResolutionError(
          `unrecognized route target kind: ${JSON.stringify(unreachable)}`
        );
      }
    }
  }

  /**
   * Whether `target` resolves to `currentPath` — the active-state Menus needs
   * for nav highlighting.
   *
   * v0 does exact-path matching only, after normalization. Ancestor/prefix
   * semantics for nested menu highlighting (is `/blog` active on `/blog/post`?)
   * are explicitly deferred to v0.1 (ADR-039 "Open" item 3) since they also
   * need the `urlFor → null` caller-render contract (hide vs. render inert)
   * pinned first.
   *
   * @returns `false` when the target is unavailable (delegates to `urlFor`).
   * @complexity Same as `urlFor` plus O(n) path normalization.
   */
  async function isActive(
    required: IsActiveRequired,
    _optional: IsActiveOptional = {}
  ): Promise<boolean> {
    const resolved = await urlFor({ deps: required.deps, target: required.target, ctx: required.ctx });
    if (!resolved) return false;
    return normalizePath(resolved.path) === normalizePath(required.currentPath);
  }

  const phaseRegistry: PhaseRegistry = {
    pre_content: [],
    post_content: [],
  };

  /** Every phase, so an owner-wide revoke never has to be told which phases it used. */
  const ALL_PHASES: readonly RouteResolvePhaseName[] = ["pre_content", "post_content"];

  /**
   * Register a resolver into an ordered, core-owned pipeline phase
   * (`normalize → pre_content → content-resolve → post_content → 404`,
   * ADR-039 §1). Not an open ADR-009 plugin hook in v1 — this is the seam
   * Redirects (ADR-033) will register into once it exists; no real rules are
   * registered by this library itself.
   *
   * Resolvers within a phase run in registration order; the first non-`null`
   * outcome short-circuits the remaining resolvers in that phase and the rest
   * of the pipeline. Per ADR-039 Round-2 amendment 5, a `pre_content` resolver
   * must only ever return a redirect/gone decision with an audited rule — it
   * must never fabricate a `not_found` for a path that live content could still
   * resolve. This library does not enforce that invariant (no rules exist yet
   * to violate it); it is a contract note for the future Redirects implementer.
   *
   * Lifecycle (2026-09-16). This registry is module-level and therefore
   * process-wide, but its registrants are not: a composition root registers a
   * handler that has CLOSED OVER that composition's resources, and more than one
   * composition runs per process (an integration test boots one site per case,
   * and `createRouteDeps()` plus `createSiteRouteDeps()` can both run in one
   * test process). Append-only, that left every previous composition's closure
   * live on the request path forever — benign
   * while the superseded resources were in-memory, a `TypeError: The database
   * connection is not open` 500 on every phase-running route once one of them
   * was a site database that had since closed. Pass {@link
   * RegisterResolvePhaseOptions.owner} to opt into supersede-on-re-registration;
   * {@link unregisterResolvePhaseOwner} revokes an owner outright.
   *
   * @returns a disposer that removes exactly this registration (idempotent, and
   * a no-op once an owner-scoped re-registration has already superseded it).
   * @complexity O(1) for an unowned registration; O(n) in the phase's existing
   * registrations for an owned one (it first evicts that owner's). O(1) space.
   */
  function registerResolvePhase(
    { phase, resolver }: { phase: RouteResolvePhaseName; resolver: RouteResolvePhaseHandler },
    options: RegisterResolvePhaseOptions = {}
  ): () => void {
    const owner = options.owner;
    if (owner !== undefined) {
      phaseRegistry[phase] = phaseRegistry[phase].filter((entry) => entry.owner !== owner);
    }
    const registration: PhaseRegistration = { owner, handler: resolver, onError: options.onError ?? "fail" };
    phaseRegistry[phase].push(registration);
    return () => {
      phaseRegistry[phase] = phaseRegistry[phase].filter((entry) => entry !== registration);
    };
  }

  /**
   * Revoke every handler `owner` registered, across every phase — the explicit
   * teardown half of {@link RegisterResolvePhaseOptions.owner}, for a host that
   * knows when a site is finished rather than only when the next one starts.
   *
   * Unowned registrations are never matched: `undefined` is the "no owner" marker,
   * not an owner, so `unregisterResolvePhaseOwner(undefined)` is a deliberate no-op.
   *
   * @complexity O(n) in total registered handlers. O(1) space.
   */
  function unregisterResolvePhaseOwner({ owner }: { owner: unknown }, _optional: EmptyOptions = {}): void {
    if (owner === undefined) return;
    for (const phase of ALL_PHASES) {
      phaseRegistry[phase] = phaseRegistry[phase].filter((entry) => entry.owner !== owner);
    }
  }

  /**
   * Run one phase's handlers in registration order, first non-`null` outcome wins.
   *
   * A handler's fault policy is its own registration's {@link RegisterResolvePhaseOptions.onError}
   * (2026-09-16, t91 F4.3 — previously every throw was unconditionally isolated). `"skip"` logs the
   * failure and continues with the next handler, rather than propagating out of the phase — correct
   * for a handler whose failure can only DECLINE an outcome (a redirect, a gone), never fabricate
   * one, which is why Redirects opts into it (`redirects/phase-handler.ts`'s INV-03). `"fail"` (the
   * default) rethrows instead: a handler that guards content (a takedown, a reserved path) must not
   * silently wave a request through just because its own check broke. No log on the `"fail"` path —
   * the caller's own catch reports it (`routes/site/pages.ts`'s `reportSiteRenderFault`), so a fault
   * produces exactly one log line either way.
   *
   * The old universal-skip default is why a stale closed-database handler could take down `/` and
   * `/pricing` while `/products` (which runs no phase) kept serving — that direction (never let one
   * registrant 500 every route) is still correct for `"skip"`; it is just no longer assumed for
   * every registrant.
   *
   * @complexity O(h) in the phase's registered handlers, plus each handler's own
   * opaque cost; short-circuits on the first outcome or the first `"fail"`-policy throw.
   */
  async function runPhase(
    phase: RouteResolvePhaseName,
    path: string,
    ctx: RouteResolveContext
  ): Promise<RouteResolvePhaseOutcome | null> {
    // Snapshot: a handler is free to register or revoke during its own run, and
    // mutating the live array mid-iteration would silently skip a sibling.
    for (const { handler, onError } of [...phaseRegistry[phase]]) {
      let outcome: RouteResolvePhaseOutcome | null;
      try {
        outcome = await handler(path, ctx);
      } catch (err) {
        if (onError !== "skip") throw err;
        // The host retains its operator-facing route fault channel.
        required.ports.reportPhaseError({ message: `[routing] a ${phase} resolver failed for ${path} — skipping it`, error: err });
        continue;
      }
      if (outcome) return outcome;
    }
    return null;
  }

  /**
   * Run the forward resolution pipeline for an inbound request path.
   *
   * v0 behavior: normalize the path, run `pre_content` resolvers, then (with no
   * `content-resolve` step wired here — that is fixed core content lookup, out
   * of scope for this library) run `post_content` resolvers. Falls through to
   * `{ matched: false }` (404) if nothing resolves. This is a registration seam
   * for Redirects, not full pipeline behavior — no real rules exist yet.
   *
   * @complexity O(h) where h is the total number of registered phase handlers
   * that run before a match (or all of them, on a full miss); each handler's own
   * cost is opaque to this function.
   */
  async function resolve(
    required: ResolveRequired,
    _optional: ResolveOptional = {}
  ): Promise<RouteResolveResult> {
    const path = normalizePath(required.input.path);
    const ctx = required.input.ctx;

    const preOutcome = await runPhase("pre_content", path, ctx);
    if (preOutcome) return { matched: true, phase: "pre_content", outcome: preOutcome };

    // content-resolve: fixed core content lookup, not a registered phase of this
    // library in v0 — intentionally a no-op here (see file header).

    const postOutcome = await runPhase("post_content", path, ctx);
    if (postOutcome) return { matched: true, phase: "post_content", outcome: postOutcome };

    return { matched: false };
  }

  /**
   * Run only the `pre_content` phase for `path` (ADR-PIPE-009 Decision B / C-012).
   *
   * The Decision B seam: `resolve()`'s v0 shape bundles `pre_content` and
   * `post_content` back-to-back with no pause for a caller's own content
   * lookup in between. This additive, thin wrapper around the already-tested
   * module-private `runPhase()` lets a real site route run ONLY `pre_content`
   * before its own content lookup, and (separately) `runPostContentPhase` only
   * after that lookup has failed — exactly ADR-039 §1's documented pipeline
   * order (`pre_content -> content-resolve -> post_content`), which the single
   * `resolve()` export cannot reproduce when a real content lookup must run in
   * the middle. `resolve()`'s own SHAPE is UNCHANGED by this addition — this
   * paragraph is about these wrapper functions existing alongside it, not about
   * `resolve()`'s own throw behavior. Separately (2026-09-16, t91 F4.3):
   * `resolve()` now CAN reject when a `"fail"`-policy handler throws, exactly
   * like these wrappers — both go through the same `runPhase()`, which gained
   * that throw path in the same change. `resolve()` has no production caller
   * today (grep; only tests call it), so this is a latent property, not a
   * behavior change any caller currently observes.
   *
   * @complexity O(h) in registered `pre_content` handlers.
   */
  async function runPreContentPhase(
    { path, ctx }: { path: string; ctx: RouteResolveContext },
    _optional: EmptyOptions = {}
  ): Promise<RouteResolvePhaseOutcome | null> {
    return runPhase("pre_content", normalizePath(path), ctx);
  }

  /**
   * Run only the `post_content` phase for `path` (ADR-PIPE-009 Decision B / C-013).
   * See {@link runPreContentPhase}'s doc for the full rationale.
   *
   * @complexity O(h) in registered `post_content` handlers.
   */
  async function runPostContentPhase(
    { path, ctx }: { path: string; ctx: RouteResolveContext },
    _optional: EmptyOptions = {}
  ): Promise<RouteResolvePhaseOutcome | null> {
    return runPhase("post_content", normalizePath(path), ctx);
  }

  // ---------------------------------------------------------------------------
  // SlugChangeCapture slot (ADR-039 §4)
  // ---------------------------------------------------------------------------

  let boundSlugChangeCapture: SlugChangeCapture | undefined;

  /**
   * Bind the single `SlugChangeCapture` implementation the content write
   * chokepoint calls inside a rename transaction. Per ADR-039 Round-2
   * amendment 1, no slot implementation may be plugin-supplied — this function
   * has no plugin-facing registration path today, only a core composition-root
   * call site.
   *
   * Fail-closed nuance (Round-2 amendment 3), NOT enforced here: an absent
   * binding is only a safe no-op before Redirects is installed, or while
   * slug-preservation is disabled for the workspace. Once link-preservation is
   * enabled, a slug-changing rename with no bound capture MUST fail
   * `LINK_PRESERVATION_UNAVAILABLE` rather than silently skip the redirect —
   * that check belongs to the content write chokepoint (which knows whether
   * preservation is enabled) and to Redirects (neither exists in this repo
   * yet). This library only exposes the registration slot itself.
   *
   * @returns a disposer that unbinds exactly THIS registration: a no-op once a later call has bound
   * another implementation, so a stale composition torn down after a newer one booted cannot clear
   * the newer site's capture (the same identity scoping `registerResolvePhase`'s disposers use).
   */
  function registerSlugChangeCapture({ impl }: { impl: SlugChangeCapture }, _optional: EmptyOptions = {}): () => void {
    boundSlugChangeCapture = impl;
    return () => {
      if (boundSlugChangeCapture === impl) boundSlugChangeCapture = undefined;
    };
  }

  /** The currently bound `SlugChangeCapture`, or `undefined` if none is bound. */
  function getSlugChangeCapture(_required: EmptyOptions, _optional: EmptyOptions = {}): SlugChangeCapture | undefined {
    return boundSlugChangeCapture;
  }

  // ---------------------------------------------------------------------------
  // Test-only registry resets (deep-imported directly by this library's own
  // tests; deliberately NOT exported from index.ts's public barrel)
  // ---------------------------------------------------------------------------

  /** Restore all module-level registries to their v0 defaults. Test use only. */
  function resetRoutingRegistrationsForTests(_required: EmptyOptions, _optional: EmptyOptions = {}): void {
    namedRoutes.clear();
    for (const [name, path] of initialNamedRoutes) namedRoutes.set(name, path);
    phaseRegistry.pre_content = [];
    phaseRegistry.post_content = [];
    boundSlugChangeCapture = undefined;
  }
  return { entryPublicPath, getNamedRoute, getSlugChangeCapture, isActive, postPublicPath, registerNamedRoute, registerResolvePhase, registerSlugChangeCapture, resolve, runPostContentPhase, runPreContentPhase, unregisterResolvePhaseOwner, urlFor, resetRoutingRegistrationsForTests };
}

/**
 * @file Core type definitions for the host `routing` Tier-2 library (ADR-039 v0).
 *
 * Purpose:
 * Declares the `RouteTarget` vocabulary, the workspace-scoped resolve context,
 * the inverse-resolver result shape, the forward resolution pipeline's phase
 * vocabulary, and the `SlugChangeCapture` slot's payload shape. This is the one
 * place `entryRef | termRef | url | route` is defined — promoted from
 * Menus-local (ADR-029 §3) to routing-owned per ADR-039 §3, so Menus/SEO/
 * Redirects share one vocabulary instead of inventing three.
 *
 * How it relates to the project:
 * - `core/ports.ts` supplies the shared primitives (`UUID`, `ISODateTime`, …).
 * - `routing/ports.ts` declares the dependency shape `urlFor`/`isActive` need
 *   (the existing `PostRepoPort`, reused rather than duplicated).
 * - `routing/routing.ts` implements the resolve functions against these types.
 *
 * Architectural role:
 * INTERFACES + TYPES ONLY (no feature logic). ADR-039 v0 is deliberately the
 * minimal shape three other sections depend on; full permalink-structure
 * design is explicitly deferred (ADR-039 "Open").
 */
import type { JsonObject, UUID } from "@jini-ai/core/primitives";

// ---------------------------------------------------------------------------
// RouteTarget vocabulary (ADR-039 §3)
// ---------------------------------------------------------------------------

/** Discriminant values for {@link RouteTarget}. */
export type RouteTargetKind = "entryRef" | "termRef" | "url" | "route";

/**
 * A link to a content entry by id. Only `post` has a real resolver in this
 * repo today (ADR-039 v0); `contentType` is accepted for forward-compat with
 * future content types but is not required to resolve a post reference.
 */
export interface EntryRefTarget {
  readonly kind: "entryRef";
  readonly entryId: UUID;
  readonly contentType?: string;
}

/**
 * A link to a taxonomy term (category/tag archive).
 *
 * NOT resolvable today: taxonomy isn't implemented in this repo, and ADR-029's
 * Round-3 audit fold promoted "term-link schema" from an Open item to an
 * explicit Wave-1 acceptance blocker — ADR-022 §5's `entry_refs` covers
 * entry-to-entry references only, with no term-target schema yet (content-lib
 * sign-off owed). `urlFor`/`isActive` resolve every `termRef` target to `null`
 * until that schema lands; see the stub in `routing.ts`.
 */
export interface TermRefTarget {
  readonly kind: "termRef";
  readonly termId: UUID;
  readonly taxonomy: string;
}

/**
 * An external or site-relative URL, passed through as given (scheme-validated:
 * `javascript:`/`data:` are rejected and resolve to `null`, mirroring the
 * "unavailable → null" contract rather than throwing).
 */
export interface UrlTarget {
  readonly kind: "url";
  readonly href: string;
}

/** A named core route (e.g. `home`, `search`), resolved via the route registry. */
export interface RouteRefTarget {
  readonly kind: "route";
  readonly route: string;
  /** Optional static params; unused by the v0 registry, reserved for v0.1 param interpolation. */
  readonly params?: JsonObject;
}

/** v0 discriminated union of route targets (ADR-039 §3). */
export type RouteTarget = EntryRefTarget | TermRefTarget | UrlTarget | RouteRefTarget;

// ---------------------------------------------------------------------------
// Resolve context + inverse-resolver result (ADR-039 §2, Round-2 amendment 4)
// ---------------------------------------------------------------------------

/**
 * Workspace-scoped context threaded through every resolve call. `siteId`/
 * `locale`/`originKey` are reserved for multi-site/i18n v0.1 work (ADR-039
 * "Open"); only `workspaceId` is load-bearing today.
 *
 * `originOverride` is a stand-in for `core/origin` (ADR-040), which is being
 * built in parallel and does not exist yet. Once it lands, `canonicalUrl`
 * composition should read the verified origin from
 * `OriginRegistryPort.canonicalOrigin(ctx)` instead of this field.
 */
export interface RouteResolveContext {
  readonly workspaceId: UUID;
  readonly siteId?: string;
  readonly locale?: string;
  readonly originKey?: string;
  /**
   * TODO(ADR-040): compose canonicalUrl from OriginRegistryPort.canonicalOrigin(ctx)
   * once src/origin exists. Until then, a caller that knows the verified origin
   * may pass it here; absent, canonicalUrl falls back to the relative path.
   */
  readonly originOverride?: string;
}

/** Result of a successful inverse resolve — the shape Menus/SEO consume. */
export interface RouteUrl {
  readonly path: string;
  readonly canonicalUrl: string;
}

// ---------------------------------------------------------------------------
// Forward resolution pipeline (ADR-039 §1) — registration vocabulary
// ---------------------------------------------------------------------------

/**
 * The two registerable phases of the forward pipeline
 * (`normalize → pre_content → content-resolve → post_content → 404`).
 * `content-resolve` is fixed core content lookup and is not a registerable
 * phase of this library; it is out of scope for ADR-039 v0's registration
 * mechanism.
 */
export type RouteResolvePhaseName = "pre_content" | "post_content";

/** Terminal decision a phase resolver may return; anything else falls through. */
export type RouteResolvePhaseOutcome =
  | { readonly kind: "redirect"; readonly location: string; readonly statusCode: number }
  | { readonly kind: "resolved"; readonly path: string }
  | { readonly kind: "not_found" };

/**
 * A single phase resolver. Returns `null` to fall through to the next
 * registered resolver in the same phase (and eventually the next phase);
 * returns an outcome to short-circuit the pipeline (ADR-039 §1 invariant:
 * `pre_content` may only redirect/gone, never turn a resolvable live path
 * into a 404 — Round-2 amendment 5).
 */
export type RouteResolvePhaseHandler = (
  path: string,
  ctx: RouteResolveContext
) => Promise<RouteResolvePhaseOutcome | null>;

/** Final outcome of {@link resolve} after all phases have run. */
export type RouteResolveResult =
  | { readonly matched: false }
  | {
      readonly matched: true;
      readonly phase: RouteResolvePhaseName;
      readonly outcome: RouteResolvePhaseOutcome;
    };

// ---------------------------------------------------------------------------
// SlugChangeCapture slot (ADR-039 §4 + Round-2/Round-3 amendments)
// ---------------------------------------------------------------------------

/** Payload handed to the bound {@link SlugChangeCapture} inside the rename transaction. */
export interface SlugChangeCaptureInput {
  readonly workspaceId: UUID;
  readonly entryId: UUID;
  readonly oldPath: string;
  readonly newPath: string;
  readonly actor: UUID;
  readonly changeSetId?: UUID;
}

/**
 * The single named slot content's write chokepoint calls inside the rename
 * transaction (ADR-039 §4). Declared here by routing (content knows nothing of
 * redirects); implemented by the redirects library; wired by the composition
 * root. **No slot implementation may be plugin-supplied** (Round-2 amendment 1
 * — the slot is core-resident by definition).
 *
 * Constraints on any bound implementation (Round-2 amendment 2): idempotent by
 * `changeSetId`, no external I/O, no in-tx publish (an outbox row may be
 * written in-tx per the transactional-outbox pattern, but dispatch happens
 * post-commit), and a strict lock order of content row before redirect rows.
 *
 * Fail-closed nuance (Round-2 amendment 3, not enforced by this library):
 * absent binding is a no-op only before Redirects is installed, or while
 * slug-preservation is disabled for the workspace. Once link-preservation is
 * enabled, a slug-changing rename with no bound capture MUST fail
 * `LINK_PRESERVATION_UNAVAILABLE` rather than silently skip the redirect. That
 * enforcement belongs to the content write chokepoint (which knows whether
 * preservation is enabled) and to Redirects (which doesn't exist yet in this
 * repo) — this library only exposes the registration slot.
 */
export interface SlugChangeCapture {
  onSlugChange(input: SlugChangeCaptureInput): Promise<void>;
}

import type { OriginRegistryPort, VerifiedOrigin } from "@jini-ai/http-kit/verified-origin";
import { OriginNotVerifiedError } from "@jini-ai/http-kit/verified-origin";


/**
 * @file `toAbsoluteUrl`/`resolveWorkspaceOrigin` — the one seam that joins a workspace's verified
 * origin onto a site-relative path (SPEC-008 gap fix, 2026-09-03).
 *
 * Before this file existed, `canonical`, `og:url`, `og:image`, and `twitter:image` all emitted bare
 * paths (`/documentation`, `/m/{assetId}/...`) on both production and local — reproduced with
 * `curl` against both. A relative `rel="canonical"` is technically resolvable by a search engine
 * (it resolves against the page's own URL), but `og:url`/`og:image` MUST be absolute per the Open
 * Graph protocol: every social crawler and link-preview fetcher fails to resolve a relative one, so
 * link previews for the live site were silently broken.
 *
 * Root cause: `platform/routing/routing.ts`'s `composeCanonicalUrl` has carried a `TODO(ADR-040)`
 * since routing was built — "compose canonicalUrl from OriginRegistryPort.canonicalOrigin(ctx) once
 * src/origin exists" — but nothing ever wired it up once `src/origin` (now `features/origin`)
 * landed; `RouteResolveContext.originOverride` (the seam that TODO describes) is never populated by
 * any real caller. This file is that wiring, scoped to SEO's own two call sites
 * (`seo.ts`'s `resolveCanonical`/`resolveShareImages`, and `routes/site/pages.ts`'s
 * `buildExtraHead` for the entry-less home/page canonical) rather than a change to the shared
 * `routing` library itself — `urlFor`/`entryPublicPath`/`RouteResolverDeps` have call sites well
 * outside SEO's ownership (menus, redirects, post tool-registrations), so widening their signature
 * to do an async origin lookup on every call is a separate, larger change than this bug fix.
 *
 * ONE join point, not scattered string concatenation: every caller in this feature that needs an
 * absolute URL goes through {@link toAbsoluteUrl}.
 */

/** Renders a `VerifiedOrigin` as a base URL with no trailing slash (`https://example.com`,
 *  `https://example.com/site`, `http://localhost:3000`).
 *
 *  Local copy, not a shared import — `features/site-evidence/same-origin.ts`'s own
 *  `verifiedOriginToBaseUrl` (the same three-line join) documents why: `newsletter/unsubscribe.ts`,
 *  `newsletter/confirmation.ts`, `redirects/phase-handler.ts`, and `members/write-service.ts` each
 *  already keep a private copy rather than import one, because `features/origin` deliberately
 *  exports no shared formatter — promoting one is a cross-cutting change owned by that module, not
 *  by any one feature. This is the same established convention, not a new one. */
function originBaseUrl(origin: VerifiedOrigin): string {
  const authority = origin.port === undefined ? origin.host : `${origin.host}:${origin.port}`;
  return `${origin.scheme}://${authority}${origin.basePath ?? ""}`;
}

const ABSOLUTE_URL_PATTERN = /^[a-z][a-z0-9+.-]*:\/\//i;

/** Whether `value` already names a full URL (a scheme is present) rather than a site-relative path
 *  — mirrors `platform/routing/routing.ts`'s and `features/seo/media.ts`'s own local copies of the
 *  identical check (both pre-existing, both unexported, so this is a third local copy by the same
 *  convention {@link originBaseUrl} follows above, not a new pattern). */
function isAbsoluteUrl(value: string): boolean {
  return ABSOLUTE_URL_PATTERN.test(value) || value.startsWith("//");
}

/**
 * Joins `path` onto `origin`'s base URL, producing an absolute URL.
 *
 * - `path` already absolute (an author's cross-domain canonical override, EC-10, or an
 *   already-resolved `ogImage`/`twitterImage` ref) is returned UNCHANGED — never double-prefixed.
 * - `origin` absent (no verified origin registered for the workspace yet — the deliberate,
 *   disclosed degradation) returns `path` unchanged, matching today's relative-path behavior. Never
 *   fabricates a broken `undefined/path` URL.
 * - Never doubles the slash on the root path: `postPublicPath`'s own contract guarantees `path`
 *   always starts with exactly one `/` (the root case is the literal string `"/"`, never `""`), and
 *   {@link originBaseUrl} never ends in one, so plain concatenation cannot produce `//`.
 *
 * @complexity O(1).
 */
export function toAbsoluteUrl(required: { origin: VerifiedOrigin | undefined; path: string }, _optional: Record<string, never> = {}): string {
  const { origin, path } = required;
  if (isAbsoluteUrl(path)) return path;
  if (!origin) return path;
  return `${originBaseUrl(origin)}${path}`;
}

/**
 * Resolves the workspace's verified origin for {@link toAbsoluteUrl}, degrading to `undefined`
 * when none is registered yet (`OriginNotVerifiedError` — ADR-040's documented fail-closed
 * precondition on `canonicalOrigin`, not a bug). Any OTHER error is a real registry failure and is
 * rethrown rather than silently swallowed into the same degraded path.
 *
 * 2026-09-18 production sitemap fix: a `dev-capability`-sourced origin (always `http://localhost`,
 * per `origin/types.ts`'s own invariant) is ALSO degraded to `undefined` whenever this process is
 * running in production (`resolveRuntimeMode() === "production"`, which `fly.toml` sets). Root
 * cause this guards against: `server/runtime/composition/deps.ts`'s `seedDevCapabilityOrigin` call
 * used to be the origin registry's ONLY writer, and ran unconditionally on every boot, including
 * the Fly deployment's. Its first boot durably persisted `http://localhost:3000` into
 * `content.db`'s `origin_settings` table, and its own idempotent find-or-create contract (by
 * design, so a future real registration is never clobbered) means that row survives every later
 * boot too — it can never self-correct on its own. Every public SEO
 * document (`sitemap.xml`, `robots.txt`'s `Sitemap:` line, `canonical`, `og:url`, `og:image`) goes
 * through this one seam, so this is the one place that must refuse to let that row leak into a
 * document served to real crawlers. Degrading here reuses the SAME pre-existing "no verified
 * origin" relative-path fallback `toAbsoluteUrl` already had — never a fabricated origin, per
 * INV-07. Outside production (local dev, tests), a `dev-capability` origin still resolves as
 * before — its entire purpose is to let a dev server exercise absolute-URL code paths.
 *
 * STILL LOAD-BEARING after the 2026-09-18 registration work (`features/origin/configured-origin.ts`,
 * design note `ADS-memory/reports/2026-09-18-public-origin-registration-design.md`), which stopped
 * the dev seed from running in production at all. That change prevents NEW poisoned rows; it cannot
 * remove the one production's `content.db` already holds. Until the host's public URL is set on that
 * deployment (and `registerConfiguredOrigin` corrects the row on the next boot), this degradation
 * is the only thing keeping that row out of documents served to real crawlers. Do not delete it as
 * "now redundant".
 *
 * @param required.runtimeMode - Required host runtime mode; the port never chooses a deployment policy.
 * @complexity O(1) plus one `canonicalOrigin` lookup.
 */
export async function resolveWorkspaceOrigin(
  required: { originRegistry: OriginRegistryPort; workspaceId: string; runtimeMode: string },
  _optional: Record<string, never> = {}
): Promise<VerifiedOrigin | undefined> {
  const { originRegistry, workspaceId, runtimeMode } = required;
  try {
    const origin = await originRegistry.canonicalOrigin({ workspaceId });
    if (origin.source === "dev-capability" && runtimeMode === "production") return undefined;
    return origin;
  } catch (err) {
    if (err instanceof OriginNotVerifiedError) return undefined;
    throw err;
  }
}

/// <reference lib="dom" />
import type { HeadElement } from "../types.js";

/**
 * Applies the finalized head descriptors using the browser's text/attribute sinks. The caller
 * owns registration, deduplication and replacement of previous contributions. JSON-LD retains the
 * server serializer's `<` escape so an embedded closing script tag cannot become markup when the
 * document is serialized. Returns the inserted nodes so the caller can remove its contribution.
 * @complexity O(total descriptor text length), one element per descriptor.
 */
export function applyHeadElements(
  required: { elements: readonly HeadElement[] },
  optional: { document: Document }
): HTMLElement[] {
  const { document } = optional;
  const nodes = required.elements.map((element) => {
    switch (element.kind) {
      case "title": {
        const node = document.createElement("title");
        node.textContent = element.text;
        return node;
      }
      case "meta": {
        const node = document.createElement("meta");
        node.setAttribute("name", element.name);
        node.setAttribute("content", element.content);
        return node;
      }
      case "og": {
        const node = document.createElement("meta");
        node.setAttribute("property", element.property);
        node.setAttribute("content", element.content);
        return node;
      }
      case "link": {
        const node = document.createElement("link");
        node.setAttribute("rel", element.rel);
        node.setAttribute("href", element.href);
        if (element.hreflang) node.setAttribute("hreflang", element.hreflang);
        if (element.type) node.setAttribute("type", element.type);
        if (element.title) node.setAttribute("title", element.title);
        return node;
      }
      case "jsonld": {
        const node = document.createElement("script");
        node.setAttribute("type", "application/ld+json");
        node.textContent = JSON.stringify(element.data).replace(/</g, "\\u003c");
        return node;
      }
    }
  });
  document.head.append(...nodes);
  return nodes;
}

/**
 * @file SEO core type definitions (SPEC-008, ADR-PIPE-008).
 *
 * Types ONLY — no feature logic. Fills in the ADR-032 design-only stub with
 * the shapes ADR-PIPE-008 actually commits to. Deviations from the original
 * stub (state.spec.md §5 + ADR-PIPE-008 Context, all disclosed there):
 *  - No `baseUrl`/`seo.base_url` anywhere (INV-07 — single-origin-authority;
 *    every absolute URL comes from `routing.urlFor`'s `canonicalUrl`).
 *  - `RobotsPolicy` stays computed-only (`sitemapUrls` is never persisted);
 *    only `robotsRules: RobotsRule[]` is stored.
 *  - `SeoPermission`'s 5-string vocabulary is replaced by the single string
 *    `"admin.seo.manage"`, used directly at call sites (no type needed).
 *  - `SeoFieldDecl`/`SeoExpressionIndexDecl` (ADR-022 generic-entries-model
 *    registration vocabulary) are dropped — this feature stores overrides on
 *    the bespoke `posts.seo_ext_json` column (state.spec.md §0), not a
 *    generic ext-bag with a content-type field registry.
 *  - `HeadElement`/`HeadElementKey`/`PageHeadContext`/`PageHeadEntryRef` live
 *    canonically in `src/server/http/site/page-head.ts` (ADR-PIPE-008
 *    Decision §2 — the render seam is core-owned, not SEO-owned); as of
 *    2026-08-20 (RouteDeps-narrowing pass 3) this file holds a structural
 *    DUPLICATE of them, not a re-export — see the block comment just above
 *    their declarations below for why.
 */
import type { ISODateTime, JsonObject, UUID } from "@jini-ai/core/primitives";


/**
 * Structural duplicate of `server/http/site/page-head.ts`'s `HeadElement`/`HeadElementKey`/
 * `JsonLd`/`PageHeadContext`/`PageHeadEntryRef`/`PageHeadHook` — NOT a re-export, as of the
 * 2026-08-20 RouteDeps-narrowing pass 3 (`check:architecture`'s `backEdgesIntoServer` metric counts
 * a type-only `export type {...} from ".../server/..."` re-export as a real graph edge, same as any
 * other import — the `--ts-pre-compilation-deps` resolution `route-manifest.ts`'s own header already
 * documents for this exact shape of edge).
 *
 * OWNERSHIP IS UNCHANGED: `page-head.ts` still owns these types canonically. That is a settled,
 * deliberate decision — ADR-PIPE-008 Decision §2 explicitly considered and REJECTED keeping this
 * seam inside `src/seo/` ("Wrong ownership — a future non-SEO contributor [the feeds plugin, ADR-032
 * §4] would have to import the SEO module... couples the render layer to a feature module. Not
 * selected — ADR-032 itself frames this as the theme layer's seam, not SEO's."). Do not "fix" this
 * duplicate by turning it back into an import, and do not move these types into this file's own
 * canonical ownership — both would reopen that rejected alternative.
 *
 * `seo/page-head-contributor.ts` never calls `registerPageHeadContributor` itself (only
 * `server/app.ts` does, at boot) — it only builds a `PageHeadHook`-shaped VALUE, so nothing here
 * needs the nominal identity of the real types, only their structure.
 *
 * Drift safety net — verified empirically with two DIFFERENT perturbations, not asserted from one
 * (a claim this shape has been wrong before in this codebase). Both were applied to this file, typo
 * checked with `npx tsc -p tsconfig.json --noEmit`, and reverted:
 *
 * 1. Dropped `canonicalUrl` from this file's `PageHeadContext` (a field `page-head-contributor.ts`'s
 *    `handle` body actually reads). Failed immediately, INSIDE `seo/`, before ever reaching the
 *    wiring call: `page-head-contributor.ts(34,55): error TS2339: Property 'canonicalUrl' does not
 *    exist on type 'PageHeadContext'.` — an even earlier tripwire than the wiring call, for any
 *    drift that touches a field this file's own contributor actually uses.
 * 2. Changed `PageHeadEntryRef.ext`'s type here from `Record<string, unknown>` to `string` — a field
 *    NOTHING in `page-head-contributor.ts` reads, chosen specifically to test whether the wiring call
 *    is a genuinely independent backstop rather than redundant with case 1. It fired exactly there:
 *    `server/app.ts(796,5): error TS2345: Argument of type '...PageHeadHook' [seo/types.ts] is not
 *    assignable to parameter of type '...PageHeadHook' [server/http/site/page-head.ts]... Types of
 *    property 'ext' are incompatible. Type 'Record<string, unknown>' is not assignable to type
 *    'string'.` — at `registerPageHeadContributor(createSeoPageHeadHook(...))`, line 796.
 *
 * So the real guarantee is TWO-LAYERED: a drift in a field this contributor reads fails fast, inside
 * `seo/`, at the point of use; a drift in a field it does NOT read still fails, loudly, at the
 * `server/app.ts` wiring call — there is no incompatible-drift shape that both layers miss silently.
 */

/** JSON-LD is a plain JSON object graph (schema.org) — duplicate of `page-head.ts`'s `JsonLd`. */
export type JsonLd = JsonObject;

interface HeadElementBase {
  /** behavior.spec.md §2.1's fixed priority bands and dedup comparator — see `page-head.ts`'s own
   *  `HeadElementBase` doc for the full rule; unchanged here. */
  readonly priority: number;
}

/** Duplicate of `page-head.ts`'s `HeadElement` — see this file's own header for why. */
export type HeadElement =
  | (HeadElementBase & { readonly kind: "title"; readonly text: string })
  | (HeadElementBase & { readonly kind: "meta"; readonly name: string; readonly content: string })
  | (HeadElementBase & { readonly kind: "og"; readonly property: string; readonly content: string })
  | (HeadElementBase & {
      readonly kind: "link";
      readonly rel: string;
      readonly href: string;
      readonly hreflang?: string | undefined;
      /** MIME type, e.g. `application/rss+xml` on a feed's `rel="alternate"`. Part of the dedup key. */
      readonly type?: string | undefined;
      readonly title?: string | undefined;
    })
  | (HeadElementBase & { readonly kind: "jsonld"; readonly data: JsonLd });

/** Stable dedup key for a HeadElement — duplicate of `page-head.ts`'s `HeadElementKey`. */
export type HeadElementKey = string;

/** Duplicate of `page-head.ts`'s `PageHeadEntryRef` — see this file's own header for why. */
export interface PageHeadEntryRef {
  id: UUID;
  type: string;
  slug: string;
  title: string;
  status: string;
  publishedAt?: ISODateTime | undefined;
