/**
 * Narrows a `RuntimeAgentDef.streamFormat` string to the supported
 * families.
 * @param value - The def's raw `streamFormat` string.
 * @returns `true` when `value` is one of the JSON-stream-parser, ACP, pi-rpc, or plain formats this driver wires.
 * @complexity O(1) — fixed membership check.
 * @overallScore 100/100
 */
export function isSupportedStreamFormat(args: { readonly value: string }): args is { readonly value: SupportedStreamFormat } {
  const { value } = args;
  return (SUPPORTED_STREAM_FORMATS as readonly string[]).includes(value);
}

/**
 * The single source of truth for whether this executor can drive a def.
 *
 * It exists because that knowledge was previously reachable only by *calling* `run()` and inspecting
 * the failure. Anything that lists agents for a user to pick from — a discovery route, an agent
 * picker, a CLI healthcheck — needs the same answer *before* a run exists, and had no way to ask it.
 * The observable symptom was a consumer advertising an agent that its own executor then rejected the
 * instant it was selected.
 *
 * `run()` consumes this rather than re-checking the conditions itself, so the discovery-time answer
 * and the run-time guards cannot disagree. A predicate that merely duplicated the guards would be
 * the same bug in a second location.
 *
 * @param def - The def to assess. Must be the **full** `RuntimeAgentDef`, not a projected
 * `DetectedAgent`: that type omits `maxPromptArgBytes`, one of the three prompt-delivery signals
 * checked here, so the argv-bound defs (`aider`, `deepseek`) would be misjudged as unsupported.
 * @returns A discriminated result — see {@link AgentExecutorCompatibility}. The `reason` text is
 * operator-facing and is what `run()` reports as its `AGENT_RUNTIME_UNSUPPORTED` message.
 * @complexity O(1) — fixed field checks.
 * @overallScore 100/100
 */
export function assessAgentExecutorCompatibility({ def }: { readonly def: RuntimeAgentDef }): AgentExecutorCompatibility {
  const format = { value: def.streamFormat };
  if (!isSupportedStreamFormat(format)) {
    return {
      supported: false,
      reason: `AgentExecutor: agent "${def.id}" has streamFormat "${format.value}", which is not implemented in v1 — only ${SUPPORTED_STREAM_FORMATS.join(', ')} are supported`,
    };
  }
  const streamFormat = format.value;
  if (
    streamFormat !== 'acp-json-rpc' &&
    def.promptViaStdin !== true &&
    def.promptViaFile !== true &&
    typeof def.maxPromptArgBytes !== 'number'
  ) {
    return {
      supported: false,
      reason: `AgentExecutor: agent "${def.id}" does not deliver its prompt via stdin, a staged prompt file, or a byte-budgeted argv — v1 has no other prompt delivery path`,
    };
  }
  return { supported: true, streamFormat };
}

/**
 * Whether `run()` can actually drive this def — the discovery-time counterpart to the guards inside
 * `run()`, so a consumer never offers a user an agent that fails the moment it is selected.
 *
 * @param def - The full `RuntimeAgentDef`; see {@link assessAgentExecutorCompatibility} for why a
 * projected `DetectedAgent` is not sufficient.
 * @returns `true` when this executor would attempt the run.
 * @complexity O(1).
 * @overallScore 100/100
 */
export function isAgentExecutorSupported({ def }: { readonly def: RuntimeAgentDef }): boolean {
  return assessAgentExecutorCompatibility({ def: def }).supported;
}

/**
 * Drops `undefined` values so `NodeJS.ProcessEnv` (whose values are
 * `string | undefined`) can feed `resolveAgentLaunch`'s
 * `Record<string, string>` parameter.
 * @param env - The source environment (the caller-supplied `input.env` escape hatch — the
 * default path builds its env via `buildAgentEnv` instead, never this function on `process.env`).
 * @returns A new object containing only the string-valued entries.
 * @complexity O(n) in the number of env entries.
 * @overallScore 100/100
 */
function toStringEnvRecord(env: NodeJS.ProcessEnv): Record<string, string> {
  const result: Record<string, string> = {};
  for (const [key, value] of Object.entries(env)) {
    if (typeof value === 'string') result[key] = value;
  }
  return result;
}

/** Snapshot only host configuration used by spawn and config staging; credentials stay per-run.
 * Returns an independent allowlisted record. @complexity O(1), fixed key list. */
export function selectAgentExecutorHostEnv({ env }: { env: NodeJS.ProcessEnv }, { runtimeState }: { runtimeState?: AgentRuntimeState } = {}): NodeJS.ProcessEnv {
  const selected = buildAgentEnv({ hostEnv: env });
  for (const key of ['CODEX_HOME', 'CLAUDE_CONFIG_DIR', 'VELA_OPENCODE_BIN', 'AGENT_RUNTIME_HOME', 'AGENT_RUNTIME_RESOURCE_ROOT', 'VP_HOME', 'NPM_CONFIG_PREFIX', 'npm_config_prefix', 'APPDATA', 'LOCALAPPDATA', 'MISE_DATA_DIR', 'FNM_DIR'] as const) {
    if (typeof env[key] === 'string') selected[key] = env[key];
  }
  // Host-configured resolution names are explicit configuration, never a scan of the env bag.
  const state = runtimeState ?? defaultRuntimeState;
  for (const key of Object.values(state.executable.envNames)) {
    if (typeof env[key] === 'string') selected[key] = env[key];
  }
  return selected;
}

/**
 * Resolves once `child` emits `'spawn'`, or rejects on `'error'`. Replicates
 * `@jini-ai/platform`'s own internal (non-exported) `waitForChildSpawn` race
 * idiom inline — see that module's `spawnLoggedProcess`/`spawnBackgroundProcess`.
 * @param child - The just-spawned `ChildProcess` to race.
 * @returns A promise settling on the first of `'spawn'`/`'error'` to fire.
 * @complexity O(1) — two one-time listener registrations.
 * @overallScore 100/100
 */
function waitForSpawnOrError(child: ChildProcess): Promise<void> {
  return new Promise((resolve, reject) => {
    child.once('error', reject);
    child.once('spawn', resolve);
  });
}

interface ResolvedAgentRuntimeDeps {
  readonly getAgentDef: typeof getAgentDef;
  readonly resolveAgentLaunch: typeof resolveAgentLaunch;
  readonly ensureAgentCapabilities: typeof ensureAgentCapabilities;
  readonly applyAgentLaunchEnv: typeof applyAgentLaunchEnv;
  readonly attachAcpSession: typeof attachAcpSession;
  readonly attachPiRpcSession: typeof attachPiRpcSession;
  readonly preparePromptFileForAgent: typeof preparePromptFileForAgent;
  readonly prepareAgentLogFile: typeof prepareAgentLogFile;
}

/**
 * Resolves `CreateAgentExecutorOptions`' agent-runtime collaborator seams (registry lookup, launch
 * resolution, ACP/pi-rpc session attachment, prompt/log file staging) to their real
 * `@jini-ai/agent-runtime` defaults. Split out of `createAgentExecutor` together with
 * {@link resolveProcessDeps}/{@link resolveMiscExecutorDeps}: a flat 14-line `options.x ?? default`
 * sequence was that function's entire cyclomatic-complexity excess (one branch point per default) —
 * grouping the same defaults by concern keeps each resulting function's own complexity low without
 * hiding which options belong together. Pure.
 */
function resolveAgentRuntimeDeps(
  options: CreateAgentExecutorOptions & { readonly hostEnv: NodeJS.ProcessEnv; readonly piGracefulShutdownMs: number },
): ResolvedAgentRuntimeDeps {
  const runtimeOptions = options.runtimeState ? { state: options.runtimeState } : {};
  // `createAgentExecutor` always resolves both before calling here (host env falls back to the
  // process env, the pi shutdown grace to its env override or 5000 ms), so neither is optional.
  const envOptions = { env: options.hostEnv };
  const lookupDef = options.getAgentDef ?? getAgentDef;
  return {
    getAgentDef: (input) => {
      const def = lookupDef(input);
      // Without owned state, only an enabled plugin policy needs binding; otherwise keep the published definition.
      if (!def || (!options.runtimeState && !options.codexDisablePlugins)) return def;
      return bindRuntimeAgentDef({ def, state: options.runtimeState ?? defaultRuntimeState }, options.codexDisablePlugins ? { codexDisablePlugins: true } : {});
    },
    resolveAgentLaunch: options.resolveAgentLaunch ?? ((input, optional = {}) => resolveAgentLaunch(input, { ...optional, ...runtimeOptions, ...envOptions })),
    ensureAgentCapabilities: options.ensureAgentCapabilities ?? ((input) => ensureAgentCapabilities(input, runtimeOptions)),
    applyAgentLaunchEnv: options.applyAgentLaunchEnv ?? ((input, optional = {}) => applyAgentLaunchEnv(input, { appendPathDirs: userToolchainBinDirs({}, { ...runtimeOptions, ...envOptions }), ...optional })),
    attachAcpSession: options.attachAcpSession ?? attachAcpSession,
    attachPiRpcSession: (required, optional = {}) => (options.attachPiRpcSession ?? attachPiRpcSession)(required, {
      ...optional, gracefulShutdownMs: options.piGracefulShutdownMs,
    }),
    preparePromptFileForAgent: options.preparePromptFileForAgent ?? preparePromptFileForAgent,
    prepareAgentLogFile: options.prepareAgentLogFile ?? prepareAgentLogFile,
  };
}

interface ResolvedProcessDeps {
  readonly createCommandInvocation: typeof createCommandInvocation;
  readonly spawn: typeof nodeSpawn;
  readonly listProcessSnapshots: typeof listProcessSnapshots;
  readonly collectProcessTreePids: CollectProcessTreePidsPort;
  readonly stopProcesses: StopProcessesPort;
}

/** Resolves the OS-process-facing collaborator seams — see {@link resolveAgentRuntimeDeps}'s doc. Pure. */
function resolveProcessDeps(options: CreateAgentExecutorOptions): ResolvedProcessDeps {
  return {
    createCommandInvocation: options.createCommandInvocation ?? createCommandInvocation,
    spawn: options.spawn ?? nodeSpawn,
    listProcessSnapshots: options.listProcessSnapshots ?? listProcessSnapshots,
    collectProcessTreePids: options.collectProcessTreePids ?? (({ processes, rootPids }) => collectProcessTreePids(processes, rootPids)),
    stopProcesses: options.stopProcesses ?? (({ pids }) => stopProcesses(pids)),
  };
}

interface ResolvedMiscExecutorDeps {
  readonly onCleanupFailure: (context: AgentCleanupFailureContext) => void;
  readonly bufferedStdoutMaxBytes: number;
}

/** Resolves the two remaining defaultable options — see {@link resolveAgentRuntimeDeps}'s doc. Pure. */
function resolveMiscExecutorDeps(options: CreateAgentExecutorOptions): ResolvedMiscExecutorDeps {
  return {
    onCleanupFailure: options.onCleanupFailure ?? defaultCleanupFailureSink,
    bufferedStdoutMaxBytes: options.bufferedStdoutMaxBytes ?? DEFAULT_BUFFERED_STDOUT_MAX_BYTES,
  };
}

// ---------------------------------------------------------------------------
// run() phases
//
// `run()` itself (below `createAgentExecutor`) was a single ~400-line function
// (cyclomatic 63 / cognitive 49) sequencing ~15 guarded pre-spawn steps. Each
// phase here owns one step's decision logic and, where the original step could
// fail, its own `failBeforeSpawn`/`releaseStagedResources` call — so `run()`
// reads as a flat sequence of `const x = await phase(...)` statements with no
// guard clauses of its own. A phase that can fail is typed to return the
// success shape and internally `return deps.failBeforeSpawn(...)` (a
// `Promise<never>`, assignable to any return type) on failure; since
// `failBeforeSpawn` always rejects, `run()` never needs to check the result —
// the `await` alone propagates the rejection exactly as the original inline
// `return failBeforeSpawn(...)` did. Every phase takes its collaborators as
// explicit parameters (no closures over `createAgentExecutor`'s scope), so
// each is independently constructible and testable.
// ---------------------------------------------------------------------------

interface ResolvedDefAndFormat {
  readonly def: RuntimeAgentDef;
  readonly streamFormat: SupportedStreamFormat;
}

/** Phase 1: registry lookup + `assessAgentExecutorCompatibility` guard. */
export async function resolveDefAndStreamFormat({ input, deps }: { readonly input: Pick<AgentExecutorRunInput, 'runId' | 'agentId'>; readonly deps: { readonly getAgentDef: typeof getAgentDef; readonly failBeforeSpawn: FailBeforeSpawn } }
): Promise<ResolvedDefAndFormat> {
  const def = deps.getAgentDef({ id: input.agentId });
  if (!def) {
    return deps.failBeforeSpawn({ runId: input.runId, code: 'AGENT_NOT_FOUND', message: `AgentExecutor: unknown agentId "${input.agentId}"` });
  }
  const compatibility = assessAgentExecutorCompatibility({ def: def });
  if (!compatibility.supported) {
    return deps.failBeforeSpawn({ runId: input.runId, code: 'AGENT_RUNTIME_UNSUPPORTED', message: compatibility.reason });
  }
  return { def, streamFormat: compatibility.streamFormat };
}

/** Phase 2: image-prompt-delivery augmentation + argv-budget guard for argv-bound defs. */
export async function resolveImageDeliveryAndArgvBudget({ input, deps }: { readonly input: {
    readonly runId: string;
    readonly def: RuntimeAgentDef;
    readonly prompt: string;
    readonly imagePaths: readonly string[] | undefined;
    readonly extraAllowedDirs: readonly string[] | undefined;
  }; readonly deps: { readonly failBeforeSpawn: FailBeforeSpawn } }
): Promise<ImagePromptDelivery> {
  const imageDelivery = applyImagePromptDelivery({ imageDelivery: input.def.imageDelivery, prompt: input.prompt, imagePaths: input.imagePaths, extraAllowedDirs: input.extraAllowedDirs });
  const argvBudgetError = checkPromptArgvBudget({ def: input.def, composed: imageDelivery.prompt });
  if (argvBudgetError) {
    return deps.failBeforeSpawn({ runId: input.runId, code: 'AGENT_PROMPT_TOO_LARGE', message: argvBudgetError.message });
  }
  return imageDelivery;
}

/**
 * Phase 3a: the subprocess environment this run's launch resolution and spawn should use — the
 * caller-supplied escape hatch verbatim, or the deny-by-default `BASELINE_AGENT_ENV_KEYS` allowlist.
 * Pure.
 */
export function resolveRunEnv({ input, hostEnv }: { readonly input: Pick<AgentExecutorRunInput, 'env' | 'credentialEnv'>; readonly hostEnv: NodeJS.ProcessEnv }
): Record<string, string> {
  return input.env !== undefined ? toStringEnvRecord(input.env) : buildAgentEnv({ hostEnv }, { credentialEnv: input.credentialEnv });
}

/** A resolved launch whose `launchPath` is confirmed non-null — see {@link resolveLaunch}. */
type ConfirmedAgentLaunchResolution = AgentLaunchResolution & { readonly launchPath: string };

/** Phase 3b: launch-path resolution + binary-not-resolved guard. */
export async function resolveLaunch({ input, deps }: { readonly input: { readonly runId: string; readonly def: RuntimeAgentDef; readonly resolvedEnv: Record<string, string> }; readonly deps: { readonly resolveAgentLaunch: typeof resolveAgentLaunch; readonly failBeforeSpawn: FailBeforeSpawn } }
): Promise<ConfirmedAgentLaunchResolution> {
  const launch = deps.resolveAgentLaunch({ def: input.def }, { configuredEnv: input.resolvedEnv });
  if (!launch.launchPath) {
    return deps.failBeforeSpawn(
      { runId: input.runId, code: 'AGENT_BINARY_NOT_RESOLVED', message: `AgentExecutor: could not resolve an executable for agent "${input.def.id}" (bin "${input.def.bin}")` },
    );
  }
  // Narrowed by the guard above; `resolveAgentLaunch`'s own return type still declares
  // `launchPath: string | null` since it can't know this call site already checked.
  return launch as ConfirmedAgentLaunchResolution;
}

/** Phase 4a: stage a `promptViaFile` def's prompt to a temp file (a no-op for every other def). */
export async function stagePromptFile({ input, deps }: { readonly input: { readonly runId: string; readonly def: RuntimeAgentDef; readonly prompt: string }; readonly deps: { readonly preparePromptFileForAgent: typeof preparePromptFileForAgent; readonly failBeforeSpawn: FailBeforeSpawn } }
): Promise<PreparedPromptFile | null> {
  try {
    return await deps.preparePromptFileForAgent({ def: input.def, prompt: input.prompt, label: input.runId });
  } catch (err) {
    return deps.failBeforeSpawn(
      { runId: input.runId, code: 'AGENT_SPAWN_FAILED', message: `AgentExecutor: could not stage a prompt file for agent "${input.def.id}": ${errorMessage(err)}` },
    );
  }
}

/** Phase 4b: stage a `needsAgentLogFile` def's diagnostic-log path (a no-op for every other def). */
export async function stageLogFile({ input, deps }: { readonly input: { readonly runId: string; readonly def: RuntimeAgentDef; readonly preparedPromptFile: PreparedPromptFile | null }; readonly deps: { readonly prepareAgentLogFile: typeof prepareAgentLogFile; readonly failBeforeSpawn: FailBeforeSpawn } }
): Promise<PreparedAgentLogFile | null> {
  try {
    return await deps.prepareAgentLogFile({ def: input.def, label: input.runId });
  } catch (err) {
    await (input.preparedPromptFile ? input.preparedPromptFile.cleanup() : Promise.resolve());
    return deps.failBeforeSpawn(
      { runId: input.runId, code: 'AGENT_SPAWN_FAILED', message: `AgentExecutor: could not stage a log file for agent "${input.def.id}": ${errorMessage(err)}` },
    );
  }
}

/**
 * Phase 6a/10c: the subprocess environment every env-riding mechanism uses — mechanism 3+4
 * (`'opencode-env-content'`/`'mimo-env-content'`, merged into whatever the host already set there,
 * never a CLI argument: the config embeds `JINI_DAEMON_TOKEN`, and process arguments are readable
 * by any other local user through `ps`), mechanism 5 (`'codex-toml'`, `CODEX_HOME` relocation),
 * mechanism 6 (`'env-passthrough'`, the bridge entry's flat env vars set directly with no carrier
 * document — see {@link McpBridgeDelivery}'s own doc), a
 * `systemPromptDelivery: 'env-var'` def's overlay (`reasonix`'s `REASONIX_ACP_SYSTEM_APPEND` today
 * — see `resolveSystemPromptOverlayDelivery`'s own doc), and a `'config-instructions-file'` def's
 * staged overlay file (`opencode` today — see {@link mergeEnvContentInstructions}'s own doc). Pure
 * — `codexHomeDir` and `stagedInstructionsFile` arrive already staged by
 * {@link prepareCodexHomeIfNeeded} and {@link prepareSystemPromptOverlayFileIfNeeded} respectively,
 * the only parts of this mechanism that are NOT pure (real `mkdtemp`/`writeFile` calls).
 * @param spawnEnv - The env every other spawn-time step (launch-path resolution, `applyAgentLaunchEnv`) already computed.
 * @param mcpBridge - This run's resolved bridge delivery, or `null` for an unconfigured host / no-strategy def.
 * @param codexHomeDir - The staged scratch `CODEX_HOME` path for a `'codex-toml'` def, or `undefined` for every other run (including a `'codex-toml'` def when `mcpJsonInjection` was never configured — see `prepareCodexHomeIfNeeded`'s own gate).
 * @param systemPromptEnvOverrides - `resolveSystemPromptOverlayDelivery`'s `envOverrides` — `{}` (default) for every def but an `'env-var'`-strategy one with an overlay present, in which case it carries that one var. Applied after `codexHomeDir`, so it can never be shadowed by it — the two never share a key (`CODEX_HOME` vs. e.g. `REASONIX_ACP_SYSTEM_APPEND`), so the ordering is a documentation choice, not a correctness one.
 * @param stagedInstructionsFile - `varName` (from the def's own `systemPromptDelivery` declaration) and the staged overlay file's `path`, or `undefined` for every def but a `'config-instructions-file'` one with an overlay present. Merged into `varName`'s value AFTER the `mcp` merge above (reading `envContentApplied`, not the original `spawnEnv`, for that same key) so both a `mcp` entry and an `instructions` entry from the two mechanisms survive together in one document — confirmed live this coexistence is safe (see {@link mergeEnvContentInstructions}'s doc).
 * @complexity O(1) plus `mergeEnvContentMcpConfig`'s and `mergeEnvContentInstructions`'s own `JSON.parse`/`JSON.stringify` cost.
 * @overallScore 100/100
 */
export function computeChildEnv({ spawnEnv, mcpBridge }: { readonly spawnEnv: NodeJS.ProcessEnv; readonly mcpBridge: McpBridgeDelivery | null }, { codexHomeDir, systemPromptEnvOverrides, stagedInstructionsFile, claudeConfigDir }: { readonly codexHomeDir?: string; readonly systemPromptEnvOverrides?: Readonly<Record<string, string>>; readonly stagedInstructionsFile?: { readonly varName: string; readonly path: string }; readonly claudeConfigDir?: string } = {}
): NodeJS.ProcessEnv {
  const envContentApplied =
    mcpBridge?.kind === 'env-content'
      ? {
          ...spawnEnv,
          [mcpBridge.envVarName]: mergeEnvContentMcpConfig({ existingRaw: spawnEnv[mcpBridge.envVarName], entry: mcpBridge.serverEntry }),
        }
      : spawnEnv;
  // `'env-passthrough'` (antigravity): no document, no named carrier variable — the bridge
  // entry's own `env` keys (`JINI_RUN_ID`/`JINI_DAEMON_URL`/`JINI_DAEMON_TOKEN`) are set directly
  // on the child's environment, for the spawned CLI to inherit down to its own globally
  // pre-registered MCP child in turn. See `McpBridgeDelivery`'s own doc for why this def has no
  // config document to merge into at all.
  const envPassthroughApplied =
    mcpBridge?.kind === 'env-passthrough' ? { ...envContentApplied, ...mcpBridge.serverEntry.env } : envContentApplied;
  const instructionsApplied =
    stagedInstructionsFile === undefined
      ? envPassthroughApplied
      : {
          ...envPassthroughApplied,
          [stagedInstructionsFile.varName]: mergeEnvContentInstructions({ existingRaw: envPassthroughApplied[stagedInstructionsFile.varName], instructionsFilePath: stagedInstructionsFile.path }
          ),
        };
  const codexHomeApplied = codexHomeDir === undefined ? instructionsApplied : withStagedCodexHome({ env: instructionsApplied, codexHomeDir });
  // Finding 1 of SEC-assistant-env-isolation-2026-09-07: same "only set when staged" shape as
  // codexHomeApplied above — mutually exclusive with it in practice (codexHomeDir is only ever set
  // for a 'codex-toml' bridge, claudeConfigDir only ever for a `claude`-id run), so both existing
  // side by side here is a documentation convenience, not a real collision risk.
  const claudeConfigDirApplied =
    claudeConfigDir === undefined ? codexHomeApplied : { ...codexHomeApplied, CLAUDE_CONFIG_DIR: claudeConfigDir };
  return systemPromptEnvOverrides === undefined ? claudeConfigDirApplied : { ...claudeConfigDirApplied, ...systemPromptEnvOverrides };
}

/** Session fields use the same nonempty-string rule as the CLI buildArgs boundary. */
function sessionRuntimeContext(
  { resumeSessionId, newSessionId }: { resumeSessionId?: string | null | undefined; newSessionId?: string | undefined }, _options = {},
): Pick<RuntimeContext, 'resumeSessionId' | 'newSessionId'> {
  // Matches claude.ts buildArgs' own `typeof x === 'string' && x` truthiness check, so an empty
  // string or explicit `null` (no resume target yet) is treated as absent here too, rather than
  // manufacturing a context that carries a session field the def would ignore anyway.
  return {
    ...(typeof resumeSessionId === 'string' && resumeSessionId.length > 0 ? { resumeSessionId } : {}),
    ...(typeof newSessionId === 'string' && newSessionId.length > 0 ? { newSessionId } : {}),
  };
}

/**
 * Phase 6b: the `RuntimeContext` `buildArgs` receives — `undefined` unless a file, bridge path, or
 * session id was staged. Pure.
 *
 * `resumeSessionId`/`newSessionId` round-trip a prior run's `RunEndPayload.sessionRef` (see
 * `@jini-ai/protocol`'s doc on that field) back into this run's `RuntimeContext`, letting a
 * `resumesSessionViaCli` def (e.g. claude) continue its own CLI session across turns instead of
 * spawning cold every time. Either one alone must still produce a context — a run supplying ONLY a
 * session id, with no prompt/log file staged and no claude-mcp-json bridge, is exactly the common
 * case for a resumed turn.
 */
export function computeRuntimeContext({ preparedPromptFile, preparedLogFile, mcpBridge }: { readonly preparedPromptFile: PreparedPromptFile | null; readonly preparedLogFile: PreparedAgentLogFile | null; readonly mcpBridge: McpBridgeDelivery | null }, { resumeSessionId, newSessionId }: { readonly resumeSessionId?: string | null; readonly newSessionId?: string } = {}
): RuntimeContext | undefined {
  const context: RuntimeContext = {
    ...(preparedPromptFile ? { promptFilePath: preparedPromptFile.path } : {}),
    ...(preparedLogFile ? { agentLogFilePath: preparedLogFile.path } : {}),
    // Safe to pass before the file exists: `writeMcpJsonForRun` runs after buildArgs but still
    // before spawn, so the path is real by the time the child process starts.
    ...(mcpBridge?.kind === 'claude-mcp-json' ? { mcpJsonPath: mcpBridge.mcpJsonPath } : {}),
    ...sessionRuntimeContext({ resumeSessionId, newSessionId }, {}),
  };
  return Object.keys(context).length === 0 ? undefined : context;
}

/**
 * Phase 8: the host's `PromptAugmenter.systemOverlay()` result, if configured — see
 * `CreateAgentExecutorOptions.promptAugmenter`'s doc for `turnIndex`'s coarse 0/1 proxy.
 */
function computeSystemPromptOverlay(
  promptAugmenter: PromptAugmenter | undefined,
  agentId: string,
): string | null | undefined {
  // Always turn 0: the only prior-turn signal, `RuntimeContext.hasPriorAssistantTurn`, is never
  // populated by `computeRuntimeContext` (it carries staged-file, MCP and session-id fields only).
  return promptAugmenter?.systemOverlay?.({ agentId, turnIndex: 0 });
}

type AgentBuildInput = Parameters<typeof buildAgentBuildArgsOptions>[0]['input'];

/** Native policy forwarding also enforces parity's permission and tool-access prerequisites. */
function nativeBuildOptions({ input, permissionMode }: { input: AgentBuildInput; permissionMode: 'restricted' | 'bypass' }, _options = {}): RuntimeBuildOptions {
  return {
    ...(input.nativeToolAccess !== undefined ? { nativeToolAccess: input.nativeToolAccess } : {}),
    ...(input.nativeCapabilities ? { nativeCapabilities: input.nativeCapabilities } : {}),
    ...(input.cliParity === true && permissionMode === 'bypass' && input.nativeToolAccess !== false ? { cliParity: true } : {}),
  };
}

/** Forward only supplied confinement paths; empty restriction arrays remain meaningful.
 * Keeps executor-resolved filesystem facts through the definition's second settings merge. Pure, O(1).
 */
function filesystemBuildOptions({ input }: { input: AgentBuildInput }, _options = {}): RuntimeBuildOptions {
  return {
    ...(input.filesystemRoot !== undefined ? { filesystemRoot: input.filesystemRoot } : {}),
    ...(input.filesystemSharedTempRoots ? { filesystemSharedTempRoots: input.filesystemSharedTempRoots } : {}),
    ...(input.filesystemTempDir ? { filesystemTempDir: input.filesystemTempDir } : {}),
    ...(input.filesystemRuntimeReadPaths ? { filesystemRuntimeReadPaths: input.filesystemRuntimeReadPaths } : {}),
    ...(input.filesystemRuntimeTempBase !== undefined ? { filesystemRuntimeTempBase: input.filesystemRuntimeTempBase } : {}),
    // Only while a folder limit applies: an unconfined CLI gets no extra grant, read-only or otherwise.
    ...(input.filesystemRoot !== undefined && input.readOnlyExtraDirs?.length ? { filesystemReadOnlyDirs: input.readOnlyExtraDirs } : {}),
  };
}

/** Preserve explicit empty restrictions and settings: they have meaning to the native CLI. */
function settingsBuildOptions({ input }: { input: AgentBuildInput }, _options = {}): RuntimeBuildOptions {
  return {
    ...filesystemBuildOptions({ input }),
    ...(input.disallowedTools !== undefined ? { disallowedTools: input.disallowedTools } : {}),
    ...(input.allowedTools !== undefined ? { allowedTools: input.allowedTools } : {}),
    ...(input.settingSources !== undefined ? { settingSources: input.settingSources } : {}),
    ...(input.settings !== undefined ? { settings: input.settings } : {}),
    ...(input.chromeIntegration !== undefined ? { chromeIntegration: input.chromeIntegration } : {}),
  };
}

/** A relay needs both a delivered bridge and a runtime that understands it. Pure, O(1). */
function canRegisterRunMessageRelay({ def, mcpBridge }: {
  def: RuntimeAgentDef; mcpBridge: McpBridgeDelivery | null;
}, _options = {}): boolean {
  return mcpBridge !== null && supportsMessageRelay({ def });
}

/** Phase 9a: the def's `buildArgs` 4th argument. Historically omitted when every override was absent;
 * that let defs silently enable auto-approval. Always supply the validated restricted default now. Pure. */
export function buildAgentBuildArgsOptions({ input, systemPromptOverlay }: { readonly input: Pick<AgentExecutorRunInput, 'filesystemRoot' | 'readOnlyExtraDirs' | 'model' | 'reasoning' | 'permissionMode' | 'nativeToolAccess' | 'nativeCapabilities' | 'cliParity' | 'disallowedTools' | 'allowedTools' | 'settingSources' | 'settings' | 'chromeIntegration'> & { filesystemRuntimeReadPaths?: readonly string[]; filesystemTempDir?: string; filesystemSharedTempRoots?: readonly string[]; filesystemRuntimeTempBase?: string; filesystemNotice?: string }; readonly systemPromptOverlay: string | null | undefined }, _options = {}
): RuntimeBuildOptions {
  const permissionMode = input.permissionMode ?? 'restricted';
  if (permissionMode !== 'restricted' && permissionMode !== 'bypass') {
    throw new AgentExecutorError({ code: 'AGENT_PERMISSION_MODE_INVALID', message: 'AgentExecutor: permissionMode must be restricted or bypass' });
  }
  const hasOverlay = systemPromptOverlay !== undefined && systemPromptOverlay !== null;
  const options: RuntimeBuildOptions = {
    ...(input.model !== undefined ? { model: input.model } : {}),
    ...(input.reasoning !== undefined ? { reasoning: input.reasoning } : {}),
    permissionMode,
    ...nativeBuildOptions({ input, permissionMode }, {}),
    ...settingsBuildOptions({ input }, {}),
    ...(hasOverlay ? { systemPromptOverlay } : {}),
  };
  return options;
}

function hasSystemPromptOverlay(args: { overlay: string | null | undefined }, _options = {}): args is { overlay: string } {
  return typeof args.overlay === 'string' && args.overlay.length > 0;
}

function appendFlagOverlay({ defId, systemPromptDelivery, overlay, prompt }: {
  defId: string; systemPromptDelivery: Extract<NonNullable<RuntimeAgentDef['systemPromptDelivery']>, { strategy: 'append-flag' }>;
  overlay: string; prompt: string;
}, { state }: { state?: AgentRuntimeState | undefined } = {}): SystemPromptOverlayDelivery {
  const capabilityKey = systemPromptDelivery.capabilityKey;
  // `!== false`, not a truthiness check: mirrors `claude.ts`'s own pre-existing
  // `agentCapabilities.get('claude') || {}` gate exactly (moved here, not changed) — an
  // undetected/never-probed capability defaults to allowed, and only an EXPLICIT `false` (the
  // `--help` probe ran and did not find the flag) withholds it. `capabilityKey === undefined`
  // (e.g. `pi`'s existing `--append-system-prompt`, trusted unconditionally) always passes, same
  // as an absent key.
  const capabilityOk = capabilityKey === undefined || (state?.capabilities ?? agentCapabilities).get(defId)?.[capabilityKey] !== false;
  return { promptPrefix: '', prompt, extraArgs: capabilityOk ? [systemPromptDelivery.flag, overlay] : [], envOverrides: {} };
}

function isContinuingOverlaySession({ resumesSessionViaCli, resumesSessionViaAcpLoad, resumeSessionId }: Pick<Parameters<typeof resolveSystemPromptOverlayDelivery>[0], 'resumesSessionViaCli' | 'resumesSessionViaAcpLoad' | 'resumeSessionId'>, _options = {}): boolean {
  return (resumesSessionViaCli === true || resumesSessionViaAcpLoad === true) &&
    typeof resumeSessionId === 'string' &&
    resumeSessionId.length > 0;
}

/**
 * **The single dispatch point from a computed system-prompt overlay to its delivery mechanism** —
 * see `RuntimeAgentDef.systemPromptDelivery`'s own doc for the declared shape. Pure and
 * synchronous, mirroring {@link buildMcpBridgeDelivery}'s "keyed off the declared strategy, never
 * off the def's id" contract: a def earns overlay delivery by declaring a strategy, not by being
 * named in this file. That is what makes every def with no declaration work via the fallback
 * without any of their own files being touched.
 *
 * The fallback (no declared strategy — every def but `claude` today) prefixes the overlay directly
 * onto the composed prompt text, clearly delimited from the user's own request. It is gated on
 * session state, not merely on whether an overlay exists: a def that carries its own conversation
 * memory across spawns (`resumesSessionViaCli` / `resumesSessionViaAcpLoad`) persists whatever its
 * session-creating turn sends it — see `RuntimeContext.resumeSessionId`'s own doc: its presence on
 * a run means "continue a prior session", not "start one". Prefixing on every later turn of that
 * same session would therefore bake the overlay into the CLI's own stored history again and again,
 * compounding without bound turn over turn. So the fallback prefixes only when there is no resume
 * target yet (the session's own first turn, or a def with no session memory at all, which never
 * replays anything back at the CLI and so gets it on every turn).
 *
 * `'append-flag'` and `'env-var'` defs are the opposite case: the flag/env var is a fresh,
 * un-stored per-spawn directive — never part of what a resumed session replays — so it is set on
 * every turn unconditionally, exactly `claude`'s pre-existing (now-centralized) behavior before
 * this function existed.
 *
 * @param input.defId - Looks up this def's probed capabilities for an `'append-flag'` strategy's
 * `capabilityKey`. Otherwise unused — the dispatch itself is keyed off `systemPromptDelivery`, per
 * this function's own doc above, never off the id.
 * @param input.systemPromptDelivery - The def's declared strategy, or `undefined` for the fallback.
 * @param input.resumesSessionViaCli - The def's own flag (see `RuntimeAgentDef`'s doc).
 * @param input.resumesSessionViaAcpLoad - The def's own flag (see `RuntimeAgentDef`'s doc).
 * @param input.overlay - The computed `PromptAugmenter.systemOverlay()` result. `null`/`undefined`/
 * empty short-circuits to "no delivery" — byte-identical to no `PromptAugmenter` configured at all.
 * @param input.prompt - The composed prompt `buildArgs` would otherwise receive verbatim.
 * @param input.resumeSessionId - This run's `RuntimeContext.resumeSessionId`; presence means an
 * existing session is being continued, not created.
 * @returns A {@link SystemPromptOverlayDelivery}: the prefix this run's prompt text must carry
 * (`''` unless the fallback applies), that prefix already applied to `input.prompt`, any extra argv
 * to append to whatever `buildArgs` itself returns, and any env var overrides to merge into the
 * spawn env (`{}` for every strategy but `'env-var'`). Every one of `run()`'s four prompt
 * transports consumes this same result — see the interface's own no-double-delivery note.
 * @complexity O(n) in the overlay/prompt lengths — string concatenation only, no I/O.
 * @overallScore 100/100
 */
export function resolveSystemPromptOverlayDelivery(input: {
  readonly defId: string;
  readonly systemPromptDelivery: RuntimeAgentDef['systemPromptDelivery'];
  readonly resumesSessionViaCli: boolean | undefined;
  readonly resumesSessionViaAcpLoad: boolean | undefined;
  readonly overlay: string | null | undefined;
  readonly prompt: string;
  readonly resumeSessionId: string | null | undefined;
}, { state }: { state?: AgentRuntimeState } = {}): SystemPromptOverlayDelivery {
  const { defId, systemPromptDelivery, resumesSessionViaCli, resumesSessionViaAcpLoad, prompt, resumeSessionId } = input;
  if (!hasSystemPromptOverlay(input, {})) {
    return { promptPrefix: '', prompt, extraArgs: [], envOverrides: {} };
  }
  const overlay = input.overlay;

  if (systemPromptDelivery?.strategy === 'append-flag') {
    return appendFlagOverlay({ defId, systemPromptDelivery, overlay, prompt }, { state });
  }

  if (systemPromptDelivery?.strategy === 'env-var') {
    // No capability gate, unlike `'append-flag'`: an unrecognized env var is inert to a CLI (it
    // simply never reads it), never a fatal "unknown option" exit — there is no equivalent hazard
    // to probe-gate against here. Set verbatim, not merged with any existing value — a dedicated
    // single-purpose var, not a shared config channel (see this field's own `types.ts` doc).
    return { promptPrefix: '', prompt, extraArgs: [], envOverrides: { [systemPromptDelivery.varName]: overlay } };
  }

  if (systemPromptDelivery?.strategy === 'config-instructions-file') {
    // Delivered elsewhere, not here: unlike `'append-flag'`/`'env-var'`, this mechanism needs real
    // filesystem I/O (staging the overlay to a temp file — `opencode`'s `instructions` array only
    // accepts a file path or URL, confirmed live, never inline text), which this function's "pure
    // and synchronous" contract cannot perform. `prepareSystemPromptOverlayFileIfNeeded` (a separate
    // async phase in `run()`, gated on this same strategy check) stages the file, and
    // `computeChildEnv` merges its path into the config document via `mergeEnvContentInstructions`.
    // This branch's only job is to make sure the universal prefix fallback below does NOT ALSO run
    // for a def that already has this strategy declared — the same "no double delivery" concern
    // `imageDelivery`'s doc calls out for its own native-vs-fallback split.
    return { promptPrefix: '', prompt, extraArgs: [], envOverrides: {} };
  }

  if (isContinuingOverlaySession({ resumesSessionViaCli, resumesSessionViaAcpLoad, resumeSessionId }, {})) {
    return { promptPrefix: '', prompt, extraArgs: [], envOverrides: {} };
  }

  // KNOWN TRADE-OFF, deliberate: for a resume-capable def with no `'append-flag'`/`'env-var'`
  // mechanism yet (`codex`, `codebuddy`, `opencode`, `amr` — all four presently on this fallback),
  // the overlay is therefore only injected on the SESSION-CREATING turn, not every turn. A host
  // whose `PromptAugmenter.systemOverlay()` result can change mid-conversation (e.g. a host that
  // lets an operator edit its own stored instructions and re-reads them before every run — see
  // `prompt-augmenter.ts`'s own doc for the seam) will see NO effect from such an edit until a NEW
  // session starts for one of these four defs specifically — a real, silent limitation, not a
  // theoretical one. This is the correct
  // trade against the alternative (re-injecting every turn would bake the overlay into that def's
  // own CLI-persisted session history again and again, compounding without bound) — do not change
  // this gating to "fix" the staleness. The actual fix is giving each of the four its own
  // `'append-flag'`-equivalent `systemPromptDelivery` (an argv flag or an env var, neither of which
  // is part of what a resumed session replays), which removes this limitation entirely for that
  // def. See `reasonix.ts`'s and `opencode.ts`'s module docs for the two already-identified,
  // not-yet-wired native mechanisms.
  const promptPrefix = `${overlay}\n\n---\n\n`;
  return { promptPrefix, prompt: `${promptPrefix}${prompt}`, extraArgs: [], envOverrides: {} };
}

/**
 * Phase 9b: calls the def's `buildArgs`, releasing staged resources and failing the run on a throw.
 *
 * @param input.overlayDelivery - This run's already-resolved overlay decision, computed once in
 * `run()` rather than here. It is resolved upstream because `buildArgs` is only ONE of the four
 * channels that can carry the prompt: the staged prompt file is written *before* this function
 * runs, and stdin/ACP/pi-rpc send theirs *after* spawn. A decision made inside this function could
 * therefore only ever reach the 7 defs whose `buildArgs` reads its first argument at all — the
 * other 17 declare it `_prompt` and discard it, which is exactly how the overlay used to go missing.
 */
export async function buildRunArgs({ input, deps }: { readonly input: {
    readonly runId: string;
    readonly def: RuntimeAgentDef;
    readonly imageDelivery: ImagePromptDelivery;
    readonly imagePaths: readonly string[] | undefined;
    readonly runInput: AgentBuildInput;
    readonly systemPromptOverlay: string | null | undefined;
    readonly overlayDelivery: SystemPromptOverlayDelivery;
    readonly runtimeContext: RuntimeContext | undefined;
  }; readonly deps: { readonly releaseStagedResources: () => Promise<void>; readonly failBeforeSpawn: FailBeforeSpawn } }
): Promise<{ readonly args: string[]; readonly envOverrides: Readonly<Record<string, string>> }> {
  try {
    const delivery = input.overlayDelivery;
    const options = buildAgentBuildArgsOptions({ input: input.runInput, systemPromptOverlay: input.systemPromptOverlay });
    const args = input.def.buildArgs(
      { prompt: delivery.prompt, imagePaths: [...(input.imagePaths ?? [])] }, {
        ...(input.imageDelivery.extraAllowedDirs === undefined ? {} : { extraAllowedDirs: [...input.imageDelivery.extraAllowedDirs] }),
        options,
        ...(input.runtimeContext === undefined ? {} : { runtimeContext: input.runtimeContext }),
      },
    );
    // `'append-flag'` delivery's extra argv (empty for every other def/strategy) is appended after
    // whatever the def's own `buildArgs` returned — safe because it is only ever non-empty for a
    // `promptViaStdin` def with no trailing positional argv (`claude`/`pi` today; see
    // `resolveSystemPromptOverlayDelivery`'s doc for why a future 'append-flag' def must keep that
    // property too). `envOverrides` (non-empty only for `'env-var'` — `reasonix` today) is handed
    // back rather than applied here, since the spawn env isn't finalized until `computeChildEnv`
    // runs, later in `run()`.
    return { args: [...args, ...delivery.extraArgs], envOverrides: delivery.envOverrides };
  } catch (err) {
    await deps.releaseStagedResources();
    return deps.failBeforeSpawn(
      { runId: input.runId, code: 'AGENT_SPAWN_FAILED', message: `AgentExecutor: could not build launch arguments for agent "${input.def.id}": ${errorMessage(err)}` },
    );
  }
}

/**
 * Phase 10b1: `systemPromptDelivery: { strategy: 'config-instructions-file' }`'s one effect —
 * stages the computed overlay to a fresh, run-scoped temp file, so `computeChildEnv` has a real
 * path to merge into that def's `instructions` config array (see
 * {@link mergeEnvContentInstructions}'s own doc for the live verification this mechanism rests on).
 * `null` for every other strategy, an unset `systemPromptDelivery`, or no overlay present at all —
 * byte-identical to before this mechanism existed, matching {@link writeMcpJsonIfNeeded}'s and
 * {@link prepareCodexHomeIfNeeded}'s identical no-op-when-inapplicable gate.
 *
 * `opencode`'s `instructions` field only accepts a file path or a remote URL — confirmed live
 * (2026-09-01): a literal instruction string in the array is silently ignored (no error, just never
 * honored), so an inline-text shortcut is not available and this staging step is load-bearing, not
 * a defensive extra.
 * @param input.def - Only used for its `id`, in the failure message, and its `systemPromptDelivery` declaration.
 * @param input.overlay - The computed `PromptAugmenter.systemOverlay()` result for this run.
 * @param deps.mkdtemp - Creates the run-scoped directory from a prefix; default a fresh `mkdtemp` under `os.tmpdir()`.
 * @complexity O(1) plus one directory creation and one file write.
 * @overallScore 100/100
 */
export async function prepareSystemPromptOverlayFileIfNeeded({ input, deps }: { readonly input: { readonly runId: string; readonly def: RuntimeAgentDef; readonly overlay: string | null | undefined }; readonly deps: { readonly releaseStagedResources: () => Promise<void>; readonly failBeforeSpawn: FailBeforeSpawn; readonly mkdtemp?: (prefix: string) => Promise<string> } }
): Promise<PreparedSystemPromptOverlayFile | null> {
  if (
    input.def.systemPromptDelivery?.strategy !== 'config-instructions-file' ||
    typeof input.overlay !== 'string' ||
    input.overlay.length === 0
  ) {
    return null;
  }
  try {
    const safeRunId = input.runId.replace(/[^A-Za-z0-9_-]/g, '-').slice(0, 80) || 'run';
    const dir = await (deps.mkdtemp ?? defaultMkdtempInTmpdir)(`jini-system-prompt-overlay-${safeRunId}-`);
    const filePath = join(dir, 'overlay.md');
    await fsPromises.writeFile(filePath, input.overlay, { encoding: 'utf8', mode: 0o600 });
    return {
      path: filePath,
      cleanup: async () => {
        await fsPromises.rm(dir, { recursive: true, force: true });
      },
    };
  } catch (err) {
    await deps.releaseStagedResources();
    return deps.failBeforeSpawn(
      { runId: input.runId, code: 'AGENT_SPAWN_FAILED', message: `AgentExecutor: could not stage a system-prompt overlay file for agent "${input.def.id}": ${errorMessage(err)}` },
    );
  }
}

/** A fresh, randomly named directory under `os.tmpdir()`: the real staging location. */
function defaultMkdtempInTmpdir(prefix: string): Promise<string> {
  return fsPromises.mkdtemp(join(tmpdir(), prefix));
}

/** Phase 11: post-`buildArgs` guard for argv-bound defs whose resolved binary is a Windows shim/.exe — a no-op off-Windows and for non-argv-bound defs. */
export async function guardWindowsCommandLineBudget({ input, deps }: { readonly input: { readonly runId: string; readonly def: RuntimeAgentDef; readonly launchPath: string; readonly args: readonly string[] }; readonly deps: { readonly releaseStagedResources: () => Promise<void>; readonly failBeforeSpawn: FailBeforeSpawn } }
): Promise<void> {
  const windowsBudgetError =
    checkWindowsCmdShimCommandLineBudget({ def: input.def, resolvedBin: input.launchPath, args: input.args }) ??
    checkWindowsDirectExeCommandLineBudget({ def: input.def, resolvedBin: input.launchPath, args: input.args });
  if (windowsBudgetError) {
    await deps.releaseStagedResources();
    // `failBeforeSpawn` always rejects (`Promise<never>`); awaiting it propagates that rejection.
    await deps.failBeforeSpawn({ runId: input.runId, code: 'AGENT_PROMPT_TOO_LARGE', message: windowsBudgetError.message });
  }
}

/**
 * Phase 12: the real `node:child_process.spawn` call.
 *
 * **Deliberately synchronous, unlike every other phase in this file.** A spawned child can emit
 * `'error'` on the very next microtask tick (Node schedules it eagerly on some failure modes, and a
 * test harness simulating "the child emits 'error' before 'spawn'" does so explicitly via
 * `queueMicrotask`). `run()` must register its `'error'` listeners (`wireChildLifecycle`'s safety net,
 * then `waitForSpawnOrError`'s `child.once('error', reject)`) in the *same synchronous turn* as this
 * spawn call — Node's `EventEmitter` throws synchronously when `'error'` fires with zero listeners
 * attached. Wrapping this call in an `async function` and `await`ing it (as every other phase here
 * does) would insert a microtask tick between spawn and listener registration, occasionally losing
 * that race — confirmed by a real test failure during this refactor (an uncaught `EventEmitter`
 * `'error'` exception) before this function was changed back to a plain, unawaited call returning a
 * result object instead of throwing/rejecting.
 * @returns `{kind:'ok', child}` on success, `{kind:'error', error}` on a synchronous throw from `spawn`
 * — `run()` itself is responsible for cleanup and `failBeforeSpawn` on the error variant, both of
 * which are safe to make asynchronous since no child (and hence no listener race) exists yet.
 * @complexity O(1) plus `spawn`'s own cost.
 */
export function spawnAgentChildProcess({ input, deps }: { readonly input: {
    readonly cwd: string;
    readonly childEnv: NodeJS.ProcessEnv;
    readonly invocation: ReturnType<typeof createCommandInvocation>;
  }; readonly deps: { readonly spawn: typeof nodeSpawn } }
): SpawnAgentChildProcessResult {
  try {
    return {
      kind: 'ok',
      child: deps.spawn(input.invocation.command, input.invocation.args, {
        cwd: input.cwd,
        env: input.childEnv,
        stdio: ['pipe', 'pipe', 'pipe'],
        windowsVerbatimArguments: input.invocation.windowsVerbatimArguments,
      }),
    };
  } catch (error) {
    return { kind: 'error', error };
  }
}

/** Named predicate replacing an inline `streamFormat === 'acp-json-rpc' || streamFormat === 'pi-rpc'` check — the two formats that own their own prompt/event protocol and skip `wireChildLifecycle`. */
export function isStdinDrivenFormat(args: { readonly streamFormat: SupportedStreamFormat }): args is { readonly streamFormat: ChildDrivenStreamFormat } {
  const { streamFormat } = args;
  return streamFormat !== 'acp-json-rpc' && streamFormat !== 'pi-rpc';
}

/** Phase 13: awaits spawn confirmation, routing a failure through the same `failBeforeSpawn` shape every earlier guard uses. */
export async function confirmChildSpawned({ input, deps }: { readonly input: { readonly runId: string; readonly def: RuntimeAgentDef; readonly child: ChildProcess }; readonly deps: { readonly releaseStagedResources: () => Promise<void>; readonly failBeforeSpawn: FailBeforeSpawn } }
): Promise<void> {
  try {
    await waitForSpawnOrError(input.child);
  } catch (err) {
    await deps.releaseStagedResources();
    await deps.failBeforeSpawn(
      { runId: input.runId, code: 'AGENT_SPAWN_FAILED', message: `AgentExecutor: failed to spawn agent "${input.def.id}": ${errorMessage(err)}` },
    );
  }
}

type MutableRunInput = { -readonly [K in keyof AgentExecutorRunInput]: AgentExecutorRunInput[K] } & { filesystemRuntimeReadPaths?: readonly string[]; filesystemTempDir?: string; filesystemSharedTempRoots?: readonly string[]; filesystemRuntimeTempBase?: string; filesystemNotice?: string };

/** Only include declared capability restrictions; absence has a distinct downstream contract. */
function nativeCapabilityInput({ input }: { input: AgentExecutorRunInput }, _options = {}) {
  return { ...(input.nativeCapabilities !== undefined ? { nativeCapabilities: input.nativeCapabilities } : {}) };
}

/** Switch names a person sees for each native capability (the host's settings use the same words). */
const NATIVE_CAPABILITY_LABELS: Readonly<Record<string, string>> = {
  shell: 'Bash/shell', fileWrite: 'File edit/write', userMcp: 'Your MCP servers', subagents: 'Subagents/Task',
  userSettings: 'Your skills and settings', web: 'Web fetch/search', workflows: 'Workflows', loginEnvironment: 'Your shell environment',
};

/** The refusal a person reads when a CLI without a native-tool policy cannot honor this run's switches:
 * it names the CLI and the switch to turn on. Owner 2026-10-27: the old "no native-tool policy and
 * audit adapter" told a Gemini user nothing. Pure, O(c) for c OFF switches.
 * @example nativeToolPolicyRefusal({ cliName: 'Antigravity', offSwitches: ['userMcp'] }, {});
 */
function nativeToolPolicyRefusal({ cliName, offSwitches }: { cliName: string; offSwitches: readonly string[] }, _options = {}): string {
  const switches = offSwitches.map(key => `'${NATIVE_CAPABILITY_LABELS[key] ?? key}'`);
  const blocked = switches.length > 0 ? `with ${new Intl.ListFormat('en', { type: 'conjunction' }).format(switches)} off` : `with this chat's CLI tool limits`;
  const pronoun = switches.length === 1 ? 'it' : 'them';
  const action = switches.length === 0 ? `Turn on 'Full CLI access'` : `Turn ${pronoun} on`;
  return `${cliName} can't run ${blocked}. ${action} in the assistant settings, or choose Claude or Codex.`;
}

/** Correlation projects retained stdout, so exact-byte journals need a separate blob writer. */
function validateStdoutJournalOptions(options: Pick<CreateAgentExecutorOptions, 'delegatedResultCorrelation' | 'journal' | 'stdoutJournalBlobs'>, _options = {}): void {
  if (options.delegatedResultCorrelation && options.journal && !options.stdoutJournalBlobs) {
    throw new Error('delegated result correlation with a byte journal requires stdoutJournalBlobs');
  }
}

/** Model discovery consumes the exact spawn environment and caller-supplied settings. */
function launchModelContext({ input, launch, spawnEnv }: { input: AgentExecutorRunInput; launch: ConfirmedAgentLaunchResolution; spawnEnv: NodeJS.ProcessEnv }, _options = {}) {
  return {
    executable: launch.launchPath, cwd: input.cwd, env: spawnEnv,
    ...(input.model && input.model !== 'default' ? { model: input.model } : {}),
    ...(input.resumeSessionId ? { resumeSessionId: input.resumeSessionId } : {}),
    ...(input.settingSources ? { settingSources: input.settingSources } : {}),
    ...(input.settings ? { settings: input.settings } : {}),
  };
}

/** Paths are available only after staging; retain the strategy gate for instructions files. */
function stagedChildEnvOptions({ def, preparedCodexHome, preparedClaudeConfigDir, preparedSystemPromptOverlayFile, systemPromptEnvOverrides }: {
  def: RuntimeAgentDef; preparedCodexHome: PreparedCodexHome | null; preparedClaudeConfigDir: PreparedClaudeConfigDir | null;
  preparedSystemPromptOverlayFile: PreparedSystemPromptOverlayFile | null; systemPromptEnvOverrides: Readonly<Record<string, string>>;
}, _options = {}) {
  return {
    ...(preparedCodexHome === null ? {} : { codexHomeDir: preparedCodexHome.path }),
    systemPromptEnvOverrides,
    ...(preparedSystemPromptOverlayFile && def.systemPromptDelivery?.strategy === 'config-instructions-file'
      ? { stagedInstructionsFile: { varName: def.systemPromptDelivery.varName, path: preparedSystemPromptOverlayFile.path } }
      : {}),
    ...(preparedClaudeConfigDir === null ? {} : { claudeConfigDir: preparedClaudeConfigDir.path }),
  };
}

/**
 * Creates the `AgentExecutor` reference implementation: an in-process
 * `RunLifecycle` driver over real (by default) `@jini-ai/agent-runtime`
 * registry lookup, launch resolution, and stream parsing, plus a real
 * `node:child_process.spawn`. Every collaborator is an injectable seam
 * (matching this package's established convention — see
 * `tool-executor.ts`/`run-lifecycle.ts`) so tests can drive a fake child
 * process and a fake registry without touching the filesystem or spawning
 * a real subprocess.
 *
 * @param options.lifecycle - The `RunLifecycle` this executor drives — its `start()` must already have been called for any `runId` passed to `run()`.
 * @returns An `AgentExecutor` whose `run()` never bare-throws (see index.ts module doc's Invariant).
 * @complexity `run()`'s own setup is O(1); steady-state cost is the chosen stream parser's.
 * @overallScore 100/100
 */
export function createAgentExecutor(requiredArgs: Pick<CreateAgentExecutorOptions, "lifecycle">, optionalArgs: Pick<CreateAgentExecutorOptions, "runtimeState" | "codexDisablePlugins" | "piGracefulShutdownMs" | "hostEnv" | "getAgentDef" | "resolveAgentLaunch" | "resolveModelForLaunch" | "ensureAgentCapabilities" | "assertClaudeFilesystemSupport" | "applyAgentLaunchEnv" | "createCommandInvocation" | "spawn" | "probeMcpBridge" | "attachAcpSession" | "acpPermissionHandler" | "attachPiRpcSession" | "preparePromptFileForAgent" | "prepareAgentLogFile" | "listProcessSnapshots" | "collectProcessTreePids" | "stopProcesses" | "onCleanupFailure" | "journal" | "delegatedResultCorrelation" | "stdoutJournalBlobs" | "continuation" | "classifyFailure" | "mcpJsonInjection" | "claudeConfigDirIsolation" | "claudeConfigDirIsolationEnabled" | "bufferedStdoutMaxBytes" | "promptAugmenter"> = {}): AgentExecutor {
  // This native composition boundary resolves ambient defaults once, before allowlisting child env.
  const env = optionalArgs.hostEnv ?? process.env;
  const options: CreateAgentExecutorOptions & { readonly piGracefulShutdownMs: number } = { ...requiredArgs, ...optionalArgs,
    codexDisablePlugins: optionalArgs.codexDisablePlugins ?? (env.CODEX_DISABLE_PLUGINS === '1'),
    piGracefulShutdownMs: optionalArgs.piGracefulShutdownMs ?? (Number(env.PI_GRACEFUL_SHUTDOWN_MS) || 5000),
  };
  const lifecycle = options.lifecycle;
  const hostEnv = selectAgentExecutorHostEnv({ env: options.hostEnv ?? process.env }, options.runtimeState ? { runtimeState: options.runtimeState } : {});
  const {
    getAgentDef: getAgentDefFn,
    resolveAgentLaunch: resolveAgentLaunchFn,
    ensureAgentCapabilities: ensureAgentCapabilitiesFn,
    applyAgentLaunchEnv: applyAgentLaunchEnvFn,
    attachAcpSession: attachAcpSessionFn,
    attachPiRpcSession: attachPiRpcSessionFn,
    preparePromptFileForAgent: preparePromptFileForAgentFn,
    prepareAgentLogFile: prepareAgentLogFileFn,
  } = resolveAgentRuntimeDeps({ ...options, hostEnv });
  const {
    createCommandInvocation: createCommandInvocationFn,
    spawn: spawnFn,
    listProcessSnapshots: listProcessSnapshotsFn,
    collectProcessTreePids: collectProcessTreePidsFn,
    stopProcesses: stopProcessesFn,
  } = resolveProcessDeps(options);
  const { onCleanupFailure: onCleanupFailureFn, bufferedStdoutMaxBytes } = resolveMiscExecutorDeps(options);
  validateStdoutJournalOptions(options);
  const { journal, continuation, classifyFailure, mcpJsonInjection, claudeConfigDirIsolation, promptAugmenter } = options;
  const claudeConfigDirIsolationEnabled = options.claudeConfigDirIsolationEnabled ?? false;

  const filesystemTemps = new Map<string, string[]>();
  const verifyClaudeFilesystem = options.assertClaudeFilesystemSupport ?? createClaudeFilesystemSupportProbe({});

  /** Remove this run's private temp directories on startup failure, exit, crash or cancellation.
   * O(d) removals for d staged directories; each failure is reported without skipping the others.
   */
  async function cleanupFilesystemTemp({ runId }: { runId: string }, _optional = {}) {
    const paths = filesystemTemps.get(runId);
    if (!paths) return;
    await Promise.all(paths.map(path => fsPromises.rm(path, { recursive: true, force: true })
      .catch(() => console.warn('[agent-executor] private temp cleanup failed'))));
    filesystemTemps.delete(runId);
  }

  /**
   * Transitions `runId` to `'failed'` (idempotent, never resumable — no
   * classifier exists, see index.ts module doc) then rejects with a typed
   * {@link AgentExecutorError}. Every pre-spawn guard in `run()` returns
   * this call directly.
   * @param runId - The run to transition.
   * @param code - The machine-readable failure reason.
   * @param message - The human-readable rejection message.
   * @throws Always — this function never returns normally.
   * @complexity O(1) plus `lifecycle.finish()`'s own cost.
   * @overallScore 100/100
   */
  async function failBeforeSpawn({ runId, code, message }: { readonly runId: string; readonly code: AgentExecutorErrorCode; readonly message: string }): Promise<never> {
    // The reason goes on the run's own stream before `end`, not only into the thrown error: the
    // thrown error reaches the server log, while a chat client sees only this stream. Without it
    // the user got a bare "Run failed". Best-effort: a stream that will not take the event must not
    // stop the run from finishing.
    await lifecycle
      .emit({ runId: runId, input: { event: 'error', data: { error: { code, message }, message: `The assistant could not start: ${message.replace(/^AgentExecutor:\s*/, '')}` } } })
      .catch(() => undefined);
    await cleanupFilesystemTemp({ runId }, {});
    await lifecycle.finish({ runId, status: 'failed', code: null, signal: null, resumable: false });
    throw new AgentExecutorError({ code: code, message: message });
  }

  /**
   * Every run with a live child, keyed by run id, mapped to how a mid-run message reaches it — the
   * stdin handle's `sendUserMessage` for a stdin-driven run, a constant `'unsupported'` for an
   * ACP/pi run (whose RPC takes one prompt per turn). Removed on the child's `'close'`, so a
   * finished or unknown run reads as `'not-running'`. Bounded by the number of live children.
   */
  const liveRunInputs = new Map<string, StdinCloseHandle['sendUserMessage']>();
  const liveRunRelays = new Map<string, RunMessageRelay>();

  const claimUserMessages: AgentExecutor['claimUserMessages'] = ({ runId, via }) => liveRunRelays.get(runId)?.claim({ via }) ?? [];

  /** `AgentExecutor.sendUserMessage()` — see that interface method's own doc. @complexity O(1). */
  async function sendUserMessage(
    { runId, text, id = randomUUID(), attachmentIds }: Parameters<AgentExecutor['sendUserMessage']>[0],
    { imageContents }: { readonly imageContents?: readonly MessageAttachmentImage[] } = {},
  ): Promise<UserMessageDelivery> {
    const deliver = liveRunInputs.get(runId);
    if (!deliver) return 'not-running';
    return deliver({ text, id, ...(attachmentIds ? { attachmentIds } : {}) }, imageContents ? { imageContents } : {});
  }

  /** Validates launch input and selects the definition synchronously before yielding. */
  async function prepareRunContext({ requiredArgs, optionalArgs }: {
    requiredArgs: Parameters<AgentExecutor['run']>[0]; optionalArgs: NonNullable<Parameters<AgentExecutor['run']>[1]>;
  }, _options = {}): Promise<ResolvedDefAndFormat & { input: MutableRunInput }> {
    const input: MutableRunInput = { ...requiredArgs, ...optionalArgs, permissionMode: optionalArgs.permissionMode ?? 'restricted' };
    if (input.permissionMode !== 'restricted' && input.permissionMode !== 'bypass') {
      return failBeforeSpawn({ runId: input.runId, code: 'AGENT_PERMISSION_MODE_INVALID', message: 'AgentExecutor: permissionMode must be restricted or bypass' });
    }
    // Lookup runs before the first await so a subsequent registry replacement cannot change this run's definition.
    const resolved = await resolveDefAndStreamFormat({ input, deps: { getAgentDef: getAgentDefFn, failBeforeSpawn } });
    return { input, ...resolved };
  }

  async function enforceNativeToolPolicy({ input, def }: { input: MutableRunInput; def: RuntimeAgentDef }, _options = {}) {
    // Never silently ignore a host's locked native-tool policy on another CLI.
    // Parity cannot override an explicit lock or a restricted run.
    input.cliParity = input.cliParity === true && input.permissionMode === 'bypass' && input.nativeToolAccess !== false;
    if (def.supportsNativeToolAccess === true) return;
    const offSwitches = Object.entries(input.nativeCapabilities ?? {}).filter(([, value]) => value === false).map(([key]) => key);
    if (input.nativeToolAccess !== undefined && !input.cliParity || offSwitches.length > 0) {
      await failBeforeSpawn({ runId: input.runId, code: 'NATIVE_TOOL_POLICY_UNSUPPORTED', message: nativeToolPolicyRefusal({ cliName: def.name, offSwitches }, {}) });
    }
  }

  /** Validate every directory after image augmentation, before model probes or resource staging.
   * Unknown containment fails this run; O(n) filesystem checks for n attachment directories.
   */
  async function enforceFilesystemPaths({ input, imageDelivery }: { input: MutableRunInput; imageDelivery: ImagePromptDelivery }, _options = {}) {
    if (input.filesystemRoot === undefined) return;
    try {
      input.filesystemRoot = validateFilesystemLaunch({ filesystemRoot: input.filesystemRoot, cwd: input.cwd,
        ...(imageDelivery.extraAllowedDirs ? { extraAllowedDirs: imageDelivery.extraAllowedDirs } : {}),
        ...(input.imagePaths ? { imagePaths: input.imagePaths } : {}),
      }, {});
      if (input.readOnlyExtraDirs) input.readOnlyExtraDirs = validateReadOnlyExtraDirs({ filesystemRoot: input.filesystemRoot, dirs: input.readOnlyExtraDirs }, {});
      input.cwd = input.filesystemRoot;
    } catch {
      await failBeforeSpawn({ runId: input.runId, code: 'FILESYSTEM_POLICY_INVALID', message: 'Folder-limited launch refused: invalid filesystem root, working directory or attachment path.' });
    }
  }

  /** Apply supported confinement without removing providers; unknown versions keep the settings.
   * Runtime and git config reads are explicit infrastructure exceptions; network is unchanged.
   * O(1) metadata/staging I/O plus the cached, bounded version probe.
   */
  async function enforceFilesystemRuntime({ input, def, launch, spawnEnv }: {
    input: MutableRunInput; def: RuntimeAgentDef; launch: ConfirmedAgentLaunchResolution; spawnEnv: NodeJS.ProcessEnv;
  }, _options = {}) {
    if (input.filesystemRoot === undefined) return;
    try {
      const supported = await verifyClaudeFilesystem({ agentId: def.id, launchPath: launch.launchPath, env: spawnEnv }, {});
      const runtimeDir = join(input.filesystemRoot, '.agent-runtime');
      await fsPromises.mkdir(runtimeDir, { recursive: true, mode: 0o700 });
      // Refuse a runtime-folder symlink escaping the site before creating anything beneath it.
      validateFilesystemLaunch({ filesystemRoot: input.filesystemRoot, cwd: input.cwd, extraAllowedDirs: [runtimeDir] }, {});
      input.filesystemTempDir = await fsPromises.realpath(await fsPromises.mkdtemp(join(runtimeDir, 'tmp-')));
      filesystemTemps.set(input.runId, [input.filesystemTempDir]);
      // Recheck after creation too: swapping the runtime symlink must never grant outside temp access.
      validateFilesystemLaunch({ filesystemRoot: input.filesystemRoot, cwd: input.cwd, extraAllowedDirs: [input.filesystemTempDir] }, {});
      input.filesystemSharedTempRoots = [spawnEnv.TMPDIR, spawnEnv.TMP, spawnEnv.TEMP].filter((path): path is string => Boolean(path));
      spawnEnv.TMPDIR = input.filesystemTempDir;
      spawnEnv.TMP = input.filesystemTempDir;
      spawnEnv.TEMP = input.filesystemTempDir;
      if (def.id === 'claude' && process.platform !== 'win32') {
        // Read denies also block create/unlink, so Claude's cwd files cannot live under /tmp.
        // /var/tmp exists on macOS/Linux; its realpath plus /claude-<uid> must fit 44 bytes
        // or the policy refuses launch instead of letting Bash fall back to shared scratch.
        // mkdtemp creates a private 0700 directory; register cleanup before resolving aliases.
        const runtimeTemp = await fsPromises.mkdtemp('/var/tmp/jini-');
        filesystemTemps.get(input.runId)!.push(runtimeTemp);
        input.filesystemRuntimeTempBase = await fsPromises.realpath(runtimeTemp);
        spawnEnv.CLAUDE_CODE_TMPDIR = input.filesystemRuntimeTempBase;
      }
      if (supported === false) {
        input.filesystemNotice = 'files and shell are not folder-limited for this agent';
        console.warn('[agent-executor] files and shell are not folder-limited for this agent');
        // Personal Claude hooks/permissions stay excluded even on an unconfined CLI fallback.
        if (def.id === 'claude') input.settingSources = [];
        delete input.filesystemRoot;
        return;
      }
      if (supported === undefined) console.warn('[agent-executor] filesystem capability unknown; applying read block and sandbox settings');
      input.filesystemRuntimeReadPaths = claudeFilesystemRuntimePaths({ launchPath: launch.launchPath }, {});
      // Validates host settings here so a malformed value fails cleanly; buildArgs merges again (idempotent).
      input.settings = claudeFilesystemSettings({ options: input }, {});
      // A login environment can otherwise force auto-memory back on despite the host setting.
      spawnEnv.CLAUDE_CODE_DISABLE_AUTO_MEMORY = '1';
    } catch {
      await failBeforeSpawn({ runId: input.runId, code: 'FILESYSTEM_POLICY_UNSUPPORTED', message: 'Folder-limited launch refused: invalid host settings or private runtime directory.' });
    }
  }

  function resolveRunOverlay({ input, def, imageDelivery }: { input: MutableRunInput; def: RuntimeAgentDef; imageDelivery: ImagePromptDelivery }, _options = {}) {
    // Phase 8, hoisted deliberately above EVERY step that writes or sends the prompt. Four
    // different channels carry a prompt in this driver, and they do not all run at the same point:
    // the `promptViaFile` staging below writes its file BEFORE `buildArgs`, `buildArgs` itself runs
    // mid-`run()`, and stdin/ACP/pi-rpc all send theirs AFTER spawn. Resolving the overlay once,
    // here, is what lets all four consume the same decision; resolving it later (as this used to,
    // inside `buildRunArgs`) could only ever reach `buildArgs`, so the 17 defs that discard that
    // argument, plus grok-build's staged file, silently received no overlay at all.
    //
    // `computeSystemPromptOverlay` reads no `RuntimeContext` at all: the one field it could use,
    // `hasPriorAssistantTurn`, is never populated by `computeRuntimeContext` from any of the
    // staged-file/MCP inputs added to the fuller context built further down, so nothing between
    // here and there can change the overlay this returns. The pre-staging context below is kept
    // for the overlay delivery's `resumeSessionId` only.
    //
    // `turnIndex` is a coarse 0/1 proxy (no exact turn counter exists on this driver) — sufficient
    // because every `PromptAugmenter.systemOverlay()` implementation this seam has today wants the
    // same overlay on every turn, not a first-turn-only one; a caller that needs finer-grained turn
    // numbering can track it itself and ignore this arg.
    const preStagingRuntimeContext = computeRuntimeContext({ preparedPromptFile: null, preparedLogFile: null, mcpBridge: null }, sessionRuntimeContext(input, {}));
    const hostOverlay = computeSystemPromptOverlay(promptAugmenter, def.id);
    const systemPromptOverlay = input.filesystemNotice ? `${hostOverlay ?? ''}\n${input.filesystemNotice}\n` : hostOverlay;
    const overlayDelivery = resolveSystemPromptOverlayDelivery({
      defId: def.id,
      systemPromptDelivery: def.systemPromptDelivery,
      resumesSessionViaCli: def.resumesSessionViaCli,
      resumesSessionViaAcpLoad: def.resumesSessionViaAcpLoad,
      overlay: systemPromptOverlay,
      prompt: imageDelivery.prompt,
      resumeSessionId: preStagingRuntimeContext?.resumeSessionId,
    }, options.runtimeState ? { state: options.runtimeState } : {});

    return { systemPromptOverlay, overlayDelivery };
  }

  /** Resolve the launch environment before staging the run's private temp overrides.
   * Mutates only this run's input; O(e) for e environment entries plus executable resolution I/O.
   */
  async function resolveRunLaunch({ input, def }: { input: MutableRunInput; def: RuntimeAgentDef }, _options = {}) {
    // The def's own declared env (e.g. claude's `ENABLE_TOOL_SEARCH=false`) is a default the run's
    // env can override. Detection already spawns with it (`detection.ts`); without this the run
    // spawn silently dropped it. Declared by the def itself, so it never widens SEC-001's allowlist.
    const defaults = { ...(def.env ?? {}) };
    // Eager loading was cheap only for the isolated bridge. Let the user's CLI decide in parity.
    if (input.cliParity) delete defaults.ENABLE_TOOL_SEARCH;
    const resolvedEnv = { ...defaults, ...resolveRunEnv({ input: input, hostEnv }) };
    const launch = await resolveLaunch({ input: { runId: input.runId, def, resolvedEnv }, deps: { resolveAgentLaunch: resolveAgentLaunchFn, failBeforeSpawn } }
    );

    const spawnEnv = applyAgentLaunchEnvFn({ env: { ...resolvedEnv }, launch });
    return { launch, spawnEnv };
  }

  async function selectRunModel({ input, def, launch, spawnEnv }: { input: MutableRunInput; def: RuntimeAgentDef; launch: ConfirmedAgentLaunchResolution; spawnEnv: NodeJS.ProcessEnv }, _options = {}) {
    // Locked runs pin the picker's concrete ID before any prompt is sent. Trusted parity keeps
    // the CLI's own configured default and effort, without requiring discovery to succeed.
    if (input.cliParity && input.model === 'default') delete input.model;
    let modelCatalog: ModelCatalogSnapshot | undefined;
    if (!input.cliParity) {
      try {
        const selectModel = options.resolveModelForLaunch ?? ((input: Parameters<typeof resolveModelForLaunch>[0]) => resolveModelForLaunch(input, options.runtimeState ? { deps: getRuntimeModelDiscoveryDeps({ state: options.runtimeState }) } : {}));
        const selection = await selectModel({ def, context: launchModelContext({ input, launch, spawnEnv }, {}) });
        input.model = selection.model;
        modelCatalog = selection.catalog;
      } catch {
        return failBeforeSpawn({ runId: input.runId, code: 'AGENT_MODEL_UNRESOLVED', message: 'AgentExecutor: pick a concrete model; the starting model could not be resolved for this launch.' });
      }
    }
    return modelCatalog;
  }

  function bridgeProbeEntryForRun({ mcpBridge }: { mcpBridge: McpBridgeDelivery | null }, _options = {}) {
    // probeMcpBridge itself strips the run credential and swaps in a diagnostic run id.
    return mcpBridge?.kind === 'claude-mcp-json' && mcpJsonInjection?.probeOnFailure !== false
      ? mcpBridge.serverEntry
      : undefined;
  }

  function wireRunInput({ input, def, streamFormat, child, modelCatalog, cleanupStagedFiles, writtenMcpJsonPath, mcpBridge }: {
    input: AgentExecutorRunInput; def: RuntimeAgentDef; streamFormat: SupportedStreamFormat; child: ChildProcess;
    modelCatalog: ModelCatalogSnapshot | undefined; cleanupStagedFiles: () => Promise<void>;
    writtenMcpJsonPath: string | undefined; mcpBridge: McpBridgeDelivery | null;
  }, _options = {}) {
    const formatForStdin = { streamFormat };
    const stdinHandle = isStdinDrivenFormat(formatForStdin)
      ? wireChildLifecycle({
          ...(canRegisterRunMessageRelay({ def, mcpBridge }) ? { registerMessageRelay: (relay: RunMessageRelay) => liveRunRelays.set(input.runId, relay) } : {}),
          ...childLifecycleOptions({ input, modelCatalog }),
          runId: input.runId,
          def,
          streamFormat: formatForStdin.streamFormat,
          child,
          lifecycle,
          listProcessSnapshots: listProcessSnapshotsFn,
          collectProcessTreePids: collectProcessTreePidsFn,
          stopProcesses: stopProcessesFn,
          onCleanupFailure: onCleanupFailureFn,
          cleanupStagedFiles,
          journal,
          continuation,
          classifyFailure,
          bufferedStdoutMaxBytes,
          expectsJiniBridge: writtenMcpJsonPath !== undefined,
          bridgeProbeEntry: bridgeProbeEntryForRun({ mcpBridge }, {}),
          probeMcpBridge: options.probeMcpBridge ?? probeMcpBridge,
        })
      : null;

    // Registered with the lifecycle wiring above, before the spawn-confirmation await, so a child
    // that closes immediately never leaves a stale entry behind.
    const runId = input.runId;
    liveRunInputs.set(runId, stdinHandle ? stdinHandle.sendUserMessage : async ({ text, id = randomUUID(), attachmentIds }, { imageContents } = {}) => {
      return liveRunRelays.get(runId)?.enqueue({ id, text, hasAttachments: (attachmentIds?.length ?? 0) > 0 || (imageContents?.length ?? 0) > 0 }) ?? 'unsupported';
    });
    child.once('close', () => { liveRunInputs.delete(runId); liveRunRelays.delete(runId); });
    return stdinHandle;
  }

  function childLifecycleOptions({ input, modelCatalog }: { input: AgentExecutorRunInput; modelCatalog: ModelCatalogSnapshot | undefined }) {
    return {
      ...(input.model ? { startingModel: input.model } : {}),
      ...(modelCatalog ? { modelCatalog } : {}),
      ...(options.delegatedResultCorrelation ? { delegatedResultCorrelation: options.delegatedResultCorrelation } : {}),
      ...(options.stdoutJournalBlobs ? { stdoutJournalBlobs: options.stdoutJournalBlobs } : {}),
    };
  }

  async function dispatchAcpPrompt({ input, def, child, modelCatalog, cleanupStagedFiles, releaseStagedResources, mcpBridge, overlayDelivery }: {
    input: AgentExecutorRunInput; def: RuntimeAgentDef; child: ChildProcess; modelCatalog: ModelCatalogSnapshot | undefined;
    cleanupStagedFiles: () => Promise<void>; releaseStagedResources: () => Promise<void>;
    mcpBridge: McpBridgeDelivery | null; overlayDelivery: SystemPromptOverlayDelivery;
  }, _options = {}) {
    await runAcpDispatch({ input: {
        runId: input.runId,
        agentId: def.id,
        child,
    // `overlayDelivery.promptPrefix` applied to `input.prompt`, NOT `overlayDelivery.prompt`:
    // this call site deliberately sends the raw input prompt rather than the image-delivery
    // rewrite (see `resolveImageDeliveryAndArgvBudget`'s call site above — an ACP def delivers
    // images natively and must never also get `'prompt-path'`'s appended paths), and the prefix
    // is the part of the overlay decision that applies to whatever prompt text a transport was
    // already sending. `''` for `reasonix` (env-var) and any resumed ACP session, so those keep
    // sending byte-identical text and never receive the overlay twice.
        prompt: `${overlayDelivery.promptPrefix}${input.prompt}`,
        cwd: input.cwd,
        permissionMode: input.permissionMode,
        cliParity: input.cliParity,
        model: input.model,
        ...(modelCatalog ? { modelCatalog } : {}),
        imagePaths: input.imagePaths ?? [],
        envFormat: def.acpMcpEnvFormat,
        mcpBridge,
      }, deps: {
        lifecycle,
        attachAcpSession: attachAcpSessionFn,
        ...(mcpBridge && supportsMessageRelay({ def }) ? { registerMessageRelay: (relay: RunMessageRelay) => liveRunRelays.set(input.runId, relay) } : {}),
        onPermissionRequest: options.acpPermissionHandler,
        listProcessSnapshots: listProcessSnapshotsFn,
        collectProcessTreePids: collectProcessTreePidsFn,
        stopProcesses: stopProcessesFn,
        onCleanupFailure: onCleanupFailureFn,
        cleanupStagedFiles,
        journal,
        classifyFailure,
        releaseStagedResources,
        failBeforeSpawn,
      } }
    );
  }

  async function dispatchPiPrompt({ input, def, child, modelCatalog, cleanupStagedFiles, releaseStagedResources, overlayDelivery }: {
    input: AgentExecutorRunInput; def: RuntimeAgentDef; child: ChildProcess; modelCatalog: ModelCatalogSnapshot | undefined;
    cleanupStagedFiles: () => Promise<void>; releaseStagedResources: () => Promise<void>;
    overlayDelivery: SystemPromptOverlayDelivery;
  }, _options = {}) {
    await runPiRpcDispatch({ input: {
        runId: input.runId,
        agentId: def.id,
        child,
        // Same reasoning as the ACP call site above. `pi` declares an `'append-flag'` strategy,
        // so its prefix is `''` and this stays byte-identical to the raw prompt — the overlay
        // rides `--append-system-prompt` instead, exactly once.
        prompt: `${overlayDelivery.promptPrefix}${input.prompt}`,
        cwd: input.cwd,
        model: input.model,
        ...(modelCatalog ? { modelCatalog } : {}),
        imagePaths: input.imagePaths ?? [],
        uploadRoot: input.uploadRoot,
      }, deps: {
        lifecycle,
        attachPiRpcSession: attachPiRpcSessionFn,
        listProcessSnapshots: listProcessSnapshotsFn,
        collectProcessTreePids: collectProcessTreePidsFn,
        stopProcesses: stopProcessesFn,
        onCleanupFailure: onCleanupFailureFn,
        cleanupStagedFiles,
        journal,
        classifyFailure,
        releaseStagedResources,
        failBeforeSpawn,
      } }
    );
  }

  function dispatchStdinPrompt({ input, def, child, overlayDelivery, imageDelivery, stdinHandle }: {
    input: AgentExecutorRunInput; def: RuntimeAgentDef; child: ChildProcess; overlayDelivery: SystemPromptOverlayDelivery;
    imageDelivery: ImagePromptDelivery; stdinHandle: StdinCloseHandle | null;
  }, _options = {}) {
    // The overlay reaches stdin only for a def that declares stdin as its prompt transport. The
    // four `plain`-format defs that do not (`aider`/`antigravity`/`deepseek` put the prompt in
    // argv, `grok-build` in a staged file) are still written to and closed here exactly as before,
    // because this driver always spawns with `stdio: ['pipe','pipe','pipe']` and their CLIs need
    // the EOF — but their prompt already carried the overlay through argv or the staged file, so
    // sending the overlaid text here too would deliver it twice. This is the one place the
    // resolver's own `''`-prefix rule is not sufficient on its own: those four defs are on the
    // fallback strategy, so their prefix is genuinely non-empty; what makes stdin the wrong
    // channel for them is the def's declared transport, not the strategy.
    const stdinPrompt = def.promptViaStdin === true ? overlayDelivery.prompt : imageDelivery.prompt;
    if (input.imageContents !== undefined) stdinHandle!.imageContents = input.imageContents;
    writePromptToStdin(def, child, stdinPrompt, stdinHandle!);
  }

  /**
   * `AgentExecutor.run()` — see that interface method's own doc for the
   * public contract. Implementation note on shape: every failure path below
   * awaits `failBeforeSpawn(...)` (a `Promise<never>`, so the await always
   * throws) and then returns, so each one reads as obviously terminal.
   * @param input - `{runId, agentId, prompt, cwd, model?, reasoning?, imagePaths?, extraAllowedDirs?, uploadRoot?, env?}` — `runId` must already be `lifecycle.start()`-ed.
   * @throws {@link AgentExecutorError} — see index.ts module doc's Invariant; never a bare `Error`.
   * @complexity O(1) setup (registry lookup, launch resolution, one spawn call); steady-state cost thereafter belongs to {@link wireChildLifecycle}.
   * @overallScore 100/100
   */
  async function run(requiredArgs: Pick<AgentExecutorRunInput, "runId" | "agentId" | "prompt" | "cwd">, optionalArgs: Pick<AgentExecutorRunInput, "filesystemRoot" | "model" | "reasoning" | "nativeToolAccess" | "nativeCapabilities" | "cliParity" | "permissionMode" | "imagePaths" | "imageContents" | "extraAllowedDirs" | "readOnlyExtraDirs" | "uploadRoot" | "credentialEnv" | "env" | "resumeSessionId" | "newSessionId" | "disallowedTools" | "allowedTools" | "settingSources" | "settings" | "chromeIntegration"> = {}): Promise<void> {
    const { input, def, streamFormat } = await prepareRunContext({ requiredArgs, optionalArgs }, {});

    // Computed once, before anything downstream ever looks at "the prompt" or "the allowed
    // dirs" — a no-op (`{prompt: input.prompt, extraAllowedDirs: input.extraAllowedDirs}`,
    // literally unchanged) unless `def.imageDelivery === 'prompt-path'` AND `input.imagePaths`
    // is non-empty, so this can never affect a 'native'-delivery def (ACP, pi-rpc, qoder) or a
    // run with no attachments. See `image-prompt-delivery.ts`'s own doc for the full mechanism;
    // every use of `input.prompt`/`input.extraAllowedDirs` below that reflects what the CLI
    // actually receives reads `imageDelivery.*` instead — the two ACP/pi-rpc `wire*Lifecycle`
    // calls further down deliberately keep reading `input.prompt` verbatim, since those two
    // defs' own native protocol already delivers the image and must never also get this
    // treatment (the double-delivery hazard this mechanism exists to avoid).
    await enforceNativeToolPolicy({ input, def }, {});
    const imageDelivery = await resolveImageDeliveryAndArgvBudget({ input: { runId: input.runId, def, prompt: input.prompt, imagePaths: input.imagePaths, extraAllowedDirs: input.extraAllowedDirs }, deps: { failBeforeSpawn } }
    );
    await enforceFilesystemPaths({ input, imageDelivery }, {});

    const { launch, spawnEnv } = await resolveRunLaunch({ input, def }, {});
    await enforceFilesystemRuntime({ input, def, launch, spawnEnv }, {});
    const { systemPromptOverlay, overlayDelivery } = resolveRunOverlay({ input, def, imageDelivery }, {});
    const modelCatalog = await selectRunModel({ input, def, launch, spawnEnv }, {});
    // Fill the def's `--help` capability gate before `buildArgs` reads it. Without this, only a
    // host that happened to call `detectAgents` in THIS process ever had the gate filled, so e.g.
    // `claude` never got `--include-partial-messages` (no streamed text). Probes once per binary;
    // never rejects (a failed probe keeps the safe no-optional-flags baseline).
    await ensureAgentCapabilitiesFn({ def, launchPath: launch.launchPath, env: spawnEnv });

    // Stage a promptViaFile def's (grok-build) prompt to a temp file before buildArgs runs — its
    // buildArgs throws without runtimeContext.promptFilePath. A no-op (returns null) for every
    // def without promptViaFile: true (preparePromptFileForAgent's own guard).
    //
    // `overlayDelivery.prompt`, not `imageDelivery.prompt`: for a `promptViaFile` def this file IS
    // the prompt transport — its `buildArgs` declares `_prompt` and passes only the path — so the
    // overlay has to be in the bytes written here or the CLI never sees it at all.
    const preparedPromptFile = await stagePromptFile({ input: { runId: input.runId, def, prompt: overlayDelivery.prompt }, deps: { preparePromptFileForAgent: preparePromptFileForAgentFn, failBeforeSpawn } }
    );
    // Stage a needsAgentLogFile def's (antigravity) diagnostic-log path, on the same terms and at
    // the same point as the prompt file above: before buildArgs, since buildArgs is what turns the
    // path into a `--log-file <path>` argument. A no-op (returns null) for every def without
    // `needsAgentLogFile: true` (prepareAgentLogFile's own guard). Sequenced after the prompt file
    // rather than concurrently so the failure path above has exactly one thing to clean up.
    const preparedLogFile = await stageLogFile({ input: { runId: input.runId, def, preparedPromptFile }, deps: { prepareAgentLogFile: prepareAgentLogFileFn, failBeforeSpawn } }
    );

    // Cleaned up after the child exits (wireChildLifecycle/wireAcpLifecycle/wirePiRpcLifecycle's
    // close handlers) and on every pre-spawn/spawn-failure path below — a leaked temp file
    // containing the full prompt, or whatever the CLI chose to write into its log, is a
    // confidentiality gap, not just a disk leak. One composed closure covering both staged files;
    // see `WireChildLifecycleContext.cleanupStagedFiles`'s doc for why they are not two fields.
    /**
     * Set once `writeMcpJsonForRun` has actually written this run's MCP config, so `cleanupStagedFiles`
     * knows there is a file holding a live bearer token to remove. Cleared as it is consumed, so the
     * removal happens exactly once across the several paths that may call the cleanup. Only the
     * `'claude-mcp-json'` mechanism stages a file at all — `'acp-merge'` and `'env-content'` leave
     * nothing on disk, so this stays `undefined` for those.
     */
    let writtenMcpJsonPath: string | undefined;
    const removeMcpJsonFileFn = mcpJsonInjection?.removeFile ?? defaultRemoveMcpJsonFile;
    /**
     * Set once `prepareCodexHomeIfNeeded` has actually staged this run's scratch `CODEX_HOME`, so
     * `cleanupStagedFiles` knows there is a directory holding a copied login credential to remove.
     * Cleared as it is consumed, matching `writtenMcpJsonPath`'s identical single-removal discipline.
     * Only the `'codex-toml'` mechanism stages a directory at all.
     */
    let preparedCodexHome: PreparedCodexHome | null = null;
    /**
     * Set once `prepareClaudeConfigDirIfNeeded` has actually staged this run's scratch
     * `CLAUDE_CONFIG_DIR`, so `cleanupStagedFiles` knows there is a directory (possibly holding a
     * copied login credential) to remove. Cleared as it is consumed, matching `preparedCodexHome`'s
     * identical single-removal discipline. Only a `claude`-id run stages a directory this way.
     */
    let preparedClaudeConfigDir: PreparedClaudeConfigDir | null = null;
    /**
     * Set once `prepareSystemPromptOverlayFileIfNeeded` has actually staged this run's overlay file
     * for a `'config-instructions-file'` def, so `cleanupStagedFiles` knows there is a temp
     * directory to remove. Cleared as it is consumed, matching `preparedCodexHome`'s identical
     * single-removal discipline. Only that one strategy stages a file this way — `null` for every
     * other def/strategy/no-overlay run.
     */
    let preparedSystemPromptOverlayFile: PreparedSystemPromptOverlayFile | null = null;
    const cleanupStagedFiles: () => Promise<void> = async () => {
      await cleanupFilesystemTemp({ runId: input.runId }, {});
      if (preparedPromptFile) await preparedPromptFile.cleanup();
      if (preparedLogFile) await preparedLogFile.cleanup();
      if (writtenMcpJsonPath !== undefined) {
        const mcpJsonFileToRemove = writtenMcpJsonPath;
        writtenMcpJsonPath = undefined;
        await removeMcpJsonFileFn({ path: mcpJsonFileToRemove });
      }
      if (preparedCodexHome) {
        const codexHomeToRemove = preparedCodexHome;
        preparedCodexHome = null;
        await codexHomeToRemove.cleanup();
      }
      if (preparedClaudeConfigDir) {
        const claudeConfigDirToRemove = preparedClaudeConfigDir;
        preparedClaudeConfigDir = null;
        await claudeConfigDirToRemove.cleanup();
      }
      if (preparedSystemPromptOverlayFile) {
        const overlayFileToRemove = preparedSystemPromptOverlayFile;
        preparedSystemPromptOverlayFile = null;
        await overlayFileToRemove.cleanup();
      }
    };
    // Resolve this run's MCP bridge delivery once, before buildArgs — the `'claude-mcp-json'`
    // variant's path has to be in `runtimeContext` for that def's own `--mcp-config` argv, and
    // resolving here means the per-run bearer credential is minted exactly once no matter which of
    // the five mechanisms ends up carrying it. `null` for an unconfigured host or a def declaring
    // no strategy — see `buildMcpBridgeDelivery`'s doc.
    const mcpBridge = await resolveMcpBridgeForRun({ input: { runId: input.runId, cwd: input.cwd, def }, deps: { mcpJsonInjection, cleanupStagedFiles, failBeforeSpawn } }
    );

    const runtimeContext = computeRuntimeContext({ preparedPromptFile: preparedPromptFile, preparedLogFile: preparedLogFile, mcpBridge: mcpBridge }, sessionRuntimeContext(input, {})
    );

    // A `runtimeLock` def's buildArgs mutates process-global state its own CLI reads back at
    // startup, so the mutex must be held from before buildArgs until the spawned child has
    // demonstrably consumed it — see `RuntimeLock`'s own doc for the concrete race. Undefined for
    // 23 of 24 defs, in which case nothing below waits on anything.
    const selectedModel = input.model;
    const runtimeLockHold = await acquireRuntimeLockIfConfigured(def, selectedModel);
    // Aborts once the spawned process is gone — or immediately, on a path where no process ever
    // ran — so a def's own handoff watcher can never outlive the run it was polling for.
    const processExitedController = new AbortController();
    /**
     * Releases the runtime lock and cancels any handoff watcher. Safe to call from any number of
     * paths: `AbortController.abort()` after the first is a no-op, and `RuntimeLockHold.release`
     * is idempotent by contract.
     */
    const releaseRuntimeLock = (): void => {
      processExitedController.abort();
      runtimeLockHold?.release();
    };
    /** Both staged-file and lock release, for the pre-spawn/spawn-failure paths that own neither a child nor a close handler. */
    const releaseStagedResources = async (): Promise<void> => {
      releaseRuntimeLock();
      await cleanupStagedFiles();
    };

    // Guarded, like every other step between staging and spawn: a `runtimeLock` def's `buildArgs` is
    // guarded precisely *because* it performs real filesystem writes (antigravity writes its model
    // choice into a shared settings file), so EACCES on a read-only home, ENOSPC, or a malformed
    // existing settings file all reach here as a throw. Unguarded, that escaped `run()` as a bare
    // `Error` — breaking this driver's "never a bare throw, always an `AgentExecutorError`" contract
    // — and left the run `'running'` forever while still holding the process-global mutex and both
    // staged files, so no later run of that def could ever acquire the lock either.
    const { args, envOverrides: systemPromptEnvOverrides } = await buildRunArgs({ input: { runId: input.runId, def, imageDelivery, imagePaths: input.imagePaths, runInput: input, systemPromptOverlay, overlayDelivery, runtimeContext }, deps: { releaseStagedResources, failBeforeSpawn } }
    );

    // Mechanism 1 of 5's one effect — stage this run's own MCP config file (run-scoped, see
    // `mcpJsonPathForRun`) before spawn so the `--mcp-config <path>` argv buildArgs just produced
    // points at a real file. Skipped entirely for the other four mechanisms and whenever no bridge
    // was resolved at all. `writtenMcpJsonPath` is set only once the write actually happens, so
    // `cleanupStagedFiles` knows there is a live-token file to remove afterward.
    writtenMcpJsonPath = await writeMcpJsonIfNeeded({ input: { runId: input.runId, cwd: input.cwd, nativeToolAccess: input.nativeToolAccess, ...nativeCapabilityInput({ input }, {}), def, mcpBridge }, deps: { mcpJsonInjection, releaseStagedResources, failBeforeSpawn } }
    );

    // Mechanism 5 of 5's one effect — stage this run's scratch `CODEX_HOME` directory. Skipped
    // entirely for the other four mechanisms and whenever no bridge was resolved at all.
    // `codex.ts`'s `buildArgs` needs no argv change for this (CODEX_HOME is an env var, not a flag),
    // so — unlike the `.mcp.json` staging above — this can run after `buildArgs` with no ordering
    // constraint of its own; it is placed here only to keep the two staging steps adjacent.
    preparedCodexHome = await prepareCodexHomeIfNeeded({ input: { runId: input.runId, nativeToolAccess: input.nativeToolAccess, ...nativeCapabilityInput({ input }, {}), def, mcpBridge }, deps: { mcpJsonInjection, hostEnv: input.cliParity ? spawnEnv : hostEnv, releaseStagedResources, failBeforeSpawn } }
    );
    // Finding 1 of SEC-assistant-env-isolation-2026-09-07's one effect — stage this run's scratch
    // `CLAUDE_CONFIG_DIR` directory. Unconditional for a `claude`-id run (unlike CODEX_HOME above,
    // this does not depend on `mcpJsonInjection` being configured at all — see
    // `prepareClaudeConfigDirIfNeeded`'s own doc for why). Placed here only to stay adjacent to the
    // other pre-`computeChildEnv` staging steps; `claude.ts`'s `buildArgs` needs no argv change for
    // this (CLAUDE_CONFIG_DIR is an env var, not a flag), same as CODEX_HOME.
    preparedClaudeConfigDir = await prepareClaudeConfigDirIfNeeded({ input: { runId: input.runId, def }, deps: {
        enabled: claudeConfigDirIsolationEnabled,
        claudeConfigDirIsolation,
        hostEnv,
        releaseStagedResources,
        failBeforeSpawn,
      } }
    );
    // `'config-instructions-file'`'s one effect — stage the overlay to a temp file so
    // `computeChildEnv` below has a real path to merge into that def's `instructions` array. A
    // no-op (`null`) for every other def/strategy or a run with no overlay at all. Independent of
    // `mcpBridge`/`preparedCodexHome` above (a different strategy field entirely), so placed here
    // only to stay adjacent to the other pre-`computeChildEnv` staging steps, not for any ordering
    // requirement between them.
    preparedSystemPromptOverlayFile = await prepareSystemPromptOverlayFileIfNeeded({ input: { runId: input.runId, def, overlay: systemPromptOverlay }, deps: { releaseStagedResources, failBeforeSpawn } }
    );
    // Computed only now, not right after `mcpBridge` resolution: mechanism 5's directory path is
    // not known until the staging step directly above actually runs `mkdtemp` (see
    // `McpBridgeDelivery`'s `'codex-toml'` variant doc for why it cannot be pre-computed the way
    // `'claude-mcp-json'`'s deterministic path is). Nothing between the old, earlier call site and
    // here ever read `childEnv`, so moving the call cost nothing.
    const childEnv = computeChildEnv({ spawnEnv, mcpBridge }, stagedChildEnvOptions({
      def, preparedCodexHome, preparedClaudeConfigDir, preparedSystemPromptOverlayFile, systemPromptEnvOverrides,
    }, {}));

    // Post-buildArgs guard for argv-bound defs whose resolved binary is a
    // Windows .cmd/.bat shim or a direct .exe: a prompt under the raw byte
    // budget can still expand past CreateProcess's command-line cap once
    // quote-escaped. Both are no-ops off-Windows / for non-argv-bound defs.
    await guardWindowsCommandLineBudget({ input: { runId: input.runId, def, launchPath: launch.launchPath, args }, deps: { releaseStagedResources, failBeforeSpawn } }
    );

    const invocation = createCommandInvocationFn({ command: launch.launchPath, args, env: childEnv });

    // Kept a synchronous call (no `await`) on purpose — see `spawnAgentChildProcess`'s own doc for
    // the microtask-timing race this avoids. The error branch's own cleanup/failBeforeSpawn calls are
    // async, which is fine: no child exists yet on that path, so nothing is racing a listener.
    const spawnResult = spawnAgentChildProcess({ input: { cwd: input.cwd, childEnv, invocation }, deps: { spawn: spawnFn } });
    if (spawnResult.kind === 'error') {
      await releaseStagedResources();
      await failBeforeSpawn(
        { runId: input.runId, code: 'AGENT_SPAWN_FAILED', message: `AgentExecutor: spawn threw synchronously for agent "${def.id}": ${errorMessage(spawnResult.error)}` },
      );
      return;
    }
    const child = spawnResult.child;

    // Registered before the spawn-confirmation await below, for the same reason
    // `wireChildLifecycle` is: a child that exits immediately must not slip past the listener.
    // `'exit'` rather than `'close'` on purpose — a `runtimeLock` guards state the *process* reads,
    // so the process being gone is the release condition, not its stdio pipes draining (which a
    // grandchild inheriting them can delay arbitrarily). A spawn that never produced a process at
    // all emits no `'exit'`, and is covered instead by `releaseStagedResources` on the reject path.
    child.once('exit', releaseRuntimeLock);

    const stdinHandle = wireRunInput({ input, def, streamFormat, child, modelCatalog, cleanupStagedFiles, writtenMcpJsonPath, mcpBridge }, {});
    const runId = input.runId;

    try {
      await confirmChildSpawned({ input: { runId: input.runId, def, child }, deps: { releaseStagedResources, failBeforeSpawn } });
    } catch (error) {
      liveRunInputs.delete(runId);
      liveRunRelays.delete(runId);
      throw error;
    }

    // Now — and only now — is there a live process that could consume the locked side effect, so
    // this is where a def's handoff watcher starts. Deliberately not awaited: the whole point is to
    // release the lock as soon as the child confirms the handoff, in parallel with this run
    // continuing. Rejection releases too — a lock stuck open because a watcher threw is strictly
    // worse than releasing early (see `RuntimeLockHold.waitForHandoff`'s own doc).
    armHandoffWatcher({ runtimeLockHold: runtimeLockHold, handoffInput: { logFilePath: preparedLogFile?.path, model: selectedModel, processExited: processExitedController.signal }, release: releaseRuntimeLock }
    );

    if (streamFormat === 'acp-json-rpc') {
      await dispatchAcpPrompt({ input, def, child, modelCatalog, cleanupStagedFiles, releaseStagedResources, mcpBridge, overlayDelivery }, {});
      return;
    }
    if (streamFormat === 'pi-rpc') {
      await dispatchPiPrompt({ input, def, child, modelCatalog, cleanupStagedFiles, releaseStagedResources, overlayDelivery }, {});
      return;
    }
    dispatchStdinPrompt({ input, def, child, overlayDelivery, imageDelivery, stdinHandle }, {});
  }

  return { run, sendUserMessage, claimUserMessages };
}

import type { PGlite } from "@electric-sql/pglite";
import {
  CompiledQuery,
  type DatabaseConnection,
  type Dialect,
  type Driver,
  type Kysely,
  PostgresAdapter,
  PostgresIntrospector,
  PostgresQueryCompiler,
  type QueryResult,
} from "kysely";

/**
 * @file A Kysely dialect over one PGlite instance: Kysely's own Postgres adapter, compiler and
 * introspector, plus a driver that runs compiled queries through `PGlite#query`.
 *
 * Written here rather than taken from npm (2026-09-28): `kysely-pglite-dialect` 1.3.1 declares
 * `@electric-sql/pglite` peer `^0.2 || ^0.3 || ^0.4` (this package pins 0.5.8), is one maintainer, and is
 * ~11 KB of the same few lines; `kysely-pglite` was last published 2024. This file is that driver,
 * sized to what the kernel needs and nothing else.
 *
 * PGlite is ONE connection. The driver hands it out one holder at a time (a transaction holds it
 * from `BEGIN` to `COMMIT`), so a statement from outside can never land inside someone else's
 * transaction. The kernel's turn lock already orders callers; this keeps the dialect correct on its
 * own too.
 */

class PgliteConnection implements DatabaseConnection {
  constructor(private readonly client: PGlite) {}

  async executeQuery<R>(compiled: CompiledQuery): Promise<QueryResult<R>> {
    const result = await this.client.query<R>(compiled.sql, [...compiled.parameters]);
    return {
      rows: result.rows,
      ...(result.affectedRows !== undefined ? { numAffectedRows: BigInt(result.affectedRows) } : {}),
    };
  }

  // eslint-disable-next-line require-yield, sonarjs/generator-without-yield -- the interface requires a generator; PGlite has no cursor API here
  async *streamQuery<R>(): AsyncIterableIterator<QueryResult<R>> {
    throw new Error("streaming queries are not supported on PGlite");
  }
}

class PgliteDriver implements Driver {
  private readonly connection: PgliteConnection;
  private holder: Promise<void> = Promise.resolve();
  private releaseHolder: (() => void) | undefined;

  constructor(private readonly client: PGlite) {
    this.connection = new PgliteConnection(client);
  }

  async init(): Promise<void> {
    await this.client.waitReady;
  }

  async acquireConnection(): Promise<DatabaseConnection> {
    const previous = this.holder;
    let release!: () => void;
    this.holder = new Promise((resolve) => (release = resolve));
    await previous;
    this.releaseHolder = release;
    return this.connection;
  }

  async releaseConnection(): Promise<void> {
    const release = this.releaseHolder;
    this.releaseHolder = undefined;
    release?.();
  }

  async beginTransaction(connection: DatabaseConnection): Promise<void> {
    await connection.executeQuery(CompiledQuery.raw("BEGIN"));
  }

  async commitTransaction(connection: DatabaseConnection): Promise<void> {
    await connection.executeQuery(CompiledQuery.raw("COMMIT"));
  }

  async rollbackTransaction(connection: DatabaseConnection): Promise<void> {
    await connection.executeQuery(CompiledQuery.raw("ROLLBACK"));
  }

  /** The PGlite instance belongs to whoever opened it (the kernel closes it). */
  async destroy(): Promise<void> {}
}

export class PgliteDialect implements Dialect {
  constructor(private readonly client: PGlite) {}

  createAdapter() {
    return new PostgresAdapter();
  }

  createDriver(): Driver {
    return new PgliteDriver(this.client);
  }

  createQueryCompiler() {
    return new PostgresQueryCompiler();
  }

  createIntrospector(db: Kysely<unknown>) {
    return new PostgresIntrospector(db);
  }
}

/**
 * @file SPEC-019 C-308 / behavior.spec.md §1.1 — degraded-state banner precedence resolver
 * (ADR-045 §4).
 *
 * Purpose:
 * Fixed precedence, highest to lowest: `migration.interrupted` > `PENDING_MIGRATION` >
 * operation-in-flight > `costClass:'unavailable'` > watermark-baseline-unavailable. Only the
 * PRIMARY banner selection is this resolver's contract (EC-06) — "an interrupted-run banner stays
 * visible beneath a superseded pending-migration banner" is a rendering-layer composition concern
 * this function does not own.
 *
 * `PENDING_MIGRATION`'s action always deep-links to the Database Timeline's own migration ceremony, never a
 * Recovery restore-flow action (AC-27/INV-07, ADR-045 §4) — restoring to an older snapshot does
 * not resolve schema drift against the current runtime.
 */

export type DegradedBannerKind =
  | "migration-interrupted"
  | "pending-migration"
  | "operation-in-flight"
  | "cost-unavailable"
  | "watermark-baseline-unavailable";

export type DegradedBannerActionKind = "deep-link-to-database-migration" | "unblock-interrupted-migration" | "none";

export interface DegradedBanner {
  kind: DegradedBannerKind;
  accessibleText: string;
  actionKind: DegradedBannerActionKind;
}

export interface DegradedBannerCapabilities {
  costClass: "cheap" | "expensive" | "unavailable";
  operationInFlight: boolean;
  pendingMigration: boolean;
  migrationInterrupted: boolean;
  watermarkBaselineAvailable: boolean;
}

export interface ResolveDegradedBannerRequired {
  capabilities: DegradedBannerCapabilities;
}

/**
 * AC-27/AC-29/EC-06/INV-07 — resolves the single primary degraded banner per the fixed precedence
 * order, or `null` when no degraded condition holds.
 *
 * @complexity O(1) — a fixed sequence of independent comparisons, no loop.
 */
export function resolveDegradedBanner(
  required: ResolveDegradedBannerRequired,
  _optional: Record<string, never> = {}
): DegradedBanner | null {
  const { capabilities } = required;

  if (capabilities.migrationInterrupted) {
    return {
      kind: "migration-interrupted",
      accessibleText:
        "A migration was interrupted mid-run. This is a real, accepted planned downtime vector, not a bug — resolve it to reopen normal Database/Recovery navigation.",
      actionKind: "unblock-interrupted-migration",
    };
  }

  if (capabilities.pendingMigration) {
    return {
      kind: "pending-migration",
      accessibleText:
        "This site is pending a schema migration before normal public serving can resume. Resolve it from the Database Timeline's own migration ceremony.",
      actionKind: "deep-link-to-database-migration",
    };
  }

  if (capabilities.operationInFlight) {
    return {
      kind: "operation-in-flight",
      accessibleText:
        "An operation is already in progress for this site. A second migrate or restore cannot start until it finishes.",
      actionKind: "none",
    };
  }

  if (capabilities.costClass === "unavailable") {
    return {
      kind: "cost-unavailable",
      accessibleText:
        "No restore-point mechanism is available for this site. See the runbook for external backup guidance.",
      actionKind: "none",
    };
  }

  if (!capabilities.watermarkBaselineAvailable) {
    return {
      kind: "watermark-baseline-unavailable",
      // Rewritten (web-design pass): the prior copy said "right now", which frames this as a
      // transient blip an operator might retry — but `watermarkBaselineAvailable` is currently a
      // hardcoded `false` (an "honest stub", see both `disclosure.ts` and this route's own
      // `status.ts`), not a live computation that can fail-then-succeed. "Right now" is therefore
      // actively misleading about the site's real state. This text also avoids the internal terms
      // "discarded-write-window"/"watermark baseline" and says what still works (restoring) and
      // what the operator will see instead (counts marked "unknown", not a verified zero — the
      // same word `DisclosurePanel`'s own per-point disclosure uses, so the two stay consistent).
      accessibleText:
        "This site can't show exactly what a restore would discard. Restoring still works — the counts you'll see are marked \"unknown\" rather than a confirmed number.",
      actionKind: "none",
    };
  }

  return null;
}

import type { Clock } from "@jini-ai/core/primitives";
/**
 * @file SPEC-019 C-301/C-302/C-303 — the Recovery restore ceremony (ADR-045 §3, CIC U-001/U-002/
 * U-003).
 *
 * Purpose:
 * `planRestore` / `confirmRestore` / `executeRestore` — three separate exports, never a combined
 * single-call restore endpoint (AC-12, REQ-06). Each is a thin orchestration wrapper around the
 * SPEC-016 `core/gated-mutations` gateway (injected here as `deps.gateway`, since that module's
 * real binding is a composition-root concern outside this domain's own certified test suite) plus
 * this domain's own binding constraints:
 *
 * - `planRestore` (CIC U-003): re-checks `costClass` FRESH at call time via `db-ops.getCapabilities()`
 *   — never a cached value — and refuses to reach the gateway at all once `costClass==='unavailable'`
 *   is freshly confirmed (U-003-ORD1, REQ-12).
 * - `confirmRestore` (CIC U-002): rejects (mints no token) unless `disclosureAcknowledged===true`
 *   STRICTLY (not merely truthy) — the composite of "the client claims acknowledgment" AND "the
 *   `planId` resolves to a plan the server's own `planRestore` actually minted," the latter half
 *   delegated entirely to the injected gateway's own plan-provenance verification.
 * - `executeRestore` (CIC U-001-ORD1): acquires the shared, cross-domain `core/operation-lock`
 *   BEFORE the gateway's own `execute()` runs — the same primitive `features/database`'s
 *   `executeMigrateForward` acquires, never an independent Recovery-local check (GOV-ADR-002) —
 *   and always releases it afterward, success or failure. Never itself clears `PENDING_MIGRATION`
 *   (REQ-18/EC-07 — restoring to an older snapshot does not resolve schema drift against the
 *   current runtime, ADR-045 §4). A successful `RESTORED` completion attaches a deep-link back to
 *   the Database Timeline (REQ-16/AC-26) — the incident thread's closing hop (ADR-041 §7).
 *
 * How it relates to the project:
 * `deps.gateway` stands in for a composition root's binding over the real
 * `core/gated-mutations.plan/confirm/execute` (SPEC-016) plus this domain's own hooks
 * (`domain="backup.restore"`); this file owns none of that gateway's own fixed check-sequence
 * (authorize -> token state -> actor-class -> plan-hash -> redeem), only this domain's binding
 * constraints layered around it.
 */

export type PrincipalKind = "user" | "agent" | "api_key";

export type Result<TValue, TError> = { ok: true; value: TValue } | { ok: false; error: TError };

export interface RecoveryErrorPayload {
  code: string;
  message?: string;
}

interface RestoreCapabilities {
  costClass: "cheap" | "expensive" | "unavailable";
  restorePointKind: string;
}

export interface PlanRestoreDbOpsPort {
  getCapabilities(): Promise<RestoreCapabilities>;
}

export interface PlanRestoreGatewayPort {
  plan(input: {
    principalId: string;
    principalKind: PrincipalKind;
    restorePointId: string;
    costClass: RestoreCapabilities["costClass"];
  }): Promise<Result<unknown, RecoveryErrorPayload>>;
}

export interface PlanRestoreRequired {
  deps: { dbOps: PlanRestoreDbOpsPort; gateway: PlanRestoreGatewayPort };
  input: { principalId: string; principalKind: PrincipalKind; restorePointId: string };
}

/**
 * C-301/CIC U-003 — `plan()` step. Never reaches the gateway when a fresh `costClass` recheck
 * reports `'unavailable'` (U-003-ORD1); `'expensive'` still reaches it (only `'unavailable'`
 * short-circuits, per ADR-041 §2's "no attestation override" carried into this domain).
 *
 * @complexity O(1) plus one `getCapabilities()` call and, when not short-circuited, one
 * `gateway.plan()` call.
 */
export async function planRestore(
  required: PlanRestoreRequired,
  _optional: Record<string, never> = {}
): Promise<Result<unknown, RecoveryErrorPayload>> {
  const { deps, input } = required;

  const capabilities = await deps.dbOps.getCapabilities();
  if (capabilities.costClass === "unavailable") {
    return {
      ok: false,
      error: {
        code: "COST_CLASS_UNAVAILABLE",
        message: `restore point '${input.restorePointId}' has no available restore mechanism for this site (no attestation override)`,
      },
    };
  }

  return deps.gateway.plan({
    principalId: input.principalId,
    principalKind: input.principalKind,
    restorePointId: input.restorePointId,
    costClass: capabilities.costClass,
  });
}

export interface ConfirmRestoreGatewayPort {
  confirm(input: { planId: string; planHash: string }): Promise<Result<unknown, RecoveryErrorPayload>>;
}

export interface ConfirmRestoreRequired {
  deps: { gateway: ConfirmRestoreGatewayPort };
  input: {
    principalId: string;
    principalKind: PrincipalKind;
    planId: string;
    planHash: string;
    disclosureAcknowledged: boolean;
  };
}

/**
 * C-302/CIC U-002 — `confirm()` step. `disclosureAcknowledged` must be exactly `true` (a truthy
 * non-boolean, e.g. the string `"true"`, is rejected — U-002-B1's exact wording) before the
 * gateway is ever consulted; plan provenance (whether `planId` was actually minted by this
 * server's own `planRestore`) is verified entirely by the injected gateway, never re-derived or
 * short-circuit-trusted here (U-002-ORD1).
 *
 * @complexity O(1) plus, when the acknowledgment gate passes, one `gateway.confirm()` call.
 */
export async function confirmRestore(
  required: ConfirmRestoreRequired,
  _optional: Record<string, never> = {}
): Promise<Result<unknown, RecoveryErrorPayload>> {
  const { deps, input } = required;

  if (input.disclosureAcknowledged !== true) {
    return {
      ok: false,
      error: {
        code: "VALIDATION_ERROR",
        message: "disclosureAcknowledged must be exactly true before a restore confirmation token may be minted",
      },
    };
  }

  return deps.gateway.confirm({ planId: input.planId, planHash: input.planHash });
}

export interface ExecuteRestoreGatewayPort {
  execute(input: { confirmationToken: string; confirmerPrincipalId?: string }): Promise<
    Result<{ restoreRunId: string; state: string; restartRequired?: boolean }, RecoveryErrorPayload>
  >;
}

interface OperationLockHandle {
  siteId: string;
  operationKind: string;
  acquiredAt: string;
}

export interface ExecuteRestoreOperationLockPort {
  acquireOperationLock(params: {
    deps: { clock: Clock };
    input: { siteId: string; operationKind: "migration" | "restore" };
  }): Promise<{ ok: true; value: OperationLockHandle } | { ok: false; error: { code: string; message?: string } }>;
  releaseOperationLock(params: {
    deps: { clock: Clock };
    input: { siteId: string; handle: OperationLockHandle };
  }): Promise<void>;
}

export interface ExecuteRestorePendingMigrationTrackerPort {
  clearPendingMigration(): Promise<void>;
}

export interface ExecuteRestoreRequired {
  deps: {
    gateway: ExecuteRestoreGatewayPort;
    operationLock: ExecuteRestoreOperationLockPort;
    clock: Clock;
    /** Never invoked by this function (REQ-18/EC-07) — accepted only so a caller cannot be
     * tempted to wire an implicit clear-on-success elsewhere; kept in the seam to make the
     * "never called" property directly testable. */
    pendingMigrationTracker?: ExecuteRestorePendingMigrationTrackerPort;
  };
  input: {
    principalId: string;
    principalKind: PrincipalKind;
    confirmationToken: string;
    siteId: string;
    /** Required only for `principalKind==='agent'` — the agent's current delegator, used as the
     * confirmer identity the gateway's own actor-class rule compares against (SPEC-016 REQ-13). */
    delegatedByPrincipalId?: string;
  };
}

export interface ExecuteRestoreValue {
  restoreRunId: string;
  state: string;
  /** Attached only on `state==='RESTORED'` (REQ-16/AC-26) — the deep-link back to the Database
   * Timeline that closes the incident thread ADR-041 §7 describes. */
  databaseTimelineDeepLink?: { v: 1; siteId: string; intent: "view" };
  /** 2026-07-16: `true` when the physical content.db file was actually swapped (real SQLite
   * composition) — the running process keeps serving the pre-restore data from its already-open
   * file handle until an operator restarts it. `false`/absent for the hermetic in-memory
   * composition, which has no real file to restore into. */
  restartRequired?: boolean;
}

/**
 * C-303/CIC U-001-ORD1 — `execute()` step. Acquires the shared cross-domain operation lock BEFORE
 * the gateway's own `execute()` runs, and releases it in a `finally` regardless of outcome (never
 * leaks a held lock). Never calls `pendingMigrationTracker.clearPendingMigration()` — a restore to
 * an older snapshot does not, by itself, resolve schema drift against the current runtime
 * (ADR-045 §4).
 *
 * @complexity O(1) plus one lock acquire/release pair and one `gateway.execute()` call.
 */
export async function executeRestore(
  required: ExecuteRestoreRequired,
  _optional: Record<string, never> = {}
): Promise<Result<ExecuteRestoreValue, RecoveryErrorPayload>> {
  const { deps, input } = required;

  const acquireResult = await deps.operationLock.acquireOperationLock({
    deps: { clock: deps.clock },
    input: { siteId: input.siteId, operationKind: "restore" },
  });
  if (!acquireResult.ok) {
    return {
      ok: false,
      error: {
        code: "RESTORE_OPERATION_IN_FLIGHT",
        message: acquireResult.error.message ?? `an operation is already in flight for site '${input.siteId}'`,
      },
    };
  }

  try {
    const confirmerPrincipalId = input.principalKind === "agent" ? input.delegatedByPrincipalId : input.principalId;
    const executeResult = await deps.gateway.execute({
      confirmationToken: input.confirmationToken,
      ...(confirmerPrincipalId !== undefined ? { confirmerPrincipalId } : {}),
    });
    if (!executeResult.ok) {
      return executeResult;
    }

    const value: ExecuteRestoreValue = { ...executeResult.value };
    if (value.state === "RESTORED") {
      value.databaseTimelineDeepLink = { v: 1, siteId: input.siteId, intent: "view" };
    }
    return { ok: true, value };
  } finally {
    await deps.operationLock.releaseOperationLock({
      deps: { clock: deps.clock },
      input: { siteId: input.siteId, handle: acquireResult.value },
    });
  }
}

import type { PrincipalKind, Result } from "./recovery-orchestrator.js";

/**
 * @file SPEC-019 C-304 / REQ-05 — `createRestorePoint`, an ordinary `authorize()`-gated mutation
 * (ADR-045 §3, "backup.create" independent of any migration).
 *
 * Purpose:
 * Structurally distinct from the gated restore ceremony (`recovery-orchestrator.ts`): this never
 * calls the gateway's `plan()`/`confirm()`/`execute()` at all (AC-10) — it mints a restore point
 * directly once `authorize()` and the shared-lock "no operation in flight" check both pass.
 * `authorize()` runs on EVERY call, before the idempotency short-circuit (AC-11, SPEC-016 REQ-14)
 * — a repeated idempotency key never skips re-authorization, only re-creation.
 *
 * How it relates to the project:
 * `operationInFlight` is supplied by the caller (typically derived from the same shared
 * `core/operation-lock` state `recovery-orchestrator.ts`'s `executeRestore` consults) rather than
 * this module acquiring the lock itself — REQ-13's "extends here too, via `onBeforeCreateOrExecute`"
 * is a pre-check on an already-resolved flag, not this module owning lock lifecycle.
 */

export interface CreateRestorePointRepoPort {
  save(row: {
    restorePointId: string;
    idempotencyKey: string;
    trigger: string;
    createdAt: string;
    createdBy: string;
  }): Promise<void>;
  findByIdempotencyKey(key: string): Promise<{ restorePointId: string; idempotencyKey: string } | null>;
}

export interface CreateRestorePointClockPort {
  nowIso(): string;
}

export interface CreateRestorePointIdPort {
  newId(): string;
}

export type CreateRestorePointAuthorizeFn = (params: {
  principalId: string;
  permission: string;
}) => Promise<{ allowed: boolean; reason: string }>;

export interface CreateRestorePointRequired {
  deps: {
    repo: CreateRestorePointRepoPort;
    clock: CreateRestorePointClockPort;
    ids: CreateRestorePointIdPort;
    authorize: CreateRestorePointAuthorizeFn;
    /** Present in the seam for shape-parity with the gated ceremony's deps; deliberately never
     * called here (AC-10) — kept so a caller wiring a shared deps object cannot be tempted to
     * route restore-point creation through it. */
    gateway: { plan: (...args: unknown[]) => Promise<unknown> };
  };
  input: {
    principalId: string;
    principalKind: PrincipalKind;
    idempotencyKey: string;
    trigger: "manual" | "pre-migration-auto" | "template-upgrade";
    operationInFlight: boolean;
  };
}

export interface CreateRestorePointValue {
  restorePointId: string;
}

/**
 * AC-10/AC-11/REQ-05/REQ-13 — authorize (always) -> in-flight refusal -> idempotency lookup ->
 * write. Never invokes `deps.gateway` at all.
 *
 * @complexity O(1) plus one `authorize()` call, one idempotency lookup, and (on the first call for
 * a given key) one `repo.save()` call.
 */
export async function createRestorePoint(
  required: CreateRestorePointRequired,
  _optional: Record<string, never> = {}
): Promise<Result<CreateRestorePointValue, { code: string; message?: string }>> {
  const { deps, input } = required;

  const authResult = await deps.authorize({ principalId: input.principalId, permission: "backup.create" });
  if (!authResult.allowed) {
    return { ok: false, error: { code: "FORBIDDEN", message: authResult.reason } };
  }

  if (input.operationInFlight) {
    return {
      ok: false,
      error: {
        code: "RESTORE_OPERATION_IN_FLIGHT",
        message: "a migration or restore is already in flight for this site",
      },
    };
  }

  const existing = await deps.repo.findByIdempotencyKey(input.idempotencyKey);
  if (existing) {
    return { ok: true, value: { restorePointId: existing.restorePointId } };
  }

  const restorePointId = deps.ids.newId();
  await deps.repo.save({
    restorePointId,
    idempotencyKey: input.idempotencyKey,
    trigger: input.trigger,
    createdAt: deps.clock.nowIso(),
    createdBy: input.principalId,
  });

  return { ok: true, value: { restorePointId } };
}

import { FOREIGN_SCHEMA_SIGNAL, COUNT_MISMATCH_SIGNAL } from "./signals.js";
import { spawn } from "node:child_process";

/**
 * @file The Postgres side of a database transfer, behind a port, plus its P0 adapter.
 *
 * The adapter shells out to `psql` rather than selecting a driver. Historically P0 had no installed
 * Postgres driver, and adding `pg` was a supply-chain decision for later slices (see
 * `ADS-memory/reports/2026-09-27-assistant-db-transfer-plan.md` §3.3). The port is what the copier
 * depends on, so swapping in `pg` later touches only this file.
 *
 * The connection string never reaches `psql`'s argv (visible to `ps`): it is split into libpq's own
 * `PG*` environment variables, and every inherited `PG*` variable is dropped first so a stray
 * `PGPASSWORD` in the server's environment can never apply to a user's database.
 */

/** What may be shown about a destination: never the password. */
export interface TargetDescription {
  readonly host: string;
  readonly port: string;
  readonly database: string;
  readonly user: string;
}

/** `error` is a copier-owned failure code or a fixed safe message; server text is private.
 * `copyTable` names the table a failed COPY was loading. */
export type TargetResult<T> = { readonly ok: true; readonly value: T } | { readonly ok: false; readonly error: string; readonly copyTable?: string };

export interface PostgresTargetPort {
  describe(): TargetDescription;
  /** One statement; rows as tab-separated text cells. */
  query(sql: string): Promise<TargetResult<string[][]>>;
  /** A psql script fed through stdin, chunk by chunk, stopping at the first error. */
  runScript(chunks: Iterable<string>): Promise<TargetResult<null>>;
}

export class InvalidConnectionStringError extends Error {}

interface ParsedConnection {
  readonly description: TargetDescription;
  readonly env: Readonly<Record<string, string>>;
}

function parsePostgresUrl({ raw }: { raw: string }, _options = {}): URL {
  let url: URL;
  try {
    url = new URL(raw.trim());
  } catch {
    throw new InvalidConnectionStringError("the connection string is not a valid postgres:// URL");
  }
  if (url.protocol !== "postgres:" && url.protocol !== "postgresql:") {
    throw new InvalidConnectionStringError("the connection string must start with postgres:// or postgresql://");
  }
  return url;
}

/**
 * Splits a `postgres://` / `postgresql://` URL into libpq environment variables.
 *
 * @throws {InvalidConnectionStringError} With a message that never quotes the string itself.
 */
export function parseConnectionString({ raw }: { raw: string }, { applicationName = "database-transfer" }: { applicationName?: string } = {}): ParsedConnection {
  const url = parsePostgresUrl({ raw });
  const host = url.searchParams.get("host") ?? decodeURIComponent(url.hostname);
  const database = decodeURIComponent(url.pathname.replace(/^\//, ""));
  const user = decodeURIComponent(url.username);
  if (host === "" || database === "" || user === "") {
    throw new InvalidConnectionStringError("the connection string must name a host, a user and a database");
  }
  const port = url.port || "5432";
  const env: Record<string, string> = { PGHOST: host, PGPORT: port, PGDATABASE: database, PGUSER: user, PGCONNECT_TIMEOUT: "5", PGAPPNAME: applicationName };
  if (url.password !== "") env.PGPASSWORD = decodeURIComponent(url.password);
  const sslmode = url.searchParams.get("sslmode");
  if (sslmode !== null) env.PGSSLMODE = sslmode;
  return { description: { host, port, database, user }, env };
}

/** The parent environment without any `PG*` variable. */
function environmentWithout(parent: NodeJS.ProcessEnv): Record<string, string> {
  const env: Record<string, string> = {};
  for (const [key, value] of Object.entries(parent)) {
    if (!key.startsWith("PG") && value !== undefined) env[key] = value;
  }
  return env;
}

/** Classifies copier failure codes; arbitrary psql text never reaches public errors or logs.
 * @complexity O(n) time/space in stderr length. */
/** Only the transfer's own signals pass through; any other psql text stays in the log. */
function publicFailure({ message, countedTable }: { message: string; countedTable: string | undefined }): string {
  if (message === FOREIGN_SCHEMA_SIGNAL) return FOREIGN_SCHEMA_SIGNAL;
  if (message.startsWith(`${COUNT_MISMATCH_SIGNAL} `)) return `${COUNT_MISMATCH_SIGNAL} ${countedTable ?? "[redacted]"}`;
  return "psql request failed";
}
function failureFrom({ stderr }: { stderr: string }, _options = {}): { ok: false; error: string; copyTable?: string } {
  const lines = stderr.split("\n").map((line) => line.trim()).filter((line) => line !== "");
  const line = lines.find((candidate) => /\bERROR:|FATAL:|could not|timeout/i.test(candidate)) ?? lines[0] ?? "psql failed without a message";
  const message = line.replace(/^psql:[^ ]*: /, "").replace(/^ERROR:\s*/, "");
  const countMismatch = new RegExp(`^${COUNT_MISMATCH_SIGNAL} ([A-Za-z_][A-Za-z0-9_]{0,62})$`).exec(message);
  const error = publicFailure({ message, countedTable: countMismatch?.[1] });
  const copyMatch = /\bCOPY ([A-Za-z0-9_."]+), line \d+/.exec(stderr);
  const copyTable = copyMatch ? copyMatch[1]!.replace(/"/g, "") : undefined;
  return copyTable === undefined ? { ok: false, error } : { ok: false, error, copyTable };
}

/** The slice of a spawned `psql` child this adapter drives: its three pipes, `error` and `close`. */
export interface PsqlProcess {
  readonly stdin: NodeJS.WritableStream;
  readonly stdout: NodeJS.ReadableStream;
  readonly stderr: NodeJS.ReadableStream;
  on(event: "error", listener: (error: Error) => void): unknown;
  on(event: "close", listener: (code: number | null) => void): unknown;
}

/** Starts `psql` with the given argv and environment; the default resolves it on the host PATH. */
export type PsqlSpawn = (args: readonly string[], options: { env: Record<string, string> }) => PsqlProcess;

const spawnPsql: PsqlSpawn = (args, { env }) =>
  // eslint-disable-next-line sonarjs/no-os-command-from-path -- Operator-installed psql intentionally resolves through the trusted host PATH; connection input supplies PG fields, never the executable or PATH.
  spawn("psql", args, { env, stdio: ["pipe", "pipe", "pipe"] });

function runPsql(env: Record<string, string>, args: readonly string[], chunks: Iterable<string> | null, launch: PsqlSpawn): Promise<TargetResult<string>> {
  return new Promise((resolve) => {
    const child = launch(["-X", "-q", "-v", "ON_ERROR_STOP=1", ...args], { env });
    let stdout = "";
    let stderr = "";
    child.stdout.setEncoding("utf8").on("data", (data: string) => (stdout += data));
    child.stderr.setEncoding("utf8").on("data", (data: string) => (stderr += data));
    child.on("error", () => resolve({ ok: false, error: "psql could not be started" }));
    child.on("close", (code) => resolve(code === 0 ? { ok: true, value: stdout } : failureFrom({ stderr })));
    child.stdin.on("error", () => undefined);
    void (async () => {
      for (const chunk of chunks ?? []) {
        if (!child.stdin.write(chunk)) await new Promise((drain) => child.stdin.once("drain", drain));
      }
      child.stdin.end();
    })();
  });
}

/**
 * The P0 adapter: every call is one short-lived `psql` process, started through `spawnProcess`
 * (default: `psql` on the host PATH).
 *
 * @throws {InvalidConnectionStringError} When the string cannot be parsed.
 */
export function createPsqlPostgresTarget({ connectionString }: { connectionString: string }, { parentEnv = process.env, applicationName, spawnProcess = spawnPsql }: { parentEnv?: NodeJS.ProcessEnv; applicationName?: string; spawnProcess?: PsqlSpawn } = {}): PostgresTargetPort {
  const parsed = parseConnectionString({ raw: connectionString }, applicationName === undefined ? {} : { applicationName });
  const env = { ...environmentWithout(parentEnv), ...parsed.env };
  return {
    describe: () => parsed.description,
    async query(sql) {
      const result = await runPsql(env, ["-t", "-A", "-F", "\t", "-c", sql], null, spawnProcess);
      if (!result.ok) return result;
      const rows = result.value.split("\n").filter((line) => line !== "").map((line) => line.split("\t"));
      return { ok: true, value: rows };
    },
    async runScript(chunks) {
      const result = await runPsql(env, ["-f", "-"], chunks, spawnProcess);
      return result.ok ? { ok: true, value: null } : result;
    },
  };
}

import path from 'node:path';
import type { InstanceRecord } from './update-policy.js';

/**
 * Concurrent instances need presence records because no single-instance lock tracks siblings:
 * one updater owner downloads, and only the last live instance may install on quit.
 * PID reuse can make a crashed instance look alive; delaying installation is the safe error.
 * Owner election separately ignores stale heartbeats so such a record cannot block all checks.
 */
/** No locking: each process owns one atomic presence record, permitting concurrent instances. */
export interface InstancePresencePort {
  write(input: { record: InstanceRecord }): void;
  readLive(): InstanceRecord[];
  remove(input: { pid: number }): void;
}
export interface PresenceFilesystemPort {
  mkdirSync(requiredArgs: { path: string }, optionalArgs?: { recursive?: boolean }): unknown;
  writeFileSync(requiredArgs: { path: string; data: string }): void;
  renameSync(requiredArgs: { oldPath: string; newPath: string }): void;
  unlinkSync(requiredArgs: { path: string }): void;
  readdirSync(requiredArgs: { path: string }): string[];
  readFileSync(requiredArgs: { path: string; encoding: 'utf8' }): string;
}
export interface FileInstancePresenceInput {
  directory: string;
  filesystem: PresenceFilesystemPort;
  isAlive: (args: { pid: number }) => boolean;
  writerPid: number;
}

/** Resolve a caller-named state directory. @complexity O(n) in path length. */
export function presenceDirPath({ userDataDir, directoryName }: { userDataDir: string; directoryName: string }): string {
  return path.join(userDataDir, directoryName);
}

/** Signal-zero liveness probe; EPERM still means alive. @complexity O(1). */
export function isPidAlive({ pid, probe }: { pid: number; probe: (args: { pid: number; signal: 0 }) => unknown }): boolean {
  try { probe({ pid, signal: 0 }); return true; }
  catch (error) { return (error as NodeJS.ErrnoException)?.code === 'EPERM'; }
}

/** Unreadable, partial and malformed records are ignored rather than deleted. @complexity O(n) in text length. */
function parseRecord(text: string): InstanceRecord | null {
  try {
    const record = JSON.parse(text) as InstanceRecord;
    if (!record || ![record.pid, record.startedAt, record.heartbeatAt].every(value => typeof value === 'number' && Number.isFinite(value))) return null;
    return record;
  } catch { return null; }
}

/** Atomic filesystem adapter. Writes propagate errors; reads and removals tolerate missing files.
 * @complexity O(1) to construct; O(n) files and probes per read.
 */
export function createFileInstancePresence({ directory, filesystem, isAlive, writerPid }: FileInstancePresenceInput): InstancePresencePort {
  const fileFor = (pid: number) => path.join(directory, `${pid}.json`);
  function remove({ pid }: { pid: number }): void {
    try { filesystem.unlinkSync({ path: fileFor(pid) }); } catch { /* Removal on exit is best effort. */ }
  }
  return {
    write({ record }) {
      // Publish by rename so a sibling never reads a half-written JSON record.
      filesystem.mkdirSync({ path: directory }, { recursive: true });
      const target = fileFor(record.pid);
      const temporary = `${target}.${writerPid}.tmp`;
      filesystem.writeFileSync({ path: temporary, data: JSON.stringify(record) });
      filesystem.renameSync({ oldPath: temporary, newPath: target });
    },
    remove,
    readLive() {
      let names: string[];
      try { names = filesystem.readdirSync({ path: directory }).filter(name => /^\d+\.json$/.test(name)); }
      catch { return []; }
      const live: InstanceRecord[] = [];
      for (const name of names) {
        let record: InstanceRecord | null;
        try { record = parseRecord(filesystem.readFileSync({ path: path.join(directory, name), encoding: 'utf8' })); }
        catch { continue; }
        // Leave unreadable/malformed records alone: a sibling may be writing on a filesystem
        // without atomic rename. Remove confirmed dead PIDs so crashes do not linger.
        if (record !== null && name === `${record.pid}.json`) {
          if (isAlive({ pid: record.pid })) live.push(record);
          else remove({ pid: record.pid });
        }
      }
      return live;
    },
  };
}

/** Fake Tauri surfaces for tests — never a real `@tauri-apps/*` import (see `tauri-surfaces.ts`). */
import type {
  TauriChildProcessLike,
  TauriDialogApi,
  TauriFileInfo,
  TauriFsApi,
  TauriShellApi,
  TauriSidecarCommandApi,
  TauriSingleInstanceApi,
  TauriWindowCreateOptions,
  TauriWindowFactory,
  TauriWindowLike,
} from './tauri-surfaces.js';

export function createFakeTauriSingleInstanceApi(_requiredArgs: Record<string, never>): TauriSingleInstanceApi & { emitSecondInstance({ args, cwd }: { args: string[]; cwd: string }): void } {
  const listeners: Array<(args: { args: string[]; cwd: string }) => void> = [];
  return {
    onSecondInstance({ listener }) {
      listeners.push(listener);
      return () => {
        const index = listeners.indexOf(listener);
        if (index >= 0) listeners.splice(index, 1);
      };
    },
    emitSecondInstance({ args, cwd }) {
      for (const listener of listeners) listener({ args, cwd });
    },
  };
}

export function createFakeTauriWindowFactory(_requiredArgs: Record<string, never>): { factory: TauriWindowFactory; windows: TauriWindowLike[] } {
  const windows: TauriWindowLike[] = [];
  const factory = async (_requiredArgs: Pick<TauriWindowCreateOptions, 'label' | 'url'>, _options: Omit<TauriWindowCreateOptions, 'label' | 'url'> = {}): Promise<TauriWindowLike> => {
    let closed = false;
    const closeListeners: Array<() => void> = [];
    const closedListeners = new Set<() => void>();
    const win: TauriWindowLike & { navigatedTo: string[] } = {
      navigatedTo: [],
      async show() {},
      async hide() {},
      async setFocus() {},
      async close() {
        for (const listener of closeListeners) listener();
        closed = true;
        for (const listener of closedListeners) listener();
      },
      async navigate({ url }: { url: string }) {
        win.navigatedTo.push(url);
      },
      isClosed() {
        return closed;
      },
      onCloseRequested({ listener }) {
        closeListeners.push(listener);
        return () => {
          const index = closeListeners.indexOf(listener);
          if (index >= 0) closeListeners.splice(index, 1);
        };
      },
      onClosed({ listener }) {
        closedListeners.add(listener);
        return () => { closedListeners.delete(listener); };
      },
    };
    windows.push(win);
    return win;
  };
  return { factory, windows };
}

export function createFakeTauriShellApi(_requiredArgs: Record<string, never>): TauriShellApi & { openedUrls: string[]; openedPaths: string[] } {
  const openedUrls: string[] = [];
  const openedPaths: string[] = [];
  return {
    openedUrls,
    openedPaths,
    async openUrl({ url }: { url: string }) {
      openedUrls.push(url);
    },
    async openPath({ path }: { path: string }) {
      openedPaths.push(path);
    },
  };
}

/** `directories`/`files` are absolute-path allow-lists the fake checks `exists`/`stat` against — no real filesystem I/O, matching this module's own "never a real @tauri-apps/* import" convention (and, transitively, no real `node:fs` either). */
export function createFakeTauriFsApi(_requiredArgs: Record<string, never>, seed: { directories?: string[]; files?: string[] } = {}): TauriFsApi {
  const directories = new Set(seed.directories ?? []);
  const files = new Set(seed.files ?? []);
  return {
    async exists({ path }: { path: string }) {
      return directories.has(path) || files.has(path);
    },
    async stat({ path }: { path: string }): Promise<TauriFileInfo> {
      return { isDirectory: directories.has(path) };
    },
  };
}

export function createFakeTauriDialogApi(_requiredArgs: Record<string, never>, script: { openResult?: string | string[] | null } = {}): TauriDialogApi & {
  lastOpenOptions: unknown;
} {
  const fake = {
    lastOpenOptions: undefined as unknown,
    async open(_requiredArgs: Record<string, never>, options: import('./tauri-surfaces.js').TauriOpenDialogOptions = {}) {
      fake.lastOpenOptions = options;
      return script.openResult ?? null;
    },
  };
  return fake;
}

export interface FakeTauriSidecarScript {
  exitImmediatelyWithCode?: number;
  readyAfterProbes?: number;
  ignoresGracefulShutdown?: boolean;
}

export function createFakeTauriSidecarCommandApi(_requiredArgs: Record<string, never>, script: FakeTauriSidecarScript = {}): TauriSidecarCommandApi & {
  spawned: Array<{ binaryName: string; args: string[] }>;
} {
  const spawned: Array<{ binaryName: string; args: string[] }> = [];
  return {
    spawned,
    async spawnSidecar({ binaryName, args }) {
      spawned.push({ binaryName, args });
      const exitListeners: Array<(args: { code: number | null; signal: NodeJS.Signals | null }) => void> = [];
      const child: TauriChildProcessLike = {
        pid: 4242,
        onExit({ listener }) {
          exitListeners.push(listener);
        },
        kill(_requiredArgs, { signal } = {}) {
          // A child that ignores graceful shutdown still accepts the signal; only SIGKILL ends it.
          if (script.ignoresGracefulShutdown === true && signal !== 'SIGKILL') return true;
          // A macrotask, not queueMicrotask: real process exit delivery
          // happens after the event loop's current microtask work drains
          // (the caller's own await chains included). queueMicrotask here
          // would race ahead of a listener a caller registers after one
          // more `await`, silently dropping the event — exactly the kind
          // of flake this fake exists to not have.
          setTimeout(() => {
            for (const listener of exitListeners) listener({ code: null, signal: signal ?? 'SIGTERM' });
          }, 0);
          return true;
        },
      };
      const exitImmediatelyWithCode = script.exitImmediatelyWithCode;
      if (exitImmediatelyWithCode != null) {
        // `exitImmediatelyWithCode` (a local, narrowed here) rather than
        // `script.exitImmediatelyWithCode` again inside the closure: TS
        // narrowing doesn't persist across a property access re-read in a
        // later closure, but re-reading the property here is genuinely
        // always defined given the guard above — a local avoids needing an
        // otherwise-dead `?? 0` fallback to satisfy the type checker.
        setTimeout(() => {
          for (const listener of exitListeners) listener({ code: exitImmediatelyWithCode, signal: null });
        }, 0);
      }
      return child;
    },
  };
}

/**
 * @file Shared site-path checks: decoded, dot-resolved segments and origin tracking.
 *
 * Why the rule is not `path.startsWith("/admin")`:
 * - `/administer-survey` is ordinary site content and must keep working, so the comparison is per
 *   SEGMENT, not per prefix.
 * - `/%61dmin` is compared AFTER one percent-decode, not on the raw bytes. Express (which routes on
 *   the raw path) and browsers (which do not decode `%61` in a path) do NOT treat it as `/admin`; a
 *   proxy or server that decodes before routing does. Refusing it is deliberate over-refusal — the
 *   safe direction for a rule whose job is to keep public redirects and fetches off the admin
 *   surface.
 * - `/ADMIN` reaches the same Express mount (Express matches paths case-insensitively by default),
 *   so the comparison is case-folded.
 * - `/blog/../admin` is `/admin` by the time a browser issues the request, so dot segments are
 *   resolved first.
 *
 */

/** {@link checkSitePathname}'s verdict. Every arm is a refusal except `ok`. */
export type SitePathCheck =
  | { kind: "ok" }
  /** `decodeURIComponent` threw — a stray or truncated `%` sequence. */
  | { kind: "malformed-encoding" }
  /** Decodes to a backslash (a `/` to URL parsers) or a C0/C1 control character (CR/LF splitting). */
  | { kind: "disallowed-character" }
  | { kind: "reserved"; surface: string };

/** {@link checkSiteRelativeTarget}'s verdict — {@link SitePathCheck} plus the two structural arms
 *  that only apply when the input is still a raw, unparsed reference. */
export type SiteRelativeTargetCheck =
  | SitePathCheck
  /** `new URL()` could not parse it at all. */
  | { kind: "unparseable" }
  /** Parses, but resolves to a DIFFERENT host — e.g. `/\evil.example`, which starts with a single
   *  slash yet is `//evil.example` to a URL parser, so a `startsWith("//")` test never sees it. */
  | { kind: "off-origin" };

/**
 * Two hosts this deployment can never actually reach, used only so `new URL()` has a base to
 * resolve a site-relative reference against. `.invalid` is reserved by RFC 2606 precisely for this.
 *
 * There are TWO because one base is NAMEABLE (t85 independent review, 2026-09-16). With a single
 * base, `//reserved-path-probe.invalid/x` resolves to that very origin, so "did the origin survive"
 * answered yes for a reference that leaves the site — reachable as `/store/buy`'s `returnTo`, which
 * sent `Location: //reserved-path-probe.invalid/x`. Requiring the resolved origin to TRACK whichever
 * base it was given leaves no origin an input can name, which is a structural answer rather than a
 * denylist of the sentinel's spellings (the same reasoning as the probe itself — see
 * {@link checkSiteRelativeTarget}). Both are bare origins, so a reference resolves to the same
 * pathname against either.
 */
// eslint-disable-next-line sonarjs/no-clear-text-protocols -- Reserved .invalid probe origin used only for URL parsing; no network transport is invoked.
const PROBE_ORIGIN = "http://reserved-path-probe.invalid";
// eslint-disable-next-line sonarjs/no-clear-text-protocols -- Reserved .invalid probe origin used only for URL parsing; no network transport is invoked.
const SECOND_PROBE_ORIGIN = "http://reserved-path-probe-2.invalid";

/**
 * Whether `value` contains a C0 or C1 control character.
 *
 * CR/LF in a request target is HTTP request splitting and in a `Location` header is response
 * splitting; NUL and friends are path-truncation tricks.
 *
 * @param required.value - Any string, already decoded or not.
 * @returns `true` if any code unit is in `U+0000`–`U+001F` or `U+007F`–`U+009F`.
 * @complexity O(n) in the string length.
 * @example hasControlCharacter({ value: "/ok" }, {}); // => false
 */
export function hasControlCharacter(
  { value }: { value: string },
  _optional: Record<string, never> = {},
): boolean {
  for (let index = 0; index < value.length; index += 1) {
    const code = value.charCodeAt(index);
    if (code <= 0x1f || (code >= 0x7f && code <= 0x9f)) return true;
  }
  return false;
}

/**
 * Resolve `.` and `..` segments, RFC 3986 §5.2.4 style, on an already-decoded path.
 *
 * Done by hand rather than with a second `new URL()` pass because a decoded path can contain a
 * literal `?` or `#` (from `%3F`/`%23`), and the URL parser would treat those as a query/fragment
 * delimiter and TRUNCATE the path — turning `/x#/../admin` into `/x` and losing the very segment
 * this check exists to find. A browser does no such thing: it never decodes `%23` before splitting
 * the path, so the truncation would be a false negative, not a match for real behavior.
 *
 * Empty segments are dropped, so `//admin` collapses to `/admin`. That is deliberately stricter
 * than a URL parser (which preserves `//`); over-matching here only ever refuses more.
 *
 * @param path - A decoded path, expected to start with `/`.
 * @returns The path with dot segments removed, always starting with `/`.
 * @complexity O(n) in the path length.
 * @example resolveDotSegments("/blog/../admin"); // => "/admin"
 */
function resolveDotSegments(path: string): string {
  const out: string[] = [];
  for (const segment of path.split("/")) {
    if (segment === "" || segment === ".") continue;
    if (segment === "..") out.pop();
    else out.push(segment);
  }
  return `/${out.join("/")}`;
}

/**
 * The actual per-segment rule, on a pathname string that is guaranteed to have come from a real
 * `URL` (see {@link checkSitePathname}, this function's only caller). Kept private: a bare
 * string carries no proof it was ever parsed — the query/fragment stripping, dot-segment removal
 * relative to a real origin, etc. are exactly what `new URL()` already did before that caller
 * reaches this. Do not export this directly.
 *
 * Check the undecoded first segment too: Express mounts `/admin/..%2fpublic` under `/admin`,
 * even though decoding and resolving dot segments produces `/public`.
 * Order is load-bearing for the decoded check: decode ONCE, then resolve dot segments, then compare
 * the first segment case-folded. Decoding first is what catches `/%61dmin` (over-refusal for Express
 * and browsers, a real match for a decoding proxy — see the module doc); resolving dot segments after the decode is
 * what catches `/blog/%2e%2e/admin`. Exactly one decode pass models one decoding intermediary:
 * `/%2561dmin` would need two, so it stays allowed.
 *
 * @param required.pathname - An already-parsed `URL`'s `.pathname` (no query, no fragment).
 * @param required.reservedSegments - First segments reserved by the host, stored case-folded.
 * @returns `{ kind: "ok" }` when it is ordinary site content; otherwise the arm naming the refusal.
 * @complexity O(n) in the pathname length.
 */
function checkDecodedSitePathname(
  { pathname, reservedSegments }: { pathname: string; reservedSegments: ReadonlySet<string> },
  _optional: Record<string, never> = {},
): SitePathCheck {
  let decoded: string;
  try {
    decoded = decodeURIComponent(pathname);
  } catch {
    return { kind: "malformed-encoding" };
  }
  if (decoded.includes("\\") || hasControlCharacter({ value: decoded }, {})) return { kind: "disallowed-character" };

  const rawFirst = pathname.slice(1).split("/", 1).join("").toLowerCase();
  if (reservedSegments.has(rawFirst)) return { kind: "reserved", surface: rawFirst };

  // `resolveDotSegments` always returns a path with a leading "/", so the first segment is
  // everything after it up to the next "/" — `split(..., 1)` yields exactly that one element.
  const first = resolveDotSegments(decoded).slice(1).split("/", 1).join("").toLowerCase();
  if (reservedSegments.has(first)) return { kind: "reserved", surface: first };
  return { kind: "ok" };
}

/**
 * Classify an already-parsed URL's pathname against the admin application's URL space.
 *
 * Takes the {@link URL} itself, not a bare pathname string, so this cannot be handed a raw,
 * unparsed reference by accident: a string has no way to prove it went through `new URL()` first,
 * and this rule's whole design (see the module doc) depends on comparing the DECODED, dot-resolved
 * form a URL parser would actually produce. A caller that only has a raw string — a stored redirect
 * target, anything from user input — must go through {@link checkSiteRelativeTarget} instead, which
 * parses it (and rejects what doesn't parse) before this check ever runs.
 *
 * PRECONDITION: the caller has already established that `url` is on the site's own origin. This
 * function reads only `pathname`, so `new URL("//admin", base)` (host `admin`, pathname `/`)
 * returns `ok`. It deliberately does not compare origins itself: `platform/routing` cannot use
 * `features/origin`'s normalizer, and a string `URL.origin` comparison is wrong for redirect
 * candidates (`https://site./admin`). Callers: `checkSiteRelativeTarget` (probe-origin check),
 * `site-inspection`'s `resolveWithinOrigin`, and `features/redirects/reserved-destination.ts` (the
 * origin oracle's `isSameOrigin`).
 *
 * @param required.url - An already-parsed `URL`; only `url.pathname` is read.
 * @param required.reservedSegments - First segments reserved by the host, stored case-folded.
 * @returns `{ kind: "ok" }` when it is ordinary site content; otherwise the arm naming the refusal.
 * @complexity O(n) in the pathname length.
 * @example checkSitePathname({ url: new URL("/administer-survey", "http://x.invalid"), reservedSegments: new Set(["admin", "api"]) }, {}); // => { kind: "ok" }
 * @example checkSitePathname({ url: new URL("/%61dmin/settings", "http://x.invalid"), reservedSegments: new Set(["admin", "api"]) }, {}); // => { kind: "reserved", surface: "admin" }
 */
export function checkSitePathname(
  { url, reservedSegments }: { url: URL; reservedSegments: ReadonlySet<string> },
  _optional: Record<string, never> = {},
): SitePathCheck {
  return checkDecodedSitePathname({ pathname: url.pathname, reservedSegments }, {});
}

/**
 * Classify a raw, site-relative reference (a stored redirect target, a caller-supplied path)
 * against the admin application's URL space, including the structural check that it is site-
 * relative at all.
 *
 * The structural pass runs FIRST and matters on its own: `/\evil.example` begins with exactly one
 * slash, so a `startsWith("//")` or scheme test calls it site-relative, while `new URL()` — and
 * every browser following a `Location` — reads the backslash as a separator and lands on
 * `evil.example`. Resolving against a probe origin and asserting the origin TRACKED that base is a
 * structural answer to that instead of a pattern someone has to keep correct — done against two
 * different bases so the probe origin itself is not a nameable way to pass (see
 * {@link PROBE_ORIGIN}).
 *
 * @param required.raw - The untrusted reference, expected to be site-relative.
 * @param required.reservedSegments - First segments reserved by the host, stored case-folded.
 * @returns `{ kind: "ok" }` when it stays on this site and names ordinary content; otherwise the
 * arm naming the refusal.
 * @complexity O(n) in the reference length.
 * @example checkSiteRelativeTarget({ raw: "/new", reservedSegments: new Set(["admin", "api"]) }, {}); // => { kind: "ok" }
 * @example checkSiteRelativeTarget({ raw: "/\\evil.example", reservedSegments: new Set(["admin", "api"]) }, {}); // => { kind: "off-origin" }
 */
export function checkSiteRelativeTarget(
  { raw, reservedSegments }: { raw: string; reservedSegments: ReadonlySet<string> },
  _optional: Record<string, never> = {},
): SiteRelativeTargetCheck {
  if (hasControlCharacter({ value: raw }, {})) return { kind: "disallowed-character" };
  let parsed: URL;
  let reparsed: URL;
  try {
    parsed = new URL(raw, PROBE_ORIGIN);
    reparsed = new URL(raw, SECOND_PROBE_ORIGIN);
  } catch {
    return { kind: "unparseable" };
  }
  if (parsed.origin !== PROBE_ORIGIN || reparsed.origin !== SECOND_PROBE_ORIGIN) return { kind: "off-origin" };
  return checkSitePathname({ url: parsed, reservedSegments }, {});
}

/** Workspace-scoped subscription/delivery records and serializable wire envelopes. */
import type { UUID, ISODateTime, JsonObject } from "@jini-ai/core/primitives";

/** Topic names share the domain-event catalog ({entity}.{action}); an entity's trailing .*
 * subscribes to all its actions, while all-topic * requires the host's owner authorization. */
export type WebhookTopic = string;

// Stable identity for an integration-owned row; the host supplies the concrete ID scheme.
export type IntegrationId = UUID;

/** Monotonic subscription signing generation; rotation increments it and honors both versions
 * during overlap. Signing material is derived from root key, subscription ID and generation,
 * never stored as plaintext on the subscription. */
export type SecretVersion = number;

export type WebhookSubscriptionStatus = "active" | "paused" | "disabled";

/** Storage must isolate rows by (workspaceId, id); API-key ownership is a principal reference,
 * not a second API-key definition. Store only signing generations, not their derived secrets. */
export interface WebhookSubscriptionRecord {
  id: IntegrationId;
  workspaceId: UUID;
  // Host authorization must bound a delivery's reach by this owner, including an API-key owner.
  ownerPrincipalId: UUID;
  label: string;
  // An absolute HTTPS target; the injected outbound HTTP adapter must apply egress policy on send.
  targetUrl: string;
  // Empty topics match nothing; catalog validation and all-topic owner authorization stay host-owned.
  topics: readonly WebhookTopic[];
  secretVersion: SecretVersion;
  // Honor the prior generation during rotation overlap so receivers can migrate without loss.
  previousSecretVersion: SecretVersion | null;
  status: WebhookSubscriptionStatus;
  // Stamp originating actor/plugin attribution at the host's mutation chokepoint.
  createdByPrincipalId: UUID;
  createdByPluginId: string | null;
  createdAt: ISODateTime;
  updatedAt: ISODateTime;
  // Retain the disabled row and timestamp for durable audit lineage.
  disabledAt: ISODateTime | null;
}

/** pending -> delivering -> delivered | failed; retryable failures become eligible again after
 * backoff, then dead after exhaustion. canceled is available to subscription-removal adapters. */
export type WebhookDeliveryStatus =
  | "pending"
  | "delivering"
  | "delivered"
  | "failed"
  | "dead"
  | "canceled";

/**
 * One event/subscription pair owns its own attempt group. Fan-out endpoints retry independently,
 * so their HTTP retry state must not share the source event's outbox row. This high-churn machine
 * state is operational bookkeeping, rather than a content revision for every retry.
 */
export interface WebhookDeliveryRecord {
  id: IntegrationId;
  workspaceId: UUID;
  subscriptionId: IntegrationId;
  eventId: UUID;
  topic: WebhookTopic;
  status: WebhookDeliveryStatus;
  attempts: number;
  nextAttemptAt: ISODateTime;
  // Null before any attempt or on transport failure; no HTTP response status exists then.
  lastResponseStatus: number | null;
  lastError: string | null;
  // Signing-generation attribution supports delivery audits and receiver diagnostics.
  signedWithVersion: SecretVersion | null;
  createdAt: ISODateTime;
  deliveredAt: ISODateTime | null;
  deadAt: ISODateTime | null;
}

/** Serializable projection of the source event, never a live core object; a stable wire
 * contract lets async redaction hooks transform data without leaking internal event objects. */
export interface WebhookEventEnvelope {
  // Stable across this event/subscription attempt group; the host echoes it in a delivery header.
  deliveryId: IntegrationId;
  // Source event identity supports receiver deduplication under at-least-once delivery.
  eventId: UUID;
  topic: WebhookTopic;
  workspaceId: UUID;
  occurredAt: ISODateTime;
  data: JsonObject;
}

export interface WebhookSignature {
  timestamp: number;
  signatures: readonly string[];
}

/** Outbound credentials must be recoverable for sending, unlike derived webhook signing keys.
 * Persist them sealed under a root key and open only through the sealer, never as portable plaintext. */
export interface IntegrationSecretRecord {
  id: IntegrationId;
  workspaceId: UUID;
  ownerPrincipalId: UUID;
  // The logical credential name is public metadata; only sealed contains its recoverable value.
  name: string;
  sealed: SealedSecret;
  createdByPrincipalId: UUID;
  createdAt: ISODateTime;
  updatedAt: ISODateTime;
}

/** keyId identifies the wrapping-key generation so export adapters can rewrap or strip a secret
 * explicitly instead of silently transporting it with ordinary content. Ciphertext/nonce are
 * base64 AEAD data; alg identifies the authenticated cipher. */
export interface SealedSecret {
  keyId: string;
  ciphertext: string;
  nonce: string;
  alg: string;
}

/** Async filters operate only on serializable envelope data before signing. They can redact,
 * replace or veto; lower priority runs first rather than relying on registration order. */
export interface WebhookBeforeDispatchHook {
  readonly priority: number;
  handle(input: {
    readonly subscription: WebhookSubscriptionRecord;
    readonly envelope: WebhookEventEnvelope;
  }): Promise<WebhookBeforeDispatchResult>;
}

/** send=false vetoes this attempt; a missing replacement passes the envelope through unchanged. */
export interface WebhookBeforeDispatchResult {
  readonly send: boolean;
  readonly envelope?: WebhookEventEnvelope;
}

import type { McpResourceDef } from '../resource-protocol.js';
import { createExecuteReadonlyDelegatedToolTool, type CreateExecuteDelegatedToolToolOptions } from '../tools/delegated-tool.js';

/** Expose a host's learning tool as an attachable resource through the EXISTING read-only gateway.
 * The run identity is host-bound; bearer headers, cancellation and authorization follow the same
 * path as tools/call. No direct registry read or privileged principal is introduced.
 * @param input - The spawning run id, never supplied by the MCP client.
 * @returns jini://site-guide, with a fresh permission-scoped overview on every read.
 * @throws When the host lacks site_guide, authorization denies, or execution does not complete.
 * @complexity O(1) plus one delegated read and result serialization.
 * @example createSiteGuideResource({ runId });
 */
export function createSiteGuideResource(input: { readonly runId: string }, options: CreateExecuteDelegatedToolToolOptions = {}): McpResourceDef {
  const gateway = createExecuteReadonlyDelegatedToolTool(input, options);
  return {
    uri: 'jini://site-guide', name: 'How this site works', mimeType: 'application/json',
    description: 'Permission-filtered building blocks and live facts for the site hosting this run. Consult before planning or building; use site_guide explain through the delegated gateway for details.',
    read: async ({ ctx }) => {
      const result = await gateway.handler({ args: { toolId: 'site_guide', input: { operation: 'overview' } }, ctx });
      const completed = typeof result === 'object' && result !== null && 'status' in result && result.status === 'completed';
      if (!completed || !('output' in result)) {
        throw new Error('site_guide resource read did not complete. Use the delegated tool result to inspect authorization or availability.');
      }
      return { text: JSON.stringify(result.output, null, 2) };
    },
  };
}

import path from "node:path";
import { createHash } from "node:crypto";
import type { DurableJsonFile } from "./durable-json.js";
import { resolveDirectoryHome } from "./directory-home.js";
import { resolveUserDataDirectories, type UserDirectoryOptions } from "./user-data-directories.js";
import { detectDirectorySync, type DirectorySyncProvider } from "./directory-sync.js";

export interface DirectoryUserConfig { sitesHome: string; siteRoots: string[]; databases: "inSite" | "appData"; }
export interface DirectoryUserConfigPolicy {
  appName: string;
  rootsEnvName: string;
  sourceRoots?: readonly string[];
  legacySettingsFile?: string;
  legacyDefaultFolder?: string;
  /** Nest new workspaces while retaining immediate old-level children for discovery. */
  defaultSubfolder?: string;
}

const SAFE_SITE_ID = /^[a-zA-Z0-9_-]+$/;
const invalidMarker = (markerPath: string) => new Error(`Interrupted database move has an invalid recovery marker: ${markerPath}. Restore the pre-move backup before starting.`);
function assertDatabaseFilename(filename: string): void {
  if (path.basename(filename) !== filename || !filename.endsWith(".db")) throw new Error("A database filename must be a .db basename.");
}
/** iCloud keeps data.nosync out of sync; every other provider syncs live databases. */
function syncsDatabases(sync: DirectorySyncProvider | null): sync is Exclude<DirectorySyncProvider, "iCloud"> { return sync !== null && sync !== "iCloud"; }
/** Old markers use the fixed home2 name; new moves identify their unique backup. Admit
 * only a sibling of this source so malformed metadata cannot supply unrelated evidence. */
function markerBackup(source: string, namedBackup: unknown): string | undefined {
  if (namedBackup === undefined) return source + ".home2-backup";
  if (typeof namedBackup !== "string" || path.dirname(namedBackup) !== path.dirname(source) || !namedBackup.startsWith(source + ".relocation-") || !namedBackup.endsWith("-backup")) return undefined;
  return namedBackup;
}

/** One atomic settings owner for multiple processes. Existing DB files always win over preferences:
 * changing placement controls new databases, never silently moves or abandons existing ones.
 * @complexity O(n) canonicalizations for n roots; DB lookup probes three fixed locations.
 */
export function createDirectoryUserConfig(
  { homeDir, defaultFolder, envName, policy, fileAt, canonicalPath, exists, isDirectory, removeFile }: {
    homeDir: string; defaultFolder: string; envName: string; policy: DirectoryUserConfigPolicy;
    fileAt: (file: string) => DurableJsonFile; canonicalPath: (required: { path: string }) => string;
    exists: (file: string) => boolean; isDirectory: (file: string) => boolean;
    removeFile?: (required: { filePath: string }) => void;
  }, { env = process.env, cwd = process.cwd(), report = console.warn, ...directoryOptions }: UserDirectoryOptions & { cwd?: string; report?: (message: string) => void } = {},
) {
  const directories = resolveUserDataDirectories({ homeDir, appName: policy.appName }, { ...directoryOptions, env });
  const paths = directoryOptions.platform === "win32" ? path.win32 : path;
  const defaultHome = paths.join(directories.documents, defaultFolder, policy.defaultSubfolder ?? "");
  const localHome = paths.join(homeDir, defaultFolder, policy.defaultSubfolder ?? "");
  const legacyHomePaths = policy.defaultSubfolder ? [paths.join(directories.documents, defaultFolder), paths.join(homeDir, defaultFolder)] : [];
  const filePath = paths.join(directories.appData, "config.json"), file = fileAt(filePath);
  const expand = (value: string) => canonicalPath({ path: resolveDirectoryHome({ homeDir, defaultFolder, envName, env: {}, setting: value }, { cwd, ...(directoryOptions.platform ? { platform: directoryOptions.platform } : {}) }) });
  const distinct = (values: readonly string[]) => [...new Set(values.map(expand))];
  const legacyHomes = distinct(legacyHomePaths);
  function stored(locked = false): Partial<DirectoryUserConfig> {
    const result = file.read({});
    if (result.state === "missing") return {};
    if (result.state === "ok") {
      try { return validateDirectoryUserConfig({ value: result.value }); } catch { /* preserve invalid settings too */ }
    }
    // Bad settings must not stop boot, and read-only discovery/dry-run must not mutate settings.
    // Preserve the original on reads; the next mutation quarantines it under the existing lock.
    if (!locked) {
      report(`User config is unreadable: ${filePath}. Using defaults; the original was left untouched.`);
      return {};
    }
    if (!file.quarantine({ notice: { label: "user config", consequence: "Using default settings; existing databases keep their locations." } })) {
      throw new Error(`User config is unreadable: ${filePath}. Nothing was overwritten.`);
    }
    return {};
  }
  const syncProvider = (sitesHome: string) => detectDirectorySync({ dir: sitesHome, homeDir, documents: directories.documents }, { ...directoryOptions, env, canonicalPath });
  function read(_required: Record<string, never>, _options = {}): DirectoryUserConfig {
    const saved = stored();
    // Old default pointers follow the owner-selected nesting rule; arbitrary custom homes and
    // explicit environment overrides keep their contracts. Reading never moves user folders.
    const savedHome = saved.sitesHome === undefined ? defaultHome : expand(saved.sitesHome);
    const nestedHome = legacyHomes.includes(savedHome) ? paths.join(savedHome, policy.defaultSubfolder!) : savedHome;
    const sitesHome = expand(env[envName] ?? nestedHome);
    const sync = syncProvider(sitesHome);
    return { sitesHome, siteRoots: distinct(configuredRoots(saved)), databases: saved.databases ?? (syncsDatabases(sync) ? "appData" : "inSite") };
  }
  function configuredRoots(saved: Partial<DirectoryUserConfig>): readonly string[] {
    const fromEnv = env[policy.rootsEnvName];
    // Saved roots are extras; policy roots remain implicit unless the environment overrides them.
    return fromEnv !== undefined ? fromEnv.split(",").map((root) => root.trim()).filter(Boolean) : [...(policy.sourceRoots ?? []), ...(saved.siteRoots ?? [])];
  }
  // Prefer explicit settings, never coerce an existing regular file into a directory.
  function assertDirectories(checked: Partial<DirectoryUserConfig>): void {
    for (const directory of [checked.sitesHome, ...(checked.siteRoots ?? [])]) {
      if (directory === undefined) continue;
      const expanded = expand(directory);
      if (exists(expanded) && !isDirectory(expanded)) throw new Error(`Sites folder is not a directory: ${directory}`);
    }
  }
  function assertNotOverridden(checked: Partial<DirectoryUserConfig>): void {
    if (checked.sitesHome !== undefined && env[envName] !== undefined) throw new Error(`${envName} overrides this setting. Unset it before changing the directory home.`);
    if (checked.siteRoots !== undefined && env[policy.rootsEnvName] !== undefined) throw new Error(`${policy.rootsEnvName} overrides this setting. Unset it before changing site roots.`);
  }
  function merged(previous: Partial<DirectoryUserConfig>, checked: Partial<DirectoryUserConfig>, incremental: boolean): Partial<DirectoryUserConfig> {
    const next = { ...previous, ...checked,
      ...(checked.sitesHome !== undefined ? { sitesHome: expand(checked.sitesHome) } : {}),
      ...(checked.siteRoots !== undefined ? { siteRoots: distinct(checked.siteRoots) } : {}),
    };
    // Empty incremental extras restore implicit defaults instead of persisting those defaults.
    if (incremental && checked.siteRoots?.length === 0) delete next.siteRoots;
    return next;
  }
  function update({ patch }: { patch: Partial<DirectoryUserConfig> }, { transform }: { transform?: (current: DirectoryUserConfig, saved: Partial<DirectoryUserConfig>) => Partial<DirectoryUserConfig> } = {}): DirectoryUserConfig {
    // Compute incremental root changes inside the same lock as the write: a sibling process's
    // added root must not disappear because this caller previously read an older array.
    file.withLock({ critical: () => {
      const previous = stored(true);
      const checked = validateDirectoryUserConfig({ value: transform ? transform(read({}), previous) : patch });
      assertDirectories(checked);
      assertNotOverridden(checked);
      const next = merged(previous, checked, transform !== undefined);
      // With no other saved settings, removing the final extra also restores an absent config.
      // The Node assembly supplies removal; non-Node adapters may retain the equivalent {}.
      if (transform && Object.keys(next).length === 0 && removeFile) removeFile({ filePath });
      else file.write({ value: next });
    } });
    return read({});
  }
  function updateRoots({ add = [], remove = [] }: { add?: readonly string[]; remove?: readonly string[] }, _options = {}): DirectoryUserConfig {
    return update({ patch: {} }, { transform: (current, saved) => {
      const protectedRoots = new Set(distinct([current.sitesHome, ...(policy.sourceRoots ?? [])]));
      const excluded = new Set(distinct(remove));
      return { siteRoots: distinct([...(saved.siteRoots ?? []), ...add]).filter((root) => !excluded.has(root) && !protectedRoots.has(root)) };
    } });
  }
  // A move journal is written before copying; the old name stays authoritative until verification
  // retires it. Recovery never guesses from two DB sizes/timestamps or asks users to delete data.
  function moveMarker(source: string, candidates: readonly string[]): { markerPath: string; target: string; backup: string } | undefined {
    const markerPath = source + ".home2-relocation.json", marker = fileAt(markerPath).read({});
    if (marker.state === "missing") return undefined;
    const value = marker.state === "ok" ? marker.value as { to?: unknown; backup?: unknown } | null : undefined;
    const target = value?.to, backup = markerBackup(source, value?.backup);
    if (typeof target !== "string" || !candidates.includes(target) || backup === undefined) throw invalidMarker(markerPath);
    return { markerPath, target, backup };
  }
  function authoritativeCopy(source: string, { markerPath, target, backup }: { markerPath: string; target: string; backup: string }): string {
    if (exists(source)) return source;
    if (exists(backup) && exists(target)) return target;
    throw new Error(`Interrupted database move needs recovery: ${markerPath}. Restore the pre-move backup before starting.`);
  }
  function recoveredMove(candidates: readonly string[]): string | undefined {
    for (const source of candidates) {
      const marker = moveMarker(source, candidates);
      if (!marker) continue;
      const authoritative = authoritativeCopy(source, marker);
      report(`Recovered interrupted database move using ${authoritative}. Keep the backup files (${marker.backup}); finish the move before changing database placement.`);
      return authoritative;
    }
    return undefined;
  }
  function existingCopy(candidates: readonly string[], filename: string): string | undefined {
    const present = candidates.filter(exists);
    if (present.length > 1) throw new Error(`Multiple copies of ${filename} exist for this site. Choose the authoritative database before starting it.`);
    return present[0];
  }
  function unsafeIdentityPath(legacy: string, placement: DirectoryUserConfig["databases"] | undefined): string {
    if (!placement && exists(legacy)) return legacy;
    throw new Error("A database directory requires a safe, stable site identity.");
  }
  function databasePath({ dir, id, filename, placement }: { dir: string; id: string; filename: string; placement?: DirectoryUserConfig["databases"] }, _options = {}): string {
    assertDatabaseFilename(filename);
    const inSite = path.join(dir, "data.nosync", filename), legacy = path.join(dir, filename);
    if (!SAFE_SITE_ID.test(id)) return unsafeIdentityPath(legacy, placement);
    const appData = path.join(directories.appData, "databases", id, filename);
    if (placement) return placement === "inSite" ? inSite : appData;
    const candidates = [legacy, inSite, appData];
    const found = recoveredMove(candidates) ?? existingCopy(candidates, filename);
    if (found) return found;
    // A missing chat DB follows an existing content DB even after the user changes preferences.
    if (filename !== "content.db") return path.join(path.dirname(databasePath({ dir, id, filename: "content.db" })), filename);
    return read({}).databases === "inSite" ? inSite : appData;
  }
  return { read, update, updateRoots, databasePath, filePath, ...directories,
    // Discovery/catalog callers list real old homes. Pointer normalization and creation admission
    // may inspect the supported spellings even before their directories have been created.
    legacyHomes: (_required: Record<string, never>, { includeMissing = false }: { includeMissing?: boolean } = {}) =>
      distinct(legacyHomes).filter((root) => includeMissing || (exists(root) && isDirectory(root))),
    defaultRoots: (_required: Record<string, never>, _options = {}) => distinct(policy.sourceRoots ?? []),
    extraRoots: (_required: Record<string, never>, _options = {}) => distinct(env[policy.rootsEnvName] !== undefined ? read({}).siteRoots : stored().siteRoots ?? []),
    roots: (_required: Record<string, never>, _options = {}) => {
      const config = read({}), parent = paths.dirname(config.sitesHome);
      // Discover only the selected home's existing former level. Scanning another old home
      // crosses the local/synced boundary and admits broad or absent roots at every boot.
      const formerRoots = legacyHomes.includes(parent) && exists(parent) && isDirectory(parent) ? [parent] : [];
      return distinct([config.sitesHome, ...formerRoots, ...(policy.sourceRoots ?? []), ...config.siteRoots]);
    },
    runningPath: ({ dir }: { dir: string }, _options = {}) => path.join(directories.appData, "running", createHash("sha256").update(canonicalPath({ path: dir })).digest("hex") + ".json"),
    syncWarning: (_required: Record<string, never>, _options = {}) => {
      const config = read({});
      const sync = syncProvider(config.sitesHome);
      if (!syncsDatabases(sync)) return null;
      return { provider: sync, message: config.databases === "appData" ? `${sync} syncs the sites folder. New databases use OS app-data for safety. Site folders are not self-contained: include their app-data databases when transferring them.` : `${sync} syncs the sites folder. It does not honor data.nosync; syncing live SQLite databases can corrupt them. Use app-data databases or a local sites folder.`, localHome };
    },
  };
}

const SETTING_RULES: readonly (readonly [key: keyof DirectoryUserConfig, valid: (value: unknown) => boolean, message: string])[] = [
  ["sitesHome", (value) => typeof value === "string" && Boolean(value.trim()), "sitesHome must name a directory."],
  ["siteRoots", (value) => Array.isArray(value) && value.every((root) => typeof root === "string" && root.trim()), "siteRoots must be an array of directory paths."],
  ["databases", (value) => value === "inSite" || value === "appData", 'databases must be "inSite" or "appData".'],
];
/** Validate only the three public settings; reject arrays, unknown fields and invalid enums.
 * @complexity O(n) root strings. No I/O or mutation.
 */
export function validateDirectoryUserConfig({ value }: { value: unknown }, _options = {}): Partial<DirectoryUserConfig> {
  if (!value || typeof value !== "object" || Array.isArray(value)) throw new Error("User config must be an object.");
  const row = value as Record<string, unknown>;
  if (Object.keys(row).some((key) => !SETTING_RULES.some(([known]) => known === key))) throw new Error("Unknown user config setting.");
  for (const [key, valid, message] of SETTING_RULES) if (row[key] !== undefined && !valid(row[key])) throw new Error(message);
  return row as Partial<DirectoryUserConfig>;
}

/**
 * @module process
 *
 * OS process lifecycle and stamp primitives: encode/decode `--flag=value`
 * process stamps and match them against a contract, spawn background and logged
 * child processes, probe liveness, enumerate process snapshots (POSIX `ps` /
 * Windows `Get-CimInstance`), walk a process tree, and stop a set of PIDs with
 * SIGTERM-then-SIGKILL escalation.
 *
 * Uses `command` for invocation construction and `shell`'s direct buffered
 * executor for bounded usage samples; keeps a private `errorCode` copy.
 */
import { execFile, spawn, type ChildProcess, type StdioOptions } from "node:child_process";
import { posix, win32 } from "node:path";
import { setTimeout as sleep } from "node:timers/promises";
import { captureLineTail } from "@jini-ai/core/text";
import { windowsPowerShell } from "./windows-system-tools.js";

import { createCommandInvocation, type CommandInvocationRequest } from "./command.js";
import { execFileBuffered } from "./shell.js";

export type ProcessStampShape = object;

export type ProcessStampField<TStamp extends ProcessStampShape> = Extract<keyof TStamp, string>;

export type ProcessStampContract<
  TStamp extends ProcessStampShape,
  TCriteria extends Partial<TStamp> = Partial<TStamp>,
> = {
  normalizeStamp(input: unknown): TStamp;
  normalizeStampCriteria(input?: unknown): TCriteria;
  stampFields: readonly ProcessStampField<TStamp>[];
  stampFlags: { readonly [K in ProcessStampField<TStamp>]: string };
};

export type SpawnProcessRequest = CommandInvocationRequest & {
  cwd?: string;
  detached?: boolean;
  logFd?: number | null;
};

export type ProcessSnapshot = {
  command: string;
  pid: number;
  ppid: number;
};

/** Display-only usage: RSS is bytes; CPU is cumulative seconds across all cores. */
export type ProcessUsage = {
  pid: number;
  ppid: number;
  rssBytes: number;
  cpuSeconds: number;
  /** Executable basename only; empty when the OS provides no name. */
  name: string;
};

export type ProcessUsagePorts = {
  platform?: NodeJS.Platform;
  run?: typeof execFileBuffered;
};

export type ProcessUsageOptions = {
  timeoutMs?: number;
};

export type StampedProcessMatchCriteria<TStamp extends ProcessStampShape> = Partial<TStamp>;

export type StopProcessesResult = {
  alreadyStopped: boolean;
  forcedPids: number[];
  matchedPids: number[];
  remainingPids: number[];
  stoppedPids: number[];
};

type WindowsProcessRecord = {
  CommandLine?: string | null;
  ParentProcessId?: number | string | null;
  ProcessId?: number | string | null;
};

/** @internal Extract a Node `error.code` as a string, or `null` when the value carries no code. */
function errorCode(error: unknown): string | null {
  if (typeof error !== "object" || error == null || !("code" in error)) return null;
  const code = (error as { code?: unknown }).code;
  return code == null ? null : String(code);
}

/**
 * Serialize a process stamp into `--flag=value` CLI arguments per the contract.
 * Every stamp field must normalize to a string or an error is thrown.
 *
 * @param stamp - The stamp object to encode.
 * @param contract - The stamp contract providing field list, flags, and normalization.
 * @returns The `--flag=value` argument strings, one per stamp field.
 */
export function createProcessStampArgs<TStamp extends ProcessStampShape>(
  stamp: TStamp,
  contract: ProcessStampContract<TStamp>,
): string[] {
  const normalized = contract.normalizeStamp(stamp);
  return contract.stampFields.map((field) => {
    const value = normalized[field];
    if (typeof value !== "string") {
      throw new Error(`process stamp field ${field} must normalize to a string`);
    }
    return `${contract.stampFlags[field]}=${value}`;
  });
}

/** @internal Split a command line string into whitespace-separated argument tokens. */
function commandArgs(command: string): string[] {
  return command.trim().split(/\s+/).filter((part) => part.length > 0);
}

/**
 * Read the value of a CLI flag from an argument list, supporting both the
 * `--flag value` and inline `--flag=value` forms.
 *
 * @param args - The argument list to search.
 * @param flagName - The flag name (including any leading dashes).
 * @returns The flag's value, or `null` when the flag is absent.
 */
export function readFlagValue(args: readonly string[], flagName: string): string | null {
  const inlinePrefix = `${flagName}=`;
  for (let index = 0; index < args.length; index += 1) {
    const argument = args[index];
    if (argument === flagName) return args[index + 1] ?? null;
    if (typeof argument === "string" && argument.startsWith(inlinePrefix)) {
      return argument.slice(inlinePrefix.length);
    }
  }
  return null;
}

/**
 * Decode a process stamp from a raw argument list per the contract, returning
 * `null` when normalization fails (e.g. a required field is missing).
 *
 * @param args - The process argument list to read stamp flags from.
 * @param contract - The stamp contract providing field list, flags, and normalization.
 * @returns The decoded stamp, or `null` when it cannot be normalized.
 */
export function readProcessStamp<TStamp extends ProcessStampShape>(
  args: readonly string[],
  contract: ProcessStampContract<TStamp>,
): TStamp | null {
  try {
    const input = Object.fromEntries(
      contract.stampFields.map((field) => [field, readFlagValue(args, contract.stampFlags[field])]),
    );
    return contract.normalizeStamp(input);
  } catch {
    return null;
  }
}

/**
 * Decode a process stamp from a full command-line string by tokenizing it first.
 *
 * @param command - The full command line to read stamp flags from.
 * @param contract - The stamp contract providing field list, flags, and normalization.
 * @returns The decoded stamp, or `null` when it cannot be normalized.
 */
export function readProcessStampFromCommand<TStamp extends ProcessStampShape>(
  command: string,
  contract: ProcessStampContract<TStamp>,
): TStamp | null {
  return readProcessStamp(commandArgs(command), contract);
}

/**
 * Test whether a stamp matches criteria: every criterion field that is set must
 * equal the corresponding normalized stamp field; unset criteria fields match
 * anything.
 *
 * @param stamp - The stamp to test.
 * @param criteria - The partial criteria to match against (undefined matches all).
 * @param contract - The stamp contract providing field list and normalization.
 * @returns `true` when every specified criterion matches the stamp.
 */
export function matchesProcessStamp<TStamp extends ProcessStampShape, TCriteria extends Partial<TStamp> = Partial<TStamp>>(
  stamp: TStamp,
  criteria: TCriteria | undefined,
  contract: ProcessStampContract<TStamp, TCriteria>,
): boolean {
  const normalizedStamp = contract.normalizeStamp(stamp);
  const normalizedCriteria = contract.normalizeStampCriteria(criteria ?? {});
  return contract.stampFields.every((field) => {
    const expected = normalizedCriteria[field as keyof TCriteria];
    return expected == null || normalizedStamp[field] === expected;
  });
}

/**
 * Test whether a process snapshot's command line carries a stamp matching the
 * criteria. Combines stamp decoding from the command with `matchesProcessStamp`.
 *
 * @param processInfo - A snapshot exposing at least the `command` string.
 * @param criteria - The partial criteria to match against (undefined matches all).
 * @param contract - The stamp contract providing field list and normalization.
 * @returns `true` when the command carries a decodable stamp that matches.
 */
export function matchesStampedProcess<TStamp extends ProcessStampShape, TCriteria extends Partial<TStamp> = Partial<TStamp>>(
  processInfo: Pick<ProcessSnapshot, "command">,
  criteria: TCriteria | undefined,
  contract: ProcessStampContract<TStamp, TCriteria>,
): boolean {
  const stamp = readProcessStampFromCommand(processInfo.command, contract);
  return stamp != null && matchesProcessStamp(stamp, criteria, contract);
}

/** @internal Build the stdio triple for a spawned process, routing stdout/stderr to a log fd when provided. */
function createLoggedStdio(logFd?: number | null): StdioOptions {
  return logFd == null ? ["ignore", "ignore", "ignore"] : ["ignore", logFd, logFd];
}

/** @internal Resolve once the child emits `spawn`, or reject on the child's `error` event. */
async function waitForChildSpawn(child: ChildProcess): Promise<void> {
  await new Promise<void>((resolveSpawn, rejectSpawn) => {
    child.once("error", rejectSpawn);
    child.once("spawn", resolveSpawn);
  });
}

/**
 * Spawn a detached background process, wait for it to actually start, then
 * `unref` it so the parent can exit independently.
 *
 * @param request - The command/args/env plus cwd, detached, and log-fd options.
 * @returns The spawned child's `{ pid }`.
 * @throws If the child fails to spawn or reports no pid.
 */
export async function spawnBackgroundProcess(request: SpawnProcessRequest): Promise<{ pid: number }> {
  const invocation = createCommandInvocation(request);
  const child = spawn(invocation.command, invocation.args, {
    cwd: request.cwd,
    detached: request.detached ?? true,
    env: request.env,
    stdio: createLoggedStdio(request.logFd),
    windowsHide: process.platform === "win32",
    windowsVerbatimArguments: invocation.windowsVerbatimArguments,
  });
  await waitForChildSpawn(child);
  if (child.pid == null) throw new Error(`failed to spawn background process: ${invocation.command}`);
  child.unref();
  return { pid: child.pid };
}

/**
 * Spawn a (by default non-detached) child process with stdout/stderr routed to
 * an optional log fd, waiting for it to start before returning the handle.
 *
 * @param request - The command/args/env plus cwd, detached, and log-fd options.
 * @returns The live `ChildProcess` handle.
 * @throws If the child fails to spawn or reports no pid.
 */
export async function spawnLoggedProcess(request: SpawnProcessRequest): Promise<ChildProcess> {
  const invocation = createCommandInvocation(request);
  const child = spawn(invocation.command, invocation.args, {
    cwd: request.cwd,
    detached: request.detached ?? false,
    env: request.env,
    stdio: createLoggedStdio(request.logFd),
    windowsHide: process.platform === "win32",
    windowsVerbatimArguments: invocation.windowsVerbatimArguments,
  });
  await waitForChildSpawn(child);
  if (child.pid == null) throw new Error(`failed to spawn process: ${invocation.command}`);
  return child;
}

/**
 * Probe whether a process is alive via a signal-0 `process.kill`. Treats
 * `ESRCH` as dead and any other error (e.g. `EPERM`) as alive.
 *
 * @param pid - The PID to probe (non-number values are treated as dead).
 * @returns `true` when the process appears to exist.
 */
export function isProcessAlive(pid: number | null | undefined): boolean {
  if (typeof pid !== "number") return false;
  try {
    process.kill(pid, 0);
    return true;
  } catch (error) {
    return errorCode(error) !== "ESRCH";
  }
}

/**
 * Poll until a process exits or the timeout elapses.
 *
 * @param pid - The PID to wait on.
 * @param timeoutMs - Maximum time to wait, in milliseconds (default 5000).
 * @returns `true` if the process is gone by the deadline, otherwise `false`.
 */
export async function waitForProcessExit(pid: number | null | undefined, timeoutMs = 5000): Promise<boolean> {
  const startedAt = Date.now();
  while (Date.now() - startedAt < timeoutMs) {
    if (!isProcessAlive(pid)) return true;
    await sleep(100);
  }
  return !isProcessAlive(pid);
}

/** @internal Parse `ps -axo pid=,ppid=,command=` output into process snapshots. */
function parsePsOutput(stdout: string): ProcessSnapshot[] {
  return stdout
    .split(/\r?\n/)
    .map((line) => {
      // Same as /^\s*(\d+)\s+(\d+)\s+(.+)$/, split so the command tail cannot backtrack.
      const match = /^\s*(\d+)\s+(\d+)/.exec(line);
      const command = match ? captureLineTail({ rest: line.slice(match[0].length) }, { minWhitespace: 1 }) : null;
      if (!match || command === null) return null;
      return { pid: Number(match[1]), ppid: Number(match[2]), command };
    })
    .filter((snapshot): snapshot is ProcessSnapshot => snapshot != null);
}

/** @internal Enumerate process snapshots on POSIX via `ps`. */
async function listPosixProcessSnapshots(): Promise<ProcessSnapshot[]> {
  const stdout = await new Promise<string>((resolveList, rejectList) => {
    // eslint-disable-next-line sonarjs/no-os-command-from-path -- Fixed process-enumeration utility intentionally uses the trusted host PATH; command and argv are code-owned.
    execFile("ps", ["-axo", "pid=,ppid=,command="], { encoding: "utf8", maxBuffer: 8 * 1024 * 1024 }, (error, out) => {
      if (error) rejectList(error);
      else resolveList(out);
    });
  });
  return parsePsOutput(stdout);
}

/** @internal Enumerate process snapshots on Windows via `Get-CimInstance Win32_Process` JSON. */
async function listWindowsProcessSnapshots(): Promise<ProcessSnapshot[]> {
  const command = [
    "$ErrorActionPreference = 'Stop'",
    "Get-CimInstance Win32_Process | Select-Object ProcessId, ParentProcessId, CommandLine | ConvertTo-Json -Compress",
  ].join("; ");
  const stdout = await new Promise<string>((resolveList, rejectList) => {
    execFile(windowsPowerShell(), ["-NoProfile", "-NonInteractive", "-Command", command], { encoding: "utf8", maxBuffer: 8 * 1024 * 1024 }, (error, out) => {
      if (error) rejectList(error);
      else resolveList(out);
    });
  });
  const payload = stdout.trim();
  if (!payload) return [];
  const records = JSON.parse(payload) as WindowsProcessRecord | WindowsProcessRecord[];
  return (Array.isArray(records) ? records : [records])
    .map((record) => {
      const pid = Number(record.ProcessId);
      const ppid = Number(record.ParentProcessId);
      const commandLine = record.CommandLine?.trim();
      if (!commandLine || Number.isNaN(pid) || Number.isNaN(ppid)) return null;
      return { command: commandLine, pid, ppid };
    })
    .filter((snapshot): snapshot is ProcessSnapshot => snapshot != null);
}

/**
 * Enumerate all running processes as `{ pid, ppid, command }` snapshots, using
 * the platform-appropriate backend. Returns an empty list on any failure.
 *
 * @returns The current process snapshots (empty on error).
 */
export async function listProcessSnapshots(): Promise<ProcessSnapshot[]> {
  try {
    return process.platform === "win32"
      ? await listWindowsProcessSnapshots()
      : await listPosixProcessSnapshots();
  } catch {
    return [];
  }
}

/** @internal Decode ps cumulative CPU time, including macOS fractional seconds and days. */
function parseCpuTime(value: string): number {
  const match = value.match(/^(?:(\d+)-)?(?:(\d+):)?(\d+):(\d+(?:\.\d+)?)$/);
  if (!match) return NaN;
  return Number(match[1] ?? 0) * 86400 + Number(match[2] ?? 0) * 3600
    + Number(match[3]) * 60 + Number(match[4]);
}

/** @internal Reject incomplete metrics instead of presenting missing usage as zero. */
function validProcessUsage(usage: ProcessUsage): boolean {
  const { pid, ppid, rssBytes, cpuSeconds } = usage;
  return [pid, ppid].every(Number.isSafeInteger) && [rssBytes, cpuSeconds].every(Number.isFinite)
    && [pid, ppid, rssBytes, cpuSeconds].every((value) => value >= 0);
}

/** @internal Read only comm, never args/command, so credentials cannot enter the result. */
function parsePsUsage(stdout: string): ProcessUsage[] {
  return stdout.split(/\r?\n/).flatMap((line) => {
    const match = line.match(/^\s*(\d+)\s+(\d+)\s+(\d+)\s+(\S+)\s+(\S.*)$/);
    if (!match) return [];
    const usage = {
      pid: Number(match[1]), ppid: Number(match[2]), rssBytes: Number(match[3]) * 1024,
      cpuSeconds: parseCpuTime(match[4]!), name: posix.basename(match[5]!.trim()),
    };
    return validProcessUsage(usage) ? [usage] : [];
  });
}

/** @internal CIM serializes numeric fields as numbers or strings; null is not zero usage. */
function cimNumber(value: unknown): number {
  if (typeof value === "number") return value;
  return typeof value === "string" && value.trim() ? Number(value) : NaN;
}

/** @internal Convert Windows 100ns CPU counters and retain nameless process rows. */
function parseCimUsage(stdout: string): ProcessUsage[] {
  if (!stdout.trim()) return [];
  const payload: unknown = JSON.parse(stdout);
  return (Array.isArray(payload) ? payload : [payload]).flatMap((record: unknown) => {
    if (!record || typeof record !== "object") return [];
    const row = record as Record<string, unknown>;
    const usage = {
      pid: cimNumber(row.ProcessId), ppid: cimNumber(row.ParentProcessId),
      rssBytes: cimNumber(row.WorkingSetSize),
      cpuSeconds: (cimNumber(row.UserModeTime) + cimNumber(row.KernelModeTime)) / 10_000_000,
      name: typeof row.Name === "string" ? win32.basename(row.Name.trim()) : "",
    };
    return validProcessUsage(usage) ? [usage] : [];
  });
}

/** @internal Fixed executable and argv, invoked directly without a command shell. */
function processUsageCommand(windows: boolean): { command: string; args: string[] } {
  return windows
    ? { command: windowsPowerShell(), args: ["-NoProfile", "-NonInteractive", "-Command",
      "$ErrorActionPreference = 'Stop'; Get-CimInstance Win32_Process | Select-Object ProcessId, ParentProcessId, WorkingSetSize, UserModeTime, KernelModeTime, Name | ConvertTo-Json -Compress"] }
    : { command: "ps", args: ["-axo", "pid=,ppid=,rss=,time=,comm="] };
}

/**
 * Sample process RSS and cumulative CPU without reading command lines. Returns
 * [] on command, timeout, buffer or JSON failure. RSS totals may count shared
 * pages more than once; CPU percentages require deltas between samples.
 * @param input - Optional host platform and bounded command-execution port.
 * @param options - Execution timeout (default 5000ms); output is capped at 8MiB.
 */
export async function listProcessUsage(
  input: ProcessUsagePorts = {},
  options: ProcessUsageOptions = {},
): Promise<ProcessUsage[]> {
  const windows = (input.platform ?? process.platform) === "win32";
  const { command, args } = processUsageCommand(windows);
  try {
    const result = await (input.run ?? execFileBuffered)(command, args, {
      encoding: "utf8", timeout: options.timeoutMs ?? 5000, maxBuffer: 8 * 1024 * 1024,
      windowsHide: true,
    });
    if (!result.ok) return [];
    return windows ? parseCimUsage(result.stdout) : parsePsUsage(result.stdout);
  } catch {
    return [];
  }
}

/**
 * Collect the transitive set of descendant PIDs (including the roots) from a
 * process snapshot list, returned sorted by numeric PID descending for deterministic ordering.
 * PID reuse and wraparound mean this does not guarantee children precede parents.
 *
 * @param processes - The full process snapshot list to walk.
 * @param rootPids - The root PIDs whose subtrees to collect (non-numbers ignored).
 * @returns The unique PIDs of the roots and all their descendants, descending.
 */
export function collectProcessTreePids(
  processes: ProcessSnapshot[],
  rootPids: Array<number | null | undefined>,
): number[] {
  const queue = [...new Set(rootPids.filter((pid): pid is number => typeof pid === "number"))];
  const visited = new Set<number>();
  const childrenByParent = new Map<number, number[]>();
  for (const processInfo of processes) {
    const children = childrenByParent.get(processInfo.ppid) ?? [];
    children.push(processInfo.pid);
    childrenByParent.set(processInfo.ppid, children);
  }
  while (queue.length > 0) {
    const pid = queue.shift();
    if (pid == null || visited.has(pid)) continue;
    visited.add(pid);
    for (const childPid of childrenByParent.get(pid) ?? []) {
      if (!visited.has(childPid)) queue.push(childPid);
    }
  }
  return [...visited].sort((left, right) => right - left);
}

/** @internal Send a signal to each PID, ignoring `ESRCH` (already-dead) but rethrowing other errors. */
function signalProcesses(pids: number[], signal: NodeJS.Signals): void {
  for (const pid of pids) {
    try {
      process.kill(pid, signal);
    } catch (error) {
      if (errorCode(error) !== "ESRCH") throw error;
    }
  }
}

/** @internal Poll until all PIDs exit or the timeout elapses; returns the PIDs still alive. */
async function waitForProcessesToExit(pids: number[], timeoutMs = 5000): Promise<number[]> {
  const startedAt = Date.now();
  while (Date.now() - startedAt < timeoutMs) {
    const remaining = pids.filter(isProcessAlive);
    if (remaining.length === 0) return [];
    await sleep(100);
  }
  return pids.filter(isProcessAlive);
}

/**
 * Stop a set of PIDs with escalation: SIGTERM, wait, then SIGKILL any
 * survivors. Excludes the current process and de-duplicates the input.
 *
 * @param pids - The PIDs to stop (non-numbers and the current PID are ignored).
 * @returns A result describing matched, stopped, force-killed, and remaining PIDs.
 */
export async function stopProcesses(pids: Array<number | null | undefined>): Promise<StopProcessesResult> {
  const uniquePids = [...new Set(pids)]
    .filter((pid): pid is number => typeof pid === "number" && pid !== process.pid)
    .sort((left, right) => right - left);
  if (uniquePids.length === 0) {
    return { alreadyStopped: true, forcedPids: [], matchedPids: [], remainingPids: [], stoppedPids: [] };
  }
  signalProcesses(uniquePids, "SIGTERM");
  const remainingAfterTerm = await waitForProcessesToExit(uniquePids);
  if (remainingAfterTerm.length === 0) {
    return { alreadyStopped: false, forcedPids: [], matchedPids: uniquePids, remainingPids: [], stoppedPids: uniquePids };
  }
  signalProcesses(remainingAfterTerm, "SIGKILL");
  const remainingAfterKill = await waitForProcessesToExit(remainingAfterTerm);
  const stoppedPids = uniquePids.filter((pid) => !remainingAfterKill.includes(pid));
  return { alreadyStopped: false, forcedPids: remainingAfterTerm, matchedPids: uniquePids, remainingPids: remainingAfterKill, stoppedPids };
}

/** Host-independent collect-all manifest validation; vocabularies are host inputs. */
export interface GlueVocabulary { readonly capabilities: readonly string[]; readonly callSites: readonly string[] }

export type GlueCallSite = string;

export type GlueCapability = string;

export interface GlueManifestAttachment {
  readonly callSite: GlueCallSite;
  readonly [payloadKey: string]: unknown;
}

export interface GlueManifest {
  readonly id: string;
  readonly version: string;
  readonly sdkRange: string;
  readonly capabilities: readonly GlueCapability[];
  readonly attachments: readonly GlueManifestAttachment[];
}

export interface GlueManifestValidationError {
  readonly code: string;
  readonly file: string | null;
  readonly message: string;
}

export interface ValidateGlueManifestRequired {
  readonly manifest: unknown;
  readonly vocabulary: GlueVocabulary;
}

export type ValidateGlueManifestOptional = Record<string, never>;

export interface ValidateGlueManifestResult {
  readonly errors: readonly GlueManifestValidationError[];
}

const REQUIRED_KEYS = ["id", "version", "sdkRange", "capabilities", "attachments"] as const;
const ALLOWED_KEYS = new Set<string>(REQUIRED_KEYS);

const ID_PATTERN = /^[a-z0-9-]+$/;
const MAX_ID_LENGTH = 50;



function malformed(message: string): GlueManifestValidationError {
  return { code: "MANIFEST_MALFORMED", file: null, message };
}

function validateKeys(raw: Readonly<Record<string, unknown>>): GlueManifestValidationError[] {
  const errors: GlueManifestValidationError[] = [];
  for (const key of Object.keys(raw)) {
    if (!ALLOWED_KEYS.has(key)) {
      errors.push(malformed(`unknown manifest key '${key}'`));
    }
  }
  for (const key of REQUIRED_KEYS) {
    if (raw[key] === undefined) {
      errors.push(malformed(`missing required manifest field '${key}'`));
    }
  }
  return errors;
}

function validateId(raw: Readonly<Record<string, unknown>>): GlueManifestValidationError[] {
  const errors: GlueManifestValidationError[] = [];
  const id = typeof raw.id === "string" ? raw.id : undefined;
  if (raw.id !== undefined && id === undefined) {
    errors.push(malformed("'id' must be a string"));
  }
  if (id !== undefined && (!ID_PATTERN.test(id) || id.length < 1 || id.length > MAX_ID_LENGTH)) {
    errors.push(malformed(`id '${id}' must match ${ID_PATTERN} and be 1-${MAX_ID_LENGTH} characters`));
  }
  return errors;
}

function validateVersionAndSdkRange(raw: Readonly<Record<string, unknown>>): GlueManifestValidationError[] {
  const errors: GlueManifestValidationError[] = [];
  if (raw.version !== undefined && typeof raw.version !== "string") {
    errors.push(malformed("'version' must be a string"));
  }
  if (raw.sdkRange !== undefined && typeof raw.sdkRange !== "string") {
    errors.push(malformed("'sdkRange' must be a string"));
  }
  return errors;
}

function validateCapabilities(raw: Readonly<Record<string, unknown>>, vocabulary: GlueVocabulary): GlueManifestValidationError[] {
  const errors: GlueManifestValidationError[] = [];
  const capabilities = Array.isArray(raw.capabilities) ? raw.capabilities : [];
  if (raw.capabilities !== undefined && !Array.isArray(raw.capabilities)) {
    errors.push(malformed("'capabilities' must be an array"));
  }
  for (const capability of capabilities) {
    if (typeof capability !== "string" || !vocabulary.capabilities.includes(capability)) {
      errors.push({
        code: "CAPABILITY_UNKNOWN",
        file: null,
        message: `capability '${String(capability)}' is outside the supplied capability vocabulary`,
      });
    }
  }
  return errors;
}

function validateAttachment(attachment: unknown, vocabulary: GlueVocabulary): GlueManifestValidationError[] {
  if (typeof attachment !== "object" || attachment === null || Array.isArray(attachment)) {
    return [malformed("each 'attachments' entry must be an object")];
  }
  const callSite = (attachment as Readonly<Record<string, unknown>>).callSite;
  if (typeof callSite !== "string" || !vocabulary.callSites.includes(callSite)) {
    return [
      {
        code: "CALL_SITE_UNKNOWN",
        file: null,
        message: `call site '${String(callSite)}' is outside the supplied call-site vocabulary`,
      },
    ];
  }
  return [];
}

function validateAttachments(raw: Readonly<Record<string, unknown>>, vocabulary: GlueVocabulary): GlueManifestValidationError[] {
  const errors: GlueManifestValidationError[] = [];
  const attachments = Array.isArray(raw.attachments) ? raw.attachments : [];
  if (raw.attachments !== undefined && !Array.isArray(raw.attachments)) {
    errors.push(malformed("'attachments' must be an array"));
  }
  for (const attachment of attachments) {
    errors.push(...validateAttachment(attachment, vocabulary));
  }
  return errors;
}

export function validateGlueManifest(
  required: ValidateGlueManifestRequired,
  _optional: ValidateGlueManifestOptional = {}
): ValidateGlueManifestResult {
  const { manifest, vocabulary } = required;

  if (typeof manifest !== "object" || manifest === null || Array.isArray(manifest)) {
    return { errors: [malformed("glue manifest must be a JSON object")] };
  }

  // Treat the input as a read-only bag of unknown values — never assigned back into.
  const raw = manifest as Readonly<Record<string, unknown>>;

  const errors: GlueManifestValidationError[] = [
    ...validateKeys(raw),
    ...validateId(raw),
    ...validateVersionAndSdkRange(raw),
    ...validateCapabilities(raw, vocabulary),
    ...validateAttachments(raw, vocabulary),
  ];

  return { errors };
}

export type GlueCallSiteDispatchStatus =
  | { readonly wired: true }
  | { readonly wired: false; readonly code: "UNWIRED_CALL_SITE" };

export function resolveCallSiteDispatch({ callSite, wiredCallSites }: { callSite: GlueCallSite; wiredCallSites: readonly GlueCallSite[] }, _optional: Record<string, never> = {}): GlueCallSiteDispatchStatus {
  return wiredCallSites.includes(callSite) ? { wired: true } : { wired: false, code: "UNWIRED_CALL_SITE" };
}

