/** Concrete content-type construction is host-owned. The required declaration port owns its
 * grammar, planning and application; this module owns ordering and deferred binding. */
/**
 * @file The enable path for a plugin's DECLARED contributions (AW-7 Tier 1): a `tier-1`
 * (manifest-only) plugin is applied from its manifest and never imported, and a code plugin that
 * also declares content types gets them.
 *
 * Runs inside `composePluginRuntime().onPluginEnabled` (`server/runtime/composition/plugin-runtime.ts`),
 * AFTER its conflict gate, so a declared content-type key is checked against every other plugin's
 * claims first (`plugin-claims.ts`, kind `content-type`). Boot re-attach skips tier-1 plugins: their
 * types were stored when they were turned on, and there is no code to load.
 *
 * Order for a code plugin with content types: plan (read-only) → load code → create types. A
 * conflict refuses the enable before the plugin's code is imported, and a failed load leaves no
 * types behind. A type that still fails to create (everything core would refuse is already refused
 * at discovery, so this is an infrastructure failure) unloads the code again, so a refused enable
 * never leaves a hook running. Types created before that failure stay: retain-by-default, and
 * tombstoning them would burn their keys for good (content-types INV-06); a later enable keeps them.
 */
import { PluginInvalidError } from "./activation.js";
import type { DeclarativeContentTypesPort, DeclaredContentTypePorts } from "./ports.js";
import type { PluginManifest } from "./manifest.js";

export interface EnableDeclaredPluginRequired {
  readonly declarativeContentTypes: DeclarativeContentTypesPort;
  readonly pluginId: string;
  readonly workspaceId: string;
  /** The discovery record's manifest — already through `validateManifest`, declarations included. */
  readonly manifest: PluginManifest;
  /** Loads and attaches the plugin's code (the runtime's own load path). Never called for tier-1. */
  readonly loadCode: () => Promise<void>;
  /** Detaches what `loadCode` attached — called only when a content type fails to create after it. */
  readonly unloadCode: () => void;
}

export interface EnableDeclaredPluginOptional {
  /** Where declared content types are created. Omitted (a composition with no content-type store)
   *  ⇒ a plugin that declares any is refused rather than enabled without them. */
  readonly contentTypes?: DeclaredContentTypePorts;
}

/**
 * Turns one plugin on around its declarations. A plugin that declares no content types is just
 * `loadCode()` (tier-1 with none: nothing at all). Content-type conflicts with what the site
 * already has throw `PluginInvalidError` (the enable route maps it to 422; `setPluginEnabled`
 * restores the prior activation row).
 *
 * @complexity O(t) port reads/writes over the manifest's declared types (bounded, ≤ 20).
 */
export async function enableDeclaredPlugin(required: EnableDeclaredPluginRequired, optional: EnableDeclaredPluginOptional = {}): Promise<void> {
  const { pluginId, workspaceId, manifest, loadCode } = required;
  // ADR-024 §1: a Tier-1 plugin is zero executable code — the runtime never imports anything for it.
  const load = manifest.tier === "tier-1" ? async () => {} : loadCode;
  const { decls } = required.declarativeContentTypes.parse({ value: manifest.contentTypes });
  if (decls.length === 0) {
    await load();
    return;
  }
  const ports = optional.contentTypes;
  if (!ports) throw new PluginInvalidError(`plugin '${pluginId}' declares content types, but this site cannot create them`);

  const plan = await required.declarativeContentTypes.plan({ ports, workspaceId, decls });
  if (plan.conflicts.length > 0) {
    throw new PluginInvalidError(`plugin '${pluginId}' cannot be turned on: ${plan.conflicts.join("; ")}`);
  }
  await load();
  try {
    await required.declarativeContentTypes.apply({ ports, workspaceId, pluginId, plan });
  } catch (error) {
    required.unloadCode();
    throw error;
  }
}

/**
 * Binds the host's `registerContentType` for the provisioner. `authorize` always allows, on purpose: the
 * real authorization already happened one layer up — turning a plugin on requires the plugin-manage
 * permission and the owner's consent, and these types are what that consented action declares
 * (the same reasoning as widgets' `PRE_AUTHORIZED`). The write is recorded as `principalKind:
 * "system"` with the plugin as actor, so the revision log says no human typed this schema.
 */
// createDeclaredContentTypePorts stays at the host composition boundary with the core write service.

/**
 * Ports built on first use. Both composition roots compose the plugin runtime before their
 * content-type repo and outbox exist (top-level composition is synchronous and enable never runs
 * during it), so they hand the runtime this and bind the real ports where those are declared.
 */
export function deferDeclaredContentTypePorts(required: { build: () => DeclaredContentTypePorts }, _optional: Record<string, never> = {}): DeclaredContentTypePorts {
  let ports: DeclaredContentTypePorts | undefined;
  const resolve = () => (ports ??= required.build());
  return {
    findByKey: (params) => resolve().findByKey(params),
    register: (input) => resolve().register(input),
  };
}

/** Manifest data contracts do not depend on validation or host composition. */
import type { PluginIdentityExtension } from '@jini-ai/core/plugin-directory';

export interface BrowserProviderDeclaration {
  readonly id: string;
  readonly kind: 'chart';
  readonly contractVersion: 1;
  readonly kinds: readonly string[];
  readonly javascript: string;
  readonly stylesheet?: string;
}

/** ADR-024 §1 trust-tier vocabulary (1.1.1 REQ-01 fix). Literal encoding reused verbatim from the
 * existing, approved SPEC-032/ADR-023 precedent (`DataModuleDecl.pluginTier`). */
export type PluginTier = "tier-1" | "tier-2" | "tier-3";

/** REQ-04's exactly-three v1 capability vocabulary, as manifest-declared strings (validated
 * against this set by `validateManifest`; `@jini-ai/plugin-sdk`'s `CONTENT_READ`/`CONTENT_EXTEND`/
 * `HOOKS_ATTACH` constants are the same literal values, kept independent here so this module has
 * no dependency on the SDK package per the Module Map). Sourced from `core/`'s
 * `SharedExtensionCapability` — the sibling `site-glue` mechanism's own capability vocabulary
 * declares this same three-member set as its first three members; both import the one shared
 * declaration rather than each retyping the literals (2026-08-20 swarm-consensus synthesis,
 * Result 1). */
export type PluginCapability = string;

/** REQ-06 field declaration — `ext.{pluginId}.{field}` (BR-06). `queryable` MUST be `false` in
 * v1 (EC-04); a `true` value is a validation error (`QUERYABLE_UNSUPPORTED_V1`), not silently
 * coerced. */
export interface PluginManifestFieldDecl {
  readonly path: string;
  readonly type: "string" | "integer" | "number" | "boolean";
  readonly queryable: boolean;
  /**
   * Optional, human-readable, action-oriented description of what this field represents and how an
   * agent should use it (2026-08-26 addition — `features/plugin-runtime/capability-tool-registrations.ts`
   * is the sole consumer: it is folded into the indexed `search_tools` description for this plugin's
   * capability-read tool when the plugin is enabled). Absent on every pre-existing manifest — this
   * is additive, not a widened requirement, so no previously-valid manifest becomes invalid by
   * omitting it; a plugin author who wants their capability to rank well against a real user query
   * simply adds one.
   */
  readonly description?: string;
}

/** `jini.plugin.json` — the ecosystem compatibility surface (state.spec.md §2, ADR-004). */
export interface PluginManifest {
  /** Storage/activation key. Publisher identity lives in extensions[identityNamespace].id. */
  readonly id: string;
  readonly keywords?: readonly string[];
  readonly extensions?: Readonly<Record<string, PluginIdentityExtension>>;
  readonly name: string;
  readonly version: string;
  readonly sdkRange: string;
  readonly engine: number;
  readonly tier: PluginTier;
  readonly capabilities: readonly string[];
  readonly hooks: readonly string[];
  readonly fields: readonly PluginManifestFieldDecl[];
  readonly integrity: Readonly<Record<string, string>>;
  /** Parsed-and-stored, UNUSED in v1 (forward-compat, no behavior — state.spec.md §2). */
  readonly adminSurfaces?: readonly unknown[] | null;
  /** Reviewed bundled chart assets only; host admission supplies trust outside this manifest. */
  readonly browserProviders?: readonly BrowserProviderDeclaration[];
  /** Content types the plugin declares (AW-7 Tier 1, 2026-10-04) — no longer unused: validated by
   *  `declarative-content-types.ts`, claimed by key (`plugin-claims.ts`), created at enable. */
  readonly contentTypes?: readonly unknown[] | null;
  readonly provenance?: { readonly sourceUrl?: string; readonly signature?: string } | null;
  readonly dependencies?: Readonly<Record<string, string>> | null;
  /**
   * What this plugin says it provides, by name (2026-10-04, conflict detection — see
   * `plugin-claims.ts` and `ADS-memory/specs/005-plugin-system/conflicts.spec.md`). Optional and
   * additive: a manifest without it claims only what its other fields already imply (its hooks and,
   * when it declares `fields`, its generated capability tool). Each entry is a CLAIM: two enabled
   * plugins, or a plugin and core, naming the same thing is refused at enable time and quarantined
   * at boot rather than silently letting one overwrite the other. Declaring a surface the runtime
   * does not mount yet (settings, widgets, routes — ADR-025/`adminSurfaces` are still unwired) is
   * still binding for conflicts, so a plugin cannot squat a name today that a future mount would
   * then have to arbitrate.
   */
  readonly contributes?: PluginContributions | null;
}

/** `jini.plugin.json`'s `contributes` block — optional named surfaces and provider declarations. */
export interface PluginContributions {
  /** Server provider factories; identity is exclusive within one contract. */
  readonly providers?: readonly PluginProviderDeclaration[];
  /** `"METHOD /path"` or `"/path"` (every method). Parameter names do not distinguish routes. */
  readonly routes?: readonly string[];
  /** Agent tool ids. The generated prefixes `plugin_capability_`/`agent_plugin_` are reserved. */
  readonly tools?: readonly string[];
  /** Data-module tables — must sit in this plugin's own `p_{id}__` namespace (ADR-023 §5). */
  readonly tables?: readonly string[];
  readonly settings?: readonly string[];
  readonly widgets?: readonly string[];
  /** Permission ids this plugin DEFINES (not ones it merely requires). */
  readonly permissions?: readonly string[];
}

export interface PluginProviderDeclaration {
  readonly contract: string;
  readonly id: string;
  readonly contractVersion: 1;
  /**
   * The settings a host collects (on its own secure settings card) and passes to this provider's
   * factory as `required[name]`. Declared here, not in code, so a host can render the card and decide
   * "configured?" without executing the plugin. Secret fields are sealed by the host and never shown back.
   */
  readonly settings?: readonly PluginProviderSettingField[];
  /** Ordered read-time public-setting migrations; never rewrite persisted rows or secrets. */
  readonly settingsMigrations?: readonly PluginProviderSettingsMigration[];
}

/** A plugin-owned migration of retired public choices, applied to a copy on read. */
export interface PluginProviderSettingsMigration {
  readonly when: { readonly field: string; readonly in: readonly string[]; readonly orAbsent?: boolean };
  readonly whenPresent?: string;
  readonly set: Readonly<Record<string, string>>;
