/** One choice of a {@link PluginProviderSettingField}'s `options`. */
export interface PluginProviderSettingOption {
  readonly value: string;
  readonly label: string;
}

/** One validation-vocabulary entry (errors.spec.md §3). `file` names the offending packaged file
 * when applicable; `null` for manifest-level errors with no single implicated file. This is the
 * shared shape used verbatim by both `PLUGINS_LIST.plugins[].errors[]` and
 * `PLUGIN_INVALID.details.errors[]` (errors.spec.md §4 — "one validator, two surfaces"). */
export interface PluginValidationError {
  readonly code: string;
  readonly file: string | null;
  readonly message: string;
}

/** Plugin wire identifiers. Readers prefer the canonical manifest; publishers emit only it. */
export const PLUGIN_MANIFEST_FILENAME = 'jini.plugin.json';
export const LEGACY_PLUGIN_MANIFEST_FILENAME = 'tovu.plugin.json'; // legacy alias
export const PLUGIN_MANIFEST_FILENAMES: readonly string[] = [PLUGIN_MANIFEST_FILENAME, LEGACY_PLUGIN_MANIFEST_FILENAME]; // legacy alias
export const PLUGIN_SDK_SPECIFIER = '@jini-ai/plugin-sdk';
export const LEGACY_PLUGIN_SDK_SPECIFIER = '@tovu/sdk'; // legacy alias
export const PLUGIN_SDK_SPECIFIERS: readonly string[] = [PLUGIN_SDK_SPECIFIER, LEGACY_PLUGIN_SDK_SPECIFIER]; // legacy alias

/** Preserve the selected manifest's exact bytes while dropping alternate manifest filenames.
 * Missing manifests remain missing so the existing validator owns the diagnostic.
 */
export function canonicalizePluginManifest<T>(
  required: { files: ReadonlyMap<string, T> },
  _optional: Record<string, never> = {},
): Map<string, T> {
  const files = new Map(required.files);
  const selected = PLUGIN_MANIFEST_FILENAMES.find(name => files.has(name)); // legacy alias
  const manifest = selected === undefined ? undefined : files.get(selected)!;
  for (const name of PLUGIN_MANIFEST_FILENAMES) files.delete(name); // legacy alias
  if (selected !== undefined) files.set(PLUGIN_MANIFEST_FILENAME, manifest!);
  return files;
}

import { paymentError, type IntentRequest, type NextAction, type Outcome, type PaymentEvidence, type ProviderContext } from "@jini-ai/commerce/payments/kernel";
import { fromStripeAmount, toStripeAmount } from "./amount.js";
import { stripeRequest } from "./http.js";

/** Encodes one validated intent line; null refuses unsupported money before dispatch.
 * The kernel guarantees unit × quantity equals the requested total. O(n) in display text.
 * @example checkoutSessionForm({ req, ctx }) */
export function checkoutSessionForm(
  { req, ctx }: { req: IntentRequest; ctx: ProviderContext }, _optional: Record<string, never> = {}
): Array<[string, string]> | null {
  if (toStripeAmount({ money: req.amount }) === null) return null;
  const line = req.line ?? { description: `Payment ${req.correlationId}`, quantity: 1, unitAmount: req.amount };
  const unit = toStripeAmount({ money: line.unitAmount });
  if (unit === null) return null;
  const form: Array<[string, string]> = [
    ["mode", "payment"], ["success_url", ctx.returnUrl], ["cancel_url", ctx.cancelUrl],
    ["client_reference_id", req.correlationId], ["metadata[jini_payment_id]", req.correlationId],
    ["payment_intent_data[metadata][jini_payment_id]", req.correlationId], ["line_items[0][quantity]", String(line.quantity)],
  ];
  if (line.providerPriceRef !== undefined) form.push(["line_items[0][price]", line.providerPriceRef]);
  else form.push(
    ["line_items[0][price_data][currency]", unit.currency], ["line_items[0][price_data][unit_amount]", String(unit.amount)],
    ["line_items[0][price_data][product_data][name]", line.description],
  );
  return form;
}

/** Dispatches exactly once; ambiguous responses stay unknown, mismatched totals give no redirect.
 * @returns Requires-action evidence and redirect, or a typed refusal/unknown outcome.
 * @example await createCheckoutSession({ req, ctx })
 * @complexity O(n) in form/response size, one bounded HTTP call through the supplied port. */
export async function createCheckoutSession(
  { req, ctx }: { req: IntentRequest; ctx: ProviderContext }, _optional: Record<string, never> = {}
): Promise<Outcome<{ evidence: PaymentEvidence; next: NextAction }>> {
  const form = checkoutSessionForm({ req, ctx });
  if (form === null) return { kind: "rejected", error: paymentError({ code: "CURRENCY_UNSUPPORTED", message: "unsupported checkout currency or amount" }) };
  const result = await stripeRequest({ ctx, method: "POST", path: "/v1/checkout/sessions" }, { form, idempotencyKey: req.idempotencyKey });
  if (result.kind !== "ok") return result;
  const { id, url, amount_total, currency } = result.value;
  // A session may already exist: never report a missing response field as proof no money moved.
  if (typeof id !== "string" || id.length === 0 || typeof url !== "string" || url.length === 0) return {
    kind: "unknown", error: paymentError({ code: "PROVIDER_ERROR", message: "checkout session response incomplete" }, { retryable: true }),
  };
  const amount = fromStripeAmount({ amount: amount_total, currency });
  if (amount === null || amount.minorUnits !== req.amount.minorUnits || amount.currency !== req.amount.currency) return {
    kind: "rejected", error: paymentError({ code: "INVALID_REQUEST", message: "checkout session total differs from intent" }),
  };
  return { kind: "ok", value: {
    evidence: { providerRef: id, correlationId: req.correlationId, status: "requires_action", amount, refunds: [], disputes: [] },
    next: { kind: "redirect", url },
  } };
}

import type { PaymentEvidence, PaymentMode, ProviderPaymentStatus } from "@jini-ai/commerce/payments/kernel";
import { fromStripeAmount } from "./amount.js";

export type SessionReading = { kind: "evidence"; evidence: PaymentEvidence } | { kind: "id_only"; sessionId: string }
  | { kind: "foreign" } | { kind: "malformed"; reason: string };
const FAILED_PI_STATUSES: ReadonlySet<unknown> = new Set(["requires_payment_method", "canceled"]);

/** Reads untrusted JSON records without coercing arrays, null or primitives. O(1) time/space. */
function record({ value }: { value: unknown }, _optional: Record<string, never> = {}): Record<string, unknown> {
  return value !== null && typeof value === "object" && !Array.isArray(value) ? value as Record<string, unknown> : {};
}

/** Pins the owned object's kind and mode to the trusted context. O(1) time/space. */
function invalidIdentity({ session, mode }: { session: Record<string, unknown>; mode: PaymentMode }, _optional: Record<string, never> = {}): boolean {
  return session.object !== "checkout.session" || session.mode !== "payment" || session.livemode !== (mode === "live");
}

/** Maps provider facts without treating delayed payment completion as success. O(1) time/space. */
function sessionStatus(
  { session, eventType }: { session: Record<string, unknown>; eventType: string | undefined }, _optional: Record<string, never> = {}
): ProviderPaymentStatus | null {
  if (eventType === "checkout.session.async_payment_failed") return "failed";
  if (eventType === "checkout.session.async_payment_succeeded") return session.payment_status === "paid" ? "succeeded" : null;
  if (session.status === "open") return "requires_action";
  if (session.status === "expired") return "canceled";
  if (session.status !== "complete") return null;
  if (session.payment_status === "paid") return "succeeded";
  if (session.payment_status !== "unpaid") return null;
  // An id-only PI says nothing about failure; only an expanded retrieval can establish it.
  const pi = record({ value: session.payment_intent });
  return FAILED_PI_STATUSES.has(pi.status) ? "failed" : "pending";
}

/** Translates an owned Checkout session, preserving incomplete facts for worker retrieval.
 * @returns Evidence, id-only, foreign, or a malformed reason; no I/O or thrown JSON errors.
 * @example readSession({ object: event.data.object, mode: ctx.account.mode }, { eventType: event.type })
 * @complexity O(n) in the currency string length; constant fields inspected. */
export function readSession(
  { object, mode }: { object: unknown; mode: PaymentMode }, optional: { eventType?: string } = {}
): SessionReading {
  const session = record({ value: object });
  const correlationId = record({ value: session.metadata }).jini_payment_id;
  if (correlationId === undefined) return { kind: "foreign" };
  if (typeof correlationId !== "string" || correlationId.length === 0) return { kind: "malformed", reason: "invalid payment correlation" };
  if (typeof session.id !== "string" || session.id.length === 0 || invalidIdentity({ session, mode })) return {
    kind: "malformed", reason: "invalid checkout session identity or mode",
  };
  const status = sessionStatus({ session, eventType: optional.eventType });
  const amount = fromStripeAmount({ amount: session.amount_total, currency: session.currency });
  if (status === null || amount === null) return { kind: "id_only", sessionId: session.id };
  return { kind: "evidence", evidence: { providerRef: session.id, correlationId, status, amount, refunds: [], disputes: [] } };
}

/**
 * @file Agent tools for site search (lot S6), subpath `@jini-ai/search/tools`.
 *
 * `search_query` and `search_status` are reads. `search_reindex` (bulk vendor writes = cost) and
 * `search_set_provider` (a settings change plus a full backfill into another backend) ask the human
 * first through core's approval lifecycle; only the reindex grant may be remembered, per provider.
 *
 * Agents only ever see PUBLIC results: `search_query` never passes viewer audiences to the service,
 * so a members-only document cannot reach a model context through this tool.
 *
 * Permission is checked through an injected `requirePermission` port (the `@jini-ai/db` transfer
 * tools' shape) rather than `@jini-ai/cms/core`'s helper, so this generic package keeps its single
 * `@jini-ai/core` dependency; the host binds the port to its own permission catalog.
