/** Independently derived from the calls each handler below makes. */
// Spell out the readonly map because the guard cannot resolve the registration kit's type alias.
export const derivedRisk: ReadonlyMap<string, AgentToolSideEffect> = new Map([
  // service.query -> provider.query + access.visibleKeys: reads only.
  ['search_query', 'none'],
  // service.status -> targets.get + state.counts: reads only.
  ['search_status', 'none'],
  // indexer.startRebuild -> targets.setBuilding: persists a new building generation.
  ['search_reindex', 'mutates-durable-state'],
  // setProviderSetting + indexer.startRebuild: persists the setting and a building generation.
  ['search_set_provider', 'mutates-durable-state'],
]);

type FilterValue = string | number | boolean;

function optionalStringList(input: Record<string, unknown>, key: string): string[] | undefined {
  const value = input[key];
  if (value === undefined) return undefined;
  if (!Array.isArray(value) || !value.every(item => typeof item === 'string')) throw new ToolInputError({ message: `'${key}' must be an array of strings` });
  return value as string[];
}

function optionalFilters(input: Record<string, unknown>): Record<string, FilterValue> | undefined {
  const value = input.filters;
  if (value === undefined) return undefined;
  const scalar = (item: unknown) => ['string', 'number', 'boolean'].includes(typeof item);
  if (typeof value !== 'object' || value === null || Array.isArray(value) || !Object.values(value).every(scalar)) {
    throw new ToolInputError({ message: "'filters' must be an object of string, number or boolean values" });
  }
  return value as Record<string, FilterValue>;
}

/** The tool input as a service query; audiences can never be part of it. */
function readQuery(rawInput: unknown): Omit<SearchQuery, 'audiences'> {
  const input = requireInputRecord({ input: rawInput });
  const optionals = {
    collections: optionalStringList(input, 'collections'),
    locale: optionalString({ input, key: 'locale' }),
    filters: optionalFilters(input),
    cursor: optionalString({ input, key: 'cursor' }),
  };
  const present = Object.fromEntries(Object.entries(optionals).filter(([, value]) => value !== undefined));
  return { text: requireString({ input, key: 'text' }), limit: readToolLimit({ input, max: 100, fallback: 10 }), ...present };
}

type Prepared = { readonly providerId: string; readonly fromProviderId: string | null } | { readonly refusal: { readonly started: false; readonly code: string; readonly message: string } };

/**
 * Build the four search tool registrations.
 * @param required - Site scope, the service/indexer/registry and the host's permission, approval and
 *   setting ports.
 * @param optional.remembered - Persisted approval grants; only `search_reindex:<providerId>` uses it.
 * @returns Registrations through core's `buildDomainRegistrations` (risk corroborated, schemas required).
 * @throws Permission and port failures propagate; malformed input is a `ToolInputError`.
 * @complexity O(1) wiring; each handler is one or two port calls.
 */
export function buildSearchToolRegistrations(required: SearchToolDeps, optional: { readonly remembered?: RememberedApprovalPort } = {}): ToolRegistration[] {
  const { workspaceId, siteId, service, indexer, registry } = required;
  const allow = (ctx: ToolExecutionContext, permission: string) => required.requirePermission({ principalId: ctx.principal.id, permission });
  const activeProviderId = async () => (await service.status({ siteId })).active?.providerId ?? null;

  /** Shared approval lifecycle for the two writes; `run` re-checks permission after the human wait. */
  const approvalTool = (spec: {
    action: SearchApprovalDescription['action'];
    prepare(ctx: ToolExecutionContext): Promise<Prepared>;
    rememberKey(providerId: string): string | undefined;
    summary(prepared: { providerId: string; fromProviderId: string | null }): string;
    effect(providerId: string, ctx: ToolExecutionContext): Promise<void>;
  }): ToolHandler => createApprovalHandler<Prepared, SearchApprovalDescription | undefined>({
    prepare: ({ ctx }) => spec.prepare(ctx),
    describe: ({ prepared }) => {
      if ('refusal' in prepared) return { ask: false, description: undefined };
      const key = spec.rememberKey(prepared.providerId);
      const description: SearchApprovalDescription = { action: spec.action, siteId, ...prepared, summary: spec.summary(prepared) };
      return { ask: true, description, ...(key === undefined ? {} : { rememberKey: key }) };
    },
    askHuman: ({ ctx, description }, options) => required.askHuman({ ctx, description: description as SearchApprovalDescription }, options),
    notConfirmed: ({ reason }) => ({ started: false, reason }),
    run: async ({ ctx, prepared }) => {
      if ('refusal' in prepared) return prepared.refusal;
      await allow(ctx, SEARCH_MANAGE_PERMISSION);
      await spec.effect(prepared.providerId, ctx);
      const targets = await indexer.startRebuild({ siteId, workspaceId, providerId: prepared.providerId });
      return { started: true, providerId: prepared.providerId, generation: targets.building?.generation ?? null };
    },
  }, optional.remembered ? { remembered: optional.remembered } : {});

  const reindex = approvalTool({
    action: 'reindex',
    prepare: async ctx => {
      requireNoInput({ input: ctx.input });
      await allow(ctx, SEARCH_MANAGE_PERMISSION);
      const providerId = await activeProviderId();
      if (providerId === null) return { refusal: { started: false, code: 'not_configured', message: 'search has no active provider yet; use search_set_provider' } };
      if (!registry.has({ id: providerId })) return { refusal: { started: false, code: 'provider_not_registered', message: `the active search provider '${providerId}' is not loaded` } };
      return { providerId, fromProviderId: providerId };
    },
    // A reindex of the same provider is a repeatable cost decision, so a grant may be remembered per provider.
    rememberKey: providerId => `search_reindex:${providerId}`,
    summary: ({ providerId }) => `Rebuild the search index in '${providerId}' (writes every public document to it).`,
    effect: async () => undefined,
  });

  const setProvider = approvalTool({
    action: 'set_provider',
    prepare: async ctx => {
      const providerId = requireString({ input: requireInputRecord({ input: ctx.input }), key: 'providerId' });
      await allow(ctx, SEARCH_MANAGE_PERMISSION);
      if (!registry.has({ id: providerId })) {
        throw new ToolInputError({ message: `unknown search provider '${providerId}'; registered: ${registry.list().map(entry => entry.id).join(', ') || 'none'}` });
      }
      return { providerId, fromProviderId: await activeProviderId() };
    },
    // Never remembered: each switch moves the site's content to a different backend.
    rememberKey: () => undefined,
    summary: ({ providerId, fromProviderId }) => `Switch site search from '${fromProviderId ?? 'none'}' to '${providerId}' and copy every public document into it.`,
    effect: (providerId, ctx) => required.setProviderSetting({ siteId, providerId, principalId: ctx.principal.id }),
  });

  return buildDomainRegistrations({
    domain: SEARCH_TOOL_DOMAIN, catalogModule: '@jini-ai/search/tools',
    catalog: indexCatalogById({ catalog }), derivedRisk,
    handlers: {
      search_query: async ctx => {
        const query = readQuery(ctx.input);
        await allow(ctx, SEARCH_READ_PERMISSION);
        // No audiences: agents get public results only.
        return service.query({ siteId, workspaceId, query });
      },
      search_status: async ctx => {
        requireNoInput({ input: ctx.input });
        await allow(ctx, SEARCH_READ_PERMISSION);
        return service.status({ siteId });
      },
      search_reindex: reindex,
      search_set_provider: setProvider,
    },
  });
}

/**
 * @module builtin-features
 *
 * Every route family this package can mount, expressed as a `JiniFeature` whose `compose` returns
 * one atomic `@jini-ai/core` `Pack`.
 *
 * The load-bearing property is that a family's **tools and its routes are the same pack**. Before
 * this module, `create-local-node-daemon.ts` registered the terminal tool and the three `daemon.db.*`
 * tools into a private registry in one place, and mounted `registerTerminalRoutes`/
 * `registerDaemonDbRoutes` in another — so gating only the route registrations would have left
 * `jini.terminal.create` registered and still reachable through the always-mounted
 * `POST /api/delegated-tool-calls`. Here, a feature that is not selected contributes neither, and
 * there is no second step to gate. `terminal: false` means the pty tool is *absent from the
 * registry*, so a delegated call naming it is an unregistered-tool error rather than a shell.
 *
 * Features borrow kernel infrastructure (`ctx.kernel`) and never own it — see `kernel-base.ts` for
 * why the sqlite connection in particular is shared rather than feature-owned.
 */
import { statSync } from 'node:fs';
import { createRequire } from 'node:module';

import { definePack, type Principal, type ToolRegistration } from '@jini-ai/core';
import { getAgentDef, type DetectedAgent, type OAuthCallbackListener } from '@jini-ai/agent-runtime';
import {
  createDefaultRunStartHandler,
  createRemoteToolEventRecorder,
  isAgentExecutorSupported,
  createTerminalSessionManager,
  createTerminalToolRegistrations,
  type ResolveRunInput,
  type TerminalSessionManager,
} from '@jini-ai/daemon';
import {
  ensureToolCatalogTables,
  getToolCatalogEntry,
  reseedToolCatalog,
  searchToolCatalog,
} from '@jini-ai/registry/tool-catalog/sqlite';
import { inspectSqliteDatabase, verifySqliteIntegrity, type SqliteDb } from '@jini-ai/db/sqlite';
import { createDaemonDbToolRegistrations, denyAllWorkspaceRoots, registerActiveContextRoutes, registerAgentRoutes, registerConnectorsRoutes, registerDaemonDbRoutes, registerDaemonStatusRoutes, registerDelegatedToolRoutes, registerFrontendSessionRoutes, registerHealthRoutes, registerHostToolsRoutes, registerMediaRoutes, registerMemoryRoutes, registerModelProxyRoutes, registerRemoteRunEventRoutes, registerResearchRoutes, registerRoutineRoutes, registerRunRoutes, registerTerminalRoutes, registerToolCatalogRoutes, registerXaiRoutes, type AgentSummary, type DaemonDbOperations, type DaemonDbVacuumResult, type DelegatedToolExecuteRequest, type FrontendSessionsHttpDeps, type MediaHttpDeps, type MemoryHttpDeps, type RemoteToolBridgeTokenConfig, type RoutineHttpDeps, type RunStartHandler, type WorkspaceRootResolver } from '@jini-ai/daemon/http';
import type { Express } from 'express';

import { defineJiniFeature, type FeatureBuildContext, type JiniFeature } from './feature.js';

/**
 * The identity every zero-config, `ToolExecutor`-gated tool this module registers (`terminal.create`,
 * `daemon.db.*`) executes as. A composition using these has no multi-tenant identity subsystem of
 * its own — the bearer gate is authenticated-or-not, not per-caller — so every authenticated caller
 * already shares one trust boundary and a single fixed `Principal` removes no distinction that
 * existed before it.
 */
export const LOCAL_DAEMON_PRINCIPAL: Principal = { id: 'local-daemon' };

const require = createRequire(import.meta.url);
/** This package's own version, the default a composition reports when a host names none. */
const packageVersion = (require('../package.json') as { readonly version: string }).version;

/** @deprecated Compatibility export only; never selected as a default delegated identity. */
export const ANONYMOUS_DELEGATED_PRINCIPAL: Principal = { id: 'anonymous-delegated' };

/** Resolves a delegated caller through the host's identity owner, refusing absent resolution.
 * @throws Error when the host supplies no resolver. O(1) plus the host resolver's work. */
export function resolveDelegatedToolPrincipal({ request, resolvePrincipal }: {
  request: DelegatedToolExecuteRequest;
  resolvePrincipal: ((request: DelegatedToolExecuteRequest) => Principal | Promise<Principal>) | undefined;
}, _options = {}): Principal | Promise<Principal> {
  if (!resolvePrincipal) throw new Error('Delegated tool calls require a host principal resolver');
  return resolvePrincipal(request);
}

/** Per-feature configuration, closed over when the catalog is built. */
export interface BuiltInFeatureOptions {
  readonly health?: {
    readonly getVersion?: () => string | Promise<string>;
    /** Folded into readiness as a `notShuttingDown` check. @default always false */
    readonly isShuttingDown?: () => boolean;
  };
  readonly runs?: {
    readonly onRunStarted?: RunStartHandler;
    readonly resolveRunInput?: ResolveRunInput;
  };
  readonly agents?: {
    readonly detector?: () => Promise<readonly DetectedAgent[]>;
  };
  readonly hostTools?: { readonly resolveWorkspaceRoot?: WorkspaceRootResolver };
  readonly terminal?: {
    readonly resolveWorkspaceRoot?: WorkspaceRootResolver;
    readonly principal?: Principal;
  };
  readonly daemonDb?: { readonly principal?: Principal };
  readonly delegatedToolCalls?: {
    readonly resolvePrincipal?: (request: DelegatedToolExecuteRequest) => Principal | Promise<Principal>;
  };
  readonly remoteRunEvents?: { readonly tokenConfig?: RemoteToolBridgeTokenConfig };
  readonly xai?: { readonly listenerRef?: { current: OAuthCallbackListener | null } };
  /**
   * Only `requestShutdown` is required, and deliberately so: everything else here
   * (`getVersion`/`host`/`getPort`/`dataDir`/`isShuttingDown`) is already known to the composition
   * and is derived when omitted, but *what shutdown means* is not something this package can invent
   * on a host's behalf. Defaulting it to a no-op would mount a shutdown endpoint that silently does
   * nothing — the "reports stopped while still serving" failure mode, shipped as a default.
   */
  readonly daemonStatus?: {
    readonly requestShutdown: () => void;
    readonly getVersion?: () => string | Promise<string>;
    readonly host?: string;
    readonly getPort?: () => number;
    readonly dataDir?: string;
    readonly isShuttingDown?: () => boolean;
  };
  /** Required to activate `memory` — this package has no note store of its own to default to. */
  readonly memory?: MemoryHttpDeps;
  readonly routines?: RoutineHttpDeps;
  readonly media?: MediaHttpDeps;
  readonly frontendSessions?: FrontendSessionsHttpDeps;
}

/** Thrown when a feature is activated without the host-supplied options it cannot default. */
function requireOptions<T>(value: T | undefined, featureId: string, optionPath: string): T {
  if (value === undefined) {
    throw new Error(
      `jini: feature "${featureId}" is active but "${optionPath}" was not supplied — ` +
        `this feature has no zero-config default. Supply it, or disable "${featureId}".`,
    );
  }
  return value;
}

function requireSqlite(context: FeatureBuildContext, featureId: string) {
  if (context.kernel.sqlite === null) {
    throw new Error(
      `jini: feature "${featureId}" needs sqlite storage but this composition uses memory storage — ` +
        `use storage: { kind: 'sqlite', dataDir } or disable "${featureId}".`,
    );
  }
  return context.kernel.sqlite;
}

/**
 * `DaemonDbOperations` over a caller-owned connection. `vacuum` measures the primary file's on-disk
 * size before/after (not the `-wal`/`-shm` sum), since a fresh `VACUUM` checkpoints and shrinks the
 * primary file itself, which is what "reclaimed" means here.
 */
export function buildDaemonDbOperations(db: SqliteDb, file: string): DaemonDbOperations {
  return {
    inspect: () => inspectSqliteDatabase({ db, file }),
    verify: ({ quick }) => verifySqliteIntegrity({ db, quick }),
    vacuum: (): DaemonDbVacuumResult => {
      const startedAt = Date.now();
      const beforeBytes = statSync(file).size;
      db.exec('VACUUM');
      const afterBytes = statSync(file).size;
      return {
        ok: true,
        beforeBytes,
        afterBytes,
        reclaimedBytes: Math.max(0, beforeBytes - afterBytes),
        elapsedMs: Date.now() - startedAt,
      };
    },
  };
}

/**
 * Whether the `agents` feature should advertise this probe result.
 *
 * Discovery scans every runtime definition, but `AgentExecutor` refuses to drive any def its
 * `assessAgentExecutorCompatibility` rejects — see `@jini-ai/daemon`'s own module doc. All currently
 * registered defs pass that check, but a future def may not. Advertising one that doesn't yields an
 * agent a user can select and then cannot run — so the executor's own compatibility answer is applied
 * here, at the surface that offers the choice.
 *
 * Assessed against the **full** `RuntimeAgentDef` resolved by id, not the `DetectedAgent` passed in:
 * the projected type omits `maxPromptArgBytes`, and the argv-bound defs (`aider`, `deepseek`) qualify
 * solely through it, so judging the projection would drop two working agents.
 *
 * An id with no registered def is **kept**, not dropped. A host supplying its own `detector` may
 * legitimately surface agents outside `AGENT_DEFS`, driven by something other than this executor;
 * there is nothing to assess, and refusing to advertise them would break that host on no evidence.
 *
 * @param agent - One probe result from the active detector.
 * @returns `true` when the agent should appear in `GET /api/agents`.
 * @complexity O(1) — one registry lookup plus fixed field checks.
 * @overallScore 100/100
 */
export function isExecutableDetectedAgent(agent: DetectedAgent): boolean {
  const def = getAgentDef({ id: agent.id });
  return def === null || isAgentExecutorSupported({ def });
}

function projectAgentDiagnostic(
  { agent }: { agent: DetectedAgent },
  _optional: Record<string, never> = {},
): Pick<AgentSummary, 'diagnostic'> {
  const diagnostic = agent.diagnostics?.[0]?.message;
  return diagnostic ? { diagnostic } : {};
}

/** Projects a real `DetectedAgent` probe onto the HTTP summary shape. */
export function projectDetectedAgent(agent: DetectedAgent): AgentSummary {
  return {
    id: agent.id,
    name: agent.name,
    available: agent.available,
    ...(agent.version !== undefined ? { version: agent.version } : {}),
    ...(agent.authStatus !== undefined ? { authStatus: agent.authStatus } : {}),
    models: agent.models.map(({ id, label, identityKind, resolvedId }) => ({ id, label, ...(identityKind ? { identityKind } : {}), ...(resolvedId ? { resolvedId } : {}) })),
    ...(agent.modelCatalog ? { modelCatalog: agent.modelCatalog } : {}),
    ...(agent.defaultModelResolution ? { defaultModelResolution: agent.defaultModelResolution } : {}),
    ...(agent.supportsConcreteModelSelection !== undefined ? { supportsConcreteModelSelection: agent.supportsConcreteModelSelection } : {}),
    ...(agent.reasoningOptions !== undefined
      ? { reasoningOptions: agent.reasoningOptions.map(({ id, label }) => ({ id, label })) }
      : {}),
    modelsSource: agent.modelsSource,
    ...(agent.supportsCustomModel !== undefined ? { supportsCustomModel: agent.supportsCustomModel } : {}),
    ...projectAgentDiagnostic({ agent }),
  };
}

/**
 * Builds the full built-in feature catalog with `options` closed over.
 *
 * Order is composition order, and it is deliberately the order `createLocalNodeDaemon` has always
 * registered these families in — so the route-registration inventory, the tool-registration order,
 * and therefore which id a duplicate-registration error names, are all unchanged.
 */
export function createBuiltInFeatures(options: BuiltInFeatureOptions = {}): readonly JiniFeature[] {
  const healthFeature = defineJiniFeature({
    id: 'health',
    // No capability: a liveness/readiness probe grants no authority and is always permitted.
    provides: [],
    phase: 'probe',
    compose: (context) => ({
      pack: definePack({
        name: 'jini.health',
        deps: [],
        services: () => ({ context }),
      }, {
        http: ({ app, services }) => {
          const sqlite = services.context.kernel.sqlite;
          const isShuttingDown = options.health?.isShuttingDown ?? (() => false);
          registerHealthRoutes({ app: app as Express, deps: {
              getVersion: options.health?.getVersion ?? (() => packageVersion),
              // Borrows the kernel's connection — see kernel-base.ts on why this is not
              // `daemonDb`'s to own. A readiness check must never itself throw and crash the
              // route: a thrown pragma read is a legitimate "not ready" signal, not a 500.
              checkReadiness: async () => {
                const notShuttingDown = !isShuttingDown();
                if (sqlite === null) return { ok: notShuttingDown, checks: { notShuttingDown } };
                let dbOk: boolean;
                try {
                  dbOk = verifySqliteIntegrity({ db: sqlite.connection, quick: true }).ok;
                } catch {
                  dbOk = false;
                }
                return { ok: dbOk && notShuttingDown, checks: { db: dbOk, notShuttingDown } };
              },
            }, adapter: services.context.adapter });
        },
      }),
    }),
  });

  const runsFeature = defineJiniFeature({
    id: 'runs',
    provides: ['run:transport'],
    compose: (context) => {
      // `onRunStarted` always wins when supplied. Otherwise a supplied `resolveRunInput` gets the
      // default handler built for it, driving the kernel's own `AgentExecutor`. With neither, runs
      // durably start with no driver attached.
      const onStarted =
        options.runs?.onRunStarted ??
        (options.runs?.resolveRunInput === undefined
          ? undefined
          : createDefaultRunStartHandler({
              agentExecutor: context.kernel.agentExecutor,
              resolveRunInput: options.runs.resolveRunInput,
            }));
      return {
        pack: definePack({
          name: 'jini.runs',
          deps: [],
          services: () => ({ context }),
        }, {
          http: ({ app, services }) => {
            registerRunRoutes({ app: app as Express, deps: {
                lifecycle: services.context.kernel.lifecycle,
                ...(onStarted === undefined ? {} : { onStarted }),
                // A mid-run message reaches whichever live run the kernel's own executor is driving;
                // a run some other driver owns reads as not-running, never as delivered.
                deliverUserMessage: (input) => services.context.kernel.agentExecutor.sendUserMessage(input),
              }, adapter: services.context.adapter });
          },
        }),
      };
    },
  });

  const agentsFeature = defineJiniFeature({
    id: 'agents',
    provides: ['agent:discovery'],
    compose: (context) => {
      // Promise-cached so concurrent clients never spawn duplicate probe sets; invalidated by
      // POST /api/agents/rescan.
      const detector = options.agents?.detector ?? ((force: boolean) => context.kernel.agentRuntime.detectAgents({}, { force }));
      let scan: Promise<readonly AgentSummary[]> | null = null;
      let expiresAt = 0;
      const scanAgents = (force: boolean): Promise<readonly AgentSummary[]> => {
        if (force || Date.now() >= expiresAt) scan = null;
        if (!scan) {
          const pending: Promise<readonly AgentSummary[]> = detector(force)
            // Filtered before projection so the executor's answer is computed from the full def —
            // see `isExecutableDetectedAgent`'s doc for why the projected shape is not enough.
            .then((agents) => agents.filter(isExecutableDetectedAgent).map(projectDetectedAgent))
            .catch((error: unknown) => {
              // Keyed by promise identity, not "whatever is cached when this failure lands": a slow
              // scan that fails after `POST /api/agents/rescan` already replaced it with a newer,
              // successful one must invalidate only its own entry. Clearing unconditionally evicts
              // the newer result and forces a duplicate probe of every agent CLI on the machine.
              if (scan === pending) scan = null;
              throw error;
            });
          scan = pending;
          expiresAt = Date.now() + 15 * 60_000;
        }
        return scan;
      };
      return {
        pack: definePack({
          name: 'jini.agents',
          deps: [],
          services: () => ({ context }),
        }, {
          http: ({ app, services }) => {
            registerAgentRoutes({ app: app as Express, deps: { listAgents: () => scanAgents(false), rescanAgents: () => scanAgents(true) }, adapter: services.context.adapter });
          },
        }),
      };
    },
  });

  const hostToolsFeature = defineJiniFeature({
    id: 'hostTools',
    // Lists editors on PATH (`host:read`) and launches one (`host:exec`).
    provides: ['host:read', 'host:exec'],
    compose: (context) => ({
      pack: definePack({
        name: 'jini.hostTools',
        deps: [],
        services: () => ({ context }),
      }, {
        http: ({ app, services }) => {
          registerHostToolsRoutes({ app: app as Express, adapter: services.context.adapter }, {
            resolveRoot: options.hostTools?.resolveWorkspaceRoot ?? denyAllWorkspaceRoots,
          });
        },
      }),
    }),
  });

  const modelProxyFeature = defineJiniFeature({
    id: 'modelProxy',
    provides: ['net:egress'],
    compose: (context) => ({
      pack: definePack({
        name: 'jini.modelProxy',
        deps: [],
        services: () => ({ context }),
      }, {
        http: ({ app, services }) => registerModelProxyRoutes({ app: app as Express, deps: {}, adapter: services.context.adapter }),
      }),
    }),
  });

  const activeContextFeature = defineJiniFeature({
    id: 'activeContext',
    provides: ['host:read'],
    compose: (context) => ({
      pack: definePack({
        name: 'jini.activeContext',
        deps: [],
        services: () => ({ context }),
      }, {
        http: ({ app, services }) =>
          registerActiveContextRoutes({ app: app as Express, deps: // Mandatory but with an honest, harmless answer this package can always give:
            // "unknown". It has no Project/Workspace noun of its own to resolve a name from.
            { resolveResource: (): undefined => undefined }, adapter: services.context.adapter }),
      }),
    }),
  });

  const terminalFeature = defineJiniFeature({
    id: 'terminal',
    provides: ['host:exec'],
    compose: (context) => {
      const manager: TerminalSessionManager = createTerminalSessionManager({});
      return {
        pack: definePack({
          name: 'jini.terminal',
          deps: [],
          services: () => ({ context, manager }),
        }, {
          // THE gap closure: the pty tool and the pty routes are one contribution. A composition
          // without this feature never registers `jini.terminal.create` at all, so a delegated call
          // naming it is an unregistered-tool error — not a shell.
          tools: ({ services }): readonly ToolRegistration[] => [
            createTerminalToolRegistrations({ manager: services.manager }).create,
          ],
          http: ({ app, services }) =>
            registerTerminalRoutes({ app: app as Express, deps: {
                manager: services.manager,
                toolExecutor: services.context.kernel.toolExecutor,
                principal: options.terminal?.principal ?? LOCAL_DAEMON_PRINCIPAL,
                resolveRoot: options.terminal?.resolveWorkspaceRoot ?? denyAllWorkspaceRoots,
              }, adapter: services.context.adapter }),
          dispose: ({ services }, _optional = {}) => services.manager.shutdownActive(),
        }),
      };
    },
  });

  const daemonDbFeature = defineJiniFeature({
    id: 'daemonDb',
    provides: ['db:admin'],
    compose: (context) => {
      const sqlite = requireSqlite(context, 'daemonDb');
      // Borrowed, never owned: `kernel.close()` closes this connection. See kernel-base.ts.
      const registrations = createDaemonDbToolRegistrations({
        operations: buildDaemonDbOperations(sqlite.connection, sqlite.eventsDbPath),
      });
      return {
        pack: definePack({
          name: 'jini.daemonDb',
          deps: [],
          services: () => ({ context }),
        }, {
          tools: (): readonly ToolRegistration[] => [registrations.inspect, registrations.verify, registrations.vacuum],
          http: ({ app, services }) =>
            registerDaemonDbRoutes({ app: app as Express, deps: {
                toolExecutor: services.context.kernel.toolExecutor,
                principal: options.daemonDb?.principal ?? LOCAL_DAEMON_PRINCIPAL,
              }, adapter: services.context.adapter }),
        }),
      };
    },
  });

  const toolCatalogFeature = defineJiniFeature({
    id: 'toolCatalog',
    provides: ['tool:catalog'],
    compose: (context) => {
      const sqlite = requireSqlite(context, 'toolCatalog');
      return {
        pack: definePack({
          name: 'jini.toolCatalog',
          deps: [],
          services: () => ({ context }),
        }, {
          http: ({ app, services }) =>
            registerToolCatalogRoutes({ app: app as Express, deps: {
                catalog: {
                  search: ({ query }, optionalArgs) => searchToolCatalog({ db: sqlite.connection, query }, optionalArgs),
                  describe: ({ id }: { id: string }) => getToolCatalogEntry({ db: sqlite.connection, id }),
                },
              }, adapter: services.context.adapter }),
        }),
        // Runs once EVERY active feature's tools are registered — the one ordering a Pack cannot
        // express itself. Seeding from inside this pack's own `tools` would snapshot a registry
        // that is still being filled, and the catalog would be silently partial.
        afterTools: () => {
          ensureToolCatalogTables({ db: sqlite.connection });
          reseedToolCatalog({ db: sqlite.connection, entries: context.kernel.registry.list({}).map((descriptor) => ({
              id: descriptor.id,
              description: descriptor.description ?? descriptor.id,
              source: 'first-party',
              ...(descriptor.inputSchema === undefined ? {} : { inputSchema: descriptor.inputSchema }),
            })) });
        },
      };
    },
  });

  const resolveDelegatedPrincipal = options.delegatedToolCalls?.resolvePrincipal;
  const delegatedToolCallsFeature = defineJiniFeature({
    id: 'delegatedToolCalls',
    provides: ['tool:delegated'],
    requires: ['runs'],
    compose: (context) => ({
      pack: definePack({
        name: 'jini.delegatedToolCalls',
        deps: [],
        services: () => ({ context }),
      }, {
        http: ({ app, services }) =>
          registerDelegatedToolRoutes({ app: app as Express, deps: {
              lifecycle: services.context.kernel.lifecycle,
              toolExecutor: services.context.kernel.toolExecutor,
              // The same registry `toolExecutor` was built over, so a `requireReadOnly` call (the
              // daemon-side half of `@jini-ai/mcp`'s `execute_readonly_delegated_tool`) is checked
              // against the descriptor that will actually run. Omitting it would not weaken the
              // gate — an unverifiable constraint is refused, never waived — it would just make the
              // read-only gateway refuse everything, so a kernel host gets it wired by default.
              toolRegistry: services.context.kernel.registry,
              resolvePrincipal: ({ request }) => resolveDelegatedToolPrincipal({ request, resolvePrincipal: resolveDelegatedPrincipal }),
            }, adapter: services.context.adapter }),
      }),
    }),
  });

  const connectorsFeature = defineJiniFeature({
    id: 'connectors',
    provides: ['net:egress'],
    compose: (context) => ({
      pack: definePack({
        name: 'jini.connectors',
        deps: [],
        services: () => ({ context }),
      }, {
        http: ({ app, services }) => registerConnectorsRoutes({ app: app as Express, deps: {}, adapter: services.context.adapter }),
      }),
    }),
  });

  const researchFeature = defineJiniFeature({
    id: 'research',
    provides: ['net:egress'],
    compose: (context) => ({
      pack: definePack({
        name: 'jini.research',
        deps: [],
        services: () => ({ context }),
      }, {
        http: ({ app, services }) => registerResearchRoutes({ app: app as Express, deps: {}, adapter: services.context.adapter }),
      }),
    }),
  });

  const xaiFeature = defineJiniFeature({
    id: 'xai',
    provides: ['net:egress'],
    compose: (context) => {
      const sqlite = requireSqlite(context, 'xai');
      // Owned here (rather than left to xai.ts's internal default) so this feature's `dispose` can
      // close an in-flight OAuth loopback listener — otherwise the fixed 127.0.0.1:56121 socket
      // outlives the composition by up to its 30-minute self-close timeout.
      const listenerRef = options.xai?.listenerRef ?? { current: null as OAuthCallbackListener | null };
      return {
        pack: definePack({
          name: 'jini.xai',
          deps: [],
          services: () => ({ context, listenerRef }),
        }, {
          http: ({ app, services }) =>
            registerXaiRoutes({ app: app as Express, deps: { dataDir: sqlite.dataDir, listenerRef: services.listenerRef }, adapter: services.context.adapter }),
          dispose: async ({ services }) => {
            const listener = services.listenerRef.current;
            services.listenerRef.current = null;
            // Best-effort — the listener self-closes on its own timeout anyway.
            if (listener) await listener.stop();
          },
        }),
      };
    },
  });

  const remoteRunEventsFeature = defineJiniFeature({
    id: 'remoteRunEvents',
    // Never granted by any shipped profile: writing agent events into a run this process does not
    // own is strictly more authority than executing a tool through the policy-gated delegated route.
    provides: ['run:inject'],
    requires: ['runs'],
    compose: (context) => ({
      pack: definePack({
        name: 'jini.remoteRunEvents',
        deps: [],
        services: () => ({ context }),
      }, {
        http: ({ app, services }) =>
          registerRemoteRunEventRoutes({ app: app as Express, deps: {
              lifecycle: services.context.kernel.lifecycle,
              recorder: createRemoteToolEventRecorder({ lifecycle: services.context.kernel.lifecycle }),
              ...(options.remoteRunEvents?.tokenConfig === undefined
                ? {}
                : { tokenConfig: options.remoteRunEvents.tokenConfig }),
              env: services.context.env,
            }, adapter: services.context.adapter }),
      }),
    }),
  });

  const memoryFeature = defineJiniFeature({
    id: 'memory',
    provides: ['memory:store'],
    compose: (context) => {
      const deps = requireOptions(options.memory, 'memory', 'featureOptions.memory');
      return {
        pack: definePack({
          name: 'jini.memory',
          deps: [],
          services: () => ({ context }),
        }, {
          http: ({ app, services }) => registerMemoryRoutes({ app: app as Express, deps, adapter: services.context.adapter }),
        }),
      };
    },
  });

  const routinesFeature = defineJiniFeature({
    id: 'routines',
    provides: ['routines:schedule'],
    compose: (context) => {
      const deps = requireOptions(options.routines, 'routines', 'featureOptions.routines');
      return {
        pack: definePack({
          name: 'jini.routines',
          deps: [],
          services: () => ({ context }),
        }, {
          http: ({ app, services }) => registerRoutineRoutes({ app: app as Express, deps, adapter: services.context.adapter }),
        }),
      };
    },
  });

  const mediaFeature = defineJiniFeature({
    id: 'media',
    provides: ['media:generate'],
    compose: (context) => {
      const deps = requireOptions(options.media, 'media', 'featureOptions.media');
      return {
        pack: definePack({
          name: 'jini.media',
          deps: [],
          services: () => ({ context }),
        }, {
          http: ({ app, services }) => registerMediaRoutes({ app: app as Express, deps, adapter: services.context.adapter }),
        }),
      };
    },
  });

  const frontendSessionsFeature = defineJiniFeature({
    id: 'frontendSessions',
    provides: ['ui:session'],
    compose: (context) => {
      const deps = requireOptions(options.frontendSessions, 'frontendSessions', 'featureOptions.frontendSessions');
      return {
        pack: definePack({
          name: 'jini.frontendSessions',
          deps: [],
          services: () => ({ context }),
        }, {
          http: ({ app, services }) => registerFrontendSessionRoutes({ app: app as Express, deps, adapter: services.context.adapter }),
        }),
      };
    },
  });

  const daemonStatusFeature = defineJiniFeature({
    id: 'daemonStatus',
    provides: ['daemon:control'],
    phase: 'status',
    compose: (context) => {
      const supplied = requireOptions(options.daemonStatus, 'daemonStatus', 'featureOptions.daemonStatus.requestShutdown');
      const deps = {
        getVersion: supplied.getVersion ?? (() => packageVersion),
        host: supplied.host ?? '127.0.0.1',
        getPort: supplied.getPort ?? (() => context.adapter.resolvedPortRef.current),
        dataDir: supplied.dataDir ?? context.kernel.sqlite?.dataDir ?? '',
        isShuttingDown: supplied.isShuttingDown ?? (() => false),
        requestShutdown: supplied.requestShutdown,
      };
      return {
        pack: definePack({
          name: 'jini.daemonStatus',
          deps: [],
          services: () => ({ context }),
        }, {
          http: ({ app, services }) => registerDaemonStatusRoutes({ app: app as Express, deps, adapter: services.context.adapter }),
        }),
      };
    },
  });

  return [
    healthFeature,
    runsFeature,
    agentsFeature,
    hostToolsFeature,
    modelProxyFeature,
    activeContextFeature,
    terminalFeature,
    daemonDbFeature,
    toolCatalogFeature,
    delegatedToolCallsFeature,
    connectorsFeature,
    researchFeature,
    xaiFeature,
    remoteRunEventsFeature,
    memoryFeature,
    routinesFeature,
    mediaFeature,
    frontendSessionsFeature,
    daemonStatusFeature,
  ];
}

import type { SqliteSyncOpener } from '@jini-ai/db/sqlite';
/**
 * @module create-local-node-daemon
 *
 * The "host preset" (extraction-plan.md §2.4) that lets a brand-new product boot a running daemon
 * process by implementing zero interfaces: assembles `@jini-ai/sqlite`'s durable `EventLog`,
 * `@jini-ai/daemon`'s `RunLifecycle` and `AgentExecutor` (the driver that actually spawns an agent
 * CLI subprocess for 23 of the 24 registered defs — see `@jini-ai/daemon`'s own archived provenance ledger), an HTTP
 * app wrapped in `@jini-ai/http-kit`'s route-registration guard and security middleware, a caller's own
 * `@jini-ai/core` packs, and the generic daemon-status routes, then listens and returns `{url, server,
 * stop}`.
 *
 * **As of 2026-07-29 this is a thin listener/discovery wrapper over `composeJiniKernel`** (see
 * `compose-jini-kernel.ts`). Everything it used to assemble inline — the kernel, the tool registry,
 * every route family — now comes from the shared feature catalog, pinned to the immutable
 * `local-daemon-v1` capability profile so this function's mounted surface, route order, tool
 * registration order and shutdown sequence are byte-for-byte what they have always been. The reason
 * for the change is not this function; it is that a preset assembling routes and tools inline, next
 * to a separate composable surface, guarantees the two eventually disagree about what a "feature"
 * mounts. There is now one path, and this is a caller of it.
 *
 * Callers who want a different surface pass `profile`/`capabilities`/`features`; callers who pass
 * nothing get the historical daemon exactly. `local-daemon-v1` is immutable: a future feature never
 * silently joins it.
 *
 * Also writes (2026-07-21) a `@jini-ai/sidecar`-backed local daemon-registry record — see
 * `resolveDaemonRegistryPath`'s own doc and this file's `CreateLocalNodeDaemonConfig.discoveryFile`
 * — once the real bound port is known, and removes it during `stop()`.
 *
 * This preset supported a switchable `transport: 'express' | 'fastify'` HTTP transport from
 * 2026-07-19 through 2026-07-22; it was removed since nothing ever consumed `transport: 'fastify'`
 * in practice — see `archived provenance ledger`'s dated entry and the `future/fastify-transport` branch.
 */
import { createRequire } from 'node:module';
import type { Server } from 'node:http';

import express, { type Express } from 'express';
import type { DetectedAgent, OAuthCallbackListener } from '@jini-ai/agent-runtime';
import type { Bindings, Principal, ToolRegistration } from '@jini-ai/core';
import type { AnyPack, MissingTokenIds } from '@jini-ai/core/composition';
import type { ResolveRunInput, RunLifecycle } from '@jini-ai/daemon';
import { installRouteRegistrationGuard, mountPackHttp, type AdapterContext } from '@jini-ai/http-kit';
import type {  DelegatedToolExecuteRequest,  RunStartHandler,  WorkspaceRootResolver } from '@jini-ai/daemon/http';
import { removeDaemonRegistryRecordIfCurrent, resolveDaemonRegistryPath, writeDaemonRegistryRecord } from '@jini-ai/sidecar';

import { composeJiniKernel, type JiniKernelSecurity, type KernelBoundIds } from './compose-jini-kernel.js';
import type { BuiltInFeatureOptions } from './builtin-features.js';
import type { CapabilityId, JiniProfileId } from './feature.js';
import { closeHttpServer, normalizeDaemonBindHost } from './host-bootstrap.js';

const require = createRequire(import.meta.url);
/** This package's own `package.json` version, echoed back by `GET /api/daemon/status`. */
const packageVersion = (require('../package.json') as { readonly version: string }).version;

const DEFAULT_HOST = '127.0.0.1';
const DEFAULT_TOKEN_ENV_VAR = 'JINI_API_TOKEN';
const DEFAULT_DISABLE_ENV_VAR = 'JINI_DISABLE_API_AUTH';
const DEFAULT_BIND_HOST_ENV_VAR = 'JINI_BIND_HOST';

// Re-exported from their new home so this module's long-standing public surface is unchanged.
export { buildDaemonDbOperations, projectDetectedAgent } from './builtin-features.js';
export { classifyRunFailureForRetry } from './kernel-base.js';

/**
 * Extracts the real bound TCP port from `server.address()`'s result once a `'listening'` event
 * has fired.
 *
 * @param address - The raw return value of `server.address()`.
 * @returns The bound port, or `null` if `address` is `null` (not yet listening), a string (a Unix
 * domain socket path — this module never listens on one), or an `AddressInfo` with a non-positive port.
 * @complexity O(1).
 * @overallScore 100/100
 */
export function resolveBoundPort(address: { port: number } | string | null): number | null {
  if (address == null || typeof address === 'string') return null;
  return address.port > 0 ? address.port : null;
}

/**
 * The host a daemon's reported base URL should use: binding to every interface (`0.0.0.0` / `::`)
 * is not itself a connectable address, so callers are told to use the IPv4 loopback address
 * instead; and an IPv6 literal is returned in bracketed authority form.
 *
 * The brackets are not cosmetic. `http://${'::1'}:5000` is not a URL — `new URL()` throws on it and
 * so does `fetch`, which made a daemon bound to `::1` hand back a base URL nothing could use and
 * write that same unusable string into its discovery record. RFC 3986 §3.2.2 requires the brackets
 * for any IPv6 literal in an authority, precisely so the address's own colons cannot be read as the
 * port separator.
 *
 * @param bindHost - The literal host `createLocalNodeDaemon` bound to (already normalized).
 * @returns `'127.0.0.1'` for an all-interfaces bind host, `'[…]'` for an IPv6 literal (already-
 * bracketed input is returned unchanged), otherwise `bindHost` unchanged.
 * @complexity O(1).
 * @overallScore 100/100
 */
export function resolveReportHost(bindHost: string): string {
  if (bindHost === '0.0.0.0' || bindHost === '::') return '127.0.0.1';
  // A colon can only mean "IPv6 literal" here: a bind host is a host, never a `host:port` pair, and
  // no DNS name or IPv4 address contains one.
  if (bindHost.includes(':') && !bindHost.startsWith('[')) return `[${bindHost}]`;
  return bindHost;
}

export type { KernelBoundIds };

/**
 * Product-level HTTP composition seam. Incubating capabilities register their routes here instead
 * of becoming downward dependencies of this locked host preset.
 */
export interface LocalNodeHttpExtensionContext {
  readonly adapter: AdapterContext;
  readonly lifecycle: RunLifecycle;
  readonly dataDir: string;
}

export type LocalNodeHttpExtension = (app: Express, context: LocalNodeHttpExtensionContext) => void;

export interface CreateLocalNodeDaemonConfig<
  Packs extends readonly AnyPack[],
  BoundIds extends string = KernelBoundIds,
> {
  /** Directory the daemon's durable state lives in. The directory itself must already exist. */
  dataDir: string;
  /** The external host supplies its driver; Jini never autoloads SQLite. */
  open: SqliteSyncOpener;
  packs: Packs;
  /**
   * Extends the kernel's own pre-bound `EventLog`/`RunLifecycle` bindings with whatever a pack's
   * own deps require. A callback rather than a pre-built `Bindings` instance because
   * `Bindings.bind()` mutates and returns `this`.
   */
  bindings?: (b: Bindings<KernelBoundIds>) => Bindings<BoundIds>;
  /** TCP port to listen on. Defaults to `0` (ask the OS for an ephemeral free port). */
  port?: number;
  /** Host/address to bind to. Defaults to `'127.0.0.1'` (loopback-only). */
  host?: string;
  /** Env var names for the optional bearer-token gate. Defaults to `JINI_API_TOKEN` / `JINI_DISABLE_API_AUTH`. Ignored when `security` below selects `sidecar-strict`. */
  apiToken?: { tokenEnvVar?: string; disableEnvVar?: string };
  /**
   * Raises this preset's default `jini-local` gate to `sidecar-strict` — see
   * {@link JiniKernelSecurity}'s own doc for what that changes: every `/api` request must carry the
   * bearer token, including one from `127.0.0.1`, and an unconfigured token fails closed rather than
   * serving unauthenticated callers. `host` is supplied automatically from this config's own `host`
   * (there is nowhere else for it to disagree with, so it is not this option's to set again).
   * Omitted (the default) keeps `jini-local` exactly as every existing caller already has it.
   */
  security?: Omit<Extract<JiniKernelSecurity, { readonly mode: 'sidecar-strict' }>, 'host'>;
  /** Invoked once the HTTP listener has fully closed, before the durable `EventLog` is closed. */
  onShutdown?: () => Promise<void> | void;
  /** Snapshotted per daemon; defaults to `process.env`. The caller's object is never mutated. */
  env?: NodeJS.ProcessEnv;
  /** Bind the preset and custom run handlers to the same owned runtime and explicit policies. */
  agentExecutor?: Parameters<typeof composeJiniKernel>[0]['agentExecutor'];
  /** Optional detector override for a host with custom PATH/env policy or a deterministic test fixture. */
  agentDetector?: () => Promise<readonly DetectedAgent[]>;
  /**
   * Optional host-owned driver attached immediately after `POST /api/runs` durably starts a run.
   * Takes full precedence over {@link resolveRunInput} when both are supplied.
   */
  onRunStarted?: RunStartHandler;
  /**
   * Host-owned prompt/cwd/env composition seam. When supplied and `onRunStarted` is not, this
   * daemon builds a default `RunStartHandler` that resolves each run's input through this seam and
   * drives it straight to the zero-config `AgentExecutor`. Ignored when `onRunStarted` is supplied.
   */
  resolveRunInput?: ResolveRunInput;
  /**
   * Resolves a `resourceRef` to a filesystem working directory for `POST /api/resources/:resourceRef/open-in`.
   * Defaults to `denyAllWorkspaceRoots`: the route exists and is reachable but denies every call
   * with `404`, never fabricating or guessing a path.
   */
  resolveWorkspaceRoot?: WorkspaceRootResolver;
  /**
   * Optional product/capability route registrars. They run after the host's security middleware
   * and locked route packs, before caller packs and daemon-status routes.
   */
  httpExtensions?: readonly LocalNodeHttpExtension[];
  /**
   * Host-contributed `{descriptor, handler, policy}` triples, registered into the same internal
   * registry this preset's own gated tools (`jini.terminal.create`, `daemon.db.*`) use — and so
   * executed through the same `ToolExecutor`, inheriting its authorization, confirmation, timeout,
   * cancellation, output truncation, and audit trail.
   *
   * @throws At startup if a `descriptor.id` is already registered — by another entry here, or by
   * one of the preset's own tools. The registry is append-only by design.
   */
  toolRegistrations?: readonly ToolRegistration[];
  /**
   * Resolves the `Principal` one `POST /api/delegated-tool-calls` request executes as.
   *
   * @default the anonymous, role-less delegated principal — inertness comes from deny-by-default
   * tool policies, not from the identity.
   */
  resolveDelegatedPrincipal?: (request: DelegatedToolExecuteRequest) => Principal | Promise<Principal>;
  /**
   * Where this daemon's local discovery record (URL/host/port/pid) is written once it starts
   * listening. Defaults to `<dataDir>/daemon.json`. Pass `false` to disable. Best-effort: a failure
   * here never fails daemon startup or shutdown.
   */
  discoveryFile?: string | false;
  /**
   * Capability profile this daemon composes against.
   *
   * @default 'local-daemon-v1' — the immutable compatibility profile holding exactly the surface
   * this preset has always mounted. Changing it changes which route families exist; see
   * `feature.ts` for the vocabulary and why profiles are versioned rather than edited.
   */
  profile?: JiniProfileId;
  /**
   * Raises or lowers the profile's capability ceiling. A denial always wins: explicitly enabling a
   * feature whose capability is denied here is a startup error naming both, never a silent
   * re-opening of a coarse switch.
   */
  capabilities?: Readonly<Partial<Record<CapabilityId, boolean | undefined>>>;
  /**
   * Turns individual features on or off within whatever the capability ceiling permits — e.g.
   * `{ terminal: false, daemonDb: false }`. A feature turned off here registers **neither its
   * routes nor its tools**, so a disabled capability is absent from the shared registry rather than
   * merely unrouted.
   */
  features?: Readonly<Record<string, boolean | undefined>>;
}

export interface LocalNodeDaemon {
  /** The daemon's real, resolved base URL (reflects the actual bound port even when `port: 0` was requested). */
  readonly url: string;
  readonly server: Server;
  /**
   * Gracefully shuts the daemon down: closes the HTTP listener, disposes every composed feature
   * (releasing e.g. an in-flight xAI OAuth loopback listener), removes the discovery record, runs
   * the caller's `onShutdown` hook, then closes the durable sqlite handles. Idempotent and safe to
   * call more than once, or concurrently.
   */
  stop(): Promise<void>;
  /** Every feature actually composed, with why and what it grants. */
  readonly activeFeatures: readonly string[];
}

type LocalPresetConfig = CreateLocalNodeDaemonConfig<readonly AnyPack[], string>;

function localKernelOptions(
  { config }: { config: LocalPresetConfig },
  _optional: Record<string, never> = {},
) {
  return {
    profile: config.profile ?? 'local-daemon-v1',
    ...(config.capabilities === undefined ? {} : { capabilities: config.capabilities }),
    ...(config.features === undefined ? {} : { features: config.features }),
    packs: config.packs,
    ...(config.bindings === undefined ? {} : { bindings: config.bindings }),
    ...(config.toolRegistrations === undefined ? {} : { toolRegistrations: config.toolRegistrations }),
  };
}

function localSecurity(
  { config, host }: { config: LocalPresetConfig; host: string },
