   * Declares that this agent's CLI carries its reasoning-effort choice INSIDE
   * the model id — as a trailing `-<level>` on the slug — instead of in a flag
   * of its own, and names which trailing tokens count as levels.
   *
   * Mirrors `@jini-ai/agent-runtime`'s `RuntimeReasoningInModelId` field-for-
   * field, the same way `reasoningOptions` above mirrors its
   * `RuntimeReasoningOption[]`, and for the same reason (see this interface's
   * own doc). Present INSTEAD of `reasoningOptions`, never alongside it: a card
   * carrying both would render two effort controls that disagree about where
   * the choice goes.
   *
   * Only the vocabulary is declared. Which of these levels a given base model
   * actually has is DERIVED from `models` by `reasoningModelGroups`
   * (`rules.ts`) — availability is genuinely not uniform (antigravity's
   * `gemini-3.1-pro` has only high and low, `gpt-oss-120b` only medium,
   * `claude-sonnet-4-6` none), so a fixed high/medium/low control would offer
   * slugs the CLI rejects outright.
   */
  reasoningInModelId?: { levels: readonly AgentModelOption[] } | undefined;
  /** See `AgentSupportsCustomModel`. `undefined` allows custom input,
   *  matching every adapter's default before this field existed. */
  supportsCustomModel?: AgentSupportsCustomModel | undefined;
  authStatus?: AgentAuthStatus | undefined;
  /** Operator-actionable detail behind a `'missing'`/`'unknown'` status —
   *  rendered as the meta line's tooltip so the card stays compact without
   *  discarding the reason. */
  authMessage?: string | undefined;
  /** Short marketing-ish tags ("Official", "Lower cost"). The mechanism is
   *  generic; the vocabulary is the host's — this package ships none. */
  badges?: readonly string[] | undefined;
  /** Why this agent is unavailable or only partially usable, as one or more
   *  renderable "reason + fix button(s)" rows — see `AgentDiagnostic`. Absent
   *  or empty means detection has nothing actionable to report (the common
   *  case for a healthy, authenticated CLI). */
  diagnostics?: readonly AgentDiagnostic[] | undefined;
  /** Destination for an `{kind: 'openInstall'}` fix action — the CLI's
   *  install/download page. Absent hides that action even if a diagnostic
   *  requests it, per `AgentDiagnosticRow`'s "only render what the host can
   *  actually do" contract. */
  installUrl?: string | undefined;
  /** Destination for an `{kind: 'openDocs'}` fix action — the CLI's
   *  configuration/auth docs. Same absent-hides-the-action rule as
   *  `installUrl`. */
  docsUrl?: string | undefined;
}

/**
 * Why a CLI agent is unavailable or only partially usable, in a shape a UI
 * can render as "one-line reason + fix button(s)" instead of a silent grey
 * card.
 *
 * Origin: OD's `packages/contracts/src/api/registry.ts#AgentDiagnostic` /
 * `AgentFixIntent`, vendored into `@jini-ai/protocol`'s `agent-catalog.ts`
 * (2026-07-29) unmodified. Mirrored here field-for-field rather than
 * imported — this file has zero imports of its own (framework-free, part of
 * this package's `./core` subpath), the same reasoning `DetectedAgent`'s own
 * doc comment gives for mirroring `@jini-ai/agent-runtime`'s shape instead of
 * depending on that Node-only package. A host on `@jini-ai/agent-runtime` /
 * `@jini-ai/protocol` passes its `AgentDiagnostic[]` straight through
 * unmapped, since the fields are identical.
 */
export interface AgentDiagnostic {
  reason: AgentDiagnosticReason;
  severity: AgentDiagnosticSeverity;
  /** Short, human-readable, single-sentence explanation. */
  message: string;
  /** Optional longer context (e.g. the probe's stderr tail). */
  detail?: string | undefined;
  /** Directories PATH detection searched, surfaced verbatim for the
   *  `'not-on-path'` case so the operator can see where detection looked
   *  before being asked to set an explicit binary path. */
  searchedDirs?: readonly string[] | undefined;
  /** Ordered fix affordances the UI should offer for this diagnostic. */
  fixActions?: readonly AgentFixIntent[] | undefined;
}

export type AgentDiagnosticReason =
  /** The binary (and any fallback names) was not found on PATH. */
  | 'not-on-path'
  /** A file matched but is not executable (missing +x / wrong PATHEXT). */
  | 'not-executable'
  /** A wrapper/shim was found but its target is gone (exit 126/127). */
  | 'shim-broken'
  /** A user-set binary-path override points at a missing/invalid file. */
  | 'configured-bin-invalid'
  /** Installed and invocable, but the CLI is not authenticated. */
  | 'auth-missing'
  /** Installed, but auth status could not be verified. */
  | 'auth-unknown';

export type AgentDiagnosticSeverity = 'error' | 'warning' | 'info';

/**
 * A typed "what should the UI do to fix this" intent attached to an
 * `AgentDiagnostic`. The UI renders one button per intent and owns the
 * concrete handler (open a URL, re-run detection, write an env override);
 * keeping the intent typed — rather than a pre-baked button label + URL —
 * lets more than one surface render the same fix affordances from one
 * source of truth.
 */
export type AgentFixIntent =
  /** Open the agent's configuration/auth docs. */
  | { kind: 'openDocs' }
  /** Open the agent's install/download page. */
  | { kind: 'openInstall' }
  /** Re-run agent detection (this tab's rescan affordance). */
  | { kind: 'rescan' }
  /** Prompt the operator to point the host at an explicit binary by writing
   *  `envKey` into `LocalCliConfig.envByAgentId` — used when the CLI is
   *  installed somewhere PATH detection can't reach. */
  | { kind: 'setEnv'; envKey: string }
  /** Clear a previously-set binary override so detection falls back to PATH. */
  | { kind: 'clearEnv'; envKey: string }
  /** Launch the agent's interactive sign-in in a system terminal (used by
   *  adapters whose OAuth flow cannot complete headlessly). */
  | { kind: 'launchOAuth'; agentId: string };

/**
 * Catalog entry describing one operator-configurable CLI environment
 * variable for one agent (a proxy base URL, a custom config directory, a
 * binary-path override, …). Origin: `AGENT_CLI_ENV_FIELDS`. A host supplies
 * its own catalog the same way it supplies `ProviderPreset`s — this package
 * ships `DEFAULT_AGENT_CLI_ENV_FIELDS` as a starting point for the CLIs it
 * already knows about (see `DEFAULT_AGENT_DESCRIPTIONS`), not as a fixed list.
 */
export interface AgentCliEnvFieldSpec {
  agentId: string;
  envKey: string;
  /** Field label. This package's convention: the English string IS the i18n
   *  key (see `PROTOCOL_OPTIONS`) — a host translates it, it does not supply
   *  a separate key. */
  label: string;
  placeholder?: string | undefined;
  /** Renders the input as `type="password"` and omits the value from any
   *  plain-text display. */
  secret?: boolean | undefined;
  /** Marks this field as the agent's executable-path override — the field a
   *  "use detected path" / "clear custom path" repair affordance (see
   *  `agentExecutableRepairState`) should set or clear. At most one field per
   *  `agentId` should carry this; the mechanism is generic, but this
   *  package's own `DEFAULT_AGENT_CLI_ENV_FIELDS` only tags Codex's
   *  `CODEX_BIN`, mirroring the origin's actual (Codex-only) behavior. */
  kind?: 'binPath' | undefined;
}

/**
 * Which detected CLI runs the operator's prompts, and with which model.
 *
 * `modelByAgentId` is keyed rather than flat because the picker is per-agent:
 * switching from Claude to Codex and back must not silently hand Codex's model
 * id to Claude. The origin kept the same shape (`cfg.agentModels`, keyed by
 * agent id) for the same reason.
 */
export interface LocalCliConfig {
  /** `null` until the operator picks one — deliberately not defaulted to the
   *  first detected agent, so "nothing selected" stays distinguishable from
   *  "the first one was chosen for you". */
  agentId: string | null;
  modelByAgentId?: Readonly<Record<string, string>>;
  /** Per-agent reasoning-effort pick, keyed the same way as `modelByAgentId`
   *  and for the same reason: switching agents and back must not hand one
   *  agent's reasoning choice to another. */
  reasoningByAgentId?: Readonly<Record<string, string>>;
  /** Per-agent CLI environment overrides — proxy URLs, custom config dirs, a
   *  binary-path override — keyed by agent id then env var name. Origin:
   *  `AppConfig.agentCliEnv`. Mirrors that two-level shape directly rather
   *  than flattening it, since a field's env-var name is only unique WITHIN
   *  an agent (`CODEX_BIN` means nothing for `claude`). */
  envByAgentId?: Readonly<Record<string, Readonly<Record<string, string>>>>;
}

/** Which required BYOK field is still blank/invalid. Drives the inline
 *  "required" markers without the tab hard-coding field labels. */
export type ByokRequiredField = 'apiKey' | 'baseUrl' | 'model';

export type ConnectionTestState =
  | { status: 'idle' }
  | { status: 'testing' }
  | { status: 'ok'; message?: string | undefined }
  | { status: 'error'; message: string };

/**
 * Which executable a Local-CLI test actually invoked. `'primary'` is the
 * normal case (the resolved/on-PATH binary ran). The two `fallback-*`
 * variants report that a configured binary-path override
 * (`AgentCliEnvFieldSpec` with `kind: 'binPath'`) could not be used and
 * detection fell back to a different binary anyway — `'fallback-invalid'`
 * when the override path never resolved to an executable, `'fallback-failed'`
 * when it resolved but failed to run. Both are the trigger for
 * `agentExecutableRepairState`'s repair affordance. Origin: OD's
 * `ConnectionTestResponse.usedExecutableSource` (`'fallback_invalid'` /
 * `'fallback_failed'`, renamed to this package's kebab-case convention).
 */
export type AgentExecutableSource = 'primary' | 'fallback-invalid' | 'fallback-failed';

/** Result of the per-agent Test button, surfaced under the selected card.
 *  Same idiom as `ConnectionTestState` — the two report the same kind of
 *  outcome for the two execution modes, so they deliberately share a shape.
 *  `usedExecutableSource`/`detectedExecutablePath` are optional passthrough
 *  from `ExecutionPort.testAgent`'s result, present only when the host's
 *  probe can report which binary it actually ran — see
 *  `agentExecutableRepairState`. */
export type AgentTestState =
  | { status: 'idle' }
  | { status: 'testing'; agentId: string }
  | {
      status: 'ok';
      agentId: string;
      message?: string | undefined;
      usedExecutableSource?: AgentExecutableSource | undefined;
      detectedExecutablePath?: string | undefined;
    }
  | { status: 'error'; agentId: string; message: string };

/** The repair affordance a successful-but-fallback agent test unlocks: an
 *  operator-set binary-path override didn't work, detection silently fell
 *  back to a different binary, and the test still passed — so the operator
 *  should be offered "use the binary that actually worked" or "clear the
 *  override and stop overriding". `canUseDetected` is carried explicitly
 *  (rather than always being implied `true`) so a future detection outcome
 *  that finds a fallback path but cannot vouch for it has somewhere to say
 *  so without a breaking shape change. */
export interface AgentExecutableRepair {
  detectedPath: string;
  canUseDetected: boolean;
}

/**
 * One base model of a `DetectedAgent.reasoningInModelId` agent, together with the effort levels
 * that model ACTUALLY has — derived from the agent's own model list by `reasoningModelGroups`
 * (`rules.ts`), never declared.
 *
 * This is the shape the card renders its two controls from: the base picker lists one entry per
 * group, and the effort picker lists exactly `levels` for whichever group is active. That is what
 * keeps it from offering a slug the CLI would reject — `gemini-3.1-pro` genuinely has no `-medium`
 * variant, so `levels` genuinely has no `medium` entry.
 */
export interface ReasoningModelGroup {
  /** The model id with any recognized effort suffix removed (`gemini-3.1-pro`). */
  baseId: string;
  /** Display name for the base. The effort qualifier is stripped from the source label only when
   *  the id it came from carried a real suffix — so `Gemini 3.1 Pro (High)` becomes `Gemini 3.1
   *  Pro`, while `Claude Sonnet 4.6 (Thinking)` (a suffix-less id) keeps its parenthetical. */
  label: string;
  /** The effort levels this base really offers, in the declared vocabulary's order. Empty for a
   *  base the catalog lists without any suffixed variant. */
  levels: readonly AgentModelOption[];
  /** Full model id per level in `levels` — the recombination table, so composing a slug is a
   *  lookup of something the catalog actually contained rather than string concatenation. */
  modelIdByLevel: Readonly<Record<string, string>>;
  /** The suffix-less id, when the catalog lists the base on its own (`claude-sonnet-4-6`,
   *  `default`). Absent for a base that only ever appears with a suffix. */
  bareModelId?: string | undefined;
}

/** Result of a local-CLI rescan, surfaced as an inline status line. */
export type AgentScanState =
  | { status: 'idle' }
  | { status: 'scanning' }
  | { status: 'ok'; count: number }
  | { status: 'error'; message: string };

/** Result of `ExecutionPort.listModels`, surfaced as an inline hint near the
 *  Model field. Mirrors `ConnectionTestState`/`AgentScanState`'s shape
 *  deliberately — one idiom for "async edge result" across this tab, per
 *  this package's error-reporting contract (§3.2: reuse an existing union
 *  over introducing a parallel shape). A failure here must NOT collapse
 *  into the same "no models" the field already tolerates when a host
 *  supplies no `listModels` at all — `'error'` is a distinct, renderable
 *  state, not an empty `'ok'`. */
export type ModelDiscoveryState =
  | { status: 'idle' }
  | { status: 'loading' }
  | { status: 'ok'; models: readonly string[] }
  | { status: 'error'; message: string };

/**
 * Generic i18n type vocabulary.
 *
 * Origin (`i18n/types.ts` in the vendored OD web tree) hard-codes a single
 * `Locale` union of 19 language tags and a `Dict` interface with ~1,400
 * named keys — OD's actual translated product copy, not reusable content.
 * This module keeps only the *shape* of that pattern (a locale is a plain
 * string, a dictionary is a flat, string-keyed lookup) so a host supplies
 * its own locale union and its own dictionary type as a generic parameter.
 */

/** A BCP-47-ish locale tag (e.g. `'en'`, `'zh-CN'`). Any string a host defines. */
export type Locale = string;

/** Interpolation values substituted into a `{name}`-style placeholder. */
export type TranslationVars = Record<string, string | number>;

/**
 * Flat, string-keyed translation dictionary. Kept flat (not deeply nested)
 * for the same reason the origin's `Dict` was: a missing key surfaces as a
 * plain string-index miss instead of a structural type mismatch.
 *
 * A host narrows this via its own dictionary interface (mirroring OD's own
 * `Dict`) and passes `Record<Locale, ItsDict>` to {@link I18nProvider}.
 */
export interface TranslationDict {
  [key: string]: string;
}

/**
 * The completion-signal sound catalog: ids, labels, and defaults.
 *
 * Split out of `@jini-ai/ui`'s `utils/notifications.ts`, which is otherwise
 * browser-bound (it drives `AudioContext`, the `Notification` constructor, and
 * a service-worker registration). This half is plain data — a settings tab has
 * to name the choices to render them, and naming them requires no DOM at all.
 * Keeping the catalog here is what lets this package stay `runtime: universal`
 * while the player stays where the Web Audio API is available.
 *
 * `utils/notifications.ts` re-exports every symbol below, so existing imports
 * of it keep resolving unchanged.
 */

export type SoundId = string;

export interface SoundOption {
  id: SoundId;
  /** i18n key rather than a literal — the sound catalog has no fixed
   *  dictionary type to key into, so hosts translate these themselves. */
  labelKey: string;
}

export const SUCCESS_SOUNDS: SoundOption[] = [
  { id: 'ding', labelKey: 'notifications.sound.ding' },
  { id: 'chime', labelKey: 'notifications.sound.chime' },
  { id: 'two-tone-up', labelKey: 'notifications.sound.twoToneUp' },
  { id: 'pluck', labelKey: 'notifications.sound.pluck' },
];

export const FAILURE_SOUNDS: SoundOption[] = [
  { id: 'buzz', labelKey: 'notifications.sound.buzz' },
  { id: 'two-tone-down', labelKey: 'notifications.sound.twoToneDown' },
  { id: 'thud', labelKey: 'notifications.sound.thud' },
];

export const DEFAULT_SUCCESS_SOUND_ID: SoundId = 'ding';
export const DEFAULT_FAILURE_SOUND_ID: SoundId = 'buzz';

// HeaderActionsMenu — a compact "More" overflow menu for a sticky/compact
// header: a single trigger button that opens a grouped popover of actions
// (divided into visually-separated groups, empty groups skipped). Closes on
// outside click or Escape.

import {
  Fragment,
  useCallback,
  useEffect,
  useMemo,
  useRef,
  useState,
  type MutableRefObject,
} from 'react';

import { Icon, type IconName } from './Icon.js';

export interface HeaderMenuAction {
  id: string;
  label: string;
  icon: IconName;
  onClick: () => void;
  disabled?: boolean;
  loading?: boolean;
  /** Toggles render with checkbox semantics + a trailing check when active. */
  active?: boolean;
}

export interface HeaderActionsMenuProps {
  /** Each inner array renders as one visually-divided group; empty groups are skipped. */
  groups: HeaderMenuAction[][];
  /** Accessible label for the trigger button and the popover menu. */
  label: string;
  /** Custom hook override for dependency injection / testing. */
  useHeaderActionsMenu?: typeof useHeaderActionsMenu;
}

// ---------------------------------------------------------------------------
// Pure helpers — no React, directly unit-testable.
// ---------------------------------------------------------------------------

/** Drops empty groups so only groups with at least one action render. */
export function filterVisibleActionGroups(groups: HeaderMenuAction[][]): HeaderMenuAction[][] {
  return groups.filter((group) => group.length > 0);
}

/** The single key that dismisses the menu. */
export function isHeaderMenuDismissKey(key: string): boolean {
  return key === 'Escape';
}

/**
 * Whether a pointer event landed outside the menu (and should therefore close
 * it). A missing container never counts as "outside".
 */
export function isOutsideHeaderMenu(
  container: HTMLElement | null,
  target: EventTarget | null,
): boolean {
  if (!container) return false;
  return !container.contains(target as Node | null);
}

/** ARIA role: plain menuitem, or checkbox semantics when the item is a toggle. */
export function headerMenuItemRole(active: boolean | undefined): 'menuitem' | 'menuitemcheckbox' {
  return active === undefined ? 'menuitem' : 'menuitemcheckbox';
}

/** `aria-checked` value: only meaningful (and only set) for toggle items. */
export function headerMenuItemAriaChecked(active: boolean | undefined): boolean | undefined {
  return active === undefined ? undefined : active;
}

/** The icon to render — the spinner while loading, otherwise the item's icon. */
export function headerMenuItemIcon(item: HeaderMenuAction): IconName {
  return item.loading ? 'spinner' : item.icon;
}

/** Disabled while explicitly disabled or loading. */
export function headerMenuItemDisabled(item: HeaderMenuAction): boolean {
  return Boolean(item.disabled || item.loading);
}

/** `aria-busy` value: `true` while loading, otherwise unset. */
export function headerMenuItemBusy(item: HeaderMenuAction): true | undefined {
  return item.loading || undefined;
}

// ---------------------------------------------------------------------------
// Hooks — every stateful/effectful seam, exported for isolated testing.
// ---------------------------------------------------------------------------

export interface HeaderActionsMenuDisclosure {
  open: boolean;
  toggle: () => void;
  close: () => void;
}

/** Open/close state for the popover with stable toggle/close callbacks. */
export function useHeaderActionsMenuDisclosure(): HeaderActionsMenuDisclosure {
  const [open, setOpen] = useState(false);
  const toggle = useCallback(() => setOpen((value) => !value), []);
  const close = useCallback(() => setOpen(false), []);
  return { open, toggle, close };
}

/** Memoized list of non-empty groups. */
export function useVisibleActionGroups(groups: HeaderMenuAction[][]): HeaderMenuAction[][] {
  return useMemo(() => filterVisibleActionGroups(groups), [groups]);
}

/**
 * While `open`, closes the menu on an outside `mousedown` or an Escape keydown.
 * Listeners are only attached while open and torn down on close/unmount.
 */
export function useHeaderActionsMenuDismiss(params: {
  open: boolean;
  onDismiss: () => void;
  containerRef: MutableRefObject<HTMLElement | null>;
}): void {
  const { open, onDismiss, containerRef } = params;
  useEffect(() => {
    if (!open) return undefined;
    function onPointerDown(event: MouseEvent) {
      if (isOutsideHeaderMenu(containerRef.current, event.target)) onDismiss();
    }
    function onKeyDown(event: KeyboardEvent) {
      if (isHeaderMenuDismissKey(event.key)) onDismiss();
    }
    document.addEventListener('mousedown', onPointerDown);
    document.addEventListener('keydown', onKeyDown);
    return () => {
      document.removeEventListener('mousedown', onPointerDown);
      document.removeEventListener('keydown', onKeyDown);
    };
  }, [open, onDismiss, containerRef]);
}

export interface UseHeaderActionsMenuResult {
  open: boolean;
  toggle: () => void;
  close: () => void;
  containerRef: MutableRefObject<HTMLDivElement | null>;
  visibleGroups: HeaderMenuAction[][];
}

/**
 * Composes the menu's whole behavior — disclosure, the visible-group filter,
 * and the outside/Escape dismissal — so {@link HeaderActionsMenu} is a dumb
 * render.
 */
export function useHeaderActionsMenu(groups: HeaderMenuAction[][]): UseHeaderActionsMenuResult {
  const containerRef = useRef<HTMLDivElement | null>(null);
  const { open, toggle, close } = useHeaderActionsMenuDisclosure();
  const visibleGroups = useVisibleActionGroups(groups);
  useHeaderActionsMenuDismiss({ open, onDismiss: close, containerRef });
  return { open, toggle, close, containerRef, visibleGroups };
}

// ---------------------------------------------------------------------------
// Component — dumb render, all logic delegated above.
// ---------------------------------------------------------------------------

export function HeaderActionsMenu({
  groups,
  label,
  useHeaderActionsMenu: useHeaderActionsMenuHook = useHeaderActionsMenu,
}: HeaderActionsMenuProps) {
  const { open, toggle, close, containerRef, visibleGroups } = useHeaderActionsMenuHook(groups);

  if (visibleGroups.length === 0) return null;

  return (
    <div className="jini-header-actions-menu" ref={containerRef}>
      <button
        type="button"
        className="jini-header-actions-menu-trigger"
        onClick={toggle}
        aria-haspopup="menu"
        aria-expanded={open}
        aria-label={label}
        title={label}
        data-testid="header-actions-menu-trigger"
      >
        <Icon name="more-horizontal" size={16} />
      </button>
      {open ? (
        <div className="jini-header-actions-menu-popover" role="menu" aria-label={label}>
          {visibleGroups.map((group, groupIndex) => (
            // `visibleGroups` is `groups.filter((g) => g.length > 0)`, so
            // `group[0]` is always defined here.
            <Fragment key={group[0]!.id}>
              {groupIndex > 0 ? <div className="jini-header-actions-menu-divider" aria-hidden /> : null}
              {group.map((item) => (
                <button
                  key={item.id}
                  type="button"
                  role={headerMenuItemRole(item.active)}
                  aria-checked={headerMenuItemAriaChecked(item.active)}
                  className="jini-header-actions-menu-item"
                  disabled={headerMenuItemDisabled(item)}
                  aria-busy={headerMenuItemBusy(item)}
                  onClick={() => {
                    item.onClick();
                    close();
                  }}
                >
                  <span className="jini-header-actions-menu-item-icon" aria-hidden>
                    <Icon name={headerMenuItemIcon(item)} size={15} />
                  </span>
                  <span className="jini-header-actions-menu-item-label">{item.label}</span>
                  {item.active ? (
                    <span className="jini-header-actions-menu-item-check" aria-hidden>
                      <Icon name="check" size={14} />
                    </span>
                  ) : null}
                </button>
              ))}
            </Fragment>
          ))}
        </div>
      ) : null}
    </div>
  );
}

/**
 * Desktop notification + short synthesized sound-cue system for
 * "long-running task finished" style completion signals.
 *
 * Origin: `utils/notifications.ts`. Genericized in two places (see
 * `packages/ui/archived provenance ledger`):
 *   - `labelKey: keyof Dict` (OD's fixed translation dictionary type)
 *     widened to a plain `string` — this package's i18n feature has no
 *     fixed `Dict` shape for a sound catalog to key into.
 *   - The hard-coded `'/od-notifications-sw.js'` service-worker URL and
 *     `'od-task-'` notification tag prefix are now caller-supplied
 *     options (defaulting to generic, non-product-branded values).
 */

// The catalog (ids, labels, defaults) now lives in
// `features/notifications/notifications-catalog.ts` so a settings surface
// can name the choices without pulling in Web Audio or the Notification
// API. Re-exported here so every existing importer of this module keeps
// working unchanged.
import type { SoundId } from '../features/notifications/notifications-catalog.js';
export {
  DEFAULT_FAILURE_SOUND_ID,
  DEFAULT_SUCCESS_SOUND_ID,
  FAILURE_SOUNDS,
  type SoundId,
  type SoundOption,
  SUCCESS_SOUNDS,
} from '../features/notifications/notifications-catalog.js';


type AudioCtxCtor = typeof AudioContext;
type NotificationOptionsWithBrowserExtensions = NotificationOptions & {
  renotify?: boolean;
};

let ctx: AudioContext | null = null;
const activeNotifications = new Set<Notification>();

function getCtx(): AudioContext | null {
  if (typeof window === 'undefined') return null;
  const Ctor: AudioCtxCtor | undefined =
    window.AudioContext ?? (window as unknown as { webkitAudioContext?: AudioCtxCtor }).webkitAudioContext;
  if (!Ctor) return null;
  if (!ctx) {
    try {
      ctx = new Ctor();
    } catch {
      return null;
    }
  }
  if (ctx && ctx.state === 'suspended') {
    void ctx.resume().catch(() => {
      // Autoplay policy can refuse — fall through silently. The next
      // user-gesture-driven call will retry.
    });
  }
  return ctx;
}

interface ToneSpec {
  freq: number;
  type: OscillatorType;
  start: number;
  duration: number;
  // Every real SOUND_PLAYERS entry (this type's only caller) always
  // supplies an explicit gain, so this is required rather than optional
  // with a fallback — an unreachable-by-any-real-caller default is dead
  // code, not real API surface (see packages/ui/archived provenance ledger).
  gain: number;
  /** Optional lowpass cutoff applied via a BiquadFilter for plucky textures. */
  lowpass?: number;
}

function playTones(c: AudioContext, tones: ToneSpec[]): void {
  const now = c.currentTime;
  for (const tone of tones) {
    const osc = c.createOscillator();
    const gain = c.createGain();
    osc.type = tone.type;
    osc.frequency.value = tone.freq;
    const peak = tone.gain;
    const startAt = now + tone.start;
    const endAt = startAt + tone.duration;
    // Short attack to avoid clicks; exponential-ish decay via a linear
    // ramp to near-zero (exponentialRamp can't reach exactly 0).
    gain.gain.setValueAtTime(0.0001, startAt);
    gain.gain.linearRampToValueAtTime(peak, startAt + Math.min(0.005, tone.duration * 0.2));
    gain.gain.exponentialRampToValueAtTime(0.0001, endAt);

    let last: AudioNode = osc;
    if (tone.lowpass) {
      const lp = c.createBiquadFilter();
      lp.type = 'lowpass';
      lp.frequency.value = tone.lowpass;
      osc.connect(lp);
      last = lp;
    }
    last.connect(gain);
    gain.connect(c.destination);
    osc.start(startAt);
    osc.stop(endAt + 0.02);
  }
}

const SOUND_PLAYERS: Record<SoundId, (c: AudioContext) => void> = {
  ding: (c) => {
    playTones(c, [{ freq: 880, type: 'sine', start: 0, duration: 0.25, gain: 0.22 }]);
  },
  chime: (c) => {
    playTones(c, [
      { freq: 880, type: 'triangle', start: 0, duration: 0.4, gain: 0.18 },
      { freq: 1320, type: 'triangle', start: 0, duration: 0.4, gain: 0.12 },
    ]);
  },
  'two-tone-up': (c) => {
    playTones(c, [
      { freq: 660, type: 'square', start: 0, duration: 0.08, gain: 0.16 },
      { freq: 990, type: 'square', start: 0.09, duration: 0.08, gain: 0.16 },
    ]);
  },
  pluck: (c) => {
    playTones(c, [{ freq: 220, type: 'sawtooth', start: 0, duration: 0.15, gain: 0.22, lowpass: 1200 }]);
  },
  buzz: (c) => {
    playTones(c, [
      { freq: 165, type: 'square', start: 0, duration: 0.06, gain: 0.2 },
      { freq: 165, type: 'square', start: 0.1, duration: 0.06, gain: 0.2 },
      { freq: 165, type: 'square', start: 0.2, duration: 0.06, gain: 0.2 },
    ]);
  },
  'two-tone-down': (c) => {
    playTones(c, [
      { freq: 880, type: 'sine', start: 0, duration: 0.12, gain: 0.2 },
      { freq: 440, type: 'sine', start: 0.13, duration: 0.12, gain: 0.2 },
    ]);
  },
  thud: (c) => {
    playTones(c, [{ freq: 80, type: 'sine', start: 0, duration: 0.12, gain: 0.32 }]);
  },
};

/** Plays a registered sound id. No-ops silently on any failure (never throws into UI code). */
export function playSound(id: SoundId): void {
  const c = getCtx();
  if (!c) return;
  const player = SOUND_PLAYERS[id];
  if (!player) return;
  try {
    player(c);
  } catch {
    // A node creation/connection failure should never throw out to UI code.
  }
}

export function previewSuccess(id: SoundId): void {
  playSound(id);
}

export function previewFailure(id: SoundId): void {
  playSound(id);
}

export function notificationPermission(): NotificationPermission | 'unsupported' {
  if (typeof Notification === 'undefined') return 'unsupported';
  return Notification.permission;
}

export async function requestNotificationPermission(): Promise<NotificationPermission | 'unsupported'> {
  if (typeof Notification === 'undefined') return 'unsupported';
  if (Notification.permission === 'granted' || Notification.permission === 'denied') {
    return Notification.permission;
  }
  try {
    return await Notification.requestPermission();
  } catch {
    return 'denied';
  }
}

export interface CompletionNotificationOpts {
  status: 'succeeded' | 'failed';
  title: string;
  body: string;
  onClick?: () => void;
  /** Service-worker script URL to register for the `showNotification` path.
   *  Omit to skip the service-worker path entirely and go straight to the
   *  `Notification` constructor. */
  serviceWorkerUrl?: string;
  /** Prefix for the notification `tag` (`${tagPrefix}-${status}`). Defaults
   *  to `'task'`. */
  tagPrefix?: string;
}

export type CompletionNotificationResult = 'shown' | 'unsupported' | 'permission-denied' | 'failed';

function notificationOptionsFor(opts: CompletionNotificationOpts): NotificationOptionsWithBrowserExtensions {
  const tag = `${opts.tagPrefix ?? 'task'}-${opts.status}`;
  return {
    body: opts.body,
    tag,
    renotify: true,
    data: {
      status: opts.status,
      url: typeof window === 'undefined' ? '/' : window.location.href,
    },
  };
}

async function showViaServiceWorker(
  opts: CompletionNotificationOpts,
): Promise<CompletionNotificationResult | null> {
  if (!opts.serviceWorkerUrl) return null;
  if (typeof navigator === 'undefined' || !('serviceWorker' in navigator)) return null;
  try {
    const registration = await navigator.serviceWorker.register(opts.serviceWorkerUrl);
    const readyRegistration = await navigator.serviceWorker.ready.catch(() => registration);
    if (!readyRegistration.showNotification) return null;
    await readyRegistration.showNotification(opts.title, notificationOptionsFor(opts));
    return 'shown';
  } catch {
    return null;
  }
}

// `showViaConstructor`'s only caller (`showCompletionNotification`) already
// checks `typeof Notification === 'undefined'` and
// `Notification.permission !== 'granted'` before ever calling this
// function, so re-checking either here is unreachable dead code — removed
// rather than tested around (this file's `ToneSpec.gain` default is the
// same pattern above).
function showViaConstructor(opts: CompletionNotificationOpts): CompletionNotificationResult {
  try {
    const note = new Notification(opts.title, notificationOptionsFor(opts));
    activeNotifications.add(note);
    const release = () => {
      note.onclick = null;
      note.onclose = null;
      note.onerror = null;
      activeNotifications.delete(note);
    };
    note.onclick = () => {
      try {
        if (typeof window !== 'undefined') window.focus();
      } catch {
        /* ignore */
      }
      opts.onClick?.();
      try {
        note.close();
      } catch {
        /* ignore */
      }
    };
    note.onclose = release;
    note.onerror = release;
    return 'shown';
  } catch {
    return 'failed';
  }
}

/**
 * Shows a completion notification, preferring the service-worker path (if
 * `serviceWorkerUrl` is supplied and registration succeeds) and falling
 * back to the direct `Notification` constructor.
 *
 * @overallScore 100
 */
export async function showCompletionNotification(
  opts: CompletionNotificationOpts,
): Promise<CompletionNotificationResult> {
  if (typeof Notification === 'undefined') return 'unsupported';
  if (Notification.permission !== 'granted') return 'permission-denied';
  return (await showViaServiceWorker(opts)) ?? showViaConstructor(opts);
}

/**
 * Tiered v4-UUID generator that survives non-secure contexts.
 *
 * `crypto.randomUUID()` is restricted to secure contexts — HTTPS or
 * `localhost`. Served over plain HTTP on a LAN IP (a common self-hosted
 * setup, e.g. `http://192.168.1.10:PORT`), a browser silently makes
 * `crypto.randomUUID` undefined, so calling it throws
 * `TypeError: crypto.randomUUID is not a function` — easy to miss behind a
 * surrounding try/catch, turning an id-generating action into a silent
 * no-op for every LAN-IP user.
 *
 * Three-tier fallback, preferred in order:
 *
 *   1. `crypto.randomUUID()` — secure-context happy path. Native, fast,
 *      cryptographically random.
 *   2. `crypto.getRandomValues()` — available in non-secure contexts too
 *      (a separate API, not gated by `isSecureContext`). Produces a real
 *      RFC 4122 v4 UUID with crypto-quality entropy.
 *   3. `Math.random()` — last resort, only for environments without either
 *      Web Crypto API. IDs generated this way are typically scoped to a
 *      single local session, so cryptographic uniqueness isn't required —
 *      just enough entropy to avoid collisions in normal use.
 *
 * @overallScore 100
 */
export function randomUUID(): string {
  // Tier 1: native randomUUID where the spec allows it.
  if (typeof crypto !== 'undefined' && typeof crypto.randomUUID === 'function') {
    return crypto.randomUUID();
  }

  // Tier 2: build a v4 UUID from `crypto.getRandomValues`. Byte layout
  // follows RFC 4122 §4.4 — set the version (high nibble of byte 6) to 4
  // and the variant (high two bits of byte 8) to `10`.
  if (typeof crypto !== 'undefined' && typeof crypto.getRandomValues === 'function') {
    const bytes = new Uint8Array(16);
    crypto.getRandomValues(bytes);
    bytes[6] = (bytes[6]! & 0x0f) | 0x40;
    bytes[8] = (bytes[8]! & 0x3f) | 0x80;
    const hex = Array.from(bytes, (b) => b.toString(16).padStart(2, '0')).join('');
    return `${hex.slice(0, 8)}-${hex.slice(8, 12)}-${hex.slice(12, 16)}-${hex.slice(16, 20)}-${hex.slice(20)}`;
  }

  // Tier 3: Math.random fallback. Same template as the de-facto browser
  // polyfill — replace `x` with a random hex nibble and `y` with one of
  // `8`/`9`/`a`/`b` to satisfy the variant bits.
  return 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g, (c) => {
    const r = (Math.random() * 16) | 0;
    return (c === 'x' ? r : (r & 0x3) | 0x8).toString(16);
  });
}

function assert(value: unknown, message: string): void {
    if (!value) {
        throw new Error(message);
    }

}

